window.TEXTS = [{"id":"a_dimotikou_0001","source_id":"a_dimotikou","title":"Αντίο, θάλασσα","content":"― Άρη, Μαρίνα! Ελάτε! Πάμε.\n― Αα, μαμά, έλα!\nΈνας αχινός!\nΘα πάρω άμμο από την παραλία.\n― Αντίο, θάλασσα.","word_count":20,"page_number":23,"chapter":"Πού είναι ο Άρης;"},{"id":"a_dimotikou_0002","source_id":"a_dimotikou","title":"Τιτίνα, η κότα","content":"― Τιτίνα! Τιτίνα, έλα, πίτα!\n― Ορφέα, Ορφέα!\n― Τι είναι, μαμά;\n― Άσε πια την κότα.\nΤο τρένο θα φύγει. Πάμε.","word_count":22,"page_number":25,"chapter":"Η παρέα"},{"id":"a_dimotikou_0003","source_id":"a_dimotikou","title":"Πεπόνι, πεπόνι!","content":"― Παππού, ένας παπαγάλος!\n― Παπαγάλε, θέλεις πεπόνι;\n― Πεπόνι, πεπόνι.\n― Παπαγάλε, θέλεις παγωτό;\n― Παγωτό, παγωτό.","word_count":18,"page_number":27,"chapter":"Η παρέα"},{"id":"a_dimotikou_0004","source_id":"a_dimotikou","title":"Τάσος, το σαλιγκάρι","content":"― Ένα σαλιγκάρι μέσα στη σακούλα!\n― Α! Το σαλιγκάρι από την παραλία.\nΤο λένε Τάσο.\n― Τάισέ το.\n― Τι;\n― Σαλάτα.","word_count":23,"page_number":31,"chapter":"Η παρέα"},{"id":"a_dimotikou_0005","source_id":"a_dimotikou","title":"Ο κύριος με το καπέλο","content":"― Ένας κύριος στον κήπο!\n― Κοίτα τι φοράει!\n― Ένα καπέλο και ένα κόκκινο σακάκι.\n― Έχει έναν σάκο και ένα πακέτο.\n― Τι να έχει ο σάκος;\n― Α! Έχει μια κότα!","word_count":34,"page_number":33,"chapter":"Η παρέα"},{"id":"a_dimotikou_0006","source_id":"a_dimotikou","title":"Όλοι στον κήπο","content":"― Να ο σάκος.\nΤι άλλο να έχει μέσα; Πάπιες;\n― Και άλλες κότες;\n― Όχι! Έχει ποντίκια.\n― Σιγά μην έχει και οχιές!\n― Πάμε στον κήπο να δούμε.","word_count":30,"page_number":35,"chapter":"Η παρέα"},{"id":"a_dimotikou_0007","source_id":"a_dimotikou","title":"Ρινόκερος και κόκορας","content":"― Άρη, ένα κορίτσι στο παράθυρο.\n\n― Η Ιωάννα! Είναι στην τάξη μου.\nΌλη μέρα τραγουδά:\n«Ρινόκερος και κόκορας,\nκότα, αετός και κόρακας\nπαρέα περπατάνε\nσε παραλία πάνε».","word_count":28,"page_number":39,"chapter":"Η παρέα"},{"id":"a_dimotikou_0008","source_id":"a_dimotikou","title":"Ιστορίες","content":"― Παππού, παππού!\nΠες μια ιστορία.\n― Τι ιστορία, Ιωάννα;\nΜια ιστορία με ιππότες;\n― Όχι, την ιστορία με τον ιπποπόταμο.\n― Μια φορά ένας ιπποπόταμος...","word_count":26,"page_number":41,"chapter":"Η παρέα"},{"id":"a_dimotikou_0009","source_id":"a_dimotikou","title":"Το παπί","content":"Μια φορά ένα Παπί\nείχε χάσει ένα Πι,\nείχε μείνει με το Πα\nκι έλεγε όλο «Πα Πα Πα».\n\nΠερπατούσε, προχωρούσε\nκαι κοιτούσε και ρωτούσε:\nΠού θα βρω, ποιος θα μου πει\nένα Πι, ωραίο Πι;\n\nΈψαξε σ᾽ όλα τα μέρη,\nβρήκε Πι από Πιπέρι,\nβρήκε Πι από Πιπίλα\nκαι το έπιασε τσαντίλα.\n\nΒρήκε Πι από Πιρούνι,\nβρήκε Πι από Πιτσούνι*,\nβρήκε Πι από Πινέζα\nκαι το πάτησε και -- τέζα!\n\nΤέλος, φόρεσε ένα Νι,\nένα Νι από Πανί,\nκι ήταν πια χωρίς το Πι,\nένα Πάνινο Παπί.","word_count":88,"page_number":45,"chapter":"Η παρέα"},{"id":"a_dimotikou_0010","source_id":"a_dimotikou","title":"Θέατρο Σκιών","content":"― Θέατρο Σκιών. «Ο Καραγκιόζης\nθαλασσόλυκος».\nΜια παράσταση από τον Σπαθάρη.\n\n― Κρατά ένα θεόρατο σπαθί.\nΈχει και ένα καλάθι.\nΘα πάμε στο θέατρο;","word_count":24,"page_number":47,"chapter":"Η παρέα"},{"id":"a_dimotikou_0011","source_id":"a_dimotikou","title":"Μύτη σαν σαλάμι","content":"― Καλημέρα σας! Είμαι ο Μορφονιός\nμε το όνομα.\n― Μμμ! Όνομα και πράμα.\n― Αχ! Η μύτη μου!\n― Μύτη είναι αυτό; Σαν σαλάμι είναι!\n― Μη, με πονάς! Άσε με πια.","word_count":33,"page_number":49,"chapter":"Μια παράσταση στην πλατεία"},{"id":"a_dimotikou_0012","source_id":"a_dimotikou","title":"Γάτα και παπαγάλος","content":"― Ο παπαγάλος μου!\n― Καλή μου γάτα, έλα εδώ.\nΓιατί έσκισες το πανί;\n― Σήμερα ήταν η παράσταση της γάτας.\nΓατάκι, μας έκανες και γελάσαμε.\n― Έκλεψες την παράσταση.","word_count":30,"page_number":53,"chapter":"Μια παράσταση στην πλατεία"},{"id":"a_dimotikou_0013","source_id":"a_dimotikou","title":"Χάσαμε τη γάτα","content":"― Βρήκαμε τον παπαγάλο,\nαλλά χάσαμε τη γάτα.\n― Να τη στον δρόμο.\n― Αχ! Ένα μηχανάκι! Γάτα, πρόσεχε!\nΤρέχα γρήγορα!\n― Χώθηκε στη χαρτοσακούλα!\nΣκόρπισε και τα λάχανα.\nΠάλι θάλασσα τα έκανε!","word_count":33,"page_number":57,"chapter":"Μια παράσταση στην πλατεία"},{"id":"a_dimotikou_0014","source_id":"a_dimotikou","title":"Ένα ζιζάνιο στη ζύμη","content":"― Εδώ είναι η γάτα; Έκανε πολλές ζημιές;\n― Όχι και τόσες!\nΣκόρπισε τη ζάχαρη στο τραπέζι.\nΎστερα πάτησε στη ζύμη.\n― Και τώρα πού είναι;\n― Να τη στο καζάνι με τη σοκολάτα.\n― Είναι μεγάλο ζιζάνιο.","word_count":38,"page_number":59,"chapter":"Μια παράσταση στην πλατεία"},{"id":"a_dimotikou_0015","source_id":"a_dimotikou","title":"Στο ζαχαροπλαστείο του Γλυκόσαυρου","content":"― Πες μου πού να βρω\nτον Γλυκόσαυρο;\n\n― Να, εδώ είμαι!\nΣε μια σκάφη μαρμελάδα\nμπήκα να δροσιστώ.\nΜε του μπακλαβά το φύλλο\nτώρα θα τυλιχτώ.\n\nΕγώ όλο τον χρόνο προσπαθούσα να φτιάξω\nτο πιο γλυκό γλυκό που έγινε ποτέ.\nΚαι το μεγαλύτερο παγωτό του κόσμου το ᾽κανα,\nκαι το άγαλμα της προπροπροπρογιαγιάς μου\nτο ’φτιαξα με ζελέ φράουλα.\nΑλλά το πιο γλυκό γλυκό, τίποτα.\nΔε μου πετυχαίνει.","word_count":69,"page_number":61,"chapter":"Μια παράσταση στην πλατεία"},{"id":"a_dimotikou_0016","source_id":"a_dimotikou","title":"Μου χαρίζεις την ουρά σου;","content":"Ένα απόγευμα ο παππούς διαβάζει στα παιδιά\nένα παραμύθι. Έξω βρέχει.\n\n― Κάποτε ήταν ένας σκύλος που δεν του\nάρεσε η ουρά του. Ήθελε μια άλλη ουρά.\n― Αλεπού, χάρισέ μου τη γούνινη ουρά σου.\n― Όχι. Ζήτα από το γουρούνι τη γυριστή\nουρά του.\n― Γουρούνι, χάρισέ μου τη γυριστή\nουρά σου.\n― Όχι. Κάθε ζώο έχει την ουρά\nπου του ταιριάζει.","word_count":63,"page_number":63,"chapter":"Μια παράσταση στην πλατεία"},{"id":"a_dimotikou_0017","source_id":"a_dimotikou","title":"Με βάρκα και σωσίβιο","content":"― Νύχτωσε. Ώρα να γυρίσουμε σπίτι!\n― Ο κήπος πλημμύρισε.\n― Και τώρα; Πώς θα περάσουμε;\n― Βρήκα τη λύση! Με βάρκα.\n― Σιγά μη βάλουμε και σωσίβιο!\n― Ένα κουτάβι στο πεζούλι!\n― Είναι μόνο του μέσα στη βροχή.\n― Πάω να το βοηθήσω.","word_count":45,"page_number":65,"chapter":"Το σύννεφο έφερε βροχή"},{"id":"a_dimotikou_0018","source_id":"a_dimotikou","title":"Μόνος στο σκοτάδι","content":"― Πώς βρέθηκες εδώ, κουταβάκι;\n― Μάλλον έχασε τον δρόμο του.\n― Καλά, και πώς ανέβηκε στο πεζούλι;\n― Θα πάτησε στη σανίδα.\n― Το καημένο, μόνο του στο σκοτάδι\nκαι τη βροχή. Τρέμουν τα ποδαράκια του.\n― Με λίγα χάδια στη μουσούδα θα είναι\nμια χαρά.\n― Δώστε του και λίγο γάλα.","word_count":53,"page_number":67,"chapter":"Το σύννεφο έφερε βροχή"},{"id":"a_dimotikou_0019","source_id":"a_dimotikou","title":"Χωρίς φως","content":"― Οχ! Σκοτάδι!\n\n― Και φοβερές αστραπές.\n\n― Μη φοβάστε! Ιωάννα, φέρε τον φακό.\nΚι εγώ, όταν ήμουν μικρός,\nφοβόμουν τις αστραπές.\nΦοβόμουν όμως περισσότερο\nτο δυνατό φύσημα του ανέμου.\nΤότε η γιαγιά μου, η Φανή,\nμου έλεγε μια ιστορία.","word_count":40,"page_number":69,"chapter":"Το σύννεφο έφερε βροχή"},{"id":"a_dimotikou_0020","source_id":"a_dimotikou","title":"Το παράξενο ταξίδι της Συννεφένιας","content":"― Ξέρω κι εγώ ένα παραμύθι για τον άνεμο\nκαι τη βροχή.\n\nΟ βασιλιάς Φωτιάς, η Συννεφένια και\nη κόρη τους η Χιονένια ζούσαν σε ένα\nπαλάτι. Ο Φωτιάς δεν τις άφηνε να βγουν\nέξω ποτέ. Στερέωνε την πόρτα με ένα\nβαρύ ξύλο.\nΜια μέρα όμως το ξέχασε. Τότε\nο Άνεμος φύσηξε δυνατά και άρπαξε\nτη Συννεφένια. Την πήρε μαζί του\nστο ταξίδι του...","word_count":64,"page_number":71,"chapter":"Το σύννεφο έφερε βροχή"},{"id":"a_dimotikou_0021","source_id":"a_dimotikou","title":"Ψιχάλες","content":"... Ο Φωτιάς έψαχνε σε όλη τη γη, πουθενά\nη Συννεφένια. Ο Άνεμος πετούσε ψηλά\nμε τη Συννεφένια στα φτερά του.\n«Θέλω να δω την κόρη μου» έλεγε\nη Συννεφένια και δάκρυζε. Ψιχάλες τότε\nέπεφταν στη διψασμένη γη.\nΟ Άνεμος της φώναζε: «Κλάψε όσο θες,\nστη γη δεν ξαναγυρνάς». Τότε το κλάμα της\nδυνάμωνε και γινόταν βροχή.","word_count":57,"page_number":73,"chapter":"Το σύννεφο έφερε βροχή"},{"id":"a_dimotikou_b_0001","source_id":"a_dimotikou_b","title":"Το καπέλο περπατάει!","content":"Άρης: Τι κάνει το σκυλάκι, Ιωάννα;\nIωάννα: Τρέχει πάνω κάτω στο σπίτι και γαβγίζει.\nΤου αρέσει να κρύβει διάφορα πράγματα.\nΧθες πήρε το μολύβι μου και το έχωσε\nπίσω από το ψυγείο. Ύστερα κρύφτηκε κάτω\nαπό το καπέλο του παππού. Ξαφνικά είδαμε\nένα καπέλο να περπατάει.\nΆρης: Τι αστείο! Ένα καπέλο με πόδια!\nΣαμπέρ: Τι άλλη ζαβολιά θα κάνει άραγε;","word_count":60,"page_number":9,"chapter":"Σκανταλιές"},{"id":"a_dimotikou_b_0002","source_id":"a_dimotikou_b","title":"Ένας καινούριος μαθητής","content":"Δάσκαλος: Παιδιά, τι βλέπω! Έχουμε έναν καινούριο\nμαθητή!\nΓιώργος: Πώς βρέθηκε εδώ; Εσύ τον έφερες, Ιωάννα;\nIωάννα: Ναι, κατά λάθος. Κρύφτηκε στο σακίδιο\nχωρίς να τον δω. Όλο κρύβεται.\nMαρία: Πώς τον λένε;\nIωάννα: Ακόμα δεν έχει όνομα.\nΠέτρος: Ωραία, να του βρούμε εμείς ένα όνομα.","word_count":46,"page_number":11,"chapter":"Σκανταλιές"},{"id":"a_dimotikou_b_0003","source_id":"a_dimotikou_b","title":"Όλοι στο οικόπεδο","content":"Πάλι κρύφτηκε ο Μολύβιος. Όλοι τον ψάχνουν\nστη γειτονιά.\n\nIωάννα: Κοιτάξτε! Είναι στο οικόπεδο. Βγήκε\nαπό την πολυκατοικία.\nΆρης: Οχ! Έχει γεμίσει με χρώματα.\nOρφέας: Τι έχει στο στόμα του;\nΣαμπέρ: Ένα πινέλο.\nIωάννα: Από ποιον το πήρε;\nMαρίνα: Μάλλον από την αδελφή του Πέτρου.\nΝα τη, ανοίγει το παράθυρο.","word_count":50,"page_number":13,"chapter":"Σκανταλιές"},{"id":"a_dimotikou_b_0004","source_id":"a_dimotikou_b","title":"Με πινέλα και φαντασία","content":"Άρης: Κύριε, χθες είδαμε ένα εργαστήρι\nζωγραφικής.\nΠέτρος: Της αδελφής μου είναι.\nIωάννα: Να κάνουμε και εμείς μια μεγάλη ζωγραφιά;\nΔάσκαλος: Εντάξει. Θα ζωγραφίσουμε τη μάντρα\nτου σχολείου. Μπορούμε να καλέσουμε\nκαι τους γονείς σας να μας βοηθήσουν.\nΆρης: Ναι, ναι! Να βάλουμε χρώμα παντού.\nΠέτρος: Εγώ θα φέρω χοντρά πινέλα.\nΆρης: Κι εγώ τη φαντασία μου!","word_count":57,"page_number":17,"chapter":"Σκανταλιές"},{"id":"a_dimotikou_b_0005","source_id":"a_dimotikou_b","title":"Oι δυο φίλοι","content":"Ο σκύλος λέει της γάτας:\n«Τα νύχια σου ετοιμάζεις,\nφυσάς και καμπουριάζεις.\nΜα τι έχεις και θυμώνεις;\nΩς πότε οι τσακωμοί;».\nΚι εκείνη: «Μη ζυγώνεις,\nσε σκίζω στη στιγμή!».\n\n«Για στάσου» λέει ο σκύλος\n«δε θέλεις να είμαι φίλος;\nΜιλώ στα σοβαρά»\nκαι κούναε την ουρά.\n«Τρωγόμαστε βδομάδες,\nπαίρνεις και δίνεις ξύλο.\nΑς πάψουν οι καβγάδες\nκαι δέξου με για φίλο.\nΔε σκέφτηκες κομμάτι\nπως απ’ την γκρίνια αυτή\nθα μείνω μ’ ένα μάτι,\nθα μείνεις μ’ ένα αυτί;»\n\nΛόγο τιμής εδώσαν.\nΉταν εχθροί, φιλιώσαν,\nξεχάσαν τι έχει γίνει.\nΣυντρόφεψαν. Ειρήνη.","word_count":91,"page_number":19,"chapter":"Σκανταλιές"},{"id":"a_dimotikou_b_0006","source_id":"a_dimotikou_b","title":"Ο παπουτσωμένος χιονόδρακος","content":"Τα παιδιά παίζουν χιονοπόλεμο. Κάνουν τσουλήθρα στο\nχιόνι.\nMαζί με τους γονείς τους έφτιαξαν έναν αστείο\nχιονάνθρωπο. Του έβαλαν μια κατσαρόλα για καπέλο και\nμια οδοντόβουρτσα για πίπα. Του φόρεσαν ένα τσουβάλι\nκαι δυο παλιά παπούτσια.\nΈφεραν και μια τσάντα με χρωματιστά πανιά. Όλοι μαζί\nέφτιαξαν με τα πανιά μια ουρά για τον χιονάνθρωπο.\n– Μοιάζει με δράκο, είπε η μαμά του Σαμπέρ.\n– Ναι, είναι ένας παπουτσωμένος χιονόδρακος,\nείπε γελώντας η Μαρίνα.","word_count":73,"page_number":21,"chapter":"ΤΟ ΧΑΜΕΝΟ ΚΛΕΙΔΙ"},{"id":"a_dimotikou_b_0007","source_id":"a_dimotikou_b","title":"Κοντά στο τζάκι","content":"Κάνει πολύ κρύο απόψε. Τα τζάμια έχουν θολώσει.\nΤα παιδιά κάθονται κοντά στο τζάκι. Πίνουν τσάι\nτου βουνού σε μεγάλα φλιτζάνια. Συζητούν για το κλειδί.\n– Τι γράφει η ταμπέλα; ρώτησε ο Oρφέας.\n– Δε φαίνεται. Έχει μόνο μια μουτζούρα, απάντησε\nο Σαμπέρ.\n– Tότε ας φυλάξουμε το κλειδί στο συρτάρι\nκι ας κολλήσουμε παντού την αγγελία μας, πρότεινε\nη Ιωάννα.\n– Θα σας πω ένα παραμύθι για ένα μαγικό κλειδί,\nείπε η Μαρίνα.","word_count":74,"page_number":25,"chapter":"ΤΟ ΧΑΜΕΝΟ ΚΛΕΙΔΙ"},{"id":"a_dimotikou_b_0008","source_id":"a_dimotikou_b","title":"Η ευχή","content":"Μια φορά κι έναν καιρό ήταν ένας ψαράς. Ένα\nαπόγευμα έπιασε ένα μικρούτσικο ψαράκι. Το λυπήθηκε και\nτο άφησε ελεύθερο.\n– Είσαι πολύ ευγενικός, είπε το ψαράκι.\nΓια να σε ευχαριστήσω, σου χαρίζω τούτο το μαγικό κλειδί.\nKράτησέ το και κάνε μια ευχή.\nΕυτυχισμένος ο ψαράς έβαλε το κλειδί στην τσέπη του.\nΣκεφτόταν: Τι να ευχηθώ; Να ψαρεύω πάντα πολλά ψάρια;\nΝα παντρευτώ μια καλή γυναίκα;\nΌμως η τσέπη του ψαρά ήταν τρύπια και έχασε\nτο κλειδί.\n\n– Λέτε ο Μολύβιος να βρήκε το κλειδί του ψαρά;\nείπε η Ιωάννα.","word_count":90,"page_number":27,"chapter":"ΤΟ ΧΑΜΕΝΟ ΚΛΕΙΔΙ"},{"id":"a_dimotikou_b_0009","source_id":"a_dimotikou_b","title":"Ο θείος Παύλος","content":"Ένα μεσημέρι, όταν η Ιωάννα γύρισε στο σπίτι,\nτης είπε η μαμά της:\n– Έχει έρθει ένα δέμα στο ταχυδρομείο για σένα.\nΑύριο, μετά το σχολείο, θα πάμε να το πάρουμε.\nΌταν πήγαν στο ταχυδρομείο, η μαμά έδειξε\nτην ταυτότητά της. Τότε ο υπάλληλος τους έδωσε\nένα δέμα.\n– Ποιος έστειλε αυτό το δέμα; ρώτησε η Ιωάννα.\n– Ο θείος σου ο Παύλος. Tο πλοίο του είναι\nστην Αφρική τώρα, είπε η μαμά.\n– Κοίτα, μαμά! Μια μαύρη μάσκα με χάντρες. Και ένα\nβιβλίο με σαύρες. Kαι ένα γράμμα για μένα.","word_count":91,"page_number":29,"chapter":"ΤΟ ΧΑΜΕΝΟ ΚΛΕΙΔΙ"},{"id":"a_dimotikou_b_0010","source_id":"a_dimotikou_b","title":"Για τ’ αγγελάκια του ουρανού","content":"Καμιά φορά στα ποιήματα\nστις λέξεις, στα τραγούδια\nακούω φτεροκοπήματα\nθαρρώ απ’ αγγελούδια.\n\nΣύννεφά μου, αφήστε με\nπάνω σας να πατήσω,\nτ’ αστράκια που θαμπώσατε\nνα πάω να τα γυαλίσω.\n\nΟι πύραυλοι στον ουρανό\nτρέχουν σαν μηχανάκια.\nΚαλέ Θεούλη, φύλαγε\nτ’ άστρα και τ’ αγγελάκια.","word_count":45,"page_number":31,"chapter":"ΤΟ ΧΑΜΕΝΟ ΚΛΕΙΔΙ"},{"id":"a_dimotikou_b_0011","source_id":"a_dimotikou_b","title":"Ένα γράμμα για την Ιωάννα","content":"Η Ιωάννα διαβάζει και ξαναδιαβάζει το γράμμα που έστειλε\nο θείος Παύλος.","word_count":12,"page_number":33,"chapter":"ΤΟ ΧΑΜΕΝΟ ΚΛΕΙΔΙ"},{"id":"a_dimotikou_b_0012","source_id":"a_dimotikou_b","title":"Δώρα για την Ιωάννα","content":"Λίγες μέρες μετά\nο θείος Παύλος έφτασε\nφορτωμένος με δώρα\nγια την Ιωάννα.\n– Ποιο πακέτο θα\nανοίξεις πρώτα; Το\nκόκκινο ή το πράσινο;\nρώτησε ο θείος\nΠαύλος.\n– Το κόκκινο, είπε\nη Ιωάννα. Α! Ο Πινόκιο! Δες πόσο μεγάλη είναι η μύτη του!\n– Τον αγόρασα από την Ιταλία, είπε ο θείος Παύλος.\nΤώρα διάλεξε. Το πράσινο πακέτο ή τη σακούλα;\n– Το πράσινο πακέτο, απάντησε η Ιωάννα. Ένα καπέλο!\nΔεν έχω ξαναδεί τόσο μεγάλο καπέλο!\n– Είναι από το Μεξικό, της είπε ο θείος Παύλος.\n– Και αυτή η σακούλα τι έχει; ρώτησε η Ιωάννα.\n– Άνοιξε και θα δεις, της απάντησε ο θείος Παύλος.\n– Ένα τύμπανο! φώναξε χαρούμενη η Ιωάννα.\n– Ένα τύμπανο από την Αφρική για να παίζεις μουσική,\nτης είπε ο θείος Παύλος γελώντας.","word_count":130,"page_number":35,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0013","source_id":"a_dimotikou_b","title":"Τι κρύβει το μπαούλο;","content":"Χθες ο θείος Παύλος άνοιξε το συρτάρι της κουζίνας. Και\nτι να δει! Το κλειδί που είχε βρει ο Μολύβιος. Άρχισε τότε\nνα φωνάζει:\n– Το κλειδί μου! Ποιος το ’βαλε εδώ; Το ’ψαχνα παντού!\nΠίστευα πως το ’χα χάσει. Ιωάννα, εσύ το βρήκες;\n– Όχι εγώ. Ο Μολύβιος, απάντησε η Ιωάννα.\n– Μπράβο, Μολύβιε! Σ’ ευχαριστώ, είπε ο θείος Παύλος.\n– Θείε, τι ανοίγεις μ’ αυτό το κλειδί; ρώτησε η Ιωάννα.\n– Το μπαούλο με τους θησαυρούς μου, απάντησε ο θείος\nΠαύλος.\n– Τι θησαυρούς, αληθινούς; ρώτησε η Ιωάννα.\n– Και βέβαια αληθινούς. Είναι πράγματα που ’χω μαζέψει\nαπ’ τα ταξίδια μου, είπε ο θείος Παύλος.\n– Τι ’ναι; Θα ’θελα να\nδω! Να φωνάξω και τους\nφίλους μου; ρώτησε η\nΙωάννα.\n– Εντάξει. Αύριο, μετά\nτο σχολείο, ελάτε όλοι\nσπίτι μου.","word_count":133,"page_number":36,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0014","source_id":"a_dimotikou_b","title":"Καράβια","content":"Καράβια μεγάλα, καράβια μικρά, καράβια με πανιά,\nκαράβια με φουγάρα*, βάρκες, καΐκια, υπερωκεάνια…\nΑυτός είναι ο θησαυρός του θείου Παύλου. Καράβια\nπαρόμοια με τα αληθινά, όμως πολύ μικρότερα. Μοιάζουν\nμε παιχνίδια. Από παιδί τα μαζεύει κι έχει πια μια μεγάλη\nσυλλογή.\nΚάθε φορά που γυρίζει απ’ τα ταξίδια του, βγάζει τα καράβια\nαπό το μπαούλο. Τα ξεσκονίζει, τα χαϊδεύει, τα καμαρώνει.\nΌλα τα καράβια έχουν ονόματα. Το αγαπημένο του είναι η\n«Σαΐτα», ένα ξύλινο καΐκι με πανιά. Το έφτιαξε ένας γέρος\nναυτικός από τη Σκόπελο.\nΣτον Ορφέα άρεσε περισσότερο το καράβι που είχε\nζωγραφισμένα δύο\nτεράστια μάτια\nστα πλαϊνά της\nπλώρης** του.\n– Έτσι ήταν\nτα πολεμικά\nκαράβια στην\nαρχαιότητα,\nείπε ο θείος\nΠαύλος.","word_count":114,"page_number":37,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0015","source_id":"a_dimotikou_b","title":"Παιχνίδια που ταξιδεύουν","content":"Tα παιδιά διάβασαν σε ένα βιβλίο με κατασκευές πώς να\nφτιάχνουν καραβάκια από απλά υλικά.","word_count":15,"page_number":39,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0016","source_id":"a_dimotikou_b","title":"Το πετροκάραβο","content":"Ο θείος Παύλος διηγήθηκε στα παιδιά μια ιστορία.\nΤην είχε ακούσει από έναν γέρο ναυτικό.\n\nΚοντά στην Κέρκυρα\nυπάρχει ένα μικρό νησάκι\nπου μοιάζει με καράβι.\nΛένε ότι κάποτε, στα\nπαλιά χρόνια, φάνηκε\nαπό μακριά ένα παράξενο\nκαράβι. Όλος ο κόσμος\nβγήκε στην ακρογιαλιά για να το\nδει. Να ήταν άραγε φίλοι ή εχθροί;\nΤο καράβι έφτασε στο πέρασμα ανάμεσα\nστα βράχια. Τότε είδαν τη σημαία του. Ήταν\nαπό μαύρο ύφασμα κι είχε ζωγραφισμένο ένα\nθεριό. Όλοι έτρεξαν στα σπίτια τους φοβισμένοι.\nΈσβησαν λάμπες και κεριά. Μόνο η Σμαρώ, ένα\nσγουρομάλλικο κορίτσι, έμεινε στην ακρογιαλιά.\n– Θεέ μου, αν είναι εχθροί, ας γίνει το καράβι\nτους πέτρα, ευχήθηκε η Σμαρώ.\nΑμέσως το καράβι πέτρωσε και έγινε ένα μικρό\nνησί.","word_count":119,"page_number":40,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0017","source_id":"a_dimotikou_b","title":"Η 25η Μαρτίου","content":"΄Yμνος εις την ελευθερία\n\nΣε γνωρίζω από την κόψη\nτου σπαθιού την τρομερή,\nσε γνωρίζω από την όψη,\nπου με βία μετράει τη γη.\n\nΑπ’ τα κόκαλα βγαλμένη\nτων Ελλήνων τα ιερά,\nκαι σαν πρώτα ανδρειωμένη,\nχαίρε, ω χαίρε, Ελευθεριά!","word_count":40,"page_number":41,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0018","source_id":"a_dimotikou_b","title":"Mια Κυριακή του Μάρτη","content":"Μια Κυριακή του Μάρτη\nκαι μια Σαρακοστή*\nεσύ ’σουν στο κατάρτι\nκι εγώ στην κουπαστή**.\n\nΚαι δίπλα στο τιμόνι\nόταν γυρίσαμε\nτο πρώτο χελιδόνι\nκαλωσορίσαμε.\n\nΔε σου ’στειλα το μήλο\nκαι σ’ έχασα από φίλο\nμα μ’ ένα πορτοκάλι\nθα σε κερδίσω πάλι.","word_count":43,"page_number":43,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0019","source_id":"a_dimotikou_b","title":"H μετακόμιση","content":"Την Κυριακή ένα μεγάλο φορτηγό σταμάτησε έξω από την\nπολυκατοικία που μένουν ο Άρης και η Μαρίνα.\n– Στον πρώτο όροφο να τα ανεβάσετε παρακαλώ, ακούστηκε μια γυναικεία φωνή.\nΤρεις εργάτες ανεβοκατέβαιναν τη σκάλα κουβαλώντας\nπράγματα. Ένα ψυγείο, μία κουζίνα, μία τηλεόραση, δύο\nβιβλιοθήκες, έναν ηλεκτρονικό υπολογιστή, μία κιθάρα,\nένα πλυντήριο, καρέκλες, ένα μεγάλο τραπέζι, γλάστρες,\nκούτες…\nΟ Άρης και η Μαρίνα κοιτούσαν από το παράθυρο.\n– Να έχουν άραγε παιδιά\nοι καινούριοι μας\nγείτονες; αναρωτήθηκε\nη Μαρίνα.\nΤότε είδαν έναν\nεργάτη να ξεφορτώνει\nένα κόκκινο παιδικό\nποδήλατο.","word_count":88,"page_number":45,"chapter":"Kαράβια"},{"id":"a_dimotikou_b_0020","source_id":"a_dimotikou_b","title":"H Aγγελική","content":"Το επόμενο απόγευμα ο\nΆρης συνάντησε στη σκάλα\nτης πολυκατοικίας ένα\nκορίτσι. Προσπαθούσε να\nανεβάσει το ποδήλατό της.\nΟ Άρης τη βοήθησε.\n– Εγώ θα κρατήσω την πίσω\nρόδα. Εσύ κράτα το τιμόνι,\nτης είπε. Πρόσεχε να μη\nχτυπήσει ο καθρέφτης στον\nτοίχο.\nΤα παιδιά ανέβασαν το ποδήλατο στον πρώτο όροφο.\n– Φτάσαμε, είπε το κορίτσι. Ευχαριστώ πολύ για τη βοήθειά\nσου.\n– Με λένε Άρη. Εδώ είναι ο όροφος που μένω, είπε ο Άρης.\n– Εμένα με λένε Αγγελική. Είμαι η καινούρια γειτόνισσά\nσας.\n– Μου αρέσει το ποδήλατό σου. Tην Kυριακή θα πάω με\nτους φίλους μου βόλτα στο βουνό. Θα πάρουμε τα ποδήλατά\nμας. Θέλεις να έρθεις κι εσύ; ρώτησε ο Άρης.","word_count":115,"page_number":47,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0021","source_id":"a_dimotikou_b","title":"Παίζουμε παντομίμα;","content":"Είναι Παρασκευή απόγευμα. Όλη η παρέα είναι στο\nσπίτι του Άρη και της Μαρίνας. Αποφάσισαν να παίξουν\nπαντομίμα. Ο Ορφέας λέει τους κανόνες του παιχνιδιού.\n\nΔιαλέγουμε ένα θέμα. Mπορεί να είναι τα ζώα,\nτα επαγγέλματα ή οι ήρωες των παραμυθιών.\nΧωριζόμαστε σε ομάδες. Κάθε ομάδα διαλέγει\nμυστικά τι θα παρουσιάσει στην άλλη ομάδα.\nH μία ομάδα παρουσιάζει το θέμα\nχωρίς λόγια, μόνο με κινήσεις. Για\nπαράδειγμα, τα παιδιά μιμούνται\nτις κινήσεις των\nζώων. Οι παίκτες\nτης άλλης\nομάδας\nπροσπαθούν\nνα μαντέψουν.\nΚερδίζουν, αν\nμαντέψουν\nσωστά.","word_count":85,"page_number":49,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0022","source_id":"a_dimotikou_b","title":"Βόλτα στο βουνό","content":"Είναι Κυριακή πρωί. Όλα τα παιδιά πηγαίνουν στο κοντινό βουνό.\nΜαζί τους είναι οι γονείς του Άρη, της Μαρίνας και της Αγγελικής.\nΌλα τα δέντρα έχουν γεμίσει φύλλα. Τα λουλούδια μυρίζουν\nωραία. Παντού έχουν φυτρώσει κατακόκκινες παπαρούνες, κίτρινες\nκι άσπρες μαργαρίτες. Τα πουλιά κελαηδούν και πετούν από κλαδί\nσε κλαδί. Ψάχνουν τροφή για τα μικρά τους.\nΟι μέλισσες ζουζουνίζουν και μαζεύουν τον χυμό των\nλουλουδιών\nγια να τον κάνουν μέλι. Οι πολύχρωμες\nπεταλούδες μοιάζουν σαν να χορεύουν στον αέρα. Μικρά και\nμεγάλα μυρμήγκια σκάβουν τις φωλιές τους και μαζεύουν την\nτροφή τους.\nΤα παιδιά αφήνουν\nτα ποδήλατά τους.\nΤρέχουν και παίζουν\nστο λιβάδι. Ο Μολύβιος\nσκάβει στο χώμα και\nκρύβει ένα κόκαλο.\nΗ Μαρίνα κοιτάζει\nψηλά και φωνάζει\nχαρούμενα:\n– Ψηλά στον ουρανό\nβλέπω χελιδόνια!","word_count":125,"page_number":51,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0023","source_id":"a_dimotikou_b","title":"Το κοτσύφι","content":"– Παιδιά, ελάτε γρήγορα, φωνάζει η Αγγελική. Ένα πουλί! Ένα μικρό μαύρο πουλί!\n– Ένα μικρό μαύρο πουλί περπατά στο μονοπάτι. Ελπίζω\nνα μη φύγει, είπε ο Άρης.\n– Δε θα φύγει, αν δεν το τρομάξετε. Γεια σας, είμαι η\nΚατερίνα. Είμαι δασοφύλακας. Το πουλί αυτό είναι κοτσύφι.\nΈχει στη φωλιά του κοτσυφάκια. Μαζεύει τροφή και τα\nταΐζει. Tα κοτσύφια τρώνε σκουλήκια, έντομα και μικρούς\nκαρπούς. Εδώ ζουν αρκετά κοτσύφια. Χτίζουν τις φωλιές\nτους σε χαμηλά κλαδιά και θάμνους. Τον χειμώνα δε βρίσκουν\nεύκολα τροφή. Η παγωνιά τα φοβίζει. Γι’ αυτό λίγο καιρό πριν\nέρθει η άνοιξη, σφυρίζουν από τη χαρά τους. Όσοι ακούνε\nτο σφύριγμά τους ξέρουν ότι η άνοιξη πλησιάζει.","word_count":112,"page_number":53,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0024","source_id":"a_dimotikou_b","title":"Γεια σου, κότσυφα","content":"Μια μέρα ο Μάρτης συνάντησε τον κότσυφα.\n– Γεια σου, κότσυφα, του είπε.\n– Για να σου πω, απάντησε ο κότσυφας θυμωμένος. Δε με λένε σκέτο κότσυφα. Με λένε κυρ κότσυφα κι αφέντη κιτρινομύτη, γιατί πρώτος απ’ όλα\nτα πουλιά έφτιαξα τη φωλιά μου. Γέννησα τ’ αυγά\nμου κι όπου να ’ναι θα δεις και τα παιδιά μου.\nΟ Μάρτης κούνησε το κεφάλι του. Την άλλη\nμέρα έπιασε τόσο κρύο, που τα αυγά του κότσυφα\nέσπασαν.\nΠριν έρθει ο Απρίλης, ο Μάρτης συνάντησε ξανά\nτον κότσυφα.\n– Καλημέρα, κότσυφα και κυρ κότσυφα κι αφέντη\nκιτρινομύτη!\n– Δεν είμαι πια κότσυφας και κυρ κότσυφας κι\nαφέντης κιτρινομύτης. Με ξεγέλασες, Μάρτη! Τη\nμια μέρα κάνεις κρύο, την άλλη κάνεις ζέστη. Πάει\nη φωλιά μου, πάνε και τ’ αυγά μου!\nΌμως ο κότσυφας, όταν ζέστανε ο καιρός, έφτιαξε\nκαινούρια φωλιά και γέννησε ξανά αυγά.","word_count":141,"page_number":56,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0025","source_id":"a_dimotikou_b","title":"Πασχαλινό","content":"Πέντε μέρες μόνο μένουν\nγια ν’ αρχίσουν οι γιορτές\nτης Mεγάλης Eβδομάδας\nκι οι πασχαλινές χαρές.\nΠώς μ’ αρέσουν οι καμπάνες\nνα χτυπούν νυχτερινές…\nKαι μοσκοβολούν οι φούρνοι\nαπ’ τις τόσες μυρωδιές…\nTα τραπέζια κοκκινίζουν\nαπ’ τα κόκκινα τ’ αυγά.\nKι ένας τ’ άλλου τα τσουγκρίζουν\nκαι του λεν: χρόνια πολλά…","word_count":51,"page_number":57,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0026","source_id":"a_dimotikou_b","title":"Στη βιβλιοθήκη","content":"Τα παιδιά κανόνισαν\nνα πάνε στη βιβλιοθήκη.\nΉθελαν να επιστρέψουν\nτο βιβλίο για τα πουλιά.\nΠήγαν στην αίθουσα\nμε τα παιδικά βιβλία.\nΟι τοίχοι ήταν γεμάτοι\nράφια με βιβλία. Βιβλία\nμεγάλα και βιβλία μικρά,\nβιβλία χοντρά και βιβλία\nλεπτά. Βιβλία με σκληρό\nεξώφυλλο και βιβλία με\nμαλακό εξώφυλλο. Βιβλία παλιά και βιβλία καινούρια. Πάνω\nαπό τα ράφια ήταν κολλημένες αφίσες για βιβλία και εικόνες\nμε ήρωες βιβλίων. Στη μέση υπήρχαν δύο μεγάλα τραπέζια\nμε καρέκλες. Σε μια γωνιά τα παιδιά είδαν ένα χαλί με πολλά\nμαξιλάρια.\nΗ υπεύθυνη της βιβλιοθήκης τούς καλημέρισε και τους\nρώτησε τι βιβλία θα ήθελαν.\n— Πείτε μου, παιδιά! Τι σας ενδιαφέρει; Στα βιβλία μπορούμε\nνα βρούμε τα πάντα.","word_count":113,"page_number":59,"chapter":"Άνοιξη"},{"id":"a_dimotikou_b_0027","source_id":"a_dimotikou_b","title":"Να σας διαβάσω;","content":"Λίγες μέρες μετά, η Μαρίνα διαβάζει στους φίλους της\nένα κομμάτι από το βιβλίο «Το γαϊτανάκι».","word_count":16,"page_number":61,"chapter":"O κόσμος των βιβλίων"},{"id":"a_dimotikou_b_0028","source_id":"a_dimotikou_b","title":"Το Αλφαβητάρι με τον Ήλιο","content":"Ύστερα ο Ορφέας διάβασε στους φίλους του ένα κομμάτι\nαπό ένα παλιό αλφαβητάρι.\n\nΟ Ρήγας καπετάνιος\n\nΜια βαρκούλα ήταν δεμένη στην ακρογιαλιά.\n«Να η βάρκα του γερο-Κοσμά! Την παίρνουμε\nνα πάμε ταξίδι;» λέει ο Ρήγας.\n«Θα μας δει, και θα χαλάσει τον κόσμο από τις\nφωνές» είπαν τ άλλα παιδιά.\n«Δε μαλώνει ο γερο-Κοσμάς» λέει ο Ρήγας.\nΛίγα παιδιά πήγαν μαζί με το Ρήγα. Ζύγωσαν τη\nβάρκα και πήδησαν μέσα. Λύνουν το σκοινί και τραβούν μακριά. Ωραία που πηγαίνει η βαρκούλα με το\nκάτασπρο πανί! «Καλό ταξίδι! Χαιρετίσματα στους\nδικούς μας!» τους φωνάζουν από την ακρογιαλιά.","word_count":96,"page_number":63,"chapter":"O κόσμος των βιβλίων"},{"id":"a_dimotikou_b_0029","source_id":"a_dimotikou_b","title":"Θα γράψουμε το δικό μας βιβλίο","content":"— Κύριε, πήγαμε στη\nδημοτική βιβλιοθήκη\nκαι είδαμε πολλά βιγια\nβλία. Διαβάσαμε\nτην περιπέτεια του\nΡήγα στη θάλασσα,\nδιαβάσαμε και\nγια\nέναν άνθρωπο που\nαγαπούσε πολύ τα\nβιβλία, τον κυρ Γαρίφαλο, είπε ο Άρης.\n— Μακάρι να μπορούσαμε να γράφαμε κι εμείς βιβλία, είπε\nη Ιωάννα.\n— Μπορείτε να γίνετε κι εσείς συγγραφείς. Να γράψετε\nδικές σας ιστορίες. Καθένας σας μπορεί να σκεφτεί μια\nπεριπέτειά του, μια αστεία ιστορία, κάτι που τον έκανε να\nχαρεί ή να στεναχωρηθεί. Θυμάστε τότε που ήρθε στην τάξη\nμας το σκυλάκι της Ιωάννας; είπε ο δάσκαλος.\n— Α, ναι, κύριε, φώναξε η Ελένη. Θα γράψω εγώ γι’ αυτό.\n— Εγώ θα γράψω για τη μέρα που ζωγραφίσαμε όλοι μαζί\nτη μάντρα του σχολείου, είπε ο Δαμιανός.\n— Κι εγώ θα πω για τη ζαβολιά της γάτας στην παράσταση\nτου Καραγκιόζη, είπε η Ιωάννα.\n— Εγώ να περιγράψω την επίσκεψή μας στο Ναυτικό\nΜουσείο; ρώτησε η Φωτεινή.\n— Θα κάνουμε ένα βιβλίο. Θα κάνουμε ένα μεγάλο βιβλίο,\nφώναξε ο Γιάννης.","word_count":165,"page_number":65,"chapter":"O κόσμος των βιβλίων"},{"id":"a_dimotikou_b_0030","source_id":"a_dimotikou_b","title":"Έκθεση βιβλίου","content":"Η ιδέα που είχαν τα παιδιά της πρώτης τάξης να φτιάξουν βιβλίο άρεσε σε όλους. Έτσι όλες οι τάξεις του σχολείου άρχισαν να φτιάχνουν βιβλία. Αποφάσισαν να τα\nπαρουσιάσουν στην έκθεση βιβλίου του σχολείου τους. Η\nδιευθύντρια του σχολείου ετοίμασε μια ανακοίνωση.","word_count":42,"page_number":67,"chapter":"O κόσμος των βιβλίων"},{"id":"a_dimotikou_b_0031","source_id":"a_dimotikou_b","title":"Kaλοκαιρινή εκδρομή","content":"Πρώτες μέρες του καλοκαιριού. Ο καιρός έχει ζεστάνει.\nΟι γονείς των παιδιών είχαν υποσχεθεί σε όλη την παρέα\nμια εκδρομή στη θάλασσα. Την Κυριακή θα πάνε στην Ψιλή\nΆμμο.\nΑπό την ανυπομονησία τους όλα τα παιδιά ξύπνησαν\nπρωί πρωί, πριν ακόμη χτυπήσει το ξυπνητήρι. Ετοίμασαν\nτα εκδρομικά τους σακίδια, φόρεσαν τα καπέλα τους και\nνα τα τώρα στον σταθμό των λεωφορείων. Η ώρα είναι 9.\nΚοιτάζουν τον πίνακα με τα δρομολόγια.\nΠροσπαθούν να βρουν τι ώρα φεύγει\nλεωφορείο για την Ψιλή Άμμο.","word_count":82,"page_number":71,"chapter":"O κόσμος των βιβλίων"},{"id":"a_dimotikou_b_0032","source_id":"a_dimotikou_b","title":"Ίχνη στην άμμο","content":"— Κάνουμε ένα μεγάλο κάστρο από άμμο; πρότεινε η\nΜαρίνα. Άρη και Ιωάννα, εσείς θα κουβαλήσετε άμμο με\nτα κουβαδάκια σας. Η Αγγελική, ο Μολύβιος και εγώ θα\nψάξουμε για αχηβάδες για να το στολίσουμε.\n— Παιδιά, ελάτε γρήγορα! Κοιτάξτε τι βρήκε ο Μολύβιος!\nΚάτι μεγάλα στρογγυλά ίχνη που ξεκινούν από τη θάλασσα,\nφώναξε ο Σαμπέρ. Ας τα ακολουθήσουμε.\nΞαφνικά τα ίχνη σταματούν. Τα παιδιά κοιτάζουν γύρω\nτους με απορία. Εκείνη τη στιγμή τους πλησιάζει η μαμά του\nΟρφέα.\n— Παιδιά, προσέχετε πού πατάτε! Μην ανακατεύετε\nκαθόλου την άμμο. Βρήκατε τα ίχνη μιας θαλάσσιας\nχελώνας. Μια χελώνα κάπου εδώ έχει θάψει τα αυγά της.\nΣτην άκρη της παραλίας υπάρχει μια ταμπέλα με πληροφορίες και φωτογραφίες. Πάμε όλοι μαζί να τη δούμε.","word_count":121,"page_number":72,"chapter":"Το κοχύλι"},{"id":"a_dimotikou_b_0033","source_id":"a_dimotikou_b","title":"Η χελώνα Καρέττα Καρέττα","content":"ΚΑΡΕΤΤΑ ΚΑΡΕΤΤΑ\nΗ θαλάσσια χελώνα είναι ερπετό.\nΖει στη θάλασσα εδώ και εκατομμύρια χρόνια, από την εποχή των δεινοσαύρων. Το καβούκι της έχει σχήμα\nκαρδιάς. Τρώει καβούρια, αστερίες,\nμέδουσες, αχινούς, σφουγγάρια και\nκαλαμαράκια.","word_count":33,"page_number":73,"chapter":"Το κοχύλι"},{"id":"a_dimotikou_b_0034","source_id":"a_dimotikou_b","title":"Αρχαίοι μύθοι","content":"— Υπάρχει ένας αρχαίος μύθος από την Ινδία για τη\nθαλάσσια χελώνα, λέει ο μπαμπάς του Σαμπέρ. Στα αρχαία\nχρόνια οι άνθρωποι πίστευαν ότι τρεις ελέφαντες κουβαλούσαν τη Γη στις ράχες τους. Αυτούς τους ελέφαντες\nτους κουβαλούσε πάνω στο καβούκι της μια τεράστια\nθαλάσσια χελώνα. Η χελώνα κολυμπούσε σε μια θάλασσα\nχωρίς αρχή και τέλος.\nΛένε πως, αν η χελώνα πάψει να υπάρχει, οι ελέφαντες θα\nχάσουν την ισορροπία τους. Τότε η Γη θα γλιστρήσει από τις\nράχες τους και θα χαθεί.\n— Και στην αρχαία Ελλάδα πίστευαν ότι η θαλάσσια χελώνα\nήταν σπουδαίο ζώο, λέει η μαμά του Ορφέα. Γι’ αυτό την\nείχαν σχεδιάσει πάνω σε νομίσματα. Έλεγαν ότι ήταν το\nαγαπημένο ζώο της Αφροδίτης, της θεάς της ομορφιάς.\n— Παλιά οι ψαράδες πίστευαν ότι θα είχαν καλό ταξίδι αν\nέβλεπαν χελώνα να κολυμπάει δεξιά από τη βάρκα τους.\nΌταν έβλεπαν τη χελώνα αριστερά, πίστευαν ότι θα είχαν\nκακό ταξίδι, συμπληρώνει ο μπαμπάς της Αγγελικής.","word_count":156,"page_number":75,"chapter":"Το κοχύλι"},{"id":"a_dimotikou_b_0035","source_id":"a_dimotikou_b","title":"Η σπηλιά","content":"Ξαφνικά ο Μολύβιος αρχίζει να τρέχει. Τα\nπαιδιά τον βλέπουν να χώνεται ανάμεσα\nστα βράχια. Το σκυλάκι χάνεται από\nτα μάτια τους.\nΌλοι ψάχνουν να τον\nβρουν. Οι πατημασιές του\nοδηγούν πίσω από έναν\nμεγάλο βράχο. Τα παιδιά\nβρίσκονται μπροστά στην\nείσοδο μιας σπηλιάς.\n— Λέτε να είναι σπηλιά\nπειρατών; ρωτάει η Ιωάννα.\nΦοβάμαι λίγο.\n— Μη φοβάσαι. Θα σου κρατώ το χέρι. Έτσι δε θα φοβάμαι\nούτε εγώ, λέει ο Άρης.\nΑς μπούμε.\n— Ακούγεται ένας θόρυβος, ψιθυρίζει ο Σαμπέρ.\n— Μου φαίνεται σαν ροχαλητό. Μήπως είναι κάποιος\nπειρατής που κοιμάται; ρωτάει η Ιωάννα.\n— Παιδιά, μη χάνετε το θάρρος σας, φωνάζει η Μαρίνα.\nΟ Μολύβιος είναι που γρυλίζει.\n— Κάτι θα βρήκε. Πάμε να δούμε, λέει ο Ορφέας.","word_count":120,"page_number":76,"chapter":"Το κοχύλι"},{"id":"a_dimotikou_b_0036","source_id":"a_dimotikou_b","title":"Η μπουρού","content":"Τα παιδιά βρήκαν τον Μολύβιο. Κι αυτός είχε βρει τον θησαυρό που κρυβόταν στη σπηλιά. Είχε σταθεί μπροστά σε ένα μεγάλο κοχύλι και το γάβγιζε. Ήταν μια μπουρού. Στα παλιά χρόνια\nοι ναυτικοί φυσούσαν μέσα σε τέτοια κοχύλια. Έβγαινε ένας δυνατός ήχος. Έτσι ειδοποιούσαν ότι φτάνουν στη στεριά.\n— Με μια μπουρού σφύριζε και ο Τρίτωνας, είπε η Μαρίνα.\nΈνας αρχαίος ελληνικός μύθος έλεγε ότι ο Τρίτωνας ζούσε στη\nθάλασσα. Αυτός είχε σώμα ανθρώπου και ουρά ψαριού, όπως οι\nγοργόνες. Ήταν γιος του Ποσειδώνα, του θεού της θάλασσας.\nΌταν ο Τρίτωνας θύμωνε, σήκωνε τρικυμία. Οι ναυτικοί έχυναν\nκρασί στη θάλασσα, για να τον καλοπιάσουν και να έχουν καλό\nταξίδι.\n— Ας παίξουμε τους πειρατές. Αυτοί οπωσδήποτε θα είχαν\nμπουρού, φώναξε η Ιωάννα.\n— Πάμε στην ακρογιαλιά να φυσήξουμε με την μπουρού. Ίσως\nκάποιος μας ακούσει και απαντήσει, είπε ο Σαμπέρ.\n— Αν βάλουμε το κοχύλι στο αυτί\nμας, μπορούμε να ακούσουμε το\nτραγούδι της θάλασσας, είπε η Αγγελική.\n— Και να ονειρευτούμε θαλασσινά ταξίδια, συμπλήρωσε ο Άρης.","word_count":167,"page_number":77,"chapter":"Το κοχύλι"},{"id":"a_dimotikou_b_0037","source_id":"a_dimotikou_b","title":"Τα τζιτζίκια","content":"Η Παναγιά το πέλαγο\nκρατούσε στην ποδιά της\nτη Σίκινο, την Αμοργό\nκαι τ’ άλλα τα παιδιά της.\n\nΑπό την άκρη του καιρού\nκαι πίσω απ’ τους χειμώνες\nάκουγα σφύριζε η μπουρού\nκι έβγαιναν οι Γοργόνες.\n\nΚι εγώ μέσα στους αχινούς\nστις γούβες στ’ αρμυρίκια*\nσαν τους παλιούς θαλασσινούς\nρωτούσα τα τζιτζίκια:\n— Ε, σεις, τζιτζίκια μου άγγελοι,\nγεια σας κι η ώρα η καλή.\nΟ βασιλιάς ο ήλιος ζει;\nΚι όλ’ αποκρίνονταν μαζί:\n\n— Ζει ζει ζει ζει ζει ζει ζει ζει.","word_count":83,"page_number":78,"chapter":"Το κοχύλι"},{"id":"a_dimotikou_b_0038","source_id":"a_dimotikou_b","title":"Κοχύλι","content":"Ένα κοχύλι μου 'δωσαν.\n\nΜέσα του τραγουδά\nμια θάλασσα του χάρτη.\nΝερό η καρδιά μου γέμισε\nμε μικρά μικρά ψάρια\nαπό σκιά κι από ασήμι.\nΈνα κοχύλι μου 'δωσαν.","word_count":29,"page_number":79,"chapter":"Το κοχύλι"},{"id":"b_dimotikou_0001","source_id":"b_dimotikou","title":"Τα φύλλα","content":"Φθινόπωρο φτάνει,\nτα φύλλα όλο πέφτουν.\nΘα πάνε ταξίδι\nπολύ μακρινό.\n\nΤο ένα στη στέγη,\nτο άλλο στον κήπο,\nτο τρίτο σε κάποιο\nμικρούλι σχολειό.","word_count":25,"page_number":14,"chapter":"Ενότητα 1 — Στον δρόμο για το σχολείο"},{"id":"b_dimotikou_0002","source_id":"b_dimotikou","title":"Δε μ’ ακούς;","content":"Έρχομαι μαζί με τα κιτρινισμένα φύλλα.\nΈλα, έλα κοριτσάκι,\nμυρίζω νοτισμένο χώμα και γομολάστιχα.\nΈλα, έλα αγοράκι,\nκάτσε σ’ ένα ιπτάμενο φύλλο να φύγουμε μαζί,\nφτιάξε χάρτινες βαρκούλες να τις πάρει η βροχή.\nΣ’ αρέσει η καινούρια σου η τσάντα;\nΓια κοίτα πόσο ψήλωσε η Βάνα!\nΈρχομαι μαζί με τα πρωτοβρόχια.\nΤρέξε, τρέξε να ψήσουμε κάστανα.\nΓέμισαν πάλι τ’ ανθοπωλεία πολύχρωμα χρυσάνθεμα.\nΠώς οργώνουν τα χωράφια τα τρακτέρ!\nΠάτα, πάτα το μούστο καλά, βάλε και μπόλικο σουσάμι στη μουσταλευριά.\nΈρχομαι μαζί με τη βαριά μυρουδιά των σταφυλιών του τρύγου.\n\nΈλα, έλα αγοράκι, έλα, έλα κοριτσάκι. Δε μ’ ακούς;\nΕίμαι το Φθινόπωρο.","word_count":101,"page_number":16,"chapter":"Ενότητα 1 — Στον δρόμο για το σχολείο"},{"id":"b_dimotikou_0003","source_id":"b_dimotikou","title":"Το κυλιόμενο πεζοδρόμιο","content":"Στον πλανήτη Μπεχ ανακάλυψαν ένα πεζοδρόμιο κυλιόμενο που γυρίζει γύρω απ’ όλη την πόλη. Κινείται με μικρή ταχύτητα, για να έχει ο κόσμος τον καιρό να κοιτάζει τις βιτρίνες και για να μη χάνουν την ισορροπία τους εκείνοι που θέλουν ν’ ανέβουν ή να κατέβουν. Πάνω στο πεζοδρόμιο υπάρχουν παγκάκια για κείνους που θέλουν να ταξιδεύουν καθιστοί, ιδιαίτερα τα γεροντάκια και οι κυρίες με τις τσάντες με τα ψώνια.\nΧάρη στην ανακάλυψη αυτού του πεζοδρομίου καταργήθηκαν τα τραμ, τα τρόλεϊ και τ’ αυτοκίνητα. O δρόμος υπάρχει ακόμα, αλλά είναι άδειος και χρησιμεύει για να παίζουν τα παιδιά μπάλα, κι αν κανείς τροχονόμος κάνει να τους την πάρει, παίρνει κλήση.","word_count":109,"page_number":19,"chapter":"Ενότητα 1 — Στον δρόμο για το σχολείο"},{"id":"b_dimotikou_0004","source_id":"b_dimotikou","title":"Ο σιδηρόδρομος","content":"Τρέχα, σιδηρόδρομε,\nτρέχα νύχτα ημέρα,\nφέρτ’ τους ταξιδιώτες σου\nσ’ άλλους τόπους πέρα!\n\nΤρέχα, σιδηρόδρομε,\nφέρε με και πάλι\nστη μικρή πατρίδα μου\nτι χαρά μεγάλη!\n\nΜόνο στάσου μια στιγμή,\nπάρε με και μένα,\nτι χαρές να φεύγουμε\nσ’ άγνωρα και ξένα!","word_count":42,"page_number":21,"chapter":"Ενότητα 1 — Στον δρόμο για το σχολείο"},{"id":"b_dimotikou_0005","source_id":"b_dimotikou","title":"Η Σερενάτα για το Κανταδοχώρι","content":"H Σερενάτα έχει ένα κρυφό όνειρο. Πώς θα ήθελε να γίνει ένα μουσικό σχολείο και στο δικό της χωριό! Να, κάτι σαν ωδείο!\nΔε δίστασε, λοιπόν, να χτυπήσει πρωί πρωί την πόρτα του δημαρχείου.\n— Καλημέρα σας, κύριε Προεδράκη, είπε με όλη της την ευγένεια η Σερενάτα.\n— Ποιος καλός άνεμος σε φέρνει τόσο νωρίς στο γραφείο μου;\n— Η αγάπη μου για τη μουσική. Βρήκα το θάρρος και ήρθα σε σας, γιατί όλη νύχτα δεν έκλεισα μάτι.\n— Σοβαρέψου Σερενάτα! Τι προσπαθείς να μου πεις;\n— Όπως σας είπα, όλη τη νύχτα συλλογιζόμουνα… Πώς είναι δυνατόν ένα χωριό σαν το δικό μας, με τέτοια ιστορία, να έχει ξεχάσει τη μουσική; Μήπως ήρθε η στιγμή να της χαρίσουμε ένα σπίτι;\n— Μουσική; Ιστορία; Σπίτι; Τι είναι όλα αυτά που μου αραδιάζεις! Εδώ εγώ καίγομαι στη δουλειά και εσύ μου μιλάς για άλλες εποχές… για περασμένα μεγαλεία. Σαν τότε που παίρναμε το μαντολίνο και κάναμε καντάδες… αχ… άλλες εποχές!\n— Ώστε για σας η μουσική είναι περασμένο μεγαλείο…\nη μουσική που ομορφαίνει τη ζωή μας, εκείνη που κάποτε χάριζε το γέλιο στα πρόσωπά μας… για σας είναι ένα τίποτα!","word_count":188,"page_number":23,"chapter":"Ενότητα 2 — Με το «σεις» και με το «σας»"},{"id":"b_dimotikou_0006","source_id":"b_dimotikou","title":"Πρωινό άστρο","content":"Κοριτσάκι μου,\nθέλω να σου φέρω\nτα φαναράκια των κρίνων\nνα σου φέγγουν τον ύπνο σου…\n…Κοιμήσου κοριτσάκι.\nΕίναι μακρύς ο δρόμος.\nΠρέπει να μεγαλώσεις.\nΕίναι μακρύς, μακρύς,\nμακρύς ο δρόμος…","word_count":31,"page_number":26,"chapter":"Ενότητα 2 — Με το «σεις» και με το «σας»"},{"id":"b_dimotikou_0007","source_id":"b_dimotikou","title":"O παπαγάλος","content":"Σαν έμαθε τη λέξη κ α λ η σ π έ ρ α\nο παπαγάλος, είπε ξαφνικά:\n«Είμαι σοφός, γνωρίζω ελληνικά.\nΤι κάθομαι εδώ πέρα;»","word_count":25,"page_number":27,"chapter":"Ενότητα 2 — Με το «σεις» και με το «σας»"},{"id":"b_dimotikou_0008","source_id":"b_dimotikou","title":"O αστροναύτης","content":"Θα γίνω αστροναύτης\nσε πύραυλο θα μπω\nταξίδι στο φεγγάρι\nθα κάνω αληθινό.\n\nΚαι στο φεγγάρι πάνω\nθα δεις να περπατώ\nτριγύρω απ’ τους κρατήρες\nθα τρέχω να κρυφτώ.\n\nΜπορεί κι εκεί να βρω παιδιά\nμπορεί κι αυτό να γίνει\nκαι όλοι να χορέψουμε\nκει πάνω στη Σελήνη.","word_count":48,"page_number":33,"chapter":"Ενότητα 3 — Στον κόσμο των κόμικς"},{"id":"b_dimotikou_0009","source_id":"b_dimotikou","title":"Το σαλιγκάρι","content":"Το μικρό το σαλιγκάρι\nκάθισε κοντά στο τζάκι\nμε μπουφάν με ένα τσεπάκι.\nΚοίταζε και το φεγγάρι\nκι όπως έπαιζε το ντέφι\nτο ’πιασε μεγάλο κέφι!","word_count":26,"page_number":34,"chapter":"Ενότητα 3 — Στον κόσμο των κόμικς"},{"id":"b_dimotikou_0010","source_id":"b_dimotikou","title":"Ο Αρμπέν χάνει το δόντι του","content":"Οι τέσσερις φίλοι είναι μαζεμένοι και συζητούν. Ξαφνικά...\n— Αρμπέν, τι έπαθες; Πού είναι το μπροστινό σου δόντι;\n— Καλά, τώρα το βλέπεις, Γαλήνη; Το δόντι μου βγήκε χτες, καθώς έτρωγα κάστανα!\n— Και τι το έκανες;\n— Το πήρε η γιαγιά μου, το πέταξε σε μια ταράτσα και είπε: «Πάρτε το παλιό και φέρτε ένα καινούριο». Μου είπε πως έτσι κάνουν στην\nΑλβανία. Εσύ τι έκανες, όταν βγήκε το δόντι σου;\n— Η μαμά μου το πέταξε στα κεραμίδια του διπλανού σπιτιού και είπε:\n«Πάρε, ποντικέ, το δόντι μου και φέρε το σιδερένιο, να ροκανίζω σίδερα, να τρώω παξιμάδια».","word_count":100,"page_number":34,"chapter":"Ενότητα 3 — Στον κόσμο των κόμικς"},{"id":"b_dimotikou_0011","source_id":"b_dimotikou","title":"O φτεροπόδαρος","content":"Λέει στον Γιάννη η μαμά του,\nμέρα που είναι στα καλά του:\n— Τρέχα, Γιάννη, στον μπακάλη,\nφέρε αλεύρι, σιμιγδάλι,\nφέρε αυγά, καφέ, κανέλα,\nζάχαρη, σησάμι… τρέλα,\nνα σου φτιάξω κουλουράκια,\nπου να γλείφεις τα χεράκια!\n\n— Έφυγα! λέει ο Γιάννης!\nΠού τον βλέπεις, πού τον φτάνεις!\n— Κυρ μπακάλη, θέλω αλάτι!\nΌχι! Στάσου… θέλω ρύζι!\nΠοπό Θεέ μου, το μυαλό μου\nτι έπαθε κι όλο γυρίζει!\nΆσε, κυρ μπακάλη, άσε!\nΒάσανο είναι να θυμάσαι!\n\nΣαν τρελούτσικο πουλάρι\nτρέχει ο Γιάννης πίσω πάλι.\n— Μάνα, μ’ έστειλε ο μπακάλης,\nσε μια λίστα να τα βάλεις…\nΔεν πουλάει πια σε κανένα,\nαν δεν τα έχει όλα γραμμένα!\nΧαμογέλασε η μαμά του,\nμα έκαμε το θέλημά του!\nΚι ο Γιαννάκης τρέχει πάλι\nπηδηχτός για τον μπακάλη!\n\nΠάει, μα… πάλι πίσω γυρίζει,\nάνεμος, λες, που σφυρίζει!\nΣίφουνας, στο σπίτι μπαίνει…\n— Αχ, μανούλα μου καημένη,\nξέχασα λεφτά να πιάσω,\nέννοια σου όμως, θα προφτάσω!\n\n«Όποιος μυαλό δεν έχει\nέχει πόδια, για να τρέχει!»","word_count":160,"page_number":38,"chapter":"Ενότητα 4 — Ετοιμασίες για το ταξίδι"},{"id":"b_dimotikou_0012","source_id":"b_dimotikou","title":"Η διαφήμιση","content":"Καλέ τι μας λες εκεί!\nΔεν είμ’ άδειο εγώ σακί,\nνα μου βάζουν στο κεφάλι\nό,τι κι όσα θέλουν άλλοι.\n\nΤι θα φάω, τι θα πιω,\nμε τι ρούχα θα ντυθώ,\nποιο παιχνίδι θ’ αποχτήσω\nκαι ποια τσίχλα θα μασήσω.\n\nΌλη μέρα ολόγυρά μου,\nδιαφήμιση κυρά μου,\nπροσπαθείς με κάθε τρόπο\nστην καρδιά μου να βρεις τόπο.\n\nΚι όλο πιότερο γλυκαίνεις\nκι όλο πιο πολύ ομορφαίνεις,\nαλλά… μην πανηγυρίζεις,\nγιατί δε με ξεμυαλίζεις.","word_count":73,"page_number":45,"chapter":"Ενότητα 5 — Πάμε για ψώνια;"},{"id":"b_dimotikou_0013","source_id":"b_dimotikou","title":"Η κυρα-Καλή και οι δώδεκα μήνες","content":"Μια φορά κι έναν καιρό ζούσαν σ’ ένα χωριό δυο κυρούλες. Τη μια την έλεγαν Καλή, γιατί ήταν ευγενική και καλόψυχη και είχε για όλους καλά λόγια. Την άλλη την έλεγαν Κακή, γιατί δεν έλεγε ποτέ τον καλό τον λόγο.\nΜια μέρα η Καλή πήγε στο βουνό να μαζέψει ξύλα. Παρουσιάζονται τότε μπροστά της δώδεκα παλικάρια. Ήταν οι δώδεκα μήνες του χρόνου.\n— Γεια σου, γιαγιά, της λένε.\n— Γεια σας και σε σας, απαντά η κυρα-Καλή.\n— Δε μας λες, γιαγιά, τι γνώμη έχεις για τους δώδεκα μήνες του χρόνου; Ποιον αγαπάς περισσότερο;\n— Τι πράγματα είναι αυτά που με ρωτάτε, παιδιά μου; Όλοι έχουν τη χάρη τους! O Γενάρης με τα χιόνια, ο Φλεβάρης με το καρναβάλι, ο Μάρτης που ξαναγεννιέται η φύση, ο Απρίλης με το Πάσχα, ο Μάης με τις παπαρούνες, ο Ιούνης κι ο Ιούλης με τα μπάνια στη θάλασσα, ο Αύγουστος με τον θέρο, ο Σεπτέμβρης με τον τρύγο, ο Oκτώβρης με τα κάστανα και τα όμορφα χρυσάνθεμα, ο Νοέμβρης με τις ευεργετικές βροχές του κι ο Δεκέμβρης με τα Χριστούγεννα. Τους αγαπώ όλους ίσα.\nOι μήνες ευχαριστήθηκαν πολύ από τα λόγια της και της έδωσαν ένα τσουβαλάκι. Όταν πήγε η γριούλα στο σπίτι της, το άνοιξε και ήταν γεμάτο φλουριά.","word_count":207,"page_number":47,"chapter":"Ενότητα 5 — Πάμε για ψώνια;"},{"id":"b_dimotikou_0014","source_id":"b_dimotikou","title":"Οι μέρες της εβδομάδας","content":"Σήμερα Δευτέρα\nας πούμε καλημέρα\n\nαύριο είναι Τρίτη\nθα ψάξω μες στο σπίτι\n\nνα βρω κανένα χάρτη\nτον μελετώ Τετάρτη\n\nΠέμπτη θ’ αποφασίσω\nκαι θα προγραμματίσω\n\nΠαρασκευή στο δρόμο\nκι ο σάκος μου στον ώμο\n\nΣάββατο πια δικός μου\nγη κι ουρανός του κόσμου\n\nτην Κυριακή πίσω ξανά\nσβούρα ο καιρός κύκλους γυρνά\n\nκαι πάλι τη Δευτέρα\nθα πούμε καλημέρα\n\nκαινούρια εβδομάδα\nπιο φρέσκια η λιακάδα\n\nόμως και με συννεφιά\nέξω η κακοκεφιά.","word_count":73,"page_number":49,"chapter":"Ενότητα 5 — Πάμε για ψώνια;"},{"id":"b_dimotikou_0015","source_id":"b_dimotikou","title":"Σαν παραμύθι","content":"Μια φορά κι έναν καιρό ήταν ένας γίγαντας, ένας μεγάλος γίγαντας, τόσο μεγάλος όσο σαράντα εκατομμύρια άνθρωποι μαζί. Τον ίδιο καιρό κάπου κοντά στον γίγαντα ήταν κι ένας νάνος. Ένας μικρός νάνος. Νάνος και γίγαντας ζούσαν ο καθένας στον τόπο του χωρίς να ενοχλεί ο ένας τον άλλο. Τους χώριζε άλλωστε ένα τεράστιο αυλάκι, μια θάλασσα.\nΚαι ήταν ευτυχισμένοι… Και περνούσε ο καιρός. O νάνος κοίταγε τη δουλειά του, ο γίγαντας τη δικιά του, και ζούσαν αγαπημένοι…\nΈνα πρωί όμως ο μεγάλος γίγαντας φόρεσε ένα περίεργο καπέλο και μια ακόμη πιο περίεργη στολή. Φόρεσε και κάτι μεγάλες μπότες και μετά έκανε ένα μεγάλο πήδημα, έφτασε μπροστά στην πόρτα του μικρού νάνου και, βάνοντάς του μια λόγχη μπροστά στην κοιλιά του, είπε: «Ήρθα να σου πάρω το σπίτι· παραδώσου!».\nO μικρός νάνος στην αρχή το πέρασε για χωρατό.\n«Κοίτα χωρατατζής που ’ναι ο μεγάλος γίγαντας!» σκέφτηκε. Και φέρνοντας στον νου τον γνωστό τους χαιρετισμό, του φώναξε:\n— Γεια σου, γείτονα!\nO γίγαντας όμως δεν καταλάβαινε πια από τέτοια.\nΠίεσε τη λόγχη πάνω στην κοιλιά του μικρού νάνου και άγρια ξαναφώναξε:\n— Παραδώσου!\nΟ μικρός νάνος τότε κατάλαβε. κοίταξε λυπημένος κατάματα τον μεγάλο γίγαντα και χωρίς κανένα φόβο τού είπε:\n— Όχι, δεν παραδίνομαι!\nΑμέσως μετά έτρεξε, έφτασε στο μικρό καλύβι του και σε λίγο ξαναγύρισε κρατώντας στα χέρια του μια σφεντόνα. Στάθηκε μπροστά στον γίγαντα και περίμενε.\nΟ μεγάλος γίγαντας τα ’χασε για λίγο. Ύστερα χύθηκε πάνω στον μικρό νάνο θέλοντας να τον συντρίψει. Έγινε όμως κάτι απίστευτο. Ο μικρός νάνος νίκησε τον μεγάλο γίγαντα! Ο μεγάλος γίγαντας το ’βαλε στα πόδια...\nΈτσι οι Έλληνες του Σαράντα, όπως ο μικρός νάνος του παραμυθιού, όταν η Ιταλία ζήτησε να της παραδώσουν τη χώρα τους, απάντησαν όπως και κείνος, μ’ ένα θαρραλέο και αποφασιστικό ΟΧΙ!\nΔεν είναι όμως μόνο πως είπαν το ΟΧΙ. Το διαφέντεψαν στη συνέχεια παλικαρίσια και νικηφόρα πάνω στις βουνοκορφές.","word_count":310,"page_number":61,"chapter":"Ενότητα 7 — Πώς λέμε ΟΧΙ ;"},{"id":"b_dimotikou_0016","source_id":"b_dimotikou","title":"Tο ερωτηματικό","content":"Mια φορά κι έναν καιρό,\nήταν το ερωτηματικό,\nπου συνέχεια ρωτούσε\nκι όλους μας μας ενοχλούσε.\n\nEίχε μια μικρή ουρίτσα\nαπό κάτω απ’ την τελίτσα,\nσαν μαστίγιο την κουνούσε\nαν κανείς δεν απαντούσε.","word_count":33,"page_number":66,"chapter":"Ενότητα 7 — Πώς λέμε ΟΧΙ ;"},{"id":"b_dimotikou_0017","source_id":"b_dimotikou","title":"Oι νότες","content":"Σήμερα στη μουσική τη νότα κάνουμε του μι αλλά σαν γνωστή μού μοιάζει.\nΌλο «μη» η μαμά φωνάζει.\nΜην κλοτσάς στο σπίτι μπάλα και μη βιάζεσαι στη σκάλα.\nΜην ξεχνάς δόντια να πλύνεις.\nΣτο μωρό γλυκά μη δίνεις.\nΦαίνεται στη μουσική, όταν ήτανε μικρή, πως δεν πρόσεχε πολύ και θυμάται τώρα αυτή μία νότα. Αυτή του μι...","word_count":57,"page_number":67,"chapter":"Ενότητα 7 — Πώς λέμε ΟΧΙ ;"},{"id":"b_dimotikou_0018","source_id":"b_dimotikou","title":"Ο ψεύτης βοσκός","content":"Ζούσε κάποτε ένας βοσκός. Κάθε πρωί πήγαινε τα πρόβατά του να βοσκήσουν. Μια μέρα αποφάσισε να κάνει ένα αστείο, για να διασκεδάσει. Ανέβηκε σ’ ένα ύψωμα και άρχισε να φωνάζει: «Λύκος! Λύκος! Τρέξτε!». Οι χωριανοί τον άκουσαν κι έτρεξαν να βοηθήσουν. Δεν είδαν όμως τον λύκο. Είδαν μόνο τον βοσκό να γελά κι έφυγαν θυμωμένοι.\nΔεν πέρασε πολύς καιρός και πλησίασε στ’ αλήθεια λύκος το κοπάδι. «Λύκος! Λύκος! Τρέξτε!» φώναζε τρομαγμένος ο βοσκός. Αλλά αυτή τη φορά οι χωριανοί δεν έδωσαν σημασία. Κανείς δεν τον πίστεψε και κανείς δεν έτρεξε να τον βοηθήσει. Έτσι, ο λύκος έφαγε τα πρόβατα του ψεύτη βοσκού.","word_count":102,"page_number":68,"chapter":"Ενότητα 7 — Πώς λέμε ΟΧΙ ;"},{"id":"b_dimotikou_0019","source_id":"b_dimotikou","title":"Aν όλα τα παιδιά της Γης","content":"Αν όλα τα παιδιά της Γης\nπιάναν γερά τα χέρια,\nκορίτσια αγόρια στη σειρά\nκαι στήνανε χορό,\nο κύκλος θα γινότανε\nπολύ πολύ μεγάλος\nκι ολόκληρη τη Γη μας\nθ’ αγκάλιαζε θαρρώ.\n\nΘα ’ρχόνταν τότε τα πουλιά,\nθα ’ρχόνταν τα λουλούδια\nθα ’ρχότανε κι η άνοιξη\nνα μπει μες στον χορό,\nκι ο κύκλος θα γινότανε\nακόμα πιο μεγάλος\nκαι τρεις φορές τη Γη μας\nθ’ αγκάλιαζε θαρρώ!","word_count":68,"page_number":78,"chapter":"Ενότητα 8 — Το ταξίδι στη Χωχαρούπα"},{"id":"b_dimotikou_b_0001","source_id":"b_dimotikou_b","title":"Ιστορία για το τσίρκο","content":"Ώρα οχτώ ακριβώς. Στο τσίρκο ανάβουν όλα τα φώτα. O κόσμος παίρνει τη θέση του. Μια μυρωδιά άχυρου ανεβαίνει από την πίστα και μπλέκεται μ’ ένα άρωμα από ξεφλουδισμένα πορτοκάλια. Τα παιδιά καθισμένα μιλάνε και ξετυλίγουν καραμέλες. O κόσμος συγκεντρώνεται όλο και περισσότερο. Ανεβοκατεβαίνει με θόρυβο τα ξύλινα σκαλοπάτια. Oι ταξιθέτριες πουλάνε προγράμματα. Oι μουσικοί δοκιμάζουν τα μπρούντζινα όργανά τους. Τα παιδιά τριγύρω διαβάζουν δυνατά τις φωτεινές επιγραφές: «ΑΠΑΓOΡΕΥΕΤΑΙ ΤO ΚΑΠΝΙΣΜΑ» ή «ΕΞOΔOΣ ΚΙΝΔΥΝOΥ». Κι όλο ρωτάνε τους δικούς τους πότε θ’ αρχίσει.\nΞαφνικά, τα φώτα χαμηλώνουν και η μουσική αρχίζει να παίζει, ενώ στην πίστα μπαίνει ο παρουσιαστής:\n— Κυρίες και κύριοι…","word_count":103,"page_number":18,"chapter":"Ενότητα 10 — ΠΡΟΣΟΧΗ! Τι λέει εκεί;"},{"id":"b_dimotikou_b_0002","source_id":"b_dimotikou_b","title":"H επανάσταση των παραμυθιών","content":"Ένα όμορφο φθινοπωριάτικο πρωί, μια παραμυθένια συντροφιά πέρασε τις χορταριασμένες πύλες της παραμυθοχώρας και πήρε την άσφαλτο για την πόλη των ανθρώπων.\nΜπροστά μπροστά πήγαινε ο Παπουτσωμένος Γάτος, πίσω η Σταχτοπούτα, που κρατούσε ένα μεγάλο φάκελο με μικρές αγγελίες «ΕΝOΙΚΙΑΖΕΤΑΙ», ξοπίσω της ο γενναίος Ραφτάκος, που κρατούσε ένα μεγάλο φάκελο «ΕΥΚΑΙΡΙΕΣ» για φορτηγάκια, ύστερα η Κοκκινοσκουφίτσα και τελευταίος ο Κοντορεβιθούλης, που άφηνε πίσω τους ψεύτικα σήματα της τροχαίας, για να μην μπορεί κανείς να τους ακολουθήσει.\nΚι όταν έφτασε η μαγική ώρα των μεταμορφώσεων κι η κολοκύθα έγινε πάλι χρυσή καρότσα, όλοι πήδησαν μέσα, απέραντα ευτυχισμένοι.","word_count":96,"page_number":21,"chapter":"Ενότητα 10 — ΠΡΟΣΟΧΗ! Τι λέει εκεί;"},{"id":"b_dimotikou_b_0003","source_id":"b_dimotikou_b","title":"Πέντε ποντικοί","content":"Στο σκοτάδι μαστορεύουν πέντε ποντικοί.\nΤι σκεπάρνια! Τι πριόνια! Τι μαστορική!\nΣε ντουλάπι νοικοκύρη βάλθηκαν να μπουν.\nΚρατς ο ένας, κριτς ο άλλος κόβουν και τρυπούν.\nΕίναι νύχτα και στον ύπνο το ’ριξαν βαριά.\nΕτεμπέλιασε ο γάτος δίπλα στη φωτιά.\nΜόνο η φάκα στο ντουλάπι κάθεται ξυπνή\nκι αφουγκράζεται τον κλέφτη, κι ώρες αγρυπνεί.","word_count":54,"page_number":23,"chapter":"Ενότητα 10 — ΠΡΟΣΟΧΗ! Τι λέει εκεί;"},{"id":"b_dimotikou_b_0004","source_id":"b_dimotikou_b","title":"Η τελευταία επίσκεψη του Αϊ-Βασίλη","content":"Όταν ο αδελφός μου κι εγώ ήμασταν μικρά παιδιά, κάθε παραμονή της Πρωτοχρονιάς μάς επισκεπτόταν ο Αϊ-Βασίλης. Ναι, δε σας λέω ψέματα. Ερχόταν ο ίδιος με την κατακόκκινη στολή του, τις γυαλιστερές του μπότες και τ’ άσπρα γένια και μουστάκια του που γέμιζαν το καλοκάγαθο πρόσωπό του. Είχε και μια μεγάλη σακούλα κρεμασμένη πίσω στον ώμο του και, αφού έσκυβε στα κρεβάτια μας και μας χάιδευε, άφηνε τα δώρα μας δίπλα στο προσκέφαλό μας.","word_count":74,"page_number":41,"chapter":"Ενότητα 12 — Ποπό! Κόσμος που περνά!"},{"id":"b_dimotikou_b_0005","source_id":"b_dimotikou_b","title":"Το αστέρι των Χριστουγέννων","content":"Μια φορά κι έναν καιρό ζούσε στον ουρανό ένα αστεράκι. Βαριόταν όμως να κάνει κάθε βράδυ τα ίδια και τα ίδια. Μια μέρα λοιπόν, που ο ήλιος έλαμπε και κανένας δεν μπορούσε να το δει, το αστεράκι το ’σκασε από το σπίτι του.\nΣτριφογύρισε, στριφογύρισε και κάποτε έφτασε πάνω απ’ τη Γη.\nΑυτό που δεν ήξερε το αστεράκι ήταν ότι τώρα το έβλεπαν κι οι άνθρωποι από τη Γη.\n— Ανακαλύψαμε, είπαν, ένα νέο αστέρι. Και του έδωσαν κι ένα όνομα. Το ονόμασαν Βιγαδεζή.\nΤο αστεράκι όμως γρήγορα βαρέθηκε να βλέπει μόνο δέντρα, τα οργωμένα χωράφια, τα πλοία και τους ελέφαντες στην Ινδία. Πλησίασε, λοιπόν, λίγο περισσότερο.\nΤώρα έβλεπε και τους ανθρώπους. Oι άνθρωποι γεμάτοι θαυμασμό έβλεπαν αυτό το υπέρλαμπρο άστρο.\n— Δεν μπορεί, έλεγαν, κάτι θα συμβεί στον κόσμο. Κάτι πολύ καλό. Αλλιώς, γιατί να φανεί αυτό το αστέρι.\nΣτο αστέρι άρεσαν πολύ οι παράξενοι άνθρωποι.\nΠαρατηρούσε, λοιπόν, εδώ και λίγες μέρες τρεις ανθρώπους που περπατούσαν στην έρημο. Περπατούσαν και περπατούσαν. Κάτι κρατούσαν στα χέρια τους και προχωρούσαν κοιτάζοντας κάπου κάπου τον ουρανό.\nΜια νύχτα, το αστεράκι είδε άλλους δύο παράξενους ανθρώπους. Έναν άντρα και μια γυναίκα. Κι ένα γαϊδουράκι. Φαινόντουσαν κουρασμένοι και πήγαιναν πολύ αργά.\nΤο αστεράκι πλησίασε λίγο περισσότερο. Η λάμψη του μεγάλωσε. Το αστεράκι είδε τη γυναίκα να κατεβαίνει από το γαϊδουράκι. Κρατούσε την κοιλιά της που ήταν μεγάλη και στρογγυλή. Άραγε αυτή η γυναίκα θα γεννούσε εκεί στην ερημιά μόνη της; Το αστεράκι ανήσυχο πλησίασε ακόμη περισσότερο.\nΗ γυναίκα μπήκε σε μια σπηλιά της ερήμου. O άντρας στάθηκε απέξω. Όταν ακούστηκε το πρώτο κλάμα του μωρού, το αστεράκι ένιωσε την καρδιά του να σπαρταράει από χαρά. Αχ, πόσο ήθελε να δει αυτό το μωράκι. Πλησίασε ακόμη λίγο. Όλη η έρημος γύρω φωτίστηκε σαν να ’ταν μέρα.\nΕίδε μέσα στη σπηλιά τους τρεις γέροντες γονατιστούς μπροστά σε μια φάτνη, να προσφέρουν στο μωράκι σμύρνα, χρυσό και λιβάνι.\nΈνα φως ξεχυνόταν γύρω από τη φάτνη και φώτιζε το ήρεμο πρόσωπο της μητέρας του μωρού. Το αστεράκι πρόλαβε να δει τα μάτια του μωρού που το κοίταζαν γλυκά. Τίποτε άλλο…\nΈπειτα έσβησε σαν κεράκι και χάθηκε απ’ τον ουρανό.","word_count":351,"page_number":43,"chapter":"Ενότητα 12 — Ποπό! Κόσμος που περνά!"},{"id":"b_dimotikou_b_0006","source_id":"b_dimotikou_b","title":"Ο δικός μας Αϊ-Βασίλης","content":"Καλή του ώρα του Αϊ-Βασίλη με την κόκκινη φόρμα και την ολόλευκη γούνα, δε λέω… Μα, αυτός, μάτια μου, τι σχέση έχει με τον δικό μας τον Αϊ-Βασίλη τον σοφό, τον δάσκαλο; Το λένε και τα κάλαντα: «Βαστάει πένα και χαρτί, χαρτί και καλαμάρι, και στο ραβδί του ακούμπησε να πει τ’ αλφαβητάρι». Στα κάλαντα της Μυκόνου τον λένε… γραμματικό! «Κι αν είσαι και γραμματικός, πες μας την αλφαβήτα».\nΚαι βέβαια ήτανε γραμματικός και πολύ σπουδαγμένος. Ένας από τους Τρεις Ιεράρχες. Κι έγραψε πάμπολλα συγγράμματα και έδωσε συμβουλές, πώς να διαβάζουν τα παιδιά, πόση αξία έχει το διάβασμα.\nΤα έλεγα όλα αυτά με λόγια απλά στην εγγονή μου, όταν ξαφνικά μπήκε ο παππούς και είπε: «Από το πολύ νέφος δε φαίνεται η Αθήνα!».\nΚι η εγγονή μου, που περιμένει τα δώρα της από τον καλό μας γραμματικό και δάσκαλο, ρώτησε με αγωνία: «Γιαγιάκα μου, λες να μην τη βρει την Αθήνα ο Αϊ-Βασίλης με τόσο πολύ νέφος;».","word_count":157,"page_number":46,"chapter":"Ενότητα 12 — Ποπό! Κόσμος που περνά!"},{"id":"b_dimotikou_b_0007","source_id":"b_dimotikou_b","title":"Η νεροσφυρίχτρα","content":"Ένα από τα πιο αγαπημένα παιχνίδια των παιδιών στα παλιότερα χρόνια ήταν η νεροσφυρίχτρα. Είναι ένα είδος σφυρίχτρας που έχει σχεδόν σφαιρικό σχήμα, χαμηλό ποδαράκι, λαιμό και στόμιο πολύ ανοιχτό. Η συγκεκριμένη, μάλιστα, είναι ζωγραφισμένη με λουλούδια. Πλάγια και στο ύψος του χερουλιού ξεκινά ένα μικρό πήλινο σωληνάκι από όπου κανείς σφυρίζει.\nΌταν η νεροσφυρίχτρα είναι άδεια και κάποιος φυσήξει από το σωληνάκι, ακούγεται ένα συνεχές σφύριγμα. Όταν όμως είναι γεμάτη νερό, οι φυσαλίδες του αέρα που περνούν από το νερό αναδίδουν ένα είδος γαργαρίσματος που μοιάζει με κελάηδημα πουλιού. Τότε λένε ότι «η λαλίτσα γουργουρίζει».","word_count":96,"page_number":51,"chapter":"Ενότητα 13 — Μες στο μουσείο"},{"id":"b_dimotikou_b_0008","source_id":"b_dimotikou_b","title":"Ήλιος","content":"Βγήκες, ήλιε, κι έλαμψες\nκι έλαμψε η πλάση,\nουρανοί και θάλασσες\nκαι βουνά και δάση.\n\nΉλιος το καθάριο φως\nλάμπει στην καρδιά μου\nκαι η λύπη και το ψέμα\nφεύγουνε μακριά μου.","word_count":32,"page_number":56,"chapter":"Ενότητα 13 — Μες στο μουσείο"},{"id":"b_dimotikou_b_0009","source_id":"b_dimotikou_b","title":"Το μυστικό τραγούδι της Μάτας","content":"Έτριψε βιαστικά τα δόντια της με την οδοντόβουρτσα κι έτρεξε στο\nκρεβάτι της. Σ’ ένα λεπτό μπήκε κι ο μπαμπάς.\n— Καληνύχτα κοριτσάκι, είπε, και... φυσικά να τα εκατοστίσεις.\n«Καληνύχτα» έγνεψε η Μάτα και κρυφογέλασε. Όλο «φυσικά» και\n«φυσικά» έλεγε ο μπαμπάς: φυσικομπαμπάς σκέτος.\nΑμέσως μετά, «τσακ τσακ» τα τακουνάκια της μαμάς.\n— Καληνύχτα, Μάτα μου, να τα εκατοστίσεις, χιλιόχρονη, είπε.\n«Καληνύχτα, μαμά» έγνεψε η Μάτα κι έκλεισε τα μάτια της.\nΜόλις έκλεισε πίσω της η πόρτα, η Μάτα πετάχτηκε σαν ελατήριο.\nΈτρεξε και κλείδωσε και βιαστικά τράβηξε στο κρεβάτι της όλα της τα\nδώρα: πακέτα με παπούτσια και κούκλες, σακούλες με μπουφάν και χρυσές\nκορδελίτσες, καινούριο σκουφί και κασκόλ... και φυσικά, τα απαραίτητα\nβιβλία της νονάς. Αχ! Αυτή η νονά! Κοντεύει να της γεμίσει τα ράφια.\nΌμορφα που ήταν απόψε, κι η τούρτα τεράστια, ολόασπρη σαν\nχιονισμένο βουνό γεμάτη σαντιγί και ανανάδες και πάνω να γράφει: «Να τα\nεκατοστίσεις», και εννέα κεράκια που τα έσβησε μεμιάς! Κι όλοι\nτραγούδησαν το τραγούδι, κι όταν τελείωσαν η Μάτα έγνεψε σε όλους\n«ευχαριστώ».","word_count":171,"page_number":64,"chapter":"Ενότητα 14 — Με προσκαλούν και προσκαλώ"},{"id":"b_dimotikou_b_0010","source_id":"b_dimotikou_b","title":"Tα γενέθλια της Χαράς","content":"Η Χαρά στα γενέθλιά της κάλεσε όλη την τάξη της, δηλαδή είκοσι πέντε συμμαθητές και συμμαθήτριές της. Τελικά από την τάξη της ήρθαν δεκαέξι παιδιά, εφτά αγόρια και εννιά κορίτσια. Ήρθαν όμως ακόμη τέσσερα παιδιά από τη γειτονιά της και τρία ξαδελφάκια της.\nΣτις 5.30 όλοι ήταν εκεί. O καιρός ήταν καλός και το πάρτι έγινε στην αυλή. Έπαιξαν έντεκα φορές κρυφτό, πέντε φορές «μήλα» και έξι φορές κυνηγητό.\nΓύρω στις 6.45 κουράστηκαν πια να τρέχουν και κάθισαν να φάνε. Έφαγαν στην αρχή σαράντα τέσσερα κεφτεδάκια και δύο σακούλες πατατάκια. Έπειτα δοκίμασαν τα είκοσι δύο γλυκά που είχε ετοιμάσει η μαμά της Χαράς.\nΚατά τις 7.15 έφεραν μία τεράστια τούρτα. Είχε πάνω οχτώ κεράκια, τέσσερις ζαχαρωτούς πιγκουίνους και ένα γατάκι.\nΗ Χαρά χρειάστηκε να φυσήξει τρεις φορές, για να σβήσει όλα τα κεράκια. Όταν η ώρα πήγε 8.00, οι γονείς των παιδιών άρχισαν να έρχονται σιγά σιγά. Στις 9.20 όλοι είχαν φύγει.","word_count":152,"page_number":65,"chapter":"Ενότητα 14 — Με προσκαλούν και προσκαλώ"},{"id":"b_dimotikou_b_0011","source_id":"b_dimotikou_b","title":"Το παιδί με το ακορντεόν","content":"Ευτυχώς για όλους, ο δάσκαλος δεν άργησε να έρθει. Η καρδιά του Σέργιου χτυπούσε δυνατά.\n— Συγχαρητήρια, παιδί μου, κέρδισες την υποτροφία του ωδείου μας. Θα χαρώ να σ’ έχω μαθητή! είπε ο δάσκαλος φανερά συγκινημένος.\nO ενθουσιασμός των τριών παιδιών ήταν απερίγραπτος. O μπαμπάς και η μαμά του Σέργιου δάκρυσαν από χαρά. Όσο για τον Σέργιο, ένιωθε σαν να πετάει στα σύννεφα!\nΤο παιδί με το ακορντεόν άρχισε να παίζει το τραγούδι τους, «Το τραγούδι της φιλίας», και μαζί του τραγουδούσαν οι φίλοι του, οι γονείς του, ο δάσκαλός του κι όλοι όσοι βρίσκονταν εκεί.\nO Σέργιος με τη βοήθεια της Ελπίδας και του Άγγελου κέρδισε μια υποτροφία στη μουσική. Όμως το πιο σπουδαίο ήταν ότι όλοι μαζί κέρδισαν το βραβείο της φιλίας.","word_count":124,"page_number":77,"chapter":"Ενότητα 16 — Νιώθω"},{"id":"b_dimotikou_b_0012","source_id":"b_dimotikou_b","title":"Ένα δέντρο ταξιδεύει","content":"H δροσοσταλίδα που κρεμάστηκε σε μια βελόνα του μικρού πεύκου,\nγια να κοιμηθεί, άκουσε το δεντράκι να κλαίει.\n— Τι έχεις δεντράκι; το ρώτησε τρυφερά.\n— Είδα απόψε στο όνειρό μου πως ταξίδευα. Ξύπνησα και βλέπω πως δεν\nέχω κάνει ούτε ένα βήμα από τη θέση μου, έκλαψε πιο δυνατά\nτο δεντράκι.\n— Τι έχει, αδελφούλα μου, το δεντράκι; ρώτησε μια δεύτερη δροσοσταλίδα, που κρεμόταν λίγο πιο πέρα.\n— Το δεντράκι θέλει να ταξιδέψει, εξήγησε η πρώτη.\n— Μακρινό ταξίδι;\n— Δεν ξέρω, θα το ρωτήσω.\nΈσκυψε η δροσοσταλίδα στο δακρυσμένο δεντράκι.\n— Θέλεις να πας μακριά;\n— Ναι, πολύ μακριά. Θέλω να πάω στην άκρη της γης!\n— Πού είναι η άκρη της γης, φίλε;\n— Να, μακριά στο αντικρινό βουνό.","word_count":122,"page_number":79,"chapter":"Ενότητα 16 — Νιώθω"},{"id":"b_dimotikou_b_0013","source_id":"b_dimotikou_b","title":"Mαζί είναι καλύτερα","content":"O Λουκάς, ο Αρμπέν και η\nΧαρά πηγαίνουν στην εξοχή,\nγια να πετάξουν χαρταετούς.\nΚαθένας προσπαθεί να στείλει\nτον δικό του πιο ψηλά από τους\nάλλους.\nΤεντώνονται, τρέχουν, λαχανιάζουν, αμολούν την καλούμπα, μα δεν\nτα καταφέρνουν. Oι χαρταετοί τους χορεύουν σαν μπαλαρίνες. Όμως\nαντί να πάνε προς τα πάνω, κάνουν τρελές τούμπες και προσγειώνονται\nστο έδαφος. Κοντεύουν να σχιστούν. Αν συνεχίσουν έτσι, σε λίγο δε θα\nμπορούν να ξαναπετάξουν. Τα παιδιά νιώθουν απογοήτευση.\n— Παιδιά, ας προσπαθήσουμε όλοι μαζί με έναν χαρταετό! προτείνει η\nΧαρά.\nΗ ιδέα τούς αρέσει. Διαλέγουν τον αετό του Αρμπέν, που έχει τα\nλιγότερα τραύματα. Του δένουν την ουρά του αετού της Χαράς, γιατί\nείναι πιο μακριά από τις άλλες, και βάζουν την καλούμπα του Λουκά,\nπου δεν έχει κόμπους.\nO Λουκάς κρατά ψηλά με τα δυο του χέρια τον χαρταετό κόντρα\nστον άνεμο και νιώθει υπερήφανος, ο Αρμπέν κρατά την ουρά, για να\nμην μπλεχτεί, και η Χαρά ξετυλίγει συνεχώς την καλούμπα. Όλα γίνονται\nμε προσοχή και με τάξη. Τα τρία παιδιά συνεργάζονται και ο χαρταετός\nτους αρχίζει ν’ ανεβαίνει… ν’ ανεβαίνει… να πετά σαν αληθινό πουλί στον\nαέρα! Όλο και πιο πολύ κερδίζει ύψος, θαρρείς και πάει να συναντήσει τα\nσύννεφα. Τα παιδιά τον καμαρώνουν με ενθουσιασμό και υπερηφάνεια.\nΓράφουν σ’ ένα χαρτάκι τα τέσσερα ονόματα μαζί και στέλνουν με την\nκαλούμπα «τηλεγράφημα» νίκης στον ουρανό. O ήλιος τούς χαμογελά,\nζεσταίνοντας με τις ακτίνες του τη φιλία\nτους.","word_count":234,"page_number":80,"chapter":"Ενότητα 16 — Νιώθω"},{"id":"b_dimotikou_b_0014","source_id":"b_dimotikou_b","title":"Ο χαρταετός","content":"Ψηλά πετά και μου γελά\nκι εκεί στα σύννεφα γελά.\nΓερά το σπάγκο του κρατώ.\nΑχ! πώς ν’ ακούσει ό,τι του πω;\n\nΧαρταετέ, θέλω κι εγώ\nμαζί μ’ εσένα ν’ ανεβώ.\nΝα δω κορφές, καμπαναριά,\nνα δω τ’ αρνάκια στην πλαγιά.","word_count":41,"page_number":81,"chapter":"Ενότητα 16 — Νιώθω"},{"id":"b_dimotikou_g_0001","source_id":"b_dimotikou_g","title":"Τα παιδιά στην πόλη","content":"Τι ζωή παιδιά είν’ αυτή\nμες στις πολιτείες\nτις ψηλές τις άχαρες\nπολυκατοικίες;\n\nΣαν σαρδέλες στο κουτί\nόλοι στριμωγμένοι\nζούμε, μπαινοβγαίνουμε\nάγνωστοι και ξένοι.\n\nΜήτε κήπο μήτε αυλή\nμήτε πρασινάδα\nόνειρο άπιαστο η απλωσιά\nκι η χρυσή λιακάδα.\n\nΤι ζωή φριχτή είν’ αυτή\nστη μεγάλη πόλη\nμες στη σκόνη, στον καπνό\nκαι δουλειά και σκόλη!","word_count":55,"page_number":12,"chapter":"Ενότητα 17 — Εφημερίδες! Εφημερίδες!"},{"id":"b_dimotikou_g_0002","source_id":"b_dimotikou_g","title":"Τα ψηλά βουνά","content":"Τα είκοσι πέντε παιδιά της πέμπτης τάξης ενός σχολείου\nαποφασίζουν να πάνε μόνα τους διακοπές ψηλά στο βουνό.\nΕκεί οργανώνουν μια καταπληκτική κατασκήνωση και περνούν\nυπέροχα. Για λίγες μέρες ζουν μακριά από τη φροντίδα των\nμεγάλων. Μέσα από ωραίες περιπέτειες μαθαίνουν να δουλεύουν\nκαι να συνεργάζονται, στηρίζοντας ο ένας τον άλλο. Από τον\nκόσμο του βουνού, από τη φύση και τους ανθρώπους του,\nαποκτούν εμπειρίες και γνώσεις και μαθαίνουν μύθους και ιστορίες. Τελικά\nόλοι μαζί συμβάλλουν στη σωστή λειτουργία της ομάδας και περνούν ένα\nαξέχαστο καλοκαίρι.","word_count":86,"page_number":13,"chapter":"Ενότητα 17 — Εφημερίδες! Εφημερίδες!"},{"id":"b_dimotikou_g_0003","source_id":"b_dimotikou_g","title":"Λίγο ακόμα","content":"Λίγο ακόμα\nθα ιδούμε τις αμυγδαλιές ν’ ανθίζουν,\nτα μάρμαρα να λάμπουν στον ήλιο\nτη θάλασσα να κυματίζει.\nΛίγο ακόμα,\nνα σηκωθούμε λίγο ψηλότερα.","word_count":24,"page_number":15,"chapter":"Ενότητα 17 — Εφημερίδες! Εφημερίδες!"},{"id":"b_dimotikou_g_0004","source_id":"b_dimotikou_g","title":"Πατρίδα","content":"Μια άσπρη βαρκούλα μέσα στο κύμα\nένα καβούρι κι ο αχινός\nκι όπου κι αν πας ο ήλιος σε βρίσκει\nκαι για καπέλο σου ο ουρανός.\n\nΒουνά κι αγάλματα, βράχια και πέτρες\nστο φως πλαγιάζουν όλα γυμνά\nκι η Παναγιά με το τσεμπέρι\nστο ερημοκλήσι της ξαγρυπνά.\n\nΜες στην υδρόγειο είσαι μικρούλα\nτο πιο γαλάζιο χρώμα φοράς\nτόσο μεγάλη όταν σε βλέπω\nμα στην καρδιά μου όλη χωράς.","word_count":68,"page_number":20,"chapter":"Ενότητα 17 — Εφημερίδες! Εφημερίδες!"},{"id":"b_dimotikou_g_0005","source_id":"b_dimotikou_g","title":"Ελλάδα","content":"Σκίνα, πεύκα και θυμάρια\nχώμα, μάρμαρα, λιθάρια,\nόλα φως πλημμυρισμένα\nκαι στον ήλιο σκορπισμένα.\n\nΜες στης θάλασσας τ’ αγέρι,\nκάθε βάρκα περιστέρι\nκαι ψηλά στα βουναλάκια\nταπεινά ερημοκλησάκια.\n\nΗ γλυκιά μας η πατρίδα\nλάμπει σαν την ηλιαχτίδα,\nέχει αμπέλια, ελαιώνες,\nμαρμαρένιους Παρθενώνες,\nμικρά μαύρα χελιδόνια\nκι έναν Όλυμπο όλο χιόνια.","word_count":50,"page_number":20,"chapter":"Ενότητα 17 — Εφημερίδες! Εφημερίδες!"},{"id":"b_dimotikou_g_0006","source_id":"b_dimotikou_g","title":"Το μήνυμα του Κολοκοτρώνη","content":"Κείνη την ώρα ξέφυγε από το πλάι της μάνας του κι ο μικρός Ασημάκης. Κανείς δεν το πήρε είδηση πως ακολουθούσε, στερνός, τον Κολοκοτρώνη... Όταν ο Γέρος έδωσε προσταγή να ταμπουρωθούνε στους Μύλους κι έκανε επιθεώρηση στον στρατό του, είδε μπροστά του, σε μια στιγμή, και τον Ασημάκη.\n– Τι θέλει αυτό το βυζασταρούδι στ’ ασκέρι μου; είπε. Ποιος το ’φερε εδώ, παιδί πράμα;\n– Μονάχος μου ήρθα, είπε ο Ασημάκης με θάρρος.\n– Να κάμεις τι; Δεν το ξέρεις πως πάμε για πόλεμο;\n– Τ’ άκουσα που το ’πες. Γι’ αυτό ήρθα. Δεν ήθελα να ’μαι κιοτής. Δε μας κάλεσες όλους;\n– Εγώ, ορέ, κάλεσα τους άντρες, είπε γελώντας ο Κολοκοτρώνης, όχι τα μωρά.\n– Είπες πως τα ρυάκια γεμίζουν τον ποταμό κατεβαίνοντας απ’ τα βουνοπλάγια. Ένα ρυάκι δεν παίρνει στον δρόμο του ό,τι βρει;\n– Μωρέ, ετούτος έχει μυαλό, είπε με το κέφι του το αιώνιο ο Γέρος. Και δε μου λες τ’ όνομά σου;\n– Ασημάκη με λεν.\nO Κολοκοτρώνης πήγε να ξεμακρύνει, μα τ’ αγόρι τον έπιασε απ’ το γιλέκο.\n– Καπετάνιο!\n– Τι είναι ορέ Ασημάκη;\n– Δε θα μου δώκεις εμένα ντουφέκι;\n– Ντουφέκι, ορέ Ασημάκη, δεν έχω στο μπόι σου, μα δε γίνεται ο πόλεμος μόνο με ντουφέκια.\nΈλα μαζί μου κι έχω δουλειά να σου δώσω.","word_count":214,"page_number":22,"chapter":"Ενότητα 17 — Εφημερίδες! Εφημερίδες!"},{"id":"b_dimotikou_g_0007","source_id":"b_dimotikou_g","title":"Νεαροί μαθητές αναλαμβάνουν δράση!","content":"Για μεγάλο διάστημα οι νεαροί μαθητές έπαιζαν στο δασάκι της γειτονιάς τους πλάι στα σπουργίτια, τους κοκκινολαίμηδες, αλλά και κάθε λογής σκουπίδια. Αφού λοιπόν οι μεγάλοι δεν έκαναν τίποτα, αποφάσισαν να αναλάβουν οι ίδιοι δράση.\nΖήτησαν από τους γονείς τους μεγάλες σακούλες σκουπιδιών και γάντια και άρχισαν να μαζεύουν τα σκουπίδια. Άλλοι μάζεψαν τα μπουκάλια, άλλοι τις σακούλες και άλλοι τα χαρτιά. Δε χρειάστηκε μεγάλη προσπάθεια. Κανείς δεν πίστευε στα μάτια του με το αποτέλεσμα!\nOι μικροί μαθητές κρέμασαν στην είσοδο του άλσους μια ταμπέλα με μεγάλα γράμματα: «ΤO ΔΑΣΑΚΙ ΜΑΣ ΧΑΡΙΖΕΙ OΞΥΓOΝO. ΜΗΝ ΤO ΚΑΝΕΤΕ ΣΚOΥΠΙΔOΤOΠO».","word_count":97,"page_number":31,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0008","source_id":"b_dimotikou_g","title":"Άσκηση για περίπτωση πυρκαγιάς","content":"Την Παρασκευή 29 Απριλίου το σχολείο μας έκανε μια άσκηση για την περίπτωση που πιάσει πυρκαγιά. Μόλις ακούσαμε τη σειρήνα, σηκωθήκαμε από τα θρανία μας, βγήκαμε από την τάξη, διασχίσαμε τον διάδρομο βιαστικά, αλλά χωρίς να τρέχουμε, και βρεθήκαμε όλοι στην αυλή του σχολείου.\nΌλοι ψύχραιμοι Όλοι ακολουθήσαμε τις οδηγίες των δασκάλων και παραμείναμε ψύχραιμοι. Όταν μας μέτρησαν οι δάσκαλοι, βρέθηκε ότι δεν έλειπε κανείς. Η πυροσβεστική στην ώρα της Έφτασαν οι πυροσβέστες. Κουβάλησαν τις μάνικες, όρμησαν στο σχολείο και έκαναν ότι σβήνουν τη φωτιά. Έπειτα στάθηκαν στο πλατύσκαλο του σχολικού κτιρίου και μας εξήγησαν πώς να σβήνουμε μια μικρή φωτιά με τον πυροσβεστήρα. Ήταν μια μέρα ενδιαφέρουσα και γεμάτη με συγκινήσεις!","word_count":112,"page_number":32,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0009","source_id":"b_dimotikou_g","title":"Το φεγγαράκι χαρταετός","content":"Το φεγγαράκι χαρταετός\nστα κέφια του πετά\nγέμισε γέλια ο ουρανός\nκι η γη το χαιρετά.\n\nΔένω αχτίδα για κλωστή\nτραβώ, αμολώ καλούμπα\nχοπ! κάνει ψηλοκρεμαστή\nστο σύμπαν κολοτούμπα.","word_count":29,"page_number":34,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0010","source_id":"b_dimotikou_g","title":"Oι πεταλούδες βοηθούν","content":"«O επιθεωρητής των κήπων έρχεται», ακούστηκε μια δυνατή φωνή.\nΧιλιάδες πεταλούδες, ξετρυπώνοντας απ’ τους φράχτες, πέταξαν γελώντας πάνω στα γυμνά κοτσάνια και βάλθηκαν να παρασταίνουν τα λουλούδια, που αμέριμνα εξακολουθούσαν να κοιμούνται μέσα στη γη.","word_count":35,"page_number":35,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0011","source_id":"b_dimotikou_g","title":"Η χελώνα καρέτα καρέτα","content":"Η θαλάσσια χελώνα καρέτα καρέτα είναι εξαιρετική κολυμβήτρια. Βγαίνει από τη θάλασσα, για να φτιάξει τη φωλιά της στην άμμο και να γεννήσει τα αυγά της. Μία από τις παραλίες που διαλέγει για να γεννήσει είναι στον κόλπο του Λαγανά στη Ζάκυνθο.\nO κόλπος του Λαγανά είναι ο πιο σημαντικός βιότοπος της θαλάσσιας χελώνας καρέτα καρέτα. Στα πέντε χιλιόμετρα της παραλίας οι χελώνες καρέτα καρέτα φτιάχνουν πάρα πολλές φωλιές. Από τα τέλη Μαΐου έως τον Αύγουστο, όταν το κλίμα είναι ζεστό, οι χελώνες αφήνουν εκατό αυγά σε καθεμιά φωλιά. Ύστερα από δύο μήνες μέσα από τα αυγά βγαίνουν τα χελωνάκια. Αφού τρυπήσουν το κέλυφος, μένουν στην άμμο για περίπου έξι μέρες και τρέφονται από τον κρόκο του αυγού. Μετά, κάποιο βράδυ ή νωρίς το πρωί, αφήνουν τη φωλιά και κατευθύνονται προς τη θάλασσα. Βγαίνουν μες στο σκοτάδι, όταν δεν κινδυνεύουν από τα πουλιά, τα άλλα ζώα ή τον άνθρωπο.","word_count":149,"page_number":38,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0012","source_id":"b_dimotikou_g","title":"O παγοπώλης","content":"Περνούσαν παγοπώλες και μοιράζανε κολόνες. Είχαν γίνει από νερό που το πάγωναν καιρό, το φαΐ να διατηρεί, να είναι φρέσκο το τυρί, το νεράκι δροσερό, μια φορά κι έναν καιρό.","word_count":30,"page_number":42,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0013","source_id":"b_dimotikou_g","title":"Δουλειές","content":"– Ραφτάκι ραφτάκι\nπώς πάν’ οι δουλειές;\n– Ψαλίδι, κοπίδι\nκαι δυο βελονιές.\n\n– Τσαγκάρη τσαγκάρη\nπαπούτσια πουλάς;\n– Σκαρπίνια, λουστρίνια\nσε γάμο να πας.\n\n– Φούρναρη φούρναρη\nτι κάνεις με βια;\n– Μια βάζω μια βγάζω\nκουλούρια, ψωμιά.\n\n– Μανάβη μανάβη\nτι τρών’ τα παιδιά;\n– Ντομάτες, πατάτες,\nφασόλια, κουκιά.","word_count":51,"page_number":43,"chapter":"Ενότητα 19 — Τα μάθατε τα νέα;"},{"id":"b_dimotikou_g_0014","source_id":"b_dimotikou_g","title":"Επιτάφιος στο νησί","content":"Στο νησί της γιαγιάς τη Μεγάλη Παρασκευή από το πρωί όλοι ετοιμάζονται για τον Επιτάφιο. O κόσμος μαζεύει λουλούδια και τα πηγαίνει στην εκκλησία, για να τον στολίσει.\nΤο βράδυ στην εκκλησία όλοι ψέλνουν και κρατούν κεράκια. O παπάς ραντίζει τον Επιτάφιο με το Άγιο Μύρο. Αυτό μοσχοβολά ανθόνερο, σαν τα αμυγδαλωτά που φτιάχνει η θεία Ελένη τη Μεγάλη Εβδομάδα.\nΜετά βγάζουν τον Επιτάφιο έξω από την εκκλησία και εμείς τον ακολουθούμε. Τον περνούν από τους δρόμους του νησιού. Τον βάζουν και μέσα στη θάλασσα για λίγο. Τα καράβια χαιρετούν τον Επιτάφιο σφυρίζοντας δυνατά.","word_count":94,"page_number":45,"chapter":"Ενότητα 21 — Χρήσιμες οδηγίες"},{"id":"b_dimotikou_g_0015","source_id":"b_dimotikou_g","title":"Μπισκότα με σταφίδες","content":"Ζυμώνετε όλα τα υλικά μαζί,\nγια να γίνουν ζυμάρι.\nΠλάθετε το ζυμάρι\nμε τον πλάστη.\nΚόβετε με φορμάκια στο ζυμάρι\nτα σχήματα που θέλετε.\nΤα βάζετε σε ένα ταψί.\nΑν θέλετε, τα στολίζετε\nμε σταφίδες.\nΤα ψήνετε για είκοσι λεπτά.","word_count":40,"page_number":48,"chapter":"Ενότητα 21 — Χρήσιμες οδηγίες"},{"id":"b_dimotikou_g_0016","source_id":"b_dimotikou_g","title":"Πασχαλιάτικη καμπάνα","content":"Ήταν μια φορά μια μικρούλα πασχαλιάτικη καμπάνα που στεκόταν λυπημένη στο καμπαναριό και περίμενε.\nΤι περιμένεις ακόμα; τη ρώτησε μια μέρα ένα χελιδόνι. Θαρρώ πως όλα είναι έτοιμα για το «Χριστός ανέστη». Κοίτα, τα δέντρα ανθίσανε κι οι παπαρούνες γέμισαν τους κάμπους. Τα σπιτάκια είν’ όλα κάτασπρα κι οι αυλές στολισμένες με κατιφέδες και κρινάκια. Τι περιμένεις, λοιπόν; Ώρα για το «Χριστός ανέστη».\n– Περιμένω τις καρδιές των ανθρώπων να γεμίσουνε μ’ αγάπη, είπε η καμπανούλα κι αναστέναξε.","word_count":78,"page_number":49,"chapter":"Ενότητα 21 — Χρήσιμες οδηγίες"},{"id":"b_dimotikou_g_0017","source_id":"b_dimotikou_g","title":"Χριστός ανέστη","content":"Στην εκκλησιά η καμπάνα\nχτυπάει χαρωπά.\nΧριστός ανέστη! ψέλνουν\nόλοι με μια καρδιά.\n\nΛευκές λαμπάδες καίνε\nστην όμορφη βραδιά\nκόκκινα αυγά τσουγκρίζουν\nχαρούμενα παιδιά.\n\nΕλάτε, ανοίξτε όλοι\nκαλόδεχτη αγκαλιά\nκαι με χαρά κι αγάπη\nν’ αλλάξουμε φιλιά.","word_count":37,"page_number":50,"chapter":"Ενότητα 21 — Χρήσιμες οδηγίες"},{"id":"b_dimotikou_g_0018","source_id":"b_dimotikou_g","title":"Ο θείος Ντίνος","content":"Από τότε που ήμουν πιτσιρικάς, θυμάμαι τον θείο τον Ντίνο να λέει: «Α, εσείς, τα σημερινά παιδιά, δεν ξέρετε να παίξετε, να ξεφαντώσετε! Όλη μέρα μπροστά σε μια οθόνη τη βγάζετε. Τι βαρετό! Ενώ εμείς στην ηλικία σας...» Όποτε όμως του έλεγα: «Έλα, θείε, δείξε μας πώς να παίξουμε! Παίξε μαζί μας κρυφτό, επιτέλους», εκείνος έβρισκε διάφορες προφάσεις, για να το αναβάλει: τη μια ήτανε βιαστικός, την άλλη τον πόναγε η μέση του, και το κυριότερο: «Τι σόι κρυφτό να παίξουμε εδώ μέσα; Όλα είναι διάφανα κι επίπεδα. Πού να κρυφτείς κάτω απ’ το γυάλινο τραπέζι; Ενώ τα σπίτια παλιά είχαν μυστικές κρυψώνες, γωνιές ανεξερεύνητες, αποθήκες, πατάρια...». Λέγοντάς τα αυτά, μια σκιά νοσταλγίας απλωνόταν στο πρόσωπό του.","word_count":117,"page_number":54,"chapter":"Ενότητα 22 — Πώς γίνεται; Πώς παίζεται;"},{"id":"b_dimotikou_g_0019","source_id":"b_dimotikou_g","title":"Τα χρωματιστά μολύβια","content":"Σήμερα τα χρωματιστά μολύβια έχασαν τα λογικά τους. Πήγε η Ελένη να ζωγραφίσει το περιβόλι.\n– Άσε, Ελένη, να το ζωγραφίσουμε εμείς, είπανε εκείνα.\nΚαι τα πράσινα, κόκκινα, κίτρινα μολύβια χρωμάτισαν ένα φανταχτερό περιβόλι. Τα δέντρα πρασίνισαν, οι ντομάτες κοκκίνισαν και τα λεμόνια κιτρίνισαν.\nΠήγε η Ελένη να ζωγραφίσει τον ουρανό.\n– Άσε, Ελένη, να τον ζωγραφίσουμε εμείς, είπανε πάλι. Κι άστραψε ο ουρανός και γέμισε χρώματα. Τα λουλούδια του περιβολιού, οι ντάλιες, τα τριαντάφυλλα και οι μενεξέδες ανεβήκανε στον ουρανό.\nΠήγε η Ελένη να ζωγραφίσει τη θάλασσα.\n– Άσε, Ελένη, να τη ζωγραφίσουμε εμείς, είπανε τα άσπρα, ασημιά και σκούρα μολύβια. Και άσπρισαν τα κύματα και γέμισε αφρούς το χαρτί και ασημώθηκαν τα ψάρια και τα κοχύλια.","word_count":118,"page_number":56,"chapter":"Ενότητα 22 — Πώς γίνεται; Πώς παίζεται;"},{"id":"b_dimotikou_g_0020","source_id":"b_dimotikou_g","title":"Η μικρή Ελένη","content":"Στο κέντρο ενός κύκλου κάθεται ένα κορίτσι που εκείνη τη στιγμή παίρνει το όνομα της μικρής Ελένης (και κάνει ότι κλαίει). Τα υπόλοιπα παιδιά πιασμένα χέρι χέρι γυρίζουν γύρω της και τραγουδούν:\nΗ μικρή Ελένη κάθεται και κλαίει γιατί δεν την παίζουνε οι φιλενάδες της.\nΣήκω επάνω, κλείσε τα ματάκια σου, κοίταξε τον ήλιο και ψάξε να μας βρεις.\nΤη στιγμή αυτή ο κύκλος χαλάει, το κορίτσι που κάνει την Ελένη σηκώνεται με κλειστά μάτια, υψώνει το κεφάλι προς τον ήλιο κι έπειτα προσπαθεί να πιάσει κάποιο απ’ τα παιδιά. Όταν πιάσει ένα κορίτσι, προσπαθεί (με κλειστά πάντα μάτια) να το αναγνωρίσει, για να πάρει τη θέση της μικρής Ελένης και να συνεχιστεί το παιχνίδι.","word_count":115,"page_number":57,"chapter":"Ενότητα 22 — Πώς γίνεται; Πώς παίζεται;"},{"id":"b_dimotikou_g_0021","source_id":"b_dimotikou_g","title":"Παιχνιδόγελα","content":"O λαιμός απ’ το μπουκάλι\nπου ’χει τάπα για κεφάλι\nμε πονόλαιμο είναι πάλι\nβραχνιασμένος κακό χάλι.\n\nΑπ’ το μάτι της βελόνας\nδάκρυα δεν μπορούν να τρέξουν\nκι οι βελόνες απ’ τα πεύκα\nκλαίν’ που δεν μπορούν να τρέξουν.\n\nΤης κουζίνας μας τα μάτια\nδε φορούν ποτέ γυαλιά\nκαι κουμπότρυπες δεν έχουν\nτα πολλά της τα κουμπιά.\n\nΤρέμουν τα βιβλία μου\nτα πιάνει ανατριχίλα\nμήπως και το φθινόπωρο\nτους πέσουνε τα φύλλα.","word_count":72,"page_number":59,"chapter":"Ενότητα 22 — Πώς γίνεται; Πώς παίζεται;"},{"id":"b_dimotikou_g_0022","source_id":"b_dimotikou_g","title":"Λαθεύοντας ιστορίες","content":"– Ήταν μια φορά ένα κοριτσάκι που το έλεγαν Κιτρινοσκουφίτσα.\n– Όχι, Κοκκινοσκουφίτσα!\n– Α, ναι, Κοκκινοσκουφίτσα. Η μαμά του το φώναξε και του είπε: Άκου, Πρασινοσκουφίτσα.\n– Μα όχι, Κοκκινοσκουφίτσα!\n– Α, ναι, Κοκκινοσκουφίτσα. Πήγαινε στη θεία Διομίρα και δώσ’ της αυτή τη φλούδα πατάτα.\n– Όχι, πήγαινε στη γιαγιά και δώσε της αυτή την πίτα.\n– Καλά. Το κοριτσάκι πήγε στο δάσος και συνάντησε μια καμηλοπάρδαλη.\n– Τι μπέρδεμα! Συνάντησε ένα λύκο, όχι καμηλοπάρδαλη.\n– Κι ο λύκος τη ρώτησε: Πόσο κάνει έξι επί οχτώ;\n– Καθόλου. O λύκος τη ρώτησε: Πού πας;\n– Έχεις δίκιο. Η Μαυροσκουφίτσα απάντησε...\n– Παππού, δεν ξέρεις καθόλου να διηγείσαι ιστορίες, τις κάνεις όλες λάθος.","word_count":113,"page_number":61,"chapter":"Ενότητα 23 — Για να γελάσουμε"},{"id":"b_dimotikou_g_0023","source_id":"b_dimotikou_g","title":"Άνοιξη στο Παγγαίο","content":"Θυμάμαι συχνά την άνοιξη που πέρασα στο γραφικό χωριουδάκι του παππού μου στις πλαγιές του όρους Παγγαίου. Με το που έφτασε ο Μάης, τα λουλούδια έστησαν χορό στον καταπράσινο κήπο του πέτρινου σπιτιού του παππού μου. Oι κατακόκκινες παπαρούνες πιάστηκαν χέρι χέρι με τις ευγενικές μαργαρίτες και άρχισαν να χορεύουν στην πρωινή δροσιά. Oι πολύχρωμες τριανταφυλλιές τούς πετούσαν ροδοπέταλα. Oι μελωδικές καμπανούλες με το ρυθμικό λίκνισμα έγερναν με χάρη στο πέρασμα του αγέρα, ο οποίος έκανε και τις πασχαλιές να σφυρίζουν απαλά.\nΑκόμη και τα ώριμα κεράσια της κερασιάς του παππού συμμετείχαν στη γιορτή.","word_count":94,"page_number":65,"chapter":"Ενότητα 23 — Για να γελάσουμε"},{"id":"b_dimotikou_g_0024","source_id":"b_dimotikou_g","title":"Το ουράνιο τόξο","content":"Μόλις σταματήσει η βροχή\nκι οι αχτίνες του ήλιου ξεπροβάλουν,\nχρώματα ξεχύνονται στη γη\nκαι τη φύση όλη περιβάλλουν.\n\nΤο ουράνιο τόξο σαν φανεί,\nη χαρά φωλιάζει στην καρδιά μου\nκαι η λύπη τρέχει να κρυφτεί,\nδιώχνοντας τα σύννεφα μακριά μου.","word_count":41,"page_number":70,"chapter":"Ενότητα 24 — Να σου πω τι έμαθα;"},{"id":"b_dimotikou_g_0025","source_id":"b_dimotikou_g","title":"O λύκος","content":"O λύκος μοιάζει με μεγάλο σκύλο. Έχει ψηλά πόδια και φαρδύ πέλμα, για να μπορεί να περπατά εύκολα στο χιόνι. Κάθε μέρα περπατά ή τρέχει 8 έως 10 ώρες, για να βρει φαγητό. Βλέπει πολύ καλά στο σκοτάδι. Κυνηγά ποντίκια, λαγούς, αγριογούρουνα και άλλα ζώα. Ζει περίπου 16 χρόνια.\nOι λύκοι ζουν σε αγέλη, δηλαδή σε ομάδα με 8 έως 15 λύκους. Αγαπούν πολύ τα παιδιά τους. Τα έχουν μαζί τους για έναν χρόνο και τους μαθαίνουν πώς να επιβιώνουν. Τα λυκάκια τα φροντίζει όλη η αγέλη. O λύκος και η λύκαινα μένουν μαζί για όλη τους τη ζωή.\nΜερικές φορές οι λύκοι τραυματίζονται ή δηλητηριάζονται από τους ανθρώπους. Αν κάποιος βρει έναν πληγωμένο ή άρρωστο λύκο, μπορεί να τον σώσει πηγαίνοντάς τον σε νοσοκομείο για ζώα. Όταν οι λύκοι συνηθίσουν πολύ τους ανθρώπους, γίνονται καλοί φίλοι τους.","word_count":138,"page_number":71,"chapter":"Ενότητα 24 — Να σου πω τι έμαθα;"},{"id":"b_dimotikou_g_0026","source_id":"b_dimotikou_g","title":"Δε μ’ ακούς;","content":"Έρχομαι μέσ’ από τη θάλασσα.\nΈλα, έλα, κοριτσάκι,\nμυρίζω φύκι και πελαγίσιο άνεμο.\nΈλα, έλα, αγοράκι,\nκυλήσου στα βότσαλα,\nχτίσε πύργους και κάστρα στην άμμο,\nσκάψε πηγαδάκι να βρούμε νερό.\nΘα πιάσουμε καβούρια;\nΘα παίξουμε κρυφτό;\nΜυρίζω καρπούζι, σταφύλια,\nκεράσια και μούσμουλα\nκαι όπου περνώ όλα γίνονται κίτρινα.\n\nΑγρότες κι αγρότισσες μ’ ακολουθούν\nμε τα δρεπάνια στο χέρι,\nτο στάρι να θερίσουμε ψωμάκι να γένει.\nΈρχομαι μέσα από τα χρυσαφένια χωράφια.\nΈλα, έλα, αγοράκι,\nέλα, έλα, κοριτσάκι.\nΔε μ’ ακούς;\nΕίμαι το Καλοκαίρι.","word_count":83,"page_number":74,"chapter":"Ενότητα 24 — Να σου πω τι έμαθα;"},{"id":"b_dimotikou_g_0027","source_id":"b_dimotikou_g","title":"Καλοκαίρι","content":"– Καλοκαίρι, καλοκαίρι,\nτι καλά μάς έχεις φέρει;\n– Φέρνω του καιρού τη γλύκα\nτα κεράσια και τα σύκα.\nΤα σταφύλια έχω στ’ αμπέλι\nκαι το μέλι στην κυψέλη\nτ’ άνθη στην τριανταφυλλιά\nκαι στα δέντρα τα πουλιά.\nΈχω και για τα παιδάκια\nμάγουλα τριανταφυλλένια\nκαι κορμιά γερά ατσαλένια.","word_count":49,"page_number":75,"chapter":"Ενότητα 24 — Να σου πω τι έμαθα;"},{"id":"d_dimotikou_0001","source_id":"d_dimotikou","title":"O Σεπτέμβρης","content":"Ο Σεπτέμβρης είναι αγόρι\nκι έχει ολόχρυσο καπέλο\nκαι χρυσό το πανωφόρι.\n\nΤα παπούτσια του είναι φύλλα,\nπου ’χουν πέσει απ’ τα πλατάνια\nκαι τα μάγουλά του μήλα.\n\nΚρατάει σάκα από νερό\nκι έχει μέσα τα βιβλία\nαπό σύννεφο κι αφρό.\n\nΜε του ανέμου τα ποδάρια\nτρέχει δίχως να τον βλέπεις.\nΣτων βημάτων του τα χνάρια\n\nδιαμαντάκια θε να βρεις,\nσταγονίτσες, σταγονίτσες\nμιας ολόχρυσης βροχής.\n\nΟ Σεπτέμβρης είναι αγόρι,\nκατεβαίνει από τα δάση,\nκατεβαίνει από τα όρη.\n\nΚι έρχεται για να χτυπήσει\nμια πελώρια καμπάνα,\nτο σχολειό για να αρχινήσει.\n\nΟ Σεπτέμβρης πάντα, δες,\nέχει όλα τα παιδάκια\nφίλους και συμμαθητές.","word_count":101,"page_number":11,"chapter":"Ενότητα 1 — Ένα ακόμα σκαλί"},{"id":"d_dimotikou_0002","source_id":"d_dimotikou","title":"Ξημερώνει μια νέα μέρα... Ώρα για σχολείο","content":"Με το πρώτο φως του ήλιου, τα παιδιά (όσα ήταν πάνω από 7 χρόνων) ήταν στο πόδι. Έτρωγαν ένα λιτό πρωινό, με σταρένιο ή κριθαρένιο ψωμί, και μετά γραμμή για το σχολείο. Παρέα με τον «παιδαγωγό» –έναν δούλο που καθήκον του ήταν να συνοδεύει παντού το παιδί– πήγαιναν στο σπίτι του «γραμματιστή».\nΓραμματιστής ονομαζόταν ο δάσκαλος που μάθαινε στα παιδιά γραφή, ανάγνωση και αριθμητική. Τα παιδιά κάθονταν σε σκαμνάκια, ακουμπούσαν στα γόνατά τους σκληρές πλάκες από κερί ή κομμάτια παπύρου και πάνω τους χάραζαν με τη μυτερή άκρη ενός ειδικού εργαλείου, της «γραφίδας». Την άλλη άκρη της γραφίδας, που ήταν πλατιά και στρογγυλεμένη, τη χρησιμοποιούσαν για να σβήνουν.\nΟι δάσκαλοι κάθονταν στους «θρόνους», δηλαδή σε καρέκλες με πλάτη και κυρτωμένα πόδια. Όση ώρα διαρκούσε το μάθημα, ο παιδαγωγός έμενε στην αίθουσα διδασκαλίας. Ήθελε δεν ήθελε, άκουγε κι αυτός την παράδοση κι αργότερα στο σπίτι μπορούσε να βοηθήσει το παιδί στα μαθήματά του.","word_count":152,"page_number":21,"chapter":"Ενότητα 1 — Ένα ακόμα σκαλί"},{"id":"d_dimotikou_0003","source_id":"d_dimotikou","title":"Το νερό συστήνεται","content":"Γεια σας. Να σας συστηθώ. Είμαι το νερό. Είμαι το γάργαρο νερό που κυλάει στα ποτάμια. Είμαι το νερό της βροχής που δροσίζει τα χωράφια και τους ανθρώπους. Είμαι το νερό της λίμνης που δίνει ζωή στις πέστροφες και τους γουλιανούς*. Είμαι το νερό της θάλασσας, το απέραντο πέλαγος. Είμαι ο ωκεανός. Έχω στην αγκαλιά μου δελφίνια, φώκιες και ψάρια. Είμαι ο ωκεανός που αρμενίζω καράβια και ταξιδεμένους ναυτικούς.\nΕίμαι το γάργαρο νερό της βρύσης που σας δροσίζει. Είμαι το νερό που κολυμπάτε και χαίρεστε τα καλοκαίρια σας. Είμαι πηγή ζωής. Αγαπώ όλα τα πλάσματα της φύσης, τα φυτά, τα δέντρα, τα ζώα και τους ανθρώπους. Τους δίνω τα ωφέλιμα συστατικά μου για να ζουν και να μεγαλώνουν με υγεία. Είμαι το νερό της πηγής, το νάμα*, το νερό που θεραπεύει το κουρασμένο σώμα. Είμαι το ευλογημένο νερό που καθαρίζει την ψυχή του ανθρώπου, είμαι το νερό της βάφτισης. Είμαι το ποτάμι, η λίμνη, η θάλασσα, η βροχή, είμαι το ΝΕΡΟ!\nΓεννιέμαι ολημερίς. Όλο σε κίνηση βρίσκομαι. Από την επιφάνεια της γης πάω μέχρι την ατμόσφαιρα και ύστερα γυρνάω πάλι πίσω. Από τη θάλασσα, τις λίμνες και τα ποτάμια εξατμίζομαι. Γίνομαι μικρές μικρές σταγόνες και ύστερα γίνομαι ατμός. Με τη βοήθεια της θερμοκρασίας του αέρα και του ανέμου, ανεβαίνω ψηλά και γίνομαι σύννεφο.\nΣκαρφαλώνω στα βουνά κι αφήνω τη βροχή μου να δροσίζει τα δάση, τα χωράφια και τους ανθρώπους. Γίνομαι χαλάζι και χιόνι. Φτάνω ως το έδαφος και γλιστράω βαθιά στο χώμα και γίνομαι υπόγειο νερό. Τρέφω τις ρίζες των φυτών, που με ρουφούν με λαχτάρα, και πλουτίζω τη γη με νερό. Γίνομαι λίμνες και ποτάμια.\nΓεννιέμαι ολημερίς. Όλο σε κίνηση βρίσκομαι. Σε τούτη την κίνηση έχω παρέα τα φυτά, που με αγαπούν και με προσέχουν.\nΤα φυτά δίνουν υγρασία στον αέρα, δίνουν τις μικρές υγρές σταγόνες τους.\nΘαυμαστή η φύση! Με γεννούν τα πλάσματά της κι ύστερα εγώ τα τρέφω. Είμαι το νερό κι όλο σε κίνηση βρίσκομαι.","word_count":320,"page_number":33,"chapter":"Ενότητα 2 — Pώτα το νερό... τι τρέχει"},{"id":"d_dimotikou_0004","source_id":"d_dimotikou","title":"Tο ποτάμι τρέχει να συναντήσει τη θάλασσα","content":"Ήταν ένας ποταμός,\nο πιο ευτυχισμένος ποταμός του κόσμου.\nΕίχε την αρχή αρχή αρχή του\nσε μιαν απάτητη βουνοκορφή\nκαι το τέλος του\nσε μια γαλάζια θάλασσα.\n«Κυλάω»\nέλεγε το τραγούδι του κάθε μέρα\nστον ήλιο.\n«Με το μακρύ μου κορμί\nπότε τεντωμένο σαν ίσια γραμμή,\nπότε σαν περισπωμένη\nκαι πότε σαν ατέλειωτος μαίανδρος*,\nκυλάω…\nΚι όταν είναι πρωί\nκαι λάμπω μες στο φως της ημέρας\nκι όταν είναι βράδυ\nκαι σβήνω μες στο σκοτάδι της νύχτας,\nκυλάω…\nΓλιστρώντας μέσα από τους μεγαλοπρεπείς\nίσκιους\nτων πανύψηλων βουνών,\nπότε σε τρυφερές κοιλάδες\nκαι πότε σε άγρια δάση,\nκυλάω…\nΚι όταν η βροχή με πλημμυρίζει\nκι όταν το χιόνι με παγώνει,\nκυλάω…\nΜέσα από φαράγγια,\nερημιές,\nχωριά\nκαι πολιτείες\nκυλάω…\nΜε τον χειμώνα,\nτην άνοιξη,\nτο καλοκαίρι\nκαι το φθινόπωρο\nκυλάω...\nΚι όταν οι αετοί και τα γεράκια\nξεδιψούν στα νερά μου\nκι όταν τ’ αηδόνια και τα σπουργίτια\nκαθρεφτίζονται πάνω μου,\nκυλάω…\nΚι όταν τα κλαδιά της πλατανιάς\nμε κρύβουν να μη φαίνομαι\nκι όταν τα χορταράκια\nπαραμερίζουν να περάσω,\nκυλάω..\nΚι όταν γλιστρώ σε στρογγυλεμένα χαλίκια\nκι όταν κατρακυλώ\nσε απότομους βράχους,\nκυλάω…\nΚι όταν είμαι ήμερος\nκι όταν γίνομαι χείμαρρος,\nκυλάω… κυλάω…\nκυλάω…\nΚι είμαι τόσο ευτυχισμένος γι’ αυτό…»\n«… Μα πιο πολύ\nείμαι ευτυχισμένος\nγιατί εκεί,\nστην άκρη του ταξιδιού μου,\nμε περιμένει\nμε ολάνοιχτη την πελώρια αγκαλιά της\nη αγαπημένη μου\nη Θάλασσα.\nΓι’ αυτό κι εγώ τρέχω έτσι γρήγορα\nκαι ποτέ δε σταματώ.\nΓιατί βιάζομαι\nκοντά της να φτάσω\nκι εκεί, στο πλάι της,\nστην αμμουδιά της, να σταματήσω\nκαι να χυθώ».","word_count":256,"page_number":36,"chapter":"Ενότητα 2 — Pώτα το νερό... τι τρέχει"},{"id":"d_dimotikou_0005","source_id":"d_dimotikou","title":"Οκτώβρης 1940","content":"Ανοίγουν τα παράθυρα,\nκι όσοι μένουν χαιρετούν αυτούς που φεύγουν\nκαι φεύγουν όλοι.\nΓέμισαν οι πόλεις τύμπανα και σημαίες.\nΟρθή η αυγή σημαιοστολίζει τα όνειρά μας\nκι η Ελλάδα λάμπει μες στα φώτα των ονείρων μας.\nΟ ήλιος πλυμένος\nμε το καθάριο πρόσωπο στραμμένο στον άνθρωπο,\nχαιρετάει τους δρόμους που τραβούν στη μάχη.\nΑυτοκίνητα περνούν γεμάτα πλήθος.\nΑποχαιρετιούνται στις πόρτες και γελάνε,\nύστερα ακούγονται τ’ άρβυλα στην άσφαλτο,\nτο μεγάλο τραγούδι των αντρίκιων βημάτων\nπου μακραίνει και σβήνει στο βάθος του δρόμου,\nως τοβραδινό σταθμό με τα χαμηλωμένα φώτα.\nΕκεί τα τρένα περιμένουν\nσφυρίζουν για λίγο έξω από την πόλη,\nακούγονται οι αποχαιρετιστήριοι πυροβολισμοί\nκι ύστερα όλα σωπαίνουν και περιμένουν.\nΔιαβάζουμε τα τελευταία παραρτήματα:\nΝικούμε. Νικούμε.\nΠάντα νικάει το δίκιο!\nΜια μέρα θα νικήσει ο άνθρωπος.\nΜια μέρα η λευτεριά θα νικήσει τον πόλεμο.\nΜια μέρα θα νικήσουμε για πάντα.","word_count":140,"page_number":49,"chapter":"Ενότητα 3 — To σχολείο γιορτάζει"},{"id":"d_dimotikou_0006","source_id":"d_dimotikou","title":"Γενική έκκληση*","content":"Εδώ Πολυτεχνείο... Εδώ Πολυτεχνείο... Ελληνικέ λαέ, η νίκη μας είναι κοντά... Όλος ο λαός να κατέβει στους δρόμους της Αθήνας... Γενική κινητοποίηση... Πρέπει να νικήσουμε. Ή τώρα ή ποτέ. Εμπρός λαέ της Αθήνας. Ή τώρα ή ποτέ...\nΕδώ Πολυτεχνείο... Εδώ Πολυτεχνείο... Λαέ της Αθήνας. Δείξε τη δύναμή σου. Κατέβα στον δρόμο... Τα ελπιδοφόρα μηνύματα μας έρχονται από παντού... Είμαστε όλοι εδώ στο Πολυτεχνείο, ψύχραιμοι... όλοι αποφασισμένοι να αγωνισθούμε μέχρι να νικήσουμε. Λαέ της Αθήνας, με ψυχραιμία και ηρεμία κατέβα στους δρόμους για να αγωνισθείς...","word_count":84,"page_number":55,"chapter":"Ενότητα 3 — To σχολείο γιορτάζει"},{"id":"d_dimotikou_0007","source_id":"d_dimotikou","title":"Τα κάγκελα","content":"Πίσω απ’ τα κάγκελα ελεύθεροι χιλιάδες\nστο δρόμο περπατάει αργά η φοβέρα\nπίσω απ’ τα σίδερα ονειρεύονται μανάδες\nπαιδιά που έχουνε αλλάξει σε μια μέρα.\n\nΜπροστά απ’ τα κάγκελα οι σκλάβοι που φοβούνται\nόπλα κρατάνε και ο δρόμος τούς ανήκει\nπίσω απ’ τα κάγκελα φωνές που δε φοβούνται\nκαι μοιάζουν θάλασσα που πλέει ένα καΐκι.\n\nΠίσω απ’ τα σίδερα τα μάτια της γενιάς τους\nχαμογελάνε σ’ ένα φως που ξημερώνει\nέξω στο δρόμο η ντροπή κι η παγωνιά τους\nβήμα με βήμα την ελπίδα τη σκοτώνει.","word_count":86,"page_number":56,"chapter":"Ενότητα 3 — To σχολείο γιορτάζει"},{"id":"d_dimotikou_0008","source_id":"d_dimotikou","title":"Στάση βροχοσταλίδων","content":"Ήταν η τελευταία μέρα του καλοκαιριού, δέκα χρόνια μετά το τέλος της δεύτερης χιλιετίας. Η κατάσταση πάνω στη Γη ανυπόφορη. Στη Συννεφοπολιτεία εδώ και καιρό έφταναν απ’ όλα τα πλάτη και τα μήκη της Γης SOS τηλεγραφήματα.\n— Πετρελαιοκηλίδα τεράστιων διαστάσεων απειλεί τα νησιά του Ειρηνικού...\n— Η τρύπα του όζοντος αυξάνει τους δείκτες της θερμοκρασίας…\n— Λιώνουν οι πάγοι στους πόλους της Γης...\n— Μεγάλη πυρκαγιά απειλεί ν’ αφανίσει τα δάση της Κεντρικής Ευρώπης...\nΔε χρειάζονταν περισσότερα για να σημάνουν συναγερμό οι βροχοσταλίδες. Άλλωστε, μέχρι να καταλάβουν οι άνθρωποι τον κίνδυνο...\n— Ως εδώ και μη παρέκει! άστραψε εξοργισμένη η πιο ζωηρή από τις βροχοσταλίδες.\n— Κι εδώ και παρακεί, κι ακόμα παραπέρα, μόνο με μέτρα δραστικά θα δούμε άσπρη μέρα, είπε η βροχοσταλίδα Στρουμπουλή, βάζοντας τα πράγματα στη θέση τους.\n— Να κηρύξουμε στάση ειρηνική, πρότεινε η πιο μεγάλη βροχοσταλίδα και σκούπισε τους πράσινους λεκέδες στο μέτωπό της.\nΣυμφώνησαν όλες. Λίγο αργότερα, όλοι οι πίνακες ανακοινώσεων σ’ ολόκληρη την πλάση έγραφαν με τεράστια γράμματα: «ΣΤΑΣΗ ΒΡΟΧΟΣΤΑΛΙΔΩΝ» κι από κάτω με μικρά γράμματα εξηγούνταν οι λεπτομέρειες, ενώ στο τέλος υπήρχαν υπογραφές.\nΤην επομένη, όλα τα ποτιστήρια ήταν διπλοσφραγισμένα με ηλιαχτίδες. Και φυσικά κανένας, ούτε μια τοσοδά βροχοσταλίδα, δεν κυκλοφόρησε στους διαδρόμους του ουρανού. Ούτε θα κατέβαινε κάτω στη Γη, όσο διάστημα κι αν χρειαζόταν.\nΚαι οι μέρες πέρασαν. Πέρασαν οι εβδομάδες, οι μήνες κι ο ουρανός δεν είχε τον παραμικρό λεκέ στον θαλασσή καμβά* του. Στην αρχή όλοι πίστεψαν πως ήταν ένα αστείο παιχνίδι των σύννεφων, γρήγορα όμως κατάλαβαν πως τα σύννεφα δεν είχαν καμιά διάθεση για παιχνίδι.\nΗ φλούδα της Γης σαν ρόδι παραγινωμένο έσκαγε επικίνδυνα.\nΚαι δεν ήταν μόνο αυτό. Τις επόμενες μέρες, το κακό πήρε μεγαλύτερες διαστάσεις. Τα ποτάμια στέρεψαν το ένα μετά το άλλο κι οι βάτραχοι βγήκαν στους δρόμους, κοάζοντας και ξεκουφαίνοντας τον κόσμο. Τα σπαρτά ξεράθηκαν κι οι μυλωνάδες έβαλαν λουκέτο στους ανεμόμυλους.\nΕνώ συνέβαιναν αυτά, η στάθμη του νερού στις δεξαμενές των πόλεων μειωνόταν απειλητικά. Οι υπεύθυνοι της ύδρευσης, για να αντιμετωπίσουν το πρόβλημα της λειψυδρίας*, φούσκωσαν τον λογαριασμό του νερού.\n— Αλίμονό μας! παραπονιέται κάποια γυναίκα. Έτσι όπως πάμε, θα πούμε το νερό νεράκι.\n— Νομίζω πως ήρθε η στιγμή να δράσουμε, είπε αποφασιστικά κάποιο από τα παιδιά.\n— Και μάλιστα αμέσως, συμφώνησε ο φίλος του.\n— Tο βρήκα τι θα κάνουμε! Θα ρωτήσουμε τους φίλους μας τ’ αστέρια. Εκείνα σίγουρα ξέρουν τι συμβαίνει και θα μας πουν τι φταίει.","word_count":399,"page_number":59,"chapter":"Ενότητα 4 — Eμένα με νοιάζει"},{"id":"d_dimotikou_0009","source_id":"d_dimotikou","title":"Στάση βροχοσταλίδων","content":"(συνέχεια)\nΤο ίδιο κιόλας βράδυ, η Μικρή Αρκούδα* μέσα από μια αστεροακτίνα της έστειλε την απάντησή της. Και το παιδί διάβασε με τρεμάμενη φωνή: «Περιβάλλον, SOS!!!».\n— Βέβαια! Πώς δεν το σκεφτήκαμε πιο πριν; Η Γη μας κινδυνεύει από τη μόλυνση. Γι’ αυτό είναι θυμωμένα τα σύννεφα.\n— Θα τα κάνουμε να ξεθυμώσουν, είπαν μ’ ένα στόμα όλα τα παιδιά, ξέροντας τώρα πια τι έπρεπε να κάνουν.\nΣαν ξημέρωσε, τα παιδιά σκορπίστηκαν στις γύρω γειτονιές, πήγαν από σχολείο σε σχολείο, από σπίτι σε σπίτι και μίλησαν με τα άλλα παιδιά στη δική τους γλώσσα. Αυτά με τη σειρά τους μίλησαν στους φίλους τους στις άλλες γειτονιές κι εκείνοι στους δικούς τους. Μέσα σε λίγες μέρες όλα τα παιδιά της Γης γνώριζαν την αλήθεια. Όμως μόνα τους, δίχως τη βοήθεια των μεγάλων, ήταν αδύνατο ν’ αλλάξουν τον κόσμο. Έβαλαν λοιπόν τα δυνατά τους και τα βράδια, σαν έπεφταν στο κρεβάτι, έπλεκαν στο παραμύθι της μαμάς ή του παππού και της γιαγιάς τη δική τους ιστορία, την αληθινή, με το περιβάλλον και τα σύννεφα. Κι η ζεστασιά των παιδικών λόγων μαλάκωσε την καρδιά τους…\nΠολύ σύντομα όλοι μιλούσαν γι’ αυτό. Στις γειτονιές, στις πλατείες και στα ξεραμένα πάρκα των πόλεων, στα έδρανα* των Κοινοβουλίων, παντού όλοι μιλούσαν για την προστασία του περιβάλλοντος. Κι όχι μόνο…\nΤα μέτρα ήταν άμεσα: οι τραγουδιστάδες έπλεξαν εγκώμια στη μητέρα φύση, οι παραμυθάδες την τίμησαν με όμορφες ιστορίες, οι πολιτικοί έκαναν νόμους να την προστατέψουν κι οι απλοί άνθρωποι της έδειξαν την αγάπη τους.\nΤα αποτελέσματα δεν άργησαν να φανούν. Και τα παιδιά ήταν αυτά που τα πρωτοαντίκρισαν.\n— Είδατε που είχαμε δίκιο;\n— Πράγματι! Έχω καιρό να δω σκουπίδια στους δρόμους...\n— Και τα πάρκα δεν είναι βουβά, αντηχούν από τα γέλια!\n— Κοιτάξτε! Όλοι βγήκαν στις γύρω πλαγιές να φυτέψουν δενδρύλλια!\n— Και τα φουγάρα στις σκεπές έγιναν ανθοδοχεία!\nΑπό τα μέσα μαζικής ενημέρωσης ανακοινώνονταν τα νέα απ’ όλο τον κόσμο: «Οι πετρελαιοκηλίδες δε μολύνουν πια τα νερά των θαλασσών... Οι φωτιές ανάβουν μόνο για να ζεστάνουν... Οι εξατμίσεις των αυτοκινήτων αποσύρονται, γιατί αυτά κινούνται με τη βοήθεια του ήλιου...».\nΑκόμα και οι βροχοσταλίδες δεν έμειναν ασυγκίνητες. Ήταν οι πρώτες που ανταποκρίθηκαν στο κάλεσμά μου κι έδωσαν το «παρών». Κι ο ουρανός σκοτείνιασε.\n— Επιτέλους, βροχή! φώναξε αυθόρμητα κάποιος νεαρός.\n— Η βροχή της σωτηρίας! συμπλήρωσε μια κοπέλα.\n— Είναι αυτό που περιμέναμε, αυτό που μας ξανανιώνει, παρατήρησε μια γριούλα. Το νερό της ζωής!\nΜήνες περίμεναν αυτή τη στιγμή και η ευκαιρία δεν πήγε χαμένη. Μικροί και μεγάλοι βγήκαν στους δρόμους μες στη βροχή και γιόρτασαν το γεγονός.\nΈτσι, η στάση των βροχοσταλίδων έληξε, με την υπόσχεση βέβαια και την ελπίδα για ένα καινούριο ξεκίνημα, μια καινούρια ζωή...","word_count":443,"page_number":62,"chapter":"Ενότητα 4 — Eμένα με νοιάζει"},{"id":"d_dimotikou_0010","source_id":"d_dimotikou","title":"Χρησιμοποίησέ το ξανά… και ξανά… και ξανά…","content":"Ξέρεις ότι...\nΚάθε χρόνο χρησιμοποιούμε δισεκατομμύρια χαρτοπετσέτες. Για σκέψου πόσα δέντρα κόβονται για να φτιαχτούν τόσες χαρτοπετσέτες!\nΤώρα μάντεψε…\nΠόσα πλαστικά μπουκάλια μιας χρήσης χρησιμοποιούνται από τους ανθρώπους σε τέσσερις μέρες;\nΑ) Όσα για να γεμίσουμε ένα φορτηγό.\nΒ) Όσα για να γεμίσουμε μια αποθήκη.\nΓ) Όσος είναι ο πληθυσμός ολόκληρης της Αμερικής.\nΠολύ πριν γεννηθείς εσύ, τότε που οι παππούδες σου ήταν ακόμα παιδιά, δεν υπήρχαν χαρτοπετσέτες και χαρτομάντιλα. Οι άνθρωποι χρησιμοποιούσαν πετσέτες και μαντίλια από πανί.\nΕκείνα τα χρόνια, τα ξαναχρησιμοποιούσαν όλα πολλές φορές. Και ούτε τους περνούσε καθόλου από το μυαλό να πετάξουν κάτι, επειδή το χρησιμοποίησαν μια φορά.\nΣήμερα όμως, έχουμε ένα σωρό πράγματα που είναι φτιαγμένα ειδικά για να τα πετάμε στα σκουπίδια, αφού τα χρησιμοποιήσουμε μονάχα μια φορά. Αυτά τα πράγματα τα λέμε «μιας χρήσης». Το αλουμινόχαρτο, οι πλαστικές σακούλες, οι χαρτοσακούλες, το πλαστικό περιτύλιγμα, θεωρούνται όλα «μιας χρήσης».\nΌμως, τι συμβαίνει με αυτό τον τρόπο; Οι θησαυροί της Γης μας πετιούνται σαν να ήταν σκουπίδια. Δε θα ήταν σπουδαίο, αν καθένας από μας έκανε κατιτί για να πάψει πια αυτή η σπατάλη; Πόσο διαφορετικός θα ήταν τότε ο κόσμος μας!","word_count":187,"page_number":65,"chapter":"Ενότητα 4 — Eμένα με νοιάζει"},{"id":"d_dimotikou_0011","source_id":"d_dimotikou","title":"Σκουπίδια στη θάλασσα","content":"Σκουπίδια που… ταξιδεύουν!\nΤο νερό των θαλασσών κυκλοφορεί συνεχώς κι έτσι μεταφέρει τα σκουπίδια που ρίχνονται σ’ αυτές σε μεγάλες αποστάσεις. Το αποτέλεσμα είναι ότι οι ακτές ακόμα και των πιο απομακρυσμένων νησιών είναι γεμάτες σκουπίδια.\nΤη δεκαετία του 1990 σε μια έρευνα στις παραλίες του ακατοίκητου νησιού Ντούσι, ενός από τα πιο απομονωμένα μέρη του κόσμου, 4.500 χλμ. μακριά από τις ακτές της Νότιας Αμερικής, βρέθηκαν χιλιάδες σκουπίδια, από πλαστικά παιχνίδια μέχρι φιάλες αερίου. Τα σκουπίδια στη θάλασσα δεν είναι μόνο μια πολύ άσχημη εικόνα, αλλά και απειλή για τη θαλάσσια ζωή.","word_count":93,"page_number":69,"chapter":"Ενότητα 4 — Eμένα με νοιάζει"},{"id":"d_dimotikou_0012","source_id":"d_dimotikou","title":"Μάθημα Κυκλοφοριακής Αγωγής","content":"Την ιστορία διηγείται ο Νικόλας, μαθητής σε ένα δημοτικό σχολείο στη Γαλλία.\nMερικές φορές, καθώς πηγαίνουμε στο σχολείο, συναντιόμαστε στον δρόμο με πολλούς φίλους και σπάμε πολλή πλάκα. Χαζεύουμε τις βιτρίνες, βάζουμε τρικλοποδιές ο ένας στον άλλο ή ρίχνουμε τις τσάντες των άλλων κάτω. Κάποια στιγμή, όμως, καταλαβαίνουμε πως έχει περάσει η ώρα και τρέχουμε σαν τρελοί για να ’μαστε στην ώρα μας στο σχολείο. Έτσι έγινε και σήμερα το πρωί με τον Αλσέστ, τον Εντ, τον Ρούφους και τον Κλοτέρ, που μένουν στη γειτονιά μου.\nΤρέχαμε σαν παλαβοί διασχίζοντας τον δρόμο, για να προλάβουμε να μπούμε στο σχολείο αφού το κουδούνι είχε ήδη χτυπήσει.\nΜετά το διάλειμμα, την τελευταία ώρα του μαθήματος, η δασκάλα μας είπε:\n— Παιδιά, δε θα κάνουμε Γραμματική, όπως λέει το πρόγραμμα... γιατί συνέβη κάτι πολύ σοβαρό. Ο τροχονόμος, υπεύθυνος για την κυκλοφορία έξω από το σχολείο μας, μόλις ήρθε κι έκανε παράπονα στον κύριο Διευθυντή. Είπε πως διασχίζατε τον δρόμο σαν άγρια θηρία τρέχοντας και κάνοντας παλαβομάρες, βάζοντας έτσι σε κίνδυνο τη ζωή σας. Πρέπει να σας πω πως κι εγώ η ίδια σας έχω δει πολλές φορές να τρέχετε σαν τρελοί στον δρόμο. Έτσι λοιπόν για το καλό σας, ο κύριος Διευθυντής μού ζήτησε να σας κάνω ένα μάθημα Κυκλοφοριακής Αγωγής.\n— Μπορεί κάποιος από σας να μου πει τι σημαίνει Κώδικας Οδικής Κυκλοφορίας;\nΟ Ανιάν, ο Μεξάν, ο Ιωακείμ, εγώ κι ο Ρούφους σηκώσαμε το χέρι.\n— Για λέγε, Μεξάν, είπε η δασκάλα.\n— Ο Κώδικας Οδικής Κυκλοφορίας, είπε ο Μεξάν, είναι ένα μικρό βιβλίο που μοιράζουν στις σχολές οδήγησης και πρέπει να το μάθει κανείς απ’ έξω, για να πάρει άδεια οδήγησης.\n— Πολύ σωστά. Ο Κώδικας Οδικής Κυκλοφορίας είναι το σύνολο των κανόνων που ρυθμίζουν τη συμπεριφορά για την ασφάλεια όσων βρίσκονται στον δρόμο. Όχι μόνο των οδηγών, αλλά και των πεζών. Για να γίνεις ένας καλός οδηγός, πρέπει πρώτα να γίνεις και σωστός πεζός. Κι αν δεν κάνω λάθος, φαντάζομαι ότι όλοι σας θα θέλατε να γίνετε καλοί οδηγοί, έτσι δεν είναι; Λοιπόν, για να δούμε... ποιος θα μας πει, ποιες προφυλάξεις πρέπει να πάρει κανείς για να περάσει έναν δρόμο;\nΗ δασκάλα πήγε στον πίνακα κι έκανε ένα σχέδιο με τέσσερις γραμμές που διασταυρώνονταν.\n— Αυτό είναι ένα σταυροδρόμι, μας εξήγησε η δασκάλα. Για να το διασχίσετε, πρέπει να περάσετε από τις διαβάσεις των πεζών, εδώ... εδώ... εδώ...\nκι εδώ. Αν υπάρχει τροχονόμος εκεί, οφείλετε να περιμένετε να σας κάνει σήμα να περάσετε. Αν υπάρχουν φανάρια, τότε πρέπει να περάσετε τη διάβαση, όταν ανάψει το πράσινο για σας. Σε όλες τις περιπτώσεις, οφείλετε να κοιτάτε δεξιά κι αριστερά, προτού να διασχίσετε έναν δρόμο και, κυρίως, να μην τρέχετε ποτέ, μα ποτέ.\nΞαφνικά χτύπησε το κουδούνι. Σηκωθήκαμε με φόρα να φύγουμε, αλλά η δασκάλα μας είπε:\n— Μη βιάζεστε, μη βιάζεστε! Κατεβείτε ήρεμα και θέλω να σας δω να περνάτε τον δρόμο. Να δούμε αν το μάθημα έπιασε τόπο.\nΒγήκαμε από το σχολείο μαζί με τη δασκάλα μας κι ο τροχονόμος, όταν μας είδε, χαμογέλασε. Σταμάτησε τα αυτοκίνητα και μας έκανε σήμα να περάσουμε.\n— Πηγαίνετε, παιδιά, μας είπε η δασκάλα. Και χωρίς τρεχαλητά! Σας βλέπω από εδώ όλους.\nΔιασχίσαμε λοιπόν τον δρόμο πολύ ήσυχα, ο ένας πίσω από τον άλλον κι όταν φτάσαμε στην άλλη πλευρά του δρόμου, είδαμε τη δασκάλα που μιλούσε χαμογελαστή με τον τροχονόμο στο πεζοδρόμιο και τον κύριο Διευθυντή που μας παρατηρούσε από το παράθυρο του γραφείου του.\n— Πολύ καλά! Μπράβο σας! φώναξε η δασκάλα. Ο κύριος τροχονόμος κι εγώ είμαστε πολύ ευχαριστημένοι από σας. Γεια σας, παιδιά μου.\nΚαι τότε ορμήσαμε όλοι και ξαναπεράσαμε τον δρόμο τρέχοντας, για να χαιρετήσουμε από κοντά τη δασκάλα μας!","word_count":603,"page_number":75,"chapter":"Ενότητα 5 — Aσφαλώς... κυκλοφορώ"},{"id":"d_dimotikou_0013","source_id":"d_dimotikou","title":"Ένα αλλιώτικο Πάρκο!","content":"Οι μαθητές στο Πάρκο Κυκλοφοριακής Αγωγής\nΟ Δήμος Καρπενησίου, στο πλαίσιο της «Ευρωπαϊκής Εβδομάδας Μετακίνησης», διοργανώνει επίσκεψη μαθητών των δημοτικών σχολείων στο Πάρκο Κυκλοφοριακής Αγωγής του Δήμου.\nΗ επίσκεψη πραγματοποιείται σήμερα, Τετάρτη 22 Σεπτεμβρίου 2004, στο συγκεκριμένο Πάρκο. Στόχος της επίσκεψης είναι η ενημέρωση των μαθητών σε θέματα οδικής συμπεριφοράς και οδικής ασφάλειας.\nΤα παιδιά περιμένουν με ανυπομονησία τη συγκεκριμένη μέρα, αφού θα διασκεδάσουν και θα μάθουν ταυτόχρονα σημαντικούς κανόνες οδικής συμπεριφοράς.","word_count":72,"page_number":84,"chapter":"Ενότητα 5 — Aσφαλώς... κυκλοφορώ"},{"id":"d_dimotikou_b_0001","source_id":"d_dimotikou_b","title":"Κορίτσι","content":"Δύο συ και τρία γω,\nπράσινο πεντόβολο*\n\nμπαίνω μέσα στον μπαξέ*,\nγεια σου, κύριε Μενεξέ.\n\nΣυντριβάνι και νερό\nκαι χαμένο μου όνειρο.\n\nΤζίντζιρας τζιντζίρισε,\nτο ροδάνι γύρισε.\n\nΧοπ αν κάνω δεξιά\nπέφτω πάνω στη ροδιά.\n\nΧοπ αν κάνω αριστερά\nπάνω στη βατομουριά.\n\nΤο ’να χέρι μου κρατεί\nμέλισσα θεόρατη,\n\nτ’ άλλο στον αέρα πιάνει\nπεταλούδα που δαγκάνει.","word_count":57,"page_number":9,"chapter":"Ενότητα 6 — Ιστορίες παιδιών"},{"id":"d_dimotikou_b_0002","source_id":"d_dimotikou_b","title":"Το μεγάλο μυστικό","content":"Μια παρέα παιδιών, με αρχηγό τον Κωσταντή, ζει σ’ ένα νησί και μαζί σκαρώνουν ένα σωρό τρέλες. Αυτή τη φορά ξεκίνησαν να μαζέψουν αχινούς στην είσοδο μιας σπηλιάς.\nΣυνεχίσαμε την πορεία μας για τη σπηλιά. Όταν φτάσαμε κοντά, ένα κοπάδι γκρίζα αγριοπερίστερα πέταξαν τρομαγμένα, χτυπώντας τα φτερά τους. Καθίσαμε έξω σ’ έναν μεγάλο βράχο, για να ξεκουραστούμε.\nΓύρισα και κοίταξα τη σπηλιά. Το λιγοστό φως της μέρας φώτιζε την είσοδό της. Πιο μέσα όλα ήταν σκοτεινά. Η ώρα κυλούσε ευχάριστα, αλλά ο αέρας δυνάμωσε κι άρχισε να φουρτουνιάζει. Τα αφρισμένα κύματα της θάλασσας μαστίγωναν τα βράχια, για να προχωρήσουν μέχρι μέσα στη σπηλιά και να ξαναβγούν, παρασέρνοντας τις πέτρες και τα βότσαλα της μικρής παραλίας που είχε σχηματιστεί έξω από αυτή.\n— Έχεις μπει ποτέ σου μέσα; ρώτησα τον Κωσταντή.\n— Φυσικά και έχω μπει. Γιατί, εσύ φοβάσαι να μπεις;\nΔίστασα λίγο να απαντήσω.\n— Για να πω την αλήθεια, φοβάμαι.\n— Κοιτάτε, μωρέ, έναν φοβητσιάρη που τον έχουμε και στην ομάδα μας... κορόιδεψε.\nΈσκυψα το κεφάλι από ντροπή. Σε λίγο μπήκαν στη συζήτηση και οι άλλοι.\n— Έχω ακούσει πως κάποτε σ’ αυτήν εδώ τη σπηλιά έκρυβαν οι πειρατές τους θησαυρούς τους, είπε ο Δημήτρης.\n— Δεν ξέρω τι γινόταν παλιά, πήρε και πάλι τον λόγο ο αρχηγός. Εγώ δε βρήκα κανένα θησαυρό. Λοιπόν, για να δούμε ποιος από εσάς έχει ψυχή μέσα του. Όποιο παλικάρι μπει στη σπηλιά, θα του δώσω τη σφυρίχτρα μου. Κοιταχτήκαμε όλοι μεταξύ μας αλλά κανένας δε σηκώθηκε από τη θέση του. Μας είχε κυριεύσει ένα δέος για τον τόπο και τον χώρο αλλά και μια ανατριχίλα για το τι θα συναντούσαμε εκεί μέσα.\n— Μωρέ κάτι παλικάρια που έχω στην ομάδα μου! Κανένας θαρραλέος! συνέχισε ο αρχηγός.\nΚανένας δεν κουνήθηκε από τη θέση του.\n— Γιατί δεν πηγαίνεις εσύ; τον ρώτησε ο Γρηγόρης.\n— Εγώ... κόμπιασε, εγώ έχω ξαναπάει. Αν θέλει, ας μπει κάποιος άλλος.\n— Τότε να πάμε όλοι μαζί, πρότεινε ο Νικολής.\n— Καλή ιδέα, απάντησε με ανακούφιση ο Κωσταντής, βγαίνοντας από τη δύσκολη θέση που βρισκόταν.\n— Να μην προχωρήσουμε πολύ μέσα στη σπηλιά, δε θα βλέπουμε, είπε ο Σταύρακας. Έφυγε και ο ήλιος και σε λίγο θα σκοτεινιάσει περισσότερο.\nΠροχωρήσαμε αργά και φοβισμένα. Σταθήκαμε λίγο για να συνηθίσουν τα μάτια μας στο μισοσκόταδο. Τα πόδια μας βούλιαζαν στη μαλακή άμμο και η υγρασία της ατμόσφαιρας μας πάγωνε ακόμα περισσότερο. Το ξαφνικό πέταγμα ενός θηλυκού περιστεριού, που πύρωνε υπομονετικά τα αβγά του, έκανε το αίμα μας να κυλήσει γρηγορότερα στις φλέβες μας. Το μάτι μας έσκισε το ημίφως της σπηλιάς. Κοιτάζαμε γύρω μας φοβισμένα. Όσο μπορούσαμε να δούμε, διακρίναμε έναν πελώριο θόλο να υψώνεται από πάνω μας. Από την οροφή του κρέμονταν δεκάδες σταλαχτίτες, που από τις άκρες τους έπεφτε, σαν το δάκρυ της μαστίχας, το νερό.\nΚανένας δε μιλούσε. Προσπαθούσαμε να κρατήσουμε μέσα μας αυτή την πρωτόγνωρη εικόνα που βλέπαμε. Η σπηλιά συνεχιζόταν προς τα μέσα αλλά το σκοτάδι μας εμπόδιζε να δούμε.\n— Τι λέτε, να προχωρήσουμε ακόμα λίγο; Η φωνή του\nΠιπίλα έσπασε την ησυχία και τη βουβαμάρα που μας σκέπαζε. Έχω μαζί μου έναν φακό. Πάμε λίγο πιο μέσα να δούμε τι έχει...\nΚανένας δεν απάντησε.\n— Αν πάμε, θα πάμε όλοι μαζί και θα κρατάμε ο ένας το χέρι του άλλου, αποκρίθηκε ο θαρραλέος αρχηγός μας. Συμφωνείτε;\nΓύρισα και κοίταξα προς τα πίσω το άνοιγμα της σπηλιάς. Η απόσταση που μας χώριζε ήταν μικρή αλλά κάθε βήμα προς τα μέσα ήταν αρκετά μέτρα προς το άγνωστο.","word_count":571,"page_number":11,"chapter":"Ενότητα 6 — Ιστορίες παιδιών"},{"id":"d_dimotikou_b_0003","source_id":"d_dimotikou_b","title":"Ο αδελφός της Ασπασίας","content":"Όταν ήμουν πιο μικρός, εκεί κατά την Πρώτη Δημοτικού, τα είχα λιγουλάκι με τον μπαμπά μου. Λιγουλάκι, αλλά πάντως ήμουν θυμωμένος μαζί του. Νόμιζα πως αγαπούσε πιο πολύ την Ασπασία από εμένα. Πώς το νόμιζα; Ε, να! Πρώτα απ’ όλα ήταν τα άλμπουμ με τις φωτογραφίες. Πέντε με φωτογραφίες της Ασπασίας και δυο μόνο με δικές μου.\n«Όλο την Ασπασία βγάζεις φωτογραφία. Αυτήν αγαπάς πιο πολύ!» του έλεγα του μπαμπά.\nΕκείνος με κοίταζε έκπληκτος.\n«Μα, αφού η Ασπασία ζει πιο πολλά χρόνια απ’ ό,τι εσύ, φυσικό είναι να έχει βγάλει πιο πολλές φωτογραφίες!»\nΔίκιο είχε, αλλά εγώ δεν το έβλεπα.\nΈπειτα ήταν κι άλλα.\nΠαρακολουθούσαμε, για παράδειγμα, όλοι μαζί τηλεόραση. Εγώ καθόμουνα με τα πόδια απλωμένα πάνω στο τραπεζάκι.\n«Κάτω τα πόδια σου, θα γδάρεις το έπιπλο!» μου φώναζε ο μπαμπάς.\n«Όλο σ’ εμένα φωνάζεις! Ποτέ και στην Ασπασία! Εκείνη αγαπάς, όχι εμένα!» έλεγα εγώ.\nΚαι ξανά ο μπαμπάς με κοιτούσε με έκπληξη.\n«Μα η Ασπασία κάθεται κανονικά!» μου έλεγε. «Γιατί να τη μαλώσω;»\nΔίκιο είχε, αλλά εγώ...\nΕ, ήμουνα ζηλιάρης. Να το παραδεχτώ.\nΈπειτα ήταν κι η μαμά. Αυτή άλλα έλεγε.\nΌταν, ας πούμε, εγώ έμπαινα στο δωμάτιο της Ασπασίας και της ανακάτευα τα... ψιλικά της κι εκείνη άρχιζε τα: «Στρίβε! Φύγε!» (και άλλα τέτοια), η μαμά έβαζε τις φωνές στην κόρη της: «Μα σταμάτα πια! Καθόλου υπομονή δεν έχεις! Παιδί είναι!».\nΕ, άκουγα εγώ κάτι τέτοια κι έλεγα πως για τη μαμά δεν υπάρχει καμιά αμφιβολία. Μ’ αγαπούσε πιο πολύ από την αδελφή μου. Δεν ήταν σαν τον μπαμπά, που όλο απαιτήσεις είχε από εμένα, άρα...\nΛοιπόν, ο μπαμπάς κι η μαμά, δεν μπορώ να πω, σε πολλά συμφωνούν, αλλά και σε πολλά διαφωνούν. Συνήθως, συμφωνούν στα βιβλία που διαβάζουν. Τα ίδια αρέσουν και στους δυο, τα ίδια και στους δυο δεν αρέσουν. Εκεί που διαφωνούν είναι στο πώς πρέπει να αντιμετωπίζουν την Ασπασία.\nΟ μπαμπάς πάντα τη δικαιολογεί: «Ε, ας έχει κι αυτή κάποιο ελάττωμα. Καλή μαθήτρια είναι, ήσυχος χαρακτήρας. Το μόνο κακό που έχει είναι πως είναι λίγο καβγατζού!»\nΗ μαμά όμως έχει άλλη γνώμη.\n«Εσύ τη χάλασες, μ’ όλα τα χατίρια που της κάνεις και να που κατάντησε να μην υπολογίζει κανέναν!»\nΚαι, όταν η Ασπασία τους ακούει να λένε όλα αυτά, αρχίζει τις μουρμούρες, δήθεν ετοιμάζεται να κλάψει και τελικά προτιμά να βροντήξει την πόρτα της κάμαράς της και να βάλει δυνατά το στερεοφωνικό της.\nΓια μένα δε διαφωνούν. Συμφωνούν κι οι δυο πως έχω καλή καρδιά και πως, αν κάποια στιγμή με μαλώσουν κι εγώ βάλω τα κλάματα, το επόμενο κιόλας λεπτό έχω ξεθυμώσει.\nΤέλος πάντων! Χαρακτήρες, όπως συνηθίζει να λέει κι η γιαγιά, αλλά εγώ το ξαναλέω: τη ζήλευα την Ασπασία.\nΌμως αργότερα μου πέρασε... Δηλαδή δε μου πέρασε ακριβώς. Μια και τα λέμε μεταξύ μας, ας το ομολογήσω: την Ασπασία τη ζηλεύω ακόμα! Μα... συνάμα και την αγαπώ, όπως κι αυτή μ’ αγαπάει. Α, η αλήθεια να λέγεται. Αλλά γιατί να έχει γεννηθεί πριν από εμένα; Και έτσι τώρα είναι η πιο μεγάλη από τους δυο μας! Αδικία!","word_count":497,"page_number":16,"chapter":"Ενότητα 6 — Ιστορίες παιδιών"},{"id":"d_dimotikou_b_0004","source_id":"d_dimotikou_b","title":"Η Ελιά","content":"Είμαι του ήλιου θυγατέρα*\nη πιο απ’ όλες χαϊδευτή,\nχρόνια η αγάπη του πατέρα\nσ’ αυτόν τον κόσμο με κρατεί.\nΌσο να γείρω νεκρωμένη,\nαυτόν το μάτι μου ζητεί.\nΕίμαι η ελιά η τιμημένη!\n\nΌπου κι αν λάχω* κατοικία,\nδεν μου απολείπουν οι καρποί.\nΩς τα βαθιά μου γερατεία\nδε βρίσκω στη δουλειά ντροπή.\nΜ’ έχει ο Θεός ευλογημένη\nκι είμαι γεμάτη προκοπή.\nΕίμαι η ελιά η τιμημένη!\n\nΦρίκη, ερημιά, νερό, σκοτάδι,\nτη γη τη θάψαν μια φορά.\nΕμέ ζωής φέρνει σημάδι\nστο Νώε η περιστερά.\nΌλης της γης είχα γραμμένη\nτην ομορφάδα και χαρά.\nΕίμαι η ελιά η τιμημένη!\n\nΕδώ στον ίσκιο μου αποκάτου\nήρθ’ ο Χριστός ν’ αναπαυθεί\nκι ακούστηκε η γλυκιά λαλιά Του\nλίγο προτού να σταυρωθεί.\nΤο δάκρυ Του, δροσιά αγιασμένη,\nέχει στη ρίζα μου χυθεί.\nΕίμαι η ελιά η τιμημένη!","word_count":135,"page_number":29,"chapter":"Ενότητα 7 — Η ελιά"},{"id":"d_dimotikou_b_0005","source_id":"d_dimotikou_b","title":"Οι μύθοι και η ελιά","content":"Η ελιά δώρο της Αθηνάς\nΟ πιο γνωστός αρχαίος μύθος που αναφέρεται στην καλλιέργεια της ελιάς είναι εκείνος που θεωρεί το δέντρο δώρο της Αθηνάς. Όλα ξεκίνησαν από τη διαμάχη ανάμεσα στην Αθηνά και στον Ποσειδώνα που μάλωναν για την κυριαρχία στην Αττική.\nΑποφασίστηκε να προσφέρει ο καθένας από ένα δώρο ακριβό. Νικητής σ’ αυτό τον διαγωνισμό θα ήταν εκείνος που η προσφορά του θα ήταν η πιο πολύτιμη για την πόλη.\nΟ Ποσειδώνας, θεός-κυρίαρχος των θαλασσών, σήκωσε την τρίαινά του και την κάρφωσε στον ιερό βράχο της Ακρόπολης. Αλμυρό νερό άρχισε να αναβλύζει και να κυλά στα ριζά του βράχου. Πίστευε ο Ποσειδώνας πως αυτή η πηγή στο άνυδρο τοπίο της Αττικής θα μπορούσε να του προσφέρει τη νίκη. Η Αθηνά δε χρειάστηκε να κάνει καμιά εντυπωσιακή κίνηση.","word_count":129,"page_number":32,"chapter":"Ενότητα 7 — Η ελιά"},{"id":"d_dimotikou_b_0006","source_id":"d_dimotikou_b","title":"Η ελιά στην Ελλάδα και στη Μεσόγειο","content":"Η ελιά εμφανίστηκε για πρώτη φορά ως αγριελιά στην ανατολική Μεσόγειο, εκεί δηλαδή όπου αναπτύχθηκαν μερικοί από τους αρχαιότερους πολιτισμούς. Σε αρχαιολογικές έρευνες που έγιναν στις Κυκλάδες βρέθηκαν απολιθωμένα* φύλλα ελιάς, τα οποία υπολόγισαν ότι είναι 50-60.000 ετών. Στις πινακίδες της Γραμμικής Β γραφής που ανακαλύφθηκαν στην Αρχαία Πύλο υπάρχει το ιδεόγραμμα* της ελιάς και του ελαιόλαδου.\nΣτις αρχαίες τελετές, το δέντρο της ελιάς ήταν το δέντρο του καλού κι αυτό του έδινε μια ξεχωριστή θέση. Αυτό το πολύτιμο και αγαπημένο δέντρο των Ελλήνων και των άλλων μεσογειακών λαών θεωρείται, ακόμα μέχρι σήμερα, θεϊκό δώρο, σύμβολο ειρήνης, προστασίας και γονιμότητας. Το λάδι του, όπως το σιτάρι και το κρασί, χρησιμοποιείται σε πολλές τελετές της ορθόδοξης χριστιανικής θρησκείας.","word_count":117,"page_number":36,"chapter":"Ενότητα 7 — Η ελιά"},{"id":"d_dimotikou_b_0007","source_id":"d_dimotikou_b","title":"Μαγειρεύουμε με ελαιόλαδο","content":"Οι ελιές και το ελαιόλαδο αποτελούν, εδώ και αιώνες, απαραίτητο στοιχείο της ελληνικής και της μεσογειακής κουζίνας. Μας προσφέρουν καθημερινά μια υγιεινή και πλούσια σε γεύση τροφή. Από μελέτες σε 7 χώρες προέκυψε ότι η διατροφή που βασίζεται στο ελαιόλαδο δίνει στον άνθρωπο υγεία και μακροζωία. Το ελαιόλαδο μπορεί να χρησιμοποιηθεί σε όλα τα φαγητά και γι’ αυτό όλοι οι διαιτολόγοι το συνιστούν. Για ακόμη πιο υγιεινό φαγητό, το ελαιόλαδο πρέπει να προστεθεί στο τέλος του μαγειρέματος. Όταν χρησιμοποιείται ωμό, αποκαλύπτει όλη του τη νοστιμιά. Δίνει άλλη γεύση στις σαλάτες και στα λαχανικά.","word_count":93,"page_number":41,"chapter":"Ενότητα 7 — Η ελιά"},{"id":"d_dimotikou_b_0008","source_id":"d_dimotikou_b","title":"Η μπουγάδα του Αϊ-Βασίλη","content":"Σήμερα ο Αϊ-Βασίλης ξυπνά απ’ τα χαράματα. Έξι μόνο μέρες μένουν ως την παραμονή της Πρωτοχρονιάς κι ένα σωρό δουλειές τον περιμένουν: να τυλίξει τα τελευταία του πακέτα, να επισκευάσει το έλκηθρό του, να ετοιμάσει την επίσημη στολή του, αυτή την κόκκινη, που βάζει μια φορά το χρόνο στο μοίρασμα των δώρων.\nΓια να δει αν είναι εντάξει, την ξεκρεμά από την ντουλάπα του και, βάζοντας τα γυαλιά του, την εξετάζει προσεχτικά.\n«Μια χαρά είναι! Ένα σιδερωματάκι θέλει μόνο».\nΌμως οχ! Εκεί μπροστά… ένας απαίσιος μαύρος λεκές στολίζει το αριστερό του μανίκι. «Κοίτα να δεις! Ένας τεράστιος λεκές. Σίγουρα θα έγινε από τις καπνιές σε κάποια καμινάδα» ψιθυρίζει ο Αϊ-Βασίλης και νευριασμένος τη χώνει βιαστικά μέσα στο πλυντήριο.\nΜετά από λίγο βγαίνει στην αυλή, ν’ απλώσει την μπουγάδα του. Πρώτα κρεμάει τις κάλτσες του, ύστερα τη φανέλα, το μακρύ του σώβρακο, το σκούφο του, το πουκάμισο και τελευταία το σακάκι και το παντελόνι του.\n«Ποπό! Ζημιά! Αδύνατον!» φωνάζει απελπισμένος.\nΤο πανωφόρι με τις άσπρες γούνες, το γυαλιστερό του παντελόνι, το πουκάμισο, οι κάλτσες μαζί με το σκουφί του κρέμονται στο σχοινί αγνώριστα! Έχουν γίνει μικρά, τόσο μικρά, που δε χωρούν να μπουν μήτε στο μικρό του δαχτυλάκι.\n«Τι θα φορέσω τώρα;» ανησυχεί. «Πώς θα μοιράσω τα δώρα; Δεν έχω άλλα επίσημα ρούχα! Πού να βρω καινούρια; Κάτι πρέπει να σκεφτώ» βηματίζει πέρα δώθε. Ώσπου τελικά το πρόσωπό του φωτίζεται.\n«Γιούπι! Το βρήκα! Θα ζητήσω από τα παιδιά να με βοηθήσουν» αποφασίζει και, δίχως να χάσει καιρό, απλώνει στο πάτωμα ένα χάρτη με όλους τους τόπους της γης.\n«Μμμμ! Μάλιστα! Θα τους στείλω από ένα γράμμα» ψιθυρίζει. Αμέσως κάθεται στο γραφείο του και γράφει πέντε όμορφα γράμματα.\nΑπό τα παιδιά της Αφρικής ζητά να του στείλουν ένα πουκάμισο, από τα παιδιά της Ασίας μάλλινες κάλτσες, από τα παιδιά της Αμερικής ένα σακάκι με ζεστές γούνες, από τα παιδιά της Αυστραλίας ένα μακρύ παντελόνι κι από τα παιδιά της Ευρώπης ένα σκούφο. Όλα σε μεγάλο νούμερο.\nΌταν τελειώνει το γράψιμο, πηγαίνοντας στην άκρη του ουρανού, τα σκορπίζει πάνω στη γη. Οι φάκελοι σαν χάρτινη βροχή φτάνουν στα χέρια των παιδιών, σε κάθε γωνιά του κόσμου.\nΕ! Από εκείνη τη στιγμή, ο Αϊ-Βασίλης ησυχία δεν μπορεί να βρει. Μια έννοια τον βασανίζει.\n«Θα πιστέψουν στο γράμμα μου τα παιδιά και θα μου στείλουν ό,τι τους ζητώ ή θα το πάρουν για αστείο και θα γελάσουν;» αναρωτιέται.\nΚάθε φορά που ακούει θόρυβο, τρέχει στην πόρτα. Μα του κάκου… Περνά μια μέρα…\nδυο… τρεις… τίποτα ακόμα.\nΣαν ξημερώνει πια κι η τελευταία μέρα, πριν την παραμονή της Πρωτοχρονιάς, κοντεύει να σκάσει από τη στενοχώρια.\n«Μα πουθενά; Ούτε ένα παιδί δε με σκέφτηκε; Εγώ ποτέ δεν ξέχασα κανένα» παραπονιέται στριφογυρίζοντας στο κρεβάτι του.\nΜα άξαφνα, μέσα στη νύχτα, ντριν ντριν το κουδούνι χτυπά. Μπροστά στην πόρτα, πέντε μεγάλα πολύχρωμα πακέτα τον περιμένουν.\n«Ζήτω! Ήρθαν τα δώρα μου! Τα παιδιά με θυμήθηκαν» φωνάζει καθώς ξετυλίγει με λαχτάρα. «Να το κόκκινο σακάκι! Το παντελόνι! Το φαρδύ πουκάμισο! Οι ζεστές καλτσούλες κι ο θαυμάσιος σκούφος με το χρυσό κουδουνάκι στην άκρη του».\n«Είναι καταπληκτικό! Eίναι υπέροχο ν’ ανοίγεις πακετάκια που μέσα τους υπάρχουν πανέμορφα δωράκια…» τραγουδά, δοκιμάζοντας ένα ένα τα κομμάτια της ολοκαίνουριας φορεσιάς του.\n«Μμμ! Άργησα, μα επιτέλους το κατάλαβα! Τώρα ξέρω γιατί με περιμένουν με λαχτάρα και μ’ αγαπούν τόσο πολύ μικροί, μεγάλοι» μουρμουρίζει κλείνοντας πονηρά το μάτι στον καθρέφτη.\nΚι επειδή ο καημένος ο Αϊ-Βασίλης πρώτη, μα πρώτη, φορά στη ζωή του παίρνει δώρα, βάζει τα κλάματα από τη χαρά του.","word_count":575,"page_number":53,"chapter":"Ενότητα 8 — Χριστός γεννάται"},{"id":"d_dimotikou_b_0009","source_id":"d_dimotikou_b","title":"Μια περιπέτεια για τον Ρωμαίο","content":"Η οικογένεια του κυρίου Όμηρου ζει σ’ ένα ψηλό παλιό κτίριο. Σ’ όλο τον κόσμο δεν υπάρχει οικογένεια ποντικών που να ζει σ’ ένα τόσο μεγάλο σπίτι! Δεν είναι ένα συνηθισμένο σπίτι, αφού δεν έχει κουζίνα, κρεβατοκάμαρες, σαλόνι και τραπεζαρία αλλά μόνο πολλά καθίσματα και μια τεράστια σκηνή όπου όλα τα απίθανα του κόσμου μπορούν να συμβούν. Το λένε θέατρο.\nΟ κύριος Όμηρος έμενε εδώ από πάντα. Θυμάται την πρώτη πρεμιέρα, την πιο λαμπερή απ’ όλες. Ήταν μικρούλης τότε κι έμενε με τους γονείς του στην υγρή αποθήκη. Ονειρευόταν όμως ότι μια μέρα θ’ ανέβει ψηλά, θα φτιάξει το δικό του ποντικόσπιτο δίπλα στη σκηνή του θεάτρου. Και τα κατάφερε. Σε μια όμορφη τρύπα μεγαλώνει, μαζί με τη γυναίκα του τη Λαβίνια, τον αγαπημένο του και μονάκριβο γιο, τον Ρωμαίο.\nΟ μικρούλης Ρωμαίος δεν έχει δει ακόμα καμιά παράσταση, γιατί οι γονείς του φοβούνται και δεν τον αφήνουν ν’ απομακρυνθεί από τη φωλίτσα τους. Όμως ο Ρωμαίος ξέρει χιλιάδες πράγματα για το θέατρο, γιατί ο μπαμπάς του δεν κάνει τίποτα άλλο απ’ το να μιλάει γι’ αυτό. Όταν ο κύριος Όμηρος διηγείται θεατροϊστορίες, ξεχνάει να φάει και να κοιμηθεί, να πλυθεί, να ντυθεί, να κάνει όλα όσα κάνει δηλαδή ένας συνηθισμένος ποντικομπαμπάς. Ο Ρωμαίος βέβαια δεν ξέρει πώς είναι οι άλλοι, συνηθισμένοι ποντικομπαμπάδες, αφού δε γνώρισε κανέναν άλλον εκτός απ’ τον δικό του.\nΗ Λαβίνια, η μαμά του Ρωμαίου, είναι μια όμορφη και χαριτωμένη ποντικίνα, που μοναδικό της όνειρο είναι μια μέρα να παίξει στη σκηνή του θεάτρου, να γίνει δηλαδή θεατρίνα. Ξέρει όλα τα έργα απέξω κι ανακατωτά και κάθε φορά που ο μικρός Ρωμαίος είναι κακόκεφος του προτείνει:\n— Πες μου, τι θες να σου παίξω; Κωμωδία ή δράμα; Δηλαδή αστείο ή λυπητερό;\nΕίναι οι καλύτερες στιγμές αυτές για τον Ρωμαίο: όταν έξω βρέχει, όταν ο μπαμπάς του έχει θυμηθεί να του φέρει ένα νόστιμο τυράκι κι όταν η μαμά του παίζει θέατρο.\nΟ Ρωμαίος δεν έχει πάει σχολείο αλλά ξέρει ένα σωρό πράγματα. Δίπλα στο σπίτι τους υπάρχει ένα ράφι με βιβλία. Ο Ρωμαίος έχει ήδη δει σε φωτογραφίες τα ζώα του δάσους, τα ζώα του αγροκτήματος, τα ζώα του Βόρειου Πόλου. Έχει δει πολλά βιβλία για το θέατρο. Ξέρει δηλαδή ότι το θέατρο είναι ένας μεγάλος καθρέφτης της ζωής. Όλα όσα συμβαίνουν στη ζωή μπορείς να τα δεις στο θέατρο. Κι όχι μόνο αυτά: μπορείς να δεις κι άλλα, πολλά. Όσα μπορείς να ονειρευτείς, να φανταστείς.","word_count":400,"page_number":59,"chapter":"Ενότητα 9 — Η παράσταση αρχίζει"},{"id":"d_dimotikou_b_0010","source_id":"d_dimotikou_b","title":"Πρώτη φορά στο θέατρο","content":"Η Ελευθερία, ένα δεκάχρονο κορίτσι, ζει με τους γονείς της και τα δίδυμα αδέρφια της στο Μαρούσι. Tο τελευταίο καλοκαίρι πριν από τον πόλεμο του 1940, o κύριος Μαρσέλ με τον ανιψιό του τον Μπενουά ήρθαν να μείνουν στο πάνω πάτωμα του σπιτιού τους. Τα παιδιά έγιναν αχώριστοι φίλοι. Σ’ αυτή την ιστορία, ο κύριος Μαρσέλ, η Ελευθερία και ο Μπενουά πηγαίνουν στο θέατρο.\nΔεν έσκαγα για το φουστάνι μου, γιατί δε σκεφτόμουνα τίποτ’ άλλο από το θέατρο. Όταν όμως κατέβηκαν ο κύριος Μαρσέλ με τον Μπενουά για να με πάρουν και τους είδα ντυμένους και τους δυο με μπλε σακάκια και παπιγιόν –μάλιστα, φορούσε κι ο Μπενουά παπιγιόν!–, ένιωσα πολύ άσχημα μέσα στο άσπρο μου φουστανάκι με το σημάδι στο στρίφωμα.\nΤα δίδυμα βάλανε τα γέλια όταν είδαν τον Μπενουά με παπιγιόν.\n— Βρε Μπενουδάκο, σαν τζιτζιφιόγκος μοιάζεις.\n— Τι θα πει τζιτζιφιόγκος; με ρώτησε ο Μπενουά.\n— Πολύ κομψός, απάντησα κι έριξα μια κακιά ματιά στ’ αδέρφια μου.\nΠήραμε το τρένο και μετά ένα τραμ για να φτάσουμε στο θέατρο. Στη διαδρομή, ο κύριος Μαρσέλ μάς εξηγούσε ότι θα πάμε στο Ηρώδειον και θα δούμε την Αντιγόνη. Όχι, δεν ήταν η Αντιγόνη του Ηρώδη. Ηρώδειον λεγότανε το θέατρο που πηγαίναμε. Την Αντιγόνη την έγραψε ο αρχαίος Σοφοκλής.\nΟ κύριος Μαρσέλ έδειξε τις προσκλήσεις στον κύριο που στεκόταν στην είσοδο και, δεν κατάλαβα γιατί, του είπε πως είμαστε Γάλλοι. Όταν αργότερα τον ρώτησα γιατί το είπε, μου απάντησε πως φοβήθηκε μήπως δεν άφηναν εμένα και τον Μπενουά να περάσουμε, επειδή ήμαστε παιδιά. Όταν είχαμε πια καθίσει στις θέσεις μας, πρόσεξα πως σ’ όλο το θέατρο δεν υπήρχε κανένα άλλο παιδί εκτός από μας.\nΕίχαμε φτάσει αρκετά νωρίς και το θέατρο ήταν σχεδόν άδειο. Φανταζόμουνα πως θα είχε ψάθινες καρέκλες, όπως η «Τιτάνια» του Μαρουσιού. Μα αυτό είχε μαρμάρινα καθίσματα ως επάνω επάνω. Στην πρώτη σειρά, τα καθίσματα είχανε πλάτη και μοιάζανε με θρόνο. Μια γυναίκα με μπλε ποδιά πήρε τις προσκλήσεις μας και μας είπε να την ακολουθήσουμε. Αυτή μπροστά κι εμείς ξοπίσω ανεβαίναμε τα μαρμάρινα σκαλοπάτια. Είχαμε ανέβει αρκετά και τότε στάθηκε και μας έδειξε τη σειρά που έπρεπε να καθίσουμε. Φοβήθηκα πως δε θ’ ακούγαμε τόσο ψηλά που ήμαστε, ο κύριος Μαρσέλ όμως είπε πως τα παλιά χρόνια ξέρανε και φτιάχνανε τα θέατρα έτσι που ν’ ακούνε όλοι όπου κι αν κάθονται.\nΣιγά σιγά το θέατρο άρχισε να γεμίζει και τότε χαρήκαμε με τον Μπενουά που καθόμασταν ψηλά, γιατί ήταν πολύ διασκεδαστικό να βλέπουμε τον κόσμο που έμπαινε. Πολλοί περνούσαν μπροστά από την πρώτη σειρά και χαιρετούσαν αυτούς που είχαν καθίσει εκεί. Ο κύριος Μαρσέλ μάς είπε πως αυτοί είναι οι επίσημοι. Σηκωθήκαμε με τον Μπενουά όρθιοι να δούμε πιο καλά τους επισήμους. Μοιάζανε σαν όλο τον κόσμο κι απορούσα πώς τους ξεχώριζαν.\nΤα φώτα χαμήλωσαν, έσβησαν κι ακούστηκε ένας ήχος που έμοιαζε με καμπάνα αλλά δεν ήταν καμπάνα. Χτύπησε τρεις φορές.\n— Αρχίζει, ψιθύρισε ο κύριος Μαρσέλ.","word_count":481,"page_number":71,"chapter":"Ενότητα 9 — Η παράσταση αρχίζει"},{"id":"d_dimotikou_b_0011","source_id":"d_dimotikou_b","title":"Γλωσσική αυτοβιογραφία","content":"Πώς πρωτογνώρισα, πώς πρωτοαντίκρισα στη ζωή μου τη Γλώσσα δε θυμάμαι καλά καλά. Όταν άρχισα να πρωτολέω τα λόγια που λένε σήμερα κι οι κούκλες, όταν τους ζουλούνε το στομάχι τους, δεν ήξερα πως το πράγμα αυτό λέγεται: Γλώσσα. Έμαθα να μιλώ, όπως έμαθα να τρώω, να περπατώ και να τραβώ τα γένια του πατέρα μου. Όλοι μιλούσαν γύρω μου και μου φαινότανε πολύ φυσικό. Το μόνο που μου φαινότανε αφύσικο ήταν γιατί δε μιλούσε σαν εμένα κι η γάτα μας. Της έκανα πολλές τυραννίες, την τσίμπησα, της έσφιξα τον λαιμό, τη μάδησα για να μιλήσει, μα επειδή και καλά δεν ήθελε να βγάλει λέξη, το πήρα απόφαση. Τότε η μητέρα μου μου είπε πως η γάτα είχε τη δική της γλώσσα. Ήτανε η πρώτη φορά που έλαβα κάποια ιδέα πως υπάρχει μια γλώσσα που μιλούσα εγώ κι άλλη μια που μιλούσε η γάτα μας και πως με το στανιό δεν μπορούσα να την κάνω να μιλάει σαν κι εμένα.\nΎστερα άκουσα κι άλλους ανθρώπους, που μιλούσαν και δεν τους καταλάβαινα. Ήτανε ένας Ιταλός ψαράς, μια ξανθή δασκάλα κι ο γιατρός του σπιτιού μας. Όταν τους άκουγα, μ’ έπιαναν τα γέλια. Είχαν κι αυτοί τη γλώσσα τη δική τους, κι επειδή όλες οι ξένες γλώσσες μού φαίνονταν ένα πράμα, είχα την ιδέα πως η γάτα μας καταλάβαινε τι έλεγαν. Ύστερα η μητέρα μου μου είπε πως ο ψαράς μιλούσε ιταλικά, η δασκάλα γερμανικά κι ο γιατρός στην καθαρεύουσα*. Έπειτα τα συνήθισα όλα αυτά, όπως συνηθίζει καθένας κάθε παράξενο, και μου ’μενε η διασκέδαση, όταν έβλεπα τον ψαρά, να φωνάζω ξεκαρδισμένος, πίσω από κανένα έπιπλο: πέσι! πέσι! όταν έβλεπα τη δασκάλα: φροϊλάιν, φροϊλάιν! κι όταν έβλεπα τον γιατρό: φέψη, φέψη. Το φέψη αυτό υποθέτω τώρα πως ήθελε να πει: αφέψημα*.","word_count":289,"page_number":86,"chapter":"Ενότητα 10 — Λέξεις φτερουγίζουν πέρα,"},{"id":"d_dimotikou_b_0012","source_id":"d_dimotikou_b","title":"Xορεύοντας με... ανήκουστους ήχους","content":"Η Ευγενία είναι ένα δεκάχρονο πολύ έξυπνο κοριτσάκι, το οποίο δεν κληρονόμησε το «προνόμιο» να ακούει τους ήχους... Είναι με λίγα λόγια μέλος της κοινότητας των κωφών. Διαθέτει εκπληκτική εκφραστικότητα, κατέχει την «επίσημη γλώσσα» των κωφών, τη νοηματική γλώσσα, και είναι πολύ καλή χειλεαναγνώστρια*. Τη γνώρισα τυχαία σε ένα πάρτι κωφών.\nΗ μικρή Ευγενία κάνει παρέα με κωφά και ακούοντα παιδιά και η πιο στενή της φίλη είναι ένα ακούον κοριτσάκι από την Κρήτη, η Στεφανία. Από την παρέα με την Ευγενία, η Στεφανία κατάφερε να μάθει αρκετά τη νοηματική γλώσσα, επομένως τίποτε δεν εμποδίζει την επικοινωνία τους. Το προηγούμενο καλοκαίρι, όταν είχε πάει στην Κρήτη για να περάσουν μαζί τις διακοπές, η Ευγενία εντυπωσιάστηκε πολύ από τα παπούτσια του μπαλέτου της Στεφανίας. Η Στεφανία τής εξηγούσε πως χορεύοντας νιώθει σαν να πετάει. Είδαν μαζί και τη βιντεοκασέτα από τις πρόβες της Στεφανίας στο μπαλέτο. «Θέλω και εγώ να νιώθω σαν να πετάω, όπως εσύ», είπε η Ευγενία στη φίλη της.\nΈπειτα από λίγο καιρό, όταν γύρισε στην Αθήνα, η Ευγενία γράφτηκε κανονικά στη σχολή μπαλέτου. Η δασκάλα του μπαλέτου τη δέχθηκε με χαρά και εξήγησε στα άλλα παιδιά πως η Ευγενία δεν ακούει τους ήχους, όπως τους ακούν εκείνοι, αλλά πως ο χορός είναι πάνω από όλα «η γλώσσα του σώματος».\nΗ αρχή δεν ήταν εύκολη. Ο πρώτος ενθουσιασμός της Ευγενίας άρχισε να υποχωρεί. Φοβόταν μήπως δεν τα καταφέρνει. Σημαντικό ρόλο για να επιμείνει έπαιξαν ο πατέρας και η δασκάλα της. «Τίποτε δε μας χαρίζεται στη ζωή. Ούτε στους κωφούς ούτε στους ακούοντες. Τα πάντα κατακτούνται με θάρρος και προσπάθεια», της είπε ο πατέρας της.\nΈπειτα από έναν χρόνο και προπαντός χάρη στο πάθος της για τον χορό, η Ευγενία έχει ενταχθεί με πλήρη επιτυχία στην ομάδα μπαλέτου. Θα αναρωτηθείτε «μα πώς ακολουθεί τον ρυθμό, αφού δεν ακούει τους ήχους;». Την ίδια ερώτηση έκανα και εγώ. «Τη μουσική τη νιώθω από τις δονήσεις, αφού υπάρχει ξύλινο πάτωμα στην αίθουσα», μου εξηγεί η Ευγενία.\nΤην ημέρα που τη γνώρισα ήταν κάπως αγχωμένη, διότι ετοιμαζόταν για την πρώτη της παράσταση. Στο θέατρο θα υπάρχει και διερμηνέας για τους κωφούς θεατές...\nΦεύγοντας από το πάρτι ευχήθηκα στην Ευγενία «καλή επιτυχία». Στη Νοηματική Γλώσσα βέβαια.","word_count":362,"page_number":90,"chapter":"Ενότητα 10 — Λέξεις φτερουγίζουν πέρα,"},{"id":"d_dimotikou_b_0013","source_id":"d_dimotikou_b","title":"Γραφή, η μνήμη των ανθρώπων","content":"Πριν αναπτυχθεί η γραφή, οι άνθρωποι συγκρατούσαν όλες τις πληροφορίες στο μυαλό τους. Όμως είναι δύσκολο να θυμόμαστε τα πάντα και να τα μεταφέρουμε με ακρίβεια σε άλλους. Η γραφή είναι ένας τρόπος με τον οποίο αποθηκεύουμε και μεταφέρουμε πληροφορίες σε ανθρώπους με τους οποίους μας χωρίζει ο χρόνος και η απόσταση. Δεν ανακαλύφθηκε από ένα άτομο ή μία κοινωνία.\nΕξελίχθηκε σε διαφορετικά μέρη και περιόδους με σκοπό τη διατήρηση αρχείων και την καταγραφή γεγονότων. Έχει πολλές μορφές, από την απλή εικονογραφία έως την τυποποιημένη γραφή, που απεικονίζει τους ήχους μιας γλώσσας και αποτυπώνεται σε κάθε είδους υλικό, από χαρτί έως κεραμικά. Σήμερα, η γραφή αποτελεί αναπόσπαστο κομμάτι της καθημερινής ζωής.","word_count":111,"page_number":94,"chapter":"Ενότητα 10 — Λέξεις φτερουγίζουν πέρα,"},{"id":"d_dimotikou_g_0001","source_id":"d_dimotikou_g","title":"Φρουτοπία","content":"Η Φρουτοπία, η χώρα των φρούτων, γιορτάζει τον πρώτο χρόνο της ανεξαρτησίας της από τους μανάβηδες. Ο Αιμίλιος το μήλο, ο αρχηγός των φρούτων, υποδέχεται σε μεγάλη δεξίωση στο προεδρικό μέγαρο τους πολλούς καλεσμένους του. Ανάμεσά τους η διάσημη σοπράνο Ευρυδίκη Ντεσιμπέλ, που δίνει μια συνέντευξη στον δημοσιογράφο της εφημερίδας «Τρέχα γύρευε» Πίκο Απίκο.","word_count":54,"page_number":16,"chapter":"Ενότητα 11 — Γελάσαμε με την ψυχή μας"},{"id":"d_dimotikou_g_0002","source_id":"d_dimotikou_g","title":"Τρύπωνας ο φαφαγάλος","content":"Η κυρία Καλλιόπη έχει στο σπίτι της ένα καναρίνι και έναν παπαγάλο που τον λένε Τρύφωνα. Ο Τρύφωνας μιλάει αλλά μπερδεύει το πι με το φι. Ο Μάριος και η Αλεξάνδρα είναι αδέρφια που ζουν στο διπλανό σπίτι και διασκεδάζουν πολύ ακούγοντας τον Τρύφωνα να μιλάει. Ο Μάριος και η Αλεξάνδρα φέρνουν στην κυρία Καλλιόπη ένα πιάτο με γλυκά που στέλνει η μαμά τους.\nκυρία Καλλιόπη.\nΠριν καλά καλά η κυρία Καλλιόπη τους πει ευχαριστώ, ο Τρύφωνας πετάγεται και λέει:\n— Εμένα απτά τα κανταΐπια μ’ αρέσουν φολύ...\n— Δεν είναι κανταΐφι, Τρύφωνα, είναι γαλακτομπούρεκο, του λέει η κυρία Καλλιόπη και πετάει μια καθαρισμένη πατάτα μέσα στην κατσαρόλα με το νερό. Πάντως, εσύ δεν πρόκειται να φας ούτε μια μπουκιά αν δε βεβαιωθώ πρώτα ότι ξέρεις τη γραμματική σου.\n— Εγώ τη γραμματική την μπερδεύω λιγάκι με τη γυμναστική, αλλά δεν κάνω φοτέ λάθη.\n— Πρέπει να κάνουμε λάθη, Τρύφωνα, γιατί έτσι μαθαίνουμε. Τι λες κι εσύ, Μάριε; λέει η\n— Ο δάσκαλός μας έχει πει να μη φοβόμαστε τα λάθη μας, αλλά να τα αγαπάμε, γιατί αυτά μας μαθαίνουν το σωστό, απαντάει ο Μάριος.\n— Πολύ σωστά, Μάριε, λέει η κυρία Καλλιόπη. Τ’ άκουσες, Τρύφωνα;\n— Το άκουσα όλο.\n— Άντε, καμάρι μου, έλα να μάθουμε λιγάκι τους τόνους. Θα σε βοηθήσουμε κι εγώ και τα παιδιά.\nΟ Τρύφωνας δίνει ένα σάλτο τώρα και βολεύεται πάνω στο κλουβί.\n— Ρώτα με, Καλλιόφη! Για ν’ ακούσει και το καναρίνι φόσο καλός είμαι!\n— Πες μου λοιπόν, αρχίζει η κυρία Καλλιόπη χαμογελώντας, πού τονίζεται η λέξη λαγός;\n— Στο λου! απαντάει γρήγορα ο Τρύφωνας.\nΗ κυρία Καλλιόπη αφήνει κάτω την πατάτα και τον κοιτάζει αυστηρά.\n— Πρώτ’ απ’ όλα, Τρύφωνα, δεν το λένε λου αλλά λάμδα. Κι ύστερα, πόσες φορές σ’ το ’χω πει ότι τα σύμφωνα δεν τονίζονται;\n— Τότε στο ξου!\n— Μα πού το είδες το ξι στη λέξη λαγός, ευλογημένο πουλί; φωνάζει τώρα η κυρία Καλλιόπη, πολύ θυμωμένη.\n— Στο γου; ρωτάει χαριτωμένα ο Τρύφωνας.\nΤώρα η κυρία Καλλιόπη σηκώνεται όρθια. Φαίνεται πολύ θυμωμένη. Πετάει μια μεγάλη πατάτα μέσα στην κατσαρόλα με το νερό, τα νερά πετάγονται και μας κάνουν μούσκεμα.\n— Η λέξη λαγός, φωνάζει και κοιτάζει θυμωμένη τον Τρύφωνα, τονίζεται στο...\n— Όμικρον! πετάγεται εκείνος.\n— Το ’ξερες; τον ρωτάει και πέφτει αποκαμωμένη πάνω στην καρέκλα της.\n— Ναι.\n— Και γιατί μου ’βγαλες το λάδι μ’ όλ’ αυτά τα λάθη; Ε; Γιατί;\n— Εσύ δε μου είφες φως φρέφει να κάνω λάθη για να μάθω; Ε; Δε μου το είφες; λέει ο Τρύφωνας, πετάει πάνω στην κερασιά και βολεύεται σ’ ένα κλαδί. Φαράξενα φουλιά απτοί οι άνθρωφοι, μονολογεί. Φρώτα σου μαθαίνουν κάτι και μόλις εσύ το μάθεις καλά σε μαλώνουν κι αφοφάνω.","word_count":448,"page_number":21,"chapter":"Ενότητα 11 — Γελάσαμε με την ψυχή μας"},{"id":"d_dimotikou_g_0003","source_id":"d_dimotikou_g","title":"Εμείς δεν προσκυνούμε","content":"Ο Ιμπραήμ έστειλε τον Κεχαγιά με χίλιους στρατιώτες με τσεκούρια και με άρματα στη Μεσσηνία να βάλουν φωτιά και τσεκούρι. Όσα δεν καίγονταν θα τα έκοβαν, ελαιώνες, συκιές, μουριές...\nΣτον Κεχαγιά έδωσε και μια διαταγή για τους Μεσσήνιους να προσκυνήσουν, ειμή* να αρχίσει το έργο του.\nΔιαβάζοντας τη διαταγή, που ήταν πολύ αυστηρή, του αποκρίθηκα από μέρους του λαού της Μεσσηνίας:\n«Αυτό που μας φοβερίζεις, να μας κάψεις και να μας κόψεις τα καρποφόρα δέντρα μας, δεν είναι έργο της πολεμικής γιατί τα άψυχα δέντρα δεν εναντιώνονται σε κανένα. Το δίκαιο του πολέμου είναι να πολεμάει κανείς με τους ανθρώπους και όχι με τα άψυχα δέντρα.\nΌχι τα κλαριά να μας κόψεις, όχι τα δέντρα, όχι τα σπίτια που μας έκαψες, μόνο πέτρα απάνω στην πέτρα να μη μείνει, εμείς δεν προσκυνούμε. Γιατί τα δέντρα μας, αν τα κόψεις και τα κάψεις, τη γη δεν μπορείς να τη σηκώσεις. Και η ίδια η γη, που τα έθρεψε, αυτή η ίδια γη μένει δική μας και τα μετακάνει.","word_count":167,"page_number":30,"chapter":"Ενότητα 12 — Χαίρε, ω χαίρε, Ελευθεριά!"},{"id":"d_dimotikou_g_0004","source_id":"d_dimotikou_g","title":"Ο τρελός μπουρλοτιέρης","content":"Τέλη Σεπτεμβρίου του 1826 ο ελληνικός στόλος βρέθηκε ξαφνικά μέσα στο στενό της Μυτιλήνης μ’ ενάντιο άνεμο κυκλωμένος από τον τουρκικό στόλο και κινδύνευε. Ο Μιαούλης σήμανε υποχώρηση με γεμάτα τα πανιά.\nΟ Υδραίος όμως Γεώργιος Πολίτης με το μπουρλότο του ούτε πανιά άνοιξε ούτε να υποχωρήσει έδειξε σκοπό. Μα ούτε και το ναύαρχό του θέλησε ν’ ακούσει, που του έστειλε βάρκες να τον ρυμουλκάρουν. Στάθηκε αντιμέτωπος και προκαλούσε τον εχθρό. Κι εκείνος, βλέποντας ένα μονάχο παλιοκάραβο να του αντιστέκεται, μάνισε, δαιμονίστηκε. Έβαλε στη μέση τον Πολίτη και για κάμποση ώρα κανονιοβολώντας τον δεν μπόρεσε μήτε να τον κάψει μήτε να τον βουλιάξει!\nΤότε έστειλε είκοσι βάρκες να πιάσουν με ρεσάλτο (έφοδο) το υδραίικο καράβι. Πηδάει αμέσως και ο Πολίτης στη δική του βάρκα, που είχε ένα κανόνι, πέφτει τυφλά μέσα στις τούρκικες κι αρχίζει με ψιλή και με χοντρή φωτιά έναν πόλεμο τρελό και τις αναγκάζει όλες να σκορπίσουν! Ύστερα ανεβαίνει πάλι στο καράβι του, απλώνει όλα τα πανιά και ορθός στην πρύμνη, φοβερίζοντας με τη μαχαίρα και με τη φωνή του, περνάει ανάμεσα από τα τούρκικα, που τον κοιτάζουν και απορούν!","word_count":183,"page_number":31,"chapter":"Ενότητα 12 — Χαίρε, ω χαίρε, Ελευθεριά!"},{"id":"d_dimotikou_g_0005","source_id":"d_dimotikou_g","title":"Το σχολείο του κόσμου","content":"Το σχολείο μας έχει μαθητές από διάφορα μέρη του κόσμου. Οι γονείς μας εργάζονται εδώ στο Παρίσι και δεν μπορούμε να πάμε σχολείο στον τόπο μας γιατί είναι μακριά.\nΈχουμε έναν δάσκαλο για τη Γυμναστική κι έναν που μας μαθαίνει τη γλώσσα αυτού του τόπου. Τα μαθήματα αυτά τα κάνουμε όλοι μαζί, χωριστά βέβαια τα μικρά παιδιά, χωριστά τα μεγάλα. Έχουμε κι έναν δάσκαλο ή μια δασκάλα από την πατρίδα μας. Όταν κάνουμε μάθημα μαζί τους, όσα παιδιά είναι από την ίδια χώρα μπαίνουν σε μια τάξη, μικρά μεγάλα.\nΟι δάσκαλοι συχνά φορούν ρούχα του τόπου τους. Κι αν φορούσαν ίδια ρούχα, πάλι δε θα έμοιαζαν μεταξύ τους. Άλλοι είναι ξανθοί, άλλοι μελαψοί, άλλοι μικροσκοπικοί, άλλοι πανύψηλοι, μερικοί με σχιστά μάτια, μερικοί με στρογγυλά. Μα όλοι είναι φίλοι μεταξύ τους.\nΚάθε ομάδα μαθαίνει τη γλώσσα, τα τραγούδια, την ιστορία και τους χορούς του τόπου της. Μια μέρα την εβδομάδα βγαίνουμε από το σχολείο και κάνουμε μια μικρή παρέλαση γύρω από το τετράγωνο κρατώντας πινακίδες. Οι γείτονες κι οι περαστικοί χαμογελούν και κοιτάζουν με ενδιαφέρον τις πινακίδες μας. Μερικοί μάλιστα χειροκροτούν. Περιμένουμε τη μέρα αυτή ανυπόμονα και την ετοιμάζουμε με πολύ κέφι.\n«Να διαλέξετε έναν άνθρωπο από τη χώρα μας που βοήθησε να γίνει καλύτερος ο κόσμος» λέει κάθε δάσκαλος στην ομάδα του. Από όσα μας έχουν πει, διαλέγουμε ένα πρόσωπο για ήρωά μας, κολλάμε σε χαρτόνι τη φωτογραφία του ή μια ζωγραφιά του και φτιάχνουμε την πινακίδα μας. Άλλος προτιμά επιστήμονα, άλλος καλλιτέχνη, άντρα ή γυναίκα, που προσπάθησε να καλυτερέψει τον κόσμο όχι με πόλεμο αλλά με την προσφορά του. Πριν βγούμε στον δρόμο, δείχνουμε τη δουλειά μας η μια ομάδα στις άλλες και εξηγούμε ποιον διαλέξαμε και γιατί. Έτσι μαθαίνουμε για ήρωες από μακρινά μέρη του πλανήτη μας.\nΜια μέρα τον μήνα κάνουμε μεγάλη παρέλαση. Περπατάμε γύρω από τέσσερα τετράγωνα και κρατάμε κάθε ομάδα τη σημαία της, τις πινακίδες με σπουδαία πρόσωπα και εικόνες με ωραία τοπία από τις χώρες μας. Εκείνη τη μέρα παρελαύνουμε φορώντας κάτι χαρακτηριστικό από τον τόπο μας: ξύλινα τσόκαρα ή ψηλές μπότες, ζωνάρι ή σάλι, σκούφο ή μαντήλα. Κάθε ομάδα τραγουδά, με τη σειρά, κάποιο τραγούδι του τόπου της, και όλοι οι περαστικοί σταματούν και μας χαιρετούν. Μια κυρία μάλιστα φίλησε συγκινημένη μια δασκάλα κι εκείνη έγινε κόκκινη σαν παντζάρι, γιατί δε συνηθίζεται να φιλιούνται στην πατρίδα της.\nΔεν ξέρουμε ακόμα χίλια πράγματα ούτε θα προλάβουμε ποτέ να τα μάθουμε όλα. Δε θα μάθουμε όλες τις γλώσσες που μελετούν τα παιδιά στις διπλανές τάξεις. Το πολύ πολύ λίγες λέξεις από καθεμιά. Και ούτε θα μάθουμε τα τραγούδια τους. Ίσως λίγες νότες εδώ κι εκεί. Ξέρουμε όμως ότι όλοι είμαστε ίδιοι και αγαπάμε ο ένας τον άλλον. Όταν μεγαλώσουμε, κάποιοι από μας ίσως γίνουν επιστήμονες, καλλιτέχνες ή αρχηγοί. Τότε, θα κάνουμε σπουδαία πράγματα, γιατί έχουμε μάθει το πιο μεγάλο μάθημα στο σχολείο μας: τη χαρά μπορείς να τη δώσεις σε κάθε άνθρωπο είτε έχει σχιστά μάτια είτε στρογγυλά είτε είναι λευκός είτε μαύρος είτε είναι φτωχός είτε πλούσιος!","word_count":493,"page_number":37,"chapter":"Ενότητα 13 — Όλοι διαφορετικοί, όλοι ίδιοι"},{"id":"d_dimotikou_g_0006","source_id":"d_dimotikou_g","title":"Η 5η Βασική Αρχή των Δικαιωμάτων των Παιδιών","content":"Τα παιδιά όλου του κόσμου συγκεντρώθηκαν για να συζητήσουν και να μάθουν τα δικαιώματά τους. Για να συνεννοηθούν μεταξύ τους χρησιμοποιούσαν την παγκόσμια γλώσσα... της αγάπης. Είχαν ήδη συζητήσει τις 4 πρώτες βασικές αρχές των δικαιωμάτων τους όταν ακούστηκε μια φωνή…\n— Εεε! Σταθείτε... Πού πάτε; Είμαι και εγώ εδώ, φώναζε όσο μπορούσε πιο δυνατά πλησιάζοντας σιγά σιγά ο Μπίλι.\nΤα παιδιά έστρεψαν το βλέμμα τους προς την κατεύθυνση όπου ακουγόταν η φωνή. Ένα ωραίο κεφαλάκι πρόβαλε με μάτια τόσο μεγάλα και το στόμα κλειστό σαν να κρατούσε από καιρό ένα τρομερό μυστικό. Τα παιδιά ανυπόμονα και περίεργα έβλεπαν την προσπάθεια που έκανε για να τα φτάσει.\n— Έχω κι εγώ ένα δικαίωμα, είπε μόλις τα πλησίασε, που είναι μόνο για μένα.\n— Μόνο για σένα; Πώς γίνεται αυτό; ρώτησε η Κατρίν.\n— Τι δικαίωμα; ρώτησαν τα άλλα παιδιά γεμάτα απορία.\n— Το δικαίωμα να με μεταχειρίζονται με τον ειδικό τρόπο που πρέπει, να με εκπαιδεύουν και να με φροντίζουν, όπως πρέπει.\n— Τι όπως πρέπει;\n— Δηλαδή εσύ έχεις ένα δικαίωμα παραπάνω από μας; Δεν είναι άδικο αυτό; Γιατί; ρώτησε κάπως αγριεμένα ο Δημήτρης.\n— Γιατί, γιατί γεννήθηκα, χωρίς να φταίω γι’ αυτό, με κάποιες αδυναμίες..., προσπαθούσε να εξηγήσει ο Μπίλι. Τα χέρια μου δεν πιάνουν μερικές φορές καλά, τα πόδια μου δεν πατούν στέρεα και δεν μπορώ να περπατήσω καλά. Άλλα παιδιά σαν εμένα δυσκολεύονται να μιλήσουν, το μυαλό τους κουράζεται και σταματά... Γι’ αυτό χρειαζόμαστε τη φροντίδα των άλλων. Χωρίς αυτή δεν μπορούμε να κάνουμε κάποια πράγματα. Όταν ξέρουμε όμως ότι φροντίζουν για μας, ότι μας αποδέχονται, ότι μας αγαπούν, τότε αντιμετωπίζουμε τις δυσκολίες μας πιο εύκολα. Γινόμαστε δυνατοί και άξιοι να ζήσουμε ισότιμα με όλους σας στην κοινωνία, απάντησε με μια φωνή γεμάτη θέληση ο Μπίλι, εκπροσωπώντας άξια όλα τα παιδιά με ιδιαιτερότητες και συνέχισε: το δικαίωμα αυτό καταλάβατε τώρα γιατί μου το δίνουν; Για να συμπληρώσω τις αδυναμίες που έχω. Δε ζηλεύετε, πιστεύω...\n— Όχι, όχι, καταλαβαίνουμε. Το δικαίωμα αυτό, το 5ο δικαίωμα, είναι μόνο δικό σου, είπαν όλα τα παιδιά μαζί. Είμαστε μαζί σου για να το διεκδικήσουμε όλοι μαζί για σένα, για όλα τα παιδιά του κόσμου που έχουν ιδιαιτερότητες. Είμαστε οι φίλοι σου.\nΤα παιδιά μέσα τους βαθιά κατάλαβαν πολλά πράγματα. Ένιωσαν πιο μεγαλωμένα, πιο υπεύθυνα και πίστεψαν πως μπορούν κάτι να κάνουν και αυτά για τους άλλους που τους χρειάζονται. Αυτό γέμισε τις καρδιές τους από ευτυχία και κουβέντιαζαν, σκέφτονταν φωναχτά, έδειχναν πόσο πολύ χαίρονταν και πόσο ένιωθαν ευχαριστημένα!","word_count":408,"page_number":44,"chapter":"Ενότητα 13 — Όλοι διαφορετικοί, όλοι ίδιοι"},{"id":"d_dimotikou_g_0007","source_id":"d_dimotikou_g","title":"Από το πρώτο τηλεφώνημα στο πρώτο ηλεκτρονικό μήνυμα!","content":"Ο καθηγητής ορθοφωνίας* Γκράχαμ Μπελ είχε μελετήσει πολύ τη λειτουργία του ανθρώπινου αυτιού. Ήθελε να βοηθήσει τους κωφούς ανθρώπους, καθώς η ίδια η μητέρα του ήταν κωφή.\nΑξιοποιώντας τις γνώσεις του κατασκεύασε μια μηχανή που θα μπορούσε να μεταφέρει την ανθρώπινη ομιλία κατά μήκος ενός καλωδίου. Έφτιαξε έναν ηλεκτρικό πομπό*, που μπορούσε να δονηθεί, όπως το τύμπανο του αυτιού μας. Ο πομπός αυτός μετέτρεπε την ομιλία σε ηλεκτρικό ρεύμα, το οποίο ταξίδευε μέσα από ένα καλώδιο προς τον δέκτη* ενός άλλου τηλεφώνου. Εκεί το ηλεκτρικό ρεύμα δονούσε έναν δίσκο. Μέσα από αυτή τη δόνηση γινόταν η αναπαραγωγή της αρχικής ομιλίας.\nΣτις 10 Μαρτίου 1875 έγινε η πρώτη τηλεφωνική κλήση στον κόσμο. Ο Γκράχαμ Μπελ βρισκόταν σ’ ένα δωμάτιο με το τηλέφωνό του έτοιμο. Ο βοηθός του, ο Γουότσον, βρισκόταν σε ένα άλλο δωμάτιο, πανέτοιμος, με το ακουστικό της συσκευής του στο αυτί του. Ο Μπελ, πάνω στον ενθουσιασμό του, εκείνη τη στιγμή αναποδογύρισε την μπαταρία που ήταν συνδεδεμένη με το τηλέφωνό του και το υγρό της μπαταρίας χύθηκε στο παντελόνι του. Ξαφνιασμένος φώναξε: «Κύριε Γουότσον, ελάτε εδώ αμέσως! Σας θέλω!». Η πρώτη τηλεφωνική συνδιάλεξη στον κόσμο ήταν γεγονός!\nΑν σκεφτείτε ότι ο κύριος Γουότσον κόντεψε να λιποθυμήσει από την έκπληξη, όταν άκουσε τη φωνή του Γκράχαμ Μπελ μέσα από ένα καλώδιο, φανταστείτε πώς θα αντιδρούσε αν βρισκόταν στο γραφείο του Ρέι Τόμλινσον.\nΓιατί, θα ρωτήσετε, και ποιος είναι πάλι αυτός ο Ρέι Τόμλινσον; Ο Τόμλινσον, λοιπόν, είναι ένας προγραμματιστής ηλεκτρονικών υπολογιστών που μια φθινοπωρινή μέρα του 1971 κατάφερε να στείλει το πρώτο μήνυμα ηλεκτρονικού ταχυδρομείου (e-mail) στην ιστορία.\nΠώς ακριβώς συνέβη; Εκείνη τη μέρα ο Ρέι «χάζευε» ένα πρόγραμμα αποστολής μηνυμάτων, που είχαν δημιουργήσει οι συνάδελφοί του για να συνεννοούνται μεταξύ τους. Αυτά όμως δεν ήταν μηνύματα κανονικού ηλεκτρονικού ταχυδρομείου, αφού όλα τα μηνύματα εμφανίζονταν στον ίδιο υπολογιστή. Τότε του Ρέι τού ήρθε η ιδέα να προσπαθήσει να στείλει ένα μήνυμα από τον δικό του υπολογιστή σε έναν άλλο. Έπειτα από πολλές προσπάθειες, κατάφερε να στείλει το –τελείως ακαταλαβίστικο μήνυμα– «QWERTYUIOP» σ’ έναν άλλο υπολογιστή που ήταν συνδεδεμένος με τον δικό του. Το πρώτο μήνυμα ηλεκτρονικού ταχυδρομείου ήταν γεγονός!\nΟ Τόμλινσον, κάποια στιγμή, αποφάσισε να χρησιμοποιήσει ένα σύμβολο που να ξεχωρίζει το όνομά του από την ηλεκτρονική του διεύθυνση στα μηνύματα που έστελνε. Έτσι, επέλεξε από το πληκτρολόγιό του το σύμβολο @,που ως τότε το έτρωγε η σκόνη, αφού δε χρησιμοποιούνταν σχεδόν ποτέ. Με αυτό τον τρόπο το @, το πασίγνωστο σήμερα «παπάκι», καθιερώθηκε σε ολόκληρο τον κόσμο ως κομμάτι των ηλεκτρονικών διευθύνσεων.\nΤο @ έχει αποκτήσει διάφορες ονομασίες. Έτσι, ενώ στην Ελλάδα λέγεται «παπάκι», στη Νότια Αφρική είναι γνωστό ως «ουρά πιθήκου» και στην Ιταλία ως «σαλιγκάρι».","word_count":438,"page_number":54,"chapter":"Ενότητα 14 — Το ανθρώπινο θαύμα"},{"id":"d_dimotikou_g_0008","source_id":"d_dimotikou_g","title":"Μια παράξενη παραγγελία","content":"Βρίσκεστε στο αεροδρόμιο του Ελσίνκι και προσπαθείτε απεγνωσμένα να βρείτε μια καντίνα για να αγοράσετε ένα αναψυκτικό. Εντοπίζετε τελικά ένα μηχάνημα και ετοιμάζετε τα απαραίτητα κέρματα. Κι όμως! Το μηχάνημα δεν έχει κερματοδέκτη. Μένετε απορημένος και προσπαθείτε να καταλάβετε τι συμβαίνει. Το μηχάνημα δε δείχνει να δέχεται ούτε πιστωτικές κάρτες, ούτε νομίσματα, ούτε χαρτονομίσματα. Τίποτε!\nΠάνω που ετοιμάζεστε να απομακρυνθείτε ενοχλημένος για το ιδιαίτερο χιούμορ των\nΦινλανδών, βλέπετε να πλησιάζει ένας άνδρας, να στέκεται δίπλα στο μηχάνημα και να βγάζει το κινητό τηλέφωνό του. Καλεί έναν αριθμό, περιμένει λίγο χωρίς να μιλάει, πατάει ένα δύο πλήκτρα, κλείνει το κινητό και ξαφνικά... το μηχάνημα προσφέρει ένα κουτάκι πορτοκαλάδας. Ο άνθρωπός μας το παίρνει και απομακρύνεται ψύχραιμος, λες και δεν έχει συμβεί τίποτε το παράξενο.\nΚαι πράγματι τίποτε το παράξενο δεν έχει συμβεί. Το συγκεκριμένο μηχάνημα προσφέρει αναψυκτικά μόνο αν το πάρετε τηλέφωνο και πληκτρολογήσετε τον κατάλληλο κωδικό. Το αναψυκτικό χρεώνεται στον λογαριασμό του κινητού σας.\nΠρόκειται για μία από τις πολλές περίεργες νέες χρήσεις για τα κινητά τηλέφωνα που έχουν επινοήσει οι Φινλανδοί, ο λαός με τον μεγαλύτερο αριθμό κινητών τηλεφώνων ανά 100 κατοίκους στον κόσμο.","word_count":185,"page_number":58,"chapter":"Ενότητα 14 — Το ανθρώπινο θαύμα"},{"id":"d_dimotikou_g_0009","source_id":"d_dimotikou_g","title":"Το διαδίκτυο","content":"Το μέσο επικοινωνίας που αναπτύσσεται πιο γρήγορα σήμερα είναι το διαδίκτυο, ένα παγκόσμιο δίκτυο από εκατομμύρια υπολογιστές. Το διαδίκτυο ξεκίνησε το 1969 σαν ένα μυστικό στρατιωτικό πρόγραμμα στις Ηνωμένες Πολιτείες.\nΣτη δεκαετία του 1980 το διαδίκτυο έβγαλε τη στρατιωτική στολή και καθιερώθηκε ως ο πιο γρήγορος και ο πιο εύκολος τρόπος ανταλλαγής ιδεών και πληροφοριών ανάμεσα στα πανεπιστήμια. Μέχρι τις αρχές της δεκαετίας του 1990 οι άνθρωποι το χρησιμοποιούσαν για εκπαίδευση, ψυχαγωγία ή για εμπορικούς λόγους. Αργότερα ο αριθμός των ανθρώπων που χρησιμοποιούν το ίντερνετ άρχισε να αυξάνεται κατά ένα εκατομμύριο περίπου κάθε μήνα.\nΜέχρι το τέλος του 21ου αιώνα όλοι οι υπολογιστές θα έχουν συνδεθεί με το διαδίκτυο και η επικοινωνία των ανθρώπων θα έχει βρει νέους συναρπαστικούς δρόμους.","word_count":120,"page_number":61,"chapter":"Ενότητα 14 — Το ανθρώπινο θαύμα"},{"id":"d_dimotikou_g_0010","source_id":"d_dimotikou_g","title":"Πρωτότυπα πασχαλινά αυγά","content":"Αυγά βρασμένα πολύ καλά.\nΈνα δοχείο, που μέσα θα βάλετε νερό και μια ποσότητα ατλακόλλας.\nΜικρά χαρτάκια από γκοφρέ χαρτί ή κρεπ, χαρτιά περιτυλίγματος κομμένα σε μικρά κομμάτια με το χέρι.\nΑφού βράσετε τα αυγά, αφήστε τα να κρυώσουν καλά. Ετοιμάστε ένα μείγμα νερού-ατλακόλλας και βουτήξτε ένα ένα τα κομματάκια χαρτιού.\nΤοποθετήστε τα πάνω στο κάθε αυγό διάσπαρτα ή το ένα δίπλα στο άλλο.\nΑφήστε τα αυγά να στεγνώσουν καλά. Αν θέλετε, όσο η ατλακόλλα δεν έχει στεγνώσει καλά, πασπαλίστε με λίγη χρυσόσκονη. Το ίδιο μπορείτε να κάνετε και με γκοφρέ χαρτί.\nΠροσοχή όμως γιατί ξεβάφει!\nΣημείωση: Μια παραλλαγή της παραπάνω χειροτεχνίας είναι να κόψετε με «κυματιστό» ψαλιδάκι ψιλές λουριδίτσες από οντουλέ χαρτί και να τις κολλήσετε με ρευστή κόλλα πάνω σε ήδη βαμμένο κόκκινο ή άλλο πολύχρωμο αυγό. Πούλιες, μπαλάκια από γκοφρέ και αυτοκόλλητα είναι μερικές άλλες ιδέες για να διακοσμήσετε αυγά του Πάσχα.","word_count":145,"page_number":71,"chapter":"Ενότητα 15 — Χριστός Ανέστη!"},{"id":"d_dimotikou_g_0011","source_id":"d_dimotikou_g","title":"Πασχαλινά έθιμα","content":"Συναντάται μόνο στο Λεωνίδιο της Αρκαδίας. Την Ανάσταση, οι νέοι που έχουν δημιουργήσει μικρά αερόστατα τ’ αφήνουν ελεύθερα να υψωθούν, δημιουργώντας ένα εντυπωσιακότατο θέαμα στον νυχτερινό ουρανό.\nΤο έθιμο αυτό ισχύει από τα τέλη του 19ου αιώνα. Σχεδόν κάθε σπίτι, βδομάδες πριν, ετοιμάζει το δικό του αερόστατο με καλάμι και χαρτί. Για την πυρόδότησή τους χρησιμοποιείται η «καλυμμάρα», πανί εμποτισμένο με λάδι και πετρέλαιο. Από κάθε ενορία (από τις 5 της Τσακωνιάς) αφήνονται περισσότερα από 100 αερόστατα.\nΦανταστείτε το θέαμα!","word_count":80,"page_number":72,"chapter":"Ενότητα 15 — Χριστός Ανέστη!"},{"id":"d_dimotikou_g_0012","source_id":"d_dimotikou_g","title":"Το παραδεισένιο Πήλιο","content":"Το μικρό τρένο που μας πάει από τον Βόλο στις Μηλιές του Πηλίου δεν έχει το όμοιό του. Θυμίζει τις ταχυδρομικές άμαξες του παλιού καλού καιρού. Δεν έχει την ακρίβεια ούτε και την περηφάνια εκείνη των μεγάλων εξπρές*, που ξεκινάνε και σταματούν σαν ανυπόμονα άλογα. Δεν έχει καν το ύφος ότι εκτελεί συγκοινωνία. Θαρρείτε πως βγήκε περίπατο για τη δική του ευχαρίστηση. Πηγαίνει αργά – σα για να χαρεί περισσότερο τη φύση και τον ανοιξιάτικο ήλιο. Σταματάει κατά το κέφι του – σα για να θαυμάσει μια ωραία θέα. Και στους μικρούς σταθμούς, όπου ξαποσταίνει, δημιουργεί μια ατμόσφαιρα φιλική και εγκάρδια.\nΣτους σταθμούς αυτούς είναι ανθισμένα πεζούλια, καφενεδάκια κάτω από πανύψηλες λεύκες, κόσμος που γνωρίζεται με τον κόσμο του τρένου. Αρχίζουν λοιπόν ατέλειωτες κουβέντες, ο μοναδικός υπάλληλος του τρένου παίρνει παραγγελίες και καλάθια για τον παραπέρα σταθμό, ένας ρομαντικός ταξιδιώτης κατεβαίνει να κόψει λουλούδια των χωραφιών, άλλοι παραγγέλνουν καφέ... Το μικρό τρένο δίνει σ’ όλους καιρό για όλ’ αυτά. Κι όταν σφυρίζει, δεν είναι για ν’ αναγγείλει ασυζήτητα ότι φεύγει, αλλά για να ρωτήσει: «E, τι λέτε; Πάμε τώρα;». Κι αν κανείς δεν έχει τελειώσει ακόμα, το μικρό τρένο τον περιμένει. Δε βιάζεται!\nΚι αλήθεια: γιατί να βιαστεί; θα ήταν ανόητο. Είναι τόσο ωραία όλα: το ανοιξιάτικο πρωί, η φύση, ο Παγασητικός... Τόσο ωραία! Πουθενά αλλού δε θα ’βρισκε κανείς τόση ομορφιά συνδυασμένη με τόση πραότητα* και ειρήνη! Όλη η φύση, από τον Βόλο στις Μηλιές, έχει μια κυριακάτικη εμφάνιση. Όλα είναι καθαρά στα μικρά χωριά που περνάμε –Αγριά, Λεχώνια– όλα είναι γιορταστικά στα χωράφια, στο φως, στα νερά του κόλπου! Στ’ ακροθαλάσσι, μπρος στη φωτεινή, την ονειρεμένη γαλήνη του Παγασητικού, βλέπεις γέρικες βάρκες ξεχασμένες σε μια γλυκιά υπνηλία. Κάτω από τις ασημένιες ελιές βόσκουν νωθρά κοπάδια προβάτων. Σ’ όλο το μάκρος του δρόμου κυλάνε ρυάκια ανάμεσα από παπαρούνες και χαμομήλια. Οι κερασιές είναι ανθισμένες, κι ο ανοιξιάτικος αέρας είναι γεμάτος ευωδίες. Θεία πραότητα είναι διάχυτη παντού. Κι ο Βρυχών*, μέσα στην κοίτη των λευκών γυαλιστερών χαλικιών του, δεν έχει τίποτα από την τρομερή εντύπωση που υποβάλλει τ’ όνομά του: αντί να βρυχάται*, κυλάει φλυαρώντας προς τη γαλανή θάλασσα...\nΤα μέρη αυτά, που ο Ιάσων τ’ άφησε για να φύγει με την Αργώ του, αξίζουν όλες τις Κολχίδες που ξεκίνησε ν’ ανακαλύψει. Η ευλογημένη καρπερότητα της γης, το χρυσό φως που λούζει τα πάντα και η απέραντη ειρηνική ομορφιά των βουνών και των νερών, όλα προσκαλούν σε διαμονή και όχι σε αναχώρηση...\nΤο μικρό τρένο ανηφορίζει τώρα στην πλαγιά του Πηλίου. Η θέα, όσο πάει, γίνεται πλατύτερη ως που στο τέλος απλώνεται από κάτω μας σαν από αεροπλάνο. Ο Παγασητικός λάμπει ολόκληρος σαν ένας χρυσός καθρέφτης. Ένας απέραντος ελαιώνας ροβολάει προς τη θάλασσα, γεμάτος ασημένια ειρήνη. Ανάμεσα στις ελιές κοκκινίζουν σαν παπαρούνες οι στέγες διασκορπισμένων εξοχικών σπιτιών. Ένα μεγάλο ευτυχισμένο φως λούζει τα πάντα. Και γύρω μας ξετυλίγεται αδιάκοπα η βλάστηση του βουνού: σφεντάμι*, θυμάρια, αγριολούλουδα, ρόδινες αγριοχαρουπιές και δροσερά πλατάνια, που φουντώνουν στις ρεματιές όπου κατρακυλούν γάργαρα τραγουδιστά νερά. Ο γλυκός αέρας έχει ένα άρωμα θυμαριού και λεβάντας. Θα ’λεγε κανείς να μην τελειώσει ποτέ μια τέτοια διαδρομή.","word_count":509,"page_number":75,"chapter":"Ενότητα 16 — Ταξίδια στην Ελλάδα"},{"id":"d_dimotikou_g_0013","source_id":"d_dimotikou_g","title":"Η Ρόδος","content":"Η Ρόδος είναι το μεγαλύτερο νησί των Δωδεκανήσων. Δίκαια την αποκαλούν το μαργαριτάρι της Μεσογείου. Οι σπάνιες ομορφιές της ξεδιπλώνονται σε κάθε γωνιά της: γοητευτικές παραλίες, όμορφα λιμανάκια, χωριά με παραδοσιακά πέτρινα σπίτια.\nΝησί πλουσιότατο σε ιστορία, αφού υπήρξε σημαντικό κέντρο της αρχαιότητας. Από το 1309 έως το 1519 βρισκόταν στην κατοχή των Ιπποτών του Αγίου Ιωάννου και τότε χτίστηκε η μεσαιωνική πόλη που κυριαρχεί ακόμη στην πόλη της Ρόδου.\nΤο νησί αποτελεί κάθε εποχή του χρόνου επίγειο παράδεισο για Έλληνες και ξένους τουρίστες.","word_count":84,"page_number":79,"chapter":"Ενότητα 16 — Ταξίδια στην Ελλάδα"},{"id":"d_dimotikou_g_0014","source_id":"d_dimotikou_g","title":"Άνοιξα του Αιγαίου τη θύρα","content":"Άνοιξα του Αιγαίου τη θύρα\nτην περνώ φτάνω στη Θήρα\n\nαπ’ την Άνδρο και τη Σύρο\nκύματα χορό θα σύρω\n\nγια να πάω στην Αίγινα\nγλαροπούλι έγινα\n\nΠάτμο, Λέρο, Κω και Ρόδο\nροδοπέταλα από ρόδο\n\nάπορος πατάω στον Πόρο\nδίχως να ’χω κάποιον πόρο\n\nόλοι παίρνουν απ’ την Πάρο\nκι εγώ πάω για να πάρω\n\nκαι ρωτάω έναν ψαρά\n«προς τα πού είναι τα Ψαρά;»\n\nΤήνος, Μύκονος και Μήλος\nστα φτερά του μ’ έχει ο μύλος\n\n«δεν υπάρχει σκόπελος»\nμου φωνάζει η Σκόπελος\n\nπαίζω σε γιαλό και σ’ άμμο\nαπ’ τη Λήμνο πάω στη Σάμο\n\nΜυτιλήνη και στη Χιο\nτριγυρίζω σαν στοιχειό\n\nσ’ ένα δέλφινα καβάλα\nπάω στη Θάσο, στην Καβάλα\n\nστη Μακεδονία, στη Θράκη\nκι από Κρήτη Σαμοθράκη.","word_count":119,"page_number":88,"chapter":"Ενότητα 16 — Ταξίδια στην Ελλάδα"},{"id":"e_dimotikou_0001","source_id":"e_dimotikou","title":"Ο φίλος μας το δάσος","content":"Ο χρόνος κυλούσε παράξενα στο δάσος. Θρόιζε μαζί με τα πράσινα φύλλα της άνοιξης ή έπεφτε αργά μαζί με τις νιφάδες του χιονιού. Έσταζε από τα κλαδιά μαζί με τις σταγόνες της φθινοπωρινής βροχής ή χόρευε σαν διαμαντόσκονη στις αχτίδες του καλοκαιριάτικου ήλιου. Κυλούσε μαζί με τη ζωή και γινόταν ένα μ’ αυτή.\nΥπήρχαν πλάσματα στο δάσος σαν τα Εφήμερα, τα μικρά έντομα που φτερούγιζαν πάνω από τα ρυάκια τον Μάη και που ζούσαν μονάχα μια μέρα. Ήταν περίεργο όταν σκεφτόσουν πως μόλις και προλάβαιναν να δουν μια δεύτερη ανατολή, αν το προλάβαιναν κι αυτό. Υπήρχαν άλλα ζωάκια που ζούσαν πολλά ή λίγα καλοκαίρια και χειμώνες. Και τέλος, υπήρχαν οι πράσινοι γίγαντες, τα δέντρα, που κανένας δεν ήξερε πόσο ζούσαν. Τα ίδια το ήξεραν, αλλά τα δέντρα ένιωθαν τόσο διαφορετικά τον χρόνο!\nΤα μικρά Εφήμερα όμως ζούσαν με τον τρόπο τους σε μία μέρα όσο ζούσαν τα δέντρα σε εκατοντάδες χρόνια. Μόνο ο ήλιος μετρούσε τη ζωή με αυγές και δειλινά. Τα πλάσματα του δάσους ήξεραν μόνο ότι ζούσαν μια ολόκληρη ζωή, και το τι μετρούσε ο ήλιος δεν είχε καμιά σημασία. Έτσι κι αλλιώς, ο ήλιος έλαμπε για όλα.\nΤο πόσο καιρό έμεινε ο Πορκιουπίνος, ο σκαντζόχοιρος, με τον Τιμ, τον σκίουρο, είναι ένα ερώτημα που μπορεί να ενδιέφερε μόνο τους ανθρώπους, αλλά οι άνθρωποι δεν ανήκαν στον κόσμο του δάσους. Τα πλάσματα που ζούσαν εκεί δεν ήξεραν τα ρολόγια, αλλά, κι αν ακόμη τα ήξεραν, είναι σίγουρο ότι δε θα ενδιαφέρονταν γι’ αυτά.\nΥπήρχε η ώρα του φαγητού και η ώρα του ύπνου. Υπήρχε η ώρα που έκανε κρύο, ζέστη, που είχε βροχή ή αέρα. Και κάποτε έφτανε η ώρα που το κάθε πλάσμα χανόταν και οι γείτονές του δεν το ξανάβλεπαν ποτέ. Όλα αυτά ήταν φυσικά. Αλλά ο χρόνος που ξέρουν τα ρολόγια ήταν κάτι αφύσικο για το δάσος.","word_count":302,"page_number":9,"chapter":"Ενότητα 1 — 0 φίλος μας το περιβάλλον"},{"id":"e_dimotikou_0002","source_id":"e_dimotikou","title":"Η φίλη μας η θάλασσα","content":"Μεγάλη οικολογική καταστροφή στις ακτές της βόρειας Ισπανίας προκάλεσε η διαρροή πετρελαίου από το δεξαμενόπλοιο «Πρεστίζ», η οποία και συνεχίζεται.\nΓια μία από τις μεγαλύτερες οικολογικές καταστροφές της πρόσφατης ιστορίας κάνουν λόγο οι επιστήμονες, καθώς η διαρροή πετρελαίου συνεχίζεται. Ειδικοί επιστήμονες και τεχνικοί που πραγματοποιούν εναέριες περιπολίες είδαν μια νέα πετρελαιοκηλίδα μήκους τριών χιλιομέτρων και πλάτους ενός, ενώ διάσπαρτες κηλίδες ρυπαίνουν από την περασμένη Τετάρτη τις ισπανικές ακτές. Κοντά στο δεξαμενόπλοιο υπάρχει ακόμα μια πετρελαιοκηλίδα μήκους πέντε χιλιομέτρων. Ισπανοί αξιωματούχοι αναφέρουν ότι από τους 4.000 τόνους αργού πετρελαίου έχουν μολυνθεί 35 χιλιόμετρα ακτών, αλλά ενώσεις αλιέων κάνουν λόγο για 200 χιλιόμετρα.\nΓίνονται μεγάλες προσπάθειες για να μη συνεχιστεί η καταστροφή, καθώς το πλοίο μεταφέρει πάνω από 70.000 τόνους πετρελαίου. Ο καπετάνιος του «Πρεστίζ» κρατείται στην Ισπανία κατηγορούμενος για καταστροφή του περιβάλλοντος.\nΤο δεξαμενόπλοιο είναι 26 ετών και έχει μονό τοίχωμα. Σύμφωνα με κανονισμό της Ευρωπαϊκής Ένωσης προβλέπεται σταδιακή κατάργηση των πλοίων αυτών.","word_count":152,"page_number":13,"chapter":"Ενότητα 1 — 0 φίλος μας το περιβάλλον"},{"id":"e_dimotikou_0003","source_id":"e_dimotikou","title":"Ο φίλος μας ο άνεμος","content":"Παλαιότερα, όποιος πλησίαζε με πλοίο στις Κυκλάδες τα πρώτα κτίσματα που αντίκριζε ήταν τα εκκλησάκια και οι ανεμόμυλοι με τις φτερωτές τους, που ξεπρόβαλλαν κάτασπροι πάνω στα υψώματα. Οι νησιώτες αισθάνονταν ευλάβεια για τις εκκλησιές τους, όμως τα πιο αγαπητά τους κτίσματα ήταν οι ανεμόμυλοι.\nΒγαίνοντας κάθε πρωί από τα σπίτια τους, έριχναν αυθόρμητα την πρώτη ματιά στη θάλασσα και τη δεύτερη στους ανεμόμυλους: «Αλέθουν οι μύλοι; Όλα καλά» σκέφτονταν.\nΆνδρες και γυναίκες περνούσαν πολλές ώρες εκεί, ώσπου να ετοιμαστεί το αλεύρι τους. Έτσι, έγινε ο ανεμόμυλος ένα κοινωνικό κέντρο, όπου συζητούσαν τα προβλήματα και τα νέα του χωριού, αντάλλασσαν αστεία και πειράγματα, έκαναν ακόμα και προξενιά. Στη σκιά του ανεμόμυλου μαζεύονταν οι κοπέλες το απόγευμα με τα εργόχειρά τους και οι νέοι τα βράδια οργάνωναν γλέντια.\nΣυγκρίνοντας τον ανεμόμυλο με το καράβι, οι νησιώτες έδιναν την πρώτη θέση στον ανεμόμυλο, επειδή το καράβι δεν ταξίδευε με τις φουρτούνες και, μόλις συναντούσε κακοκαιρία, κατέφευγε σε λιμάνι. Αντίθετα, ο ανεμόμυλος, χτισμένος σε ανεμόδαρτη τοποθεσία, αντιμετώπιζε ανέμους και καταιγίδες.\nΣυγκρίνοντας επίσης τον μυλωνά με τον καπετάνιο, θαύμαζαν περισσότερο τον πρώτο: ο καπετάνιος οδηγούσε το σκάφος του πρίμα με τον αέρα*, ο μυλωνάς όμως ανέμιζε πάντα κόντρα* τα πανιά της φτερωτής. Οδηγώντας το πλοίο του σε λιμάνι, ο καπετάνιος ησύχαζε, γιατί δεν κινδύνευε πια. Ο μυλωνάς δεν ξέγνοιαζε ποτέ, ούτε μέρα ούτε νύχτα, είτε δούλευε ο ανεμόμυλος είτε όχι, γιατί οποιαδήποτε στιγμή μπορούσε να πάθει ζημιά από κακοκαιρία.\nΟ καπετάνιος είχε το πλήρωμά του βοηθό και συμπαραστάτη σε κάθε δύσκολη περίπτωση, ενώ ο μυλωνάς κατάμονος πάλευε με τα ξεσπάσματα του καιρού.\nΣτις Κυκλάδες λειτούργησαν περισσότεροι από εξακόσιοι ανεμόμυλοι. Πρόκειται για αριθμό μοναδικό στον κόσμο. Ο ανεμόμυλος προσαρμόστηκε στις πατροπαράδοτες κατασκευαστικές συνήθειες του κάθε νησιού. Ο κυκλαδίτικος είχε πάντοτε έναν πέτρινο πύργο με στέγη από ξύλινο σκελετό και επένδυση από χόρτο και η κατασκευή του ήταν δύσκολη και πολυδάπανη, όσο και ενός μεγάλου ιστιοφόρου.","word_count":310,"page_number":17,"chapter":"Ενότητα 1 — 0 φίλος μας το περιβάλλον"},{"id":"e_dimotikou_0004","source_id":"e_dimotikou","title":"Η παλιά γειτονιά","content":"Έκλεισα τα μάτια μου. Και τότε έγινε κάτι υπέροχο: σιγά σιγά έσβησε το σημερινό Κολωνάκι. Το δικό μου Κολωνάκι, η δική μου Δεξαμενή, η συνοικία των παιδικών μου χρόνων είναι αθάνατη! Οι δρόμοι γεμίζουν νεοκλασικά σπίτια, κάθε πόρτα κι ένας φίλος! Οι περισσότεροι δρόμοι είναι χωματόδρομοι. Οι πλανόδιοι πωλητές: Ο ψαράς με το πανέρι στο κεφάλι: «Φρέσκα ψάρια, πάρτε φρέσκα ψάρια!». Ο γαλατάς, πρωί και σούρουπο, με τα γιαούρτια ισορροπημένα δεξιά και αριστερά πάνω στη μακριά βέργα: «Γιαούρτι προοοόβειο!». Ο παγοπώλης στα σκαλιά της Λουκιανού. Οι φωνές των παιδιών που παίζουν ξένοιαστα στους δρόμους, μέχρι να σκοτεινιάσει, μέχρι ν’ ακουστεί η φωνή της μητέρας: «Φροσούλα, Αννούλα, ελάτε, τρώμε!...».","word_count":108,"page_number":25,"chapter":"Ενότητα 2 — Η ζωή στην πόλη"},{"id":"e_dimotikou_0005","source_id":"e_dimotikou","title":"Η πολιτιστική ζωή της Θεσσαλονίκης","content":"Έντονη είναι η πολιτιστική ζωή της Θεσσαλονίκης ολόκληρο τον χρόνο. Εκδηλώσεις του Μακεδονικού Μουσείου της Σύγχρονης Τέχνης, του Βαφοπούλειου Πνευματικού Κέντρου, του Πολιτιστικού Κέντρου της Εθνικής Τράπεζας, συναυλίες της Κρατικής και Δημοτικής Ορχήστρας, παραστάσεις του Κρατικού Θεάτρου Βορείου Ελλάδος, οι Γιορτές Ανοιχτού Θεάτρου το καλοκαίρι, η συνάντηση χορευτικών σχημάτων στον Διεθνή Μήνα Χορού, τα Φεστιβάλ Κινηματογράφου, Βιβλίου και Τραγουδιού, οι παραστάσεις της Όπερας Δωματίου, το Διεθνές Φεστιβάλ Θεάτρου, το Φεστιβάλ Μουσικής Δωματίου, τα Δημήτρια, ένα μεγάλο φεστιβάλ μουσικών και θεατρικών, κυρίως, εκδηλώσεων που οργανώνει κάθε φθινόπωρο ο Δήμος Θεσσαλονίκης, είναι μόνο μερικά από τα καλλιτεχνικά γεγονότα που μπορεί να παρακολουθήσει κανείς στη συμπρωτεύουσα. Η πόλη, με τα σημαντικά μουσεία που διαθέτει, προβάλλει το πλουσιότατο και πολύχρωμο παρελθόν της.","word_count":118,"page_number":30,"chapter":"Ενότητα 2 — Η ζωή στην πόλη"},{"id":"e_dimotikou_0006","source_id":"e_dimotikou","title":"Υπόγειες διαδρομές","content":"Πριν από 137 χρόνια κατασκευάστηκε στο Λονδίνο ο πρώτος υπόγειος σιδηρόδρομος του κόσμου. Άρχισε να λειτουργεί το 1863, με σκοπό να μεταφέρει επιβάτες από τα προάστια στην καρδιά της πόλης. Όμως, ο καπνός της ατμομηχανής έκανε το ταξίδι ιδιαίτερα επίπονο και προβληματικό. Ο καπνός ήταν αποπνικτικός και λέρωνε τους επιβάτες, αλλά το ταξίδι ήταν ταχύτερο και, παρ’ όλα αυτά, πιο άνετο σε σύγκριση με άλλα μέσα μεταφοράς. Το 1890 κυκλοφόρησαν τα πρώτα ηλεκτρικά τρένα και το πρόβλημα περιορίστηκε. Το 1900 ακολούθησαν το παράδειγμα του Λονδίνου η Βουδαπέστη και το Παρίσι, όπου εκεί, για πρώτη φορά, ο υπόγειος σιδηρόδρομος ονομάστηκε «μετρό». Το 1904 λειτούργησε το μετρό της Νέας Υόρκης. Μία μία όλες οι μεγάλες πόλεις υιοθέτησαν το μετρό, αναγνωρίζοντας τα πλεονεκτήματα της υπόγειας μετακίνησης των επιβατών: ταχύτητα, ακρίβεια δρομολογίων, μείωση κυκλοφοριακού φόρτου.\nΞέρετε πότε άρχισαν οι συζητήσεις για την κατασκευή του μετρό στην Αθήνα; Το 1955! Όμως η κατασκευή άρχισε 38 χρόνια αργότερα, τα ξημερώματα της Δευτέρας 28 Ιουνίου 1993, όταν ένα μεγάλο φορτηγό διέσχισε αργά τους δρόμους της Αθήνας μεταφέροντας τα πρώτα τμήματα του γνωστού μετροπόντικα, βάρους άνω των 200 τόνων. Εβδομήντα οκτώ μήνες αργότερα ένα μεγάλο τμήμα του έργου ολοκληρώθηκε. Η Αθήνα δε θα είναι ποτέ πια η ίδια. Το μετρό θα δώσει λύσεις στο κυκλοφοριακό πρόβλημά της.\nΤο τρένο της Αθήνας λειτούργησε για πρώτη φορά το 1869. Τα εγκαίνια αποτέλεσαν το σημαντικότερο γεγονός της εποχής. Στις 28 Ιανουαρίου 2000 υποδεχτήκαμε το μετρό με τον ίδιο ενθουσιασμό.\nΜε το μετρό δύο νέες υπόγειες σιδηροδρομικές γραμμές συμπληρώνουν την παλιά γραμμή του Ηλεκτρικού (ΗΣΑΠ), που ενώνει την Κηφισιά με τον Πειραιά. Η γραμμή 2 ξεκινάει από τα Σεπόλια και, με ενδιάμεσους σταθμούς στην πλατεία Αττικής, στον σταθμό Λαρίσης, στο Μεταξουργείο, στην Ομόνοια και στο Πανεπιστήμιο, φτάνει στο Σύνταγμα. Η γραμμή 3 ξεκινάει από το Πεντάγωνο (Εθνική Άμυνα) και, με ενδιάμεσους σταθμούς στη λεωφόρο Κατεχάκη, στην Πανόρμου, στους Αμπελοκήπους, στο Μέγαρο Μουσικής και στον Ευαγγελισμό, φτάνει επίσης στο Σύνταγμα.","word_count":317,"page_number":37,"chapter":"Ενότητα 2 — Η ζωή στην πόλη"},{"id":"e_dimotikou_0007","source_id":"e_dimotikou","title":"Η πορεία προς το μέτωπο*","content":"Ξημερώνοντας του Αγιαννιού, με την αύριο των Φώτων, λάβαμε τη διαταγή να κινήσουμε πάλι μπροστά*, για τα μέρη όπου δεν έχει καθημερινές και σκόλες. Έπρεπε, λέει, να πιάσουμε τις γραμμές που κρατούσανε ως τότε οι Αρτινοί*, από Χιμάρα ως Τεπελένι. Λόγω που εκείνοι πολεμούσανε απ’ την πρώτη μέρα, συνέχεια, κι είχαν μείνει σχεδόν οι μισοί και δεν αντέχανε άλλο.\nΔώδεκα μέρες κιόλας είχαμε μεις πιο πίσω, στα χωριά. Κι απάνω που συνήθιζε το αυτί μας πάλι στα γλυκά τριξίματα της γης και δειλά συλλαβίζαμε το γάβγισμα του σκύλου ή τον αχό της μακρινής καμπάνας, να που ήταν ανάγκη, λέει, να γυρίσουμε στο μόνο αχολόι που ξέραμε: στο αργό και στο βαρύ των κανονιών, στο ξερό και στο γρήγορο των πολυβόλων.\nΝύχτα πάνω στη νύχτα βαδίζαμε* ασταμάτητα, ένας πίσω απ’ τον άλλο, ίδια τυφλοί. Με κόπο ξεκολλώντας το ποδάρι από τη λάσπη, όπου, φορές, εκαταβούλιαζε ίσαμε το γόνατο. Επειδή το πιο συχνά ψιχάλιζε στους δρόμους έξω, καθώς μες στην ψυχή μας. Και τις λίγες φορές όπου κάναμε στάση να ξεκουραστούμε, μήτε που αλλάζαμε κουβέντα, μονάχα σοβαροί και αμίλητοι, φέγγοντας μ’ ένα μικρό δαδί, μια μια μοιραζόμασταν τη σταφίδα. Ή φορές πάλι, αν ήταν βολετό, λύναμε βιαστικά τα ρούχα και ξυνόμασταν με λύσσα ώρες πολλές, όσο να τρέξουν τα αίματα. Τι μας είχε ανέβει η ψείρα ως το λαιμό, κι ήταν αυτό πιο απ’ την κούραση ανυπόφερτο. Τέλος, κάποτε ακουγότανε στα σκοτεινά η σφυρίχτρα, σημάδι ότι κινούσαμε, και πάλι σαν τα ζα τραβούσαμε μπροστά να κερδίσουμε δρόμο, πριχού ξημερώσει και μας βάλουνε στόχο τα αεροπλάνα.","word_count":253,"page_number":43,"chapter":"Ενότητα 3 — 28η Οκτωβρίου"},{"id":"e_dimotikou_0008","source_id":"e_dimotikou","title":"Η πείνα","content":"Έτσι μου έρχεται να κλαίω, να κλαίω συνέχεια. Όταν θα τελειώσει τούτος ο φριχτός χειμώνας, θα γράψω μια τραγωδία που θα αρχίζει έτσι: «Πατάω ένα κουμπί και βγαίνει μια χοντρή και λέει στα παιδάκια νιξ φαΐ». Ύστερα θα παρουσιάζεται ο χορός. Παιδάκια σκελετωμένα που θα τραγουδάνε μια λέξη, μόνο μια λέξη. Θα την τραγουδάνε σε μονότονο ρυθμό: «Πεινάω. Πεινάω». Τίποτε άλλο ως το τέλος, όσο θα κρατάει η τραγωδία. Ο Βίκτορας Ουγκό για να γράψει τους Άθλιους μεταχειρίστηκε χιλιάδες λέξεις. Εγώ θα μεταχειριστώ μόνο μία: το ρήμα πεινάω, που θα τα λέει όλα. Τα παιδάκια μου θα τραγουδάνε και κάθε πεινάω θα είναι και μια εικόνα. Ίσως να χρειαστεί να γράψω πολλούς τόμους, γιατί θα έχει πολλά πεινάω. Δε χρειάζεται να τα γράψω με τη σειρά, δηλαδή πρώτα τούτο το πεινάω κι ύστερα το άλλο το πεινάω. Αν θέλω, αρχίζω από το τέλος. Τώρα εγώ σε ποιο πεινάω βρίσκομαι;\nΗ κοιλιά μου είναι φουσκωμένη σαν μπαλόνι και πεινάω. Σήμερα λιποθύμησα. Πεινάω, ουφ, έμμονη ιδέα μού έχει γίνει τούτο το ρήμα. Θα παίξω για να περάσει η ώρα. Θα βάλω τα ρήματα στη γραμμή, να παραβγούνε στο τρέξιμο. Το πεινάω τερματίζει πρώτο, δεύτερο ακολουθεί το κρυώνω, τρίτο το φοβάμαι και σε μεγάλη απόσταση πίσω τους το πονάω, το μισώ, το αγαπώ. Το γελώ, ξεφτίδι, ούτε ξεκίνησε από την αφετηρία.","word_count":218,"page_number":47,"chapter":"Ενότητα 3 — 28η Οκτωβρίου"},{"id":"e_dimotikou_0009","source_id":"e_dimotikou","title":"Ο Μάγκας","content":"Πρώτη φορά βρισκόμουν σε βαπόρι. Η θάλασσα μύριζε δυνατά, ο άνεμος φυσούσε.\nΜαζί ταξίδευε όλη η οικογένεια. Μα ιδιαίτερη γνωριμία και φιλία είχα με τον Λουκά και τις δίδυμες Άννα και Λίζα, τα τρία μικρότερα παιδιά του αφέντη μου. Αυτά έρχονταν κι έπαιζαν τακτικά μαζί μου, στην άκρη του περιβολιού της Κηφισιάς, όπου καθόταν ο Σωτήρης ο υπηρέτης, και όπου ήταν και το δικό μου σπιτάκι.\nΤον αφέντη μου δεν τον πολυήξερα. Είχε φτάσει από ταξίδι την παραμονή που φύγαμε από την Κηφισιά, με τον μεγάλο του γιο, τον Μήτσο. Ως προς τις δυο κυρίες, την κυρία Βασιωτάκη και την Εύα, τη μεγάλη της κόρη, που ήταν δεκαπέντε χρονών και δεν καταδεχόταν πια παιχνίδια, σχεδόν δεν τις γνώριζα. Σπάνιες ήταν οι επισκέψεις τους στη δική μου γωνιά του κήπου και μετρημένα τα χάδια τους.\nΤο βαπόρι ήταν πανηγύρι. Πολλοί οι επιβάτες, και με όλους ήμουν φίλος.\nΜόνο με μια κοπέλα, νόστιμη γαλανομάτα Εγγλεζίτσα, τα χάλασα από την πρώτη μέρα.\nΜα μήπως έφταιγα εγώ;\nΚαθόταν σε μια πάνινη καρέκλα κοντά στον Μήτσο και κουβέντιαζε μαζί του. Στο χέρι της, που τ’ άφηνε και κρεμόταν απ’ έξω από την καρέκλα, βαστούσε ένα άσπρο κουρελάκι και, ενόσω μιλούσε του Μήτσου, το κουνούσε μια εμπρός και μια πίσω, αργά αργά.\nΑνασηκώθηκα και ύψωσα τ’ αυτιά μου. Το κουρελάκι εξακολουθούσε να πηγαινοέρχεται σαν να μου λέει:\n— Και αμέ δε θα με πιάσεις ποτέ... και αμέ δε... και αμέ δε... και αμέ δε...\n— Α, έτσι είναι; του φώναξα.\nΜ’ έναν πήδο όρμησα στο χέρι της μικρής Εγγλέζας, άρπαξα το κουρέλι, το τίναξα δυο τρεις φορές, έτσι που να βγάλω από μέσα του κάθε πνοή, και, πιάνοντάς το ανάμεσα στα πόδια μου, του τράβηξα δυο δαγκωματιές και το έκανα τρία κομμάτια.\nΠού να φανταστώ εγώ πως θα σηκωνόταν τέτοια επανάσταση για ένα κουρέλι που σκότωσα!\nΗ κοπέλα έβαλε τις φωνές σαν να την είχα προσβάλει, φώναξε πως της έσχισα το νταντελένιο της μαντίλι. Ο Μήτσος, ο Λουκάς, ο κύριος Βασιωτάκης, οι δίδυμες, όλοι σηκώθηκαν ξεφωνίζοντας:\n— Μάγκα! Μάγκα!\nΔεν ήξερα ποιον να πρωτακούσω, σε ποιον να πρωτοτρέξω. Η κυρία Βασιωτάκη έλεγε και ξανάλεγε πως τα σκυλιά δεν είναι για συντροφιές. Μόνο η Εύα δεν είχε κουνήσει από την πλαγιαστή της καρέκλα, και γελούσε με την καρδιά της.\nΣταμάτησα να συλλογιστώ πώς να ευχαριστήσω όλους, πώς να πάω μεμιάς σε όλους, και τότε μ’ έπιασε ο Μήτσος και μ’ έδειρε.\nΔεν πόνεσα πολύ. Μια δυο μπατσιές στη ράχη δεν είναι πράμα να γίνει λόγος. Μα το φιλότιμό μου πειράχτηκε πολύ, γιατί τον Μήτσο δεν τον γνώριζα ακόμα αρκετά, ώστε να παραδεχθώ από εκείνον τέτοιες ελευθερίες απέναντί μου.\nΘύμωσα κι εγώ. Κακιωμένος με όλους, αρνήθηκα να πάω στη γαλανομάτα Εγγλεζίτσα, που, μετανιωμένη τώρα, με ξαναφώναζε κοντά της. Δε μ’ αρέσουν οι άνθρωποι που ανακατώνονται στις δουλειές των άλλων, κι εννοούσα να της το αποδείξω.","word_count":467,"page_number":51,"chapter":"Ενότητα 4 — Τα ζώα που ζουν κοντά μας"},{"id":"e_dimotikou_0010","source_id":"e_dimotikou","title":"«Αγάπες... με ουρά»","content":"Η μαμά μου είναι γατόφιλη, δηλαδή ανήκει σ’ εκείνη την τάξη των ανθρώπων που προτιμούν τις γάτες από τους σκύλους. Εμένα, αν με ρωτήσεις, μ’ αρέσουν περισσότερο οι σκύλοι. Όταν αγριεύουν, σου δίνουν μια ντόμπρα δαγκωνιά κι όχι εκείνες τις ύπουλες γατίσιες νυχιές, που δεν αποκλείεται να συνοδεύονται ΚΑΙ από δαγκωνιά! Διότι, βεβαίως, άλλη χάρη έχει του σκύλου. Η δαγκωνιά λέω. Πάει και τελείωσε.\nΗ μαμά, όμως, από τότε που έχασε το σκυλί ΤΗΣ –και πάνε πάρα πολλά χρόνια από τότε, γιατί το έχασε όταν ήταν δώδεκα χρονώ–, από τότε, λέω, δεν εννοεί να αγαπήσει άλλο σκυλί, και όλη την αγάπη της τη δίνει στις γάτες. Και όχι σε όλες, παρακαλώ, αλλά ΣΤΗ γάτα, που είναι κάθε φορά, βέβαια, η γάτα ΤΗΣ.\nΕδώ θα πρέπει να πω πως δεν μπορείς να θεωρείς εσύ μια γάτα για δικιά σου, γιατί γενικά αυτά τα πλάσματα είναι μονόχνοτα κι ανεξάρτητα, και δε θέλουν ν’ ανήκουν σε κανέναν παρά στον εαυτό τους. Μόνο μερικές φορές –κι αυτό σπάνια– συμβαίνει να δεθούν με κάποιον άνθρωπο, αλλά και τότε είναι γιατί τον διάλεξαν αποκλειστικά εκείνες.","word_count":179,"page_number":59,"chapter":"Ενότητα 4 — Τα ζώα που ζουν κοντά μας"},{"id":"e_dimotikou_0011","source_id":"e_dimotikou","title":"Τριήμερο στα κάγκελα","content":"Σε μια στιγμή παραμερίζει το πλήθος. Μαζί του κι εμείς. Παραμερίζουμε για να περάσει μια εικόνα ζωής, νιογέννητη κι αυτή, φερμένη όμως από πολύ παλιά παραμύθια:\nΈνας άντρας –ο πατέρας πρέπει να είναι– και στο σβέρκο του καθισμένο ένα μικρό παιδί. Πολύ μικρό. Περνούν αμίλητοι ανάμεσά μας και το παιδί από ψηλά, μ’ ένα πρόσωπο σοβαρό, κοιτάζει όλους μας αμίλητο κουνώντας με το χέρι του ένα χάρτινο σημαιάκι. Πού βρέθηκε τέτοια ώρα το παιδί; Πού βρέθηκε το σημαιάκι; Τα παιδιά τέτοια ώρα κοιμούνται. Τα σημαιάκια τέτοια ώρα είναι θαμμένα σε μπαούλα περιμένοντας κάποια εθνική γιορτή για να βγουν και να κρατηθούν από παιδικά χέρια.\nΥποδεχόμαστε σιωπηλοί τη νέα ζωή που περνάει ανάμεσά μας.\nΝα γονατίσουμε πρέπει.\nΝα σκύψουμε τα κεφάλια μας πρέπει στη νέα ζωή.\nΠαραμερίζουμε μόνο. Και σωπαίνουμε. Και το παιδί προχωράει πιο πάνω, όλο πιο πάνω, και το αυλάκι που ανοίγει πίσω του ξανακλείνει.\nΤώρα το παιδί φαντάζει από μακριά σαν να πορεύεται μοναχό του πάνω απ’ τα κεφάλια μας, σαν να ξανάγινε το θαύμα λες, και περπατάει πάνω στα κύματα το παιδί, έπειτα από τόσους αιώνες, δίχως να βουλιάζει.\nΏρα μεσάνυχτα.\nΣείεται η γη απ’ άκρη σ’ άκρη. Τρίζουν τα παράθυρα. Παραβιάζονται οι πόρτες. Όχι! Δεν είναι οχλοβοή. Είναι φωνές καθαρές. Δεν είναι όχλος. Δεν είναι βουητό. Είναι απόσταγμα γνώσης αιώνων, που τη ζύμωσαν οι άνθρωποι μέσα σε μπουντρούμια και σε κρυφά σχολειά.\nΧάνομαι προς τα αριστερά. Άλλος κόσμος στριμώχνεται εδώ. Κάποιοι κουβαλάνε θεόρατα πανέρια γεμάτα τρόφιμα. Για τα παιδιά. Για την καρδιά την πολιορκημένη.","word_count":248,"page_number":68,"chapter":"Ενότητα 5 — 17η Νοέμβρη"},{"id":"e_dimotikou_0012","source_id":"e_dimotikou","title":"Μικρός τύμβος","content":"Δίχως τουφέκι και σπαθί, με τον ήλιο στο μέτωπο,\nυπήρξατε ήρωες και ποιητές μαζί. Είστε το Ποίημα.\n\nΑπλώνοντας το χέρι μου δε φτάνει ως εκεί\nπου ωραία λουλούδια σε υψηλό λειμώνα* τις μορφές σας\n\nλιτανεύει ο αέρας της αρετής. Ω παιδιά μου,\nμπροστά σ’ αυτό το Ποίημα μετράει μόνο η σιωπή.","word_count":51,"page_number":69,"chapter":"Ενότητα 5 — 17η Νοέμβρη"},{"id":"e_dimotikou_0013","source_id":"e_dimotikou","title":"Άγνωστος αγωνιστής","content":"Η σφαίρα που σε σκότωσε\nπέρασε δίπλα από την καρδιά μου,\nδίπλα απ’ την καρδιά μου έπεσες νεκρός,\nδίπλα απ’ την καρδιά μου σ’ έθαψαν,\nαπάνω στον τάφο σου χτυπά.","word_count":30,"page_number":69,"chapter":"Ενότητα 5 — 17η Νοέμβρη"},{"id":"e_dimotikou_0014","source_id":"e_dimotikou","title":"Κοίτα με στα μάτια","content":"Κοίτα με στα μάτια κι έλα πιο κοντά,\nάγια μου καρδιά κι αγαπημένη,\nάκουσα κι απόψε πόρτα να χτυπά\nπέτρες θα κυλάν οι πεθαμένοι.\n\nΠώς να το ξεχάσω κείνο το παιδί\nστο περιβολάκι τ’ Αϊ-Νικόλα,\nέπινε τον ήλιο σαν χλωρό κλαδί\nπριν το θυμηθούν τα πολυβόλα.\n\nΚοίτα με στα μάτια και με το σουγιά\nπάρε απ’ τη φλέβα μου μελάνι\nγράψε τ’ όνομά του στην αστροφεγγιά\nχέρι φονικό να μην το φτάνει.\n\nΠού είσαι, Πέτρο; Πού είσαι, Γιάννη;\nΣτου κάτω κόσμου το σιντριβάνι.\nΝεράκι πίνω να λησμονήσω.\nΓύρισε πίσω. Γύρισε πίσω.","word_count":91,"page_number":69,"chapter":"Ενότητα 5 — 17η Νοέμβρη"},{"id":"e_dimotikou_0015","source_id":"e_dimotikou","title":"Ο Φωκίων ήταν ελάφι","content":"– Εμείς ξεκινήσαμε!\nΟ Λευτέρης –ναι– ήταν περήφανος.\n– Εμείς ξεκινήσαμε! ξανάπε. Κι άρχισαν να τρέμουν τα φίδια κι οι σαύρες απ’ τον φόβο τους! συνέχισε.\nΚαι ήταν –ναι!– περήφανος ο Λευτέρης.\nΟ Ιάκωβος σάστισε:\n– Μπράβο σας!\n– Κι εμείς που μόλις τώρα αρχίσαμε την προσπάθειά μας να σας βοηθήσουμε!\nΤο χελιδόνι φοβήθηκε πως τώρα κανείς δε θα το χρειαζόταν.\n– Μα δε θα μπορούσατε να βρείτε πιο κατάλληλη στιγμή! Τώρα είναι που χρειαζόμαστε τη βοήθεια όλων! το καθησύχασε ο σπουργίτης.\n– Συμφωνώ κι εγώ! Μια μικρή μονάχα αλλαγή θα γίνει στο σχέδιό μας. Μια ευχάριστη αλλαγή! χαμογελούσε ο σκίουρος. Λευτέρη, εξακολουθώ να θέλω να τραβήξω φωτογραφίες!\n– Από φωτογραφίες όσες θες! Έλα μαζί μου!\nΟ σπουργίτης φτερούγισε προς την πολιτεία.\nΤα μερμήγκια είχαν γεμίσει όλη την πλατεία.\nΠαντού μερμήγκια τραγουδούσαν, φώναζαν, ύψωναν σημαίες και πλακάτ.\n«ΛΕΥΤΕΡΙΑ ΓΙΑ ΟΛΟΥΣ» ο σκίουρος διάβασε ένα.\n«ΟΧΙ ΠΙΑ ΑΛΛΗ ΤΥΡΑΝΝΙΑ» συλλάβισε ένα άλλο το χελιδόνι δίπλα του.\nΟ σπουργίτης ήταν όλο καμάρι. Πλησίασε πιο κοντά στους άλλους δυο. Είχε μεγάλη φασαρία και ήθελε να τον ακούσουν.\n– Τα μερμήγκια πρώτα ξεκίνησαν τον αγώνα! τους φώναξε.\nΤο χελιδόνι απόρησε:\n– Τα μερμήγκια!\n– Και γιατί κλείστηκαν μέσα σ’ αυτό το κτίριο; ρώτησε ο σκίουρος.\n– Είναι το πιο μεγάλο σχολειό της χώρας! Γι’ αυτό κλείστηκαν εδώ. Επειδή τα γράμματα δεν αντέχουν την καταπίεση! Όμως θα σας τα πει πιο καλά ένα απ’ αυτά τα μερμήγκια. Οποιοδήποτε απ’ αυτά.\nΟ σπουργίτης έγνεψε σ’ ένα μερμήγκι που περνούσε δίπλα τους.\n– Μπήκαμε εδώ μέσα κι αποφασίσαμε να μη βγούμε παρά μονάχα με βία, αν δε μας ξαναδώσουν τη λευτεριά μας. Ήταν καιρός να δώσουμε ένα μάθημα σε όλα τα φίδια και στις σαύρες, σε όλους τους ποντικούς! τους εξήγησε αυτό.\n– Καλά και τι περιμένετε πως θα πετύχετε; ρώτησε το χελιδόνι.\n– Να σου πω εγώ! είπε ένα άλλο μερμήγκι που ήρθε και στάθηκε δίπλα τους. Ελπίζουμε πως έτσι θα κάνουμε τους συμπατριώτες μας να νικήσουν τον φόβο τους και να ενωθούν μαζί μας. Να ξεσηκωθούμε όλοι και να απαιτήσουμε λευτεριά και δικαιοσύνη.\n– Και δε φοβάστε;\nΟ σκίουρος έβλεπε κάπως μικρό το μερμήγκι για έναν τόσο μεγάλο αγώνα.\nΕκείνο έδειξε πίσω απ’ τα κάγκελα που περιτριγύριζαν τον τοίχο του μεγάλου κτιρίου:\n– Δείτε εκεί έξω!\nΦίδια, σαύρες, ποντικοί με όπλα, με κράνη και με σκοτεινά, ολοσκότεινα πρόσωπα στέκονταν και κοιτούσαν τα κλεισμένα μερμήγκια.\nΚάτι κρύο, παγωμένο, πέρασε πάνω απ’ τα πούπουλα του χελιδονιού.\nΚάτι κρύο, παγωμένο, άγγιζε τη γούνα του σκίουρου.\n– Ναι, φοβόμαστε! συνέχισε το μερμήγκι. Όμως πρέπει να νικήσουμε αυτόν τον φόβο. Το άλλο μερμήγκι πλησίασε τα κάγκελα:\n– Κι έπειτα δες! Δες εκεί πίσω. Πίσω απ’ τα φίδια, πίσω απ’ τα ποντίκια υπάρχουν όλοι εκείνοι που μας συμπαραστέκονται. Βουβά τώρα. Πιο ζωντανά σε λίγο. Κοντεύουμε να τους πείσουμε.\n– Ναι, πρέπει κάτι να κάνουν! φώναξε ο σκίουρος κι η φωτογραφική μηχανή υψώθηκε στο μάτι του.\nΈνα μερμήγκι με ένα πανό που έγραφε «ΛΕΥΤΕΡΙΑ ΣΕ ΟΛΟΥΣ» πέρασε μπροστά απ’ τον φακό και καθρεφτίστηκε μέσα του.","word_count":493,"page_number":70,"chapter":"Ενότητα 5 — 17η Νοέμβρη"},{"id":"e_dimotikou_0016","source_id":"e_dimotikou","title":"Ιστορίες με φίλους","content":"Η μικρή Τσιγγάνα έφτασε στο σπίτι του Δημήτρη λαχανιασμένη. Κρατούσε κάτι σφιχτά. Είδε τη\nγιαγιά στην αυλή.\n«Είναι εδώ ο Δημήτρης;»\n«Δημήτρηηηη, έλα κάτω που σε θέλει η φίλη σου».\nΟ Δημήτρης έβγαλε το κεφάλι του από ψηλά. Την είδε που περίμενε.\n«Έρχομαι».\n«Τι να σε φιλέψουμε;» τη ρώτησε η γιαγιά.\n«Τίποτα, ευχαριστώ. Βιάζομαι».\nΟ Δημήτρης κατέβηκε γρήγορα γρήγορα τα σκαλοπάτια.\n«Πώς και έτσι νωρίς; Θα ερχόμουν να σε πάρω».\n«Ήθελα να σου δώσω κάτι. Πάμε λίγο έξω».\nΒγήκαν από το σπίτι και κοντοστάθηκαν.\n«Λοιπόν; Τι είναι;»\nΆνοιξε τα χέρια της και του έδωσε μια φυσαρμόνικα. Το αγόρι έμεινε να κοιτάει την ανοιχτή της\nπαλάμη.\n«Είναι για σένα. Τη βρήκα στα πράγματα του παππού» είπε χωρίς να πάρει ανάσα.\nΟ Δημήτρης εξακολουθούσε να την κοιτάζει.\n«Γιατί δεν την κράτησες εσύ;» τη ρώτησε στο τέλος.\nΤα μάτια της μικρής άρχισαν τώρα να βουρκώνουν.\n«Αν ήθελα, θα την κράταγα. Όμως θέλω να την πάρεις εσύ».\nΆπλωσε το χέρι του και την πήρε. Ήταν πανέμορφη. Ασημένια με σκαλιστά γράμματα επάνω.\n«Δεν ξέρω να παίζω, όμως δε θα αργήσω να μάθω. Ευχαριστώ!» Την κοίταξε βαθιά στα σκοτεινά\nτης μάτια. «Πολύ!»\n«Χαίρομαι που σ’ αρέσει. Τώρα πρέπει να βιαστώ, γιατί η μάνα μου με περιμένει».\n«Στάσου λίγο. Έχω κάτι κι εγώ για σένα. Σκεφτόμουν να σ’ το δώσω αργότερα, μα αφού ήρθαν έτσι\nτα πράγματα... Περίμενε».\nΈτρεξε γρήγορα πάνω και ξανακατέβηκε στη στιγμή. Της έδωσε μια χρωματιστή πέτρα.\n\n«Τη βρήκα μόνος μου. Όταν έψαχνα κάτω στη θάλασσα. Μόλις την είδα, σκέφτηκα να τη χαρίσω\nσε σένα».\nΤην πήρε στα χέρια της.\n«Δεν έχω ξαναδεί πιο όμορφη πέτρα!»\n«Πήγαινε τώρα γιατί θα αργήσεις. Θα περάσω σε καμιά ώρα να πάμε να δούμε το Θωμά».\n«Γεια σου, Δημήτρη!»\nΓύρισε και άρχισε να τρέχει. Ο Δημήτρης μπήκε μέσα...\nΟ ουρανός σαν ν’ άρχισε να σκοτεινιάζει. Κι ένας αέρας χτύπαγε μ’ επιμονή τα δέντρα. Το αγόρι\nετοιμάστηκε να βγει.\nΠλησίασε στο ξέφωτο και κοντοστάθηκε. Ο τόπος που ήταν άλλοτε πλημμυρισμένος από ζωή είχε\nτώρα σωπάσει. Δεν υπήρχε ψυχή. Μονάχα ερημιά.\nΈτρεξε με όλη του τη δύναμη, κρατώντας τη φυσαρμόνικα στο χέρι, προς το λιμάνι. Όποιοι τον\nέβλεπαν απορούσαν. Ένα καράβι σήκωνε την άγκυρα. Την είδε που στεκόταν στα κάγκελα του πλοίου.\nΤον είδε και σήκωσε το χέρι της. Κάτι φάνηκε να του λέει, όμως εκείνος δεν την άκουγε. Δυνατός αέρας φύσηξε. Τρύπωσε στη φυσαρμόνικα που σφιχτά κρατούσε, κι εκείνη σαν να άφησε έναν ήχο.","word_count":395,"page_number":78,"chapter":"Ενότητα 6 — Οι φίλοι μας, οι φίλες μας"},{"id":"e_dimotikou_0017","source_id":"e_dimotikou","title":"Οι φίλοι τραγουδάνε","content":"Η φιλία μας!\nΣαν το πουλί απού πετά και μπάλα δεν το πιάνει,\nετσά ’ναι η φιλία μας κι ο κόσμος δεν τη βάνει!\n\nΤο φως του φίλου\nΌταν θα έχει ο φίλος σου λόγο κι εμπιστοσύνη,\nβαστάς ’να φως και πορπατείς τη νύχτα και δε σβήνει.\n\nΦίλος\nΚάνε έναν φίλο Κρητικό και άμα σε συμπαθήσει,\nτότε να είσαι σίγουρος πως δε θα σε πουλήσει.\n\nΦίλος γκαρδιακός\nΛένε πως η καρδιά χτυπά για να μας δίνει αίμα,\nμα γω την έχω να χτυπά για φίλους σαν κι εσένα.\n\nΦτωχός αλλά...\nΕίμαι φτωχός και το θωρώ, μα έχω καρδιά ατσαλένη,\nπου σε κιντύνους εκατό για τη φιλιά της μπαίνει.\n\nΚάποιες φορές\nΚαμιά φορά οι φίλοι σου δεν ξέρουνε τι λένε\nκαι σε πληγώνουνε βαθιά χωρίς να το κατένε.","word_count":127,"page_number":82,"chapter":"Ενότητα 6 — Οι φίλοι μας, οι φίλες μας"},{"id":"e_dimotikou_0018","source_id":"e_dimotikou","title":"Ακτύπη...τα γενέθλια","content":"Σήμερα ο Ακτύπης Ακτυπίδης ξύπνησε με πολύ κέφι. Ζήτημα αν είχε κοιμηθεί μία ώρα όλο το βράδυ. Στριφογύριζε ανυπόμονα και, όταν αποκοιμιόταν, έβλεπε όνειρα με...\nΙπτάμενες τρούφες, εκλεράκια, σου α λα κρεμ και κεφτεδάκια!\nΌχι, όχι! Δεν είχε κοιμηθεί νηστικός. Αλλά η μέρα που θα ξημέρωνε ήταν αυτή των γενεθλίων του. Των δέκατων γενεθλίων της ζωής του!\nΕπιτέλους όμως ξημέρωσε. Ο Ακτύπης πετάχτηκε σαν ελατήριο από το κρεβάτι του και όρμησε στην κουζίνα...\nΣε λίγο, όλη η οικογένεια, ο κύριος Ακτυπίδης, η κυρία Ακτυπίδου και ο Βαλάντης, ο μικρός αδερφός του Ακτύπη, έτρωγαν το αφράτο κέικ με ρευστή σοκολάτα – σπεσιαλιτέ της γιαγιάς. Ο Ακτύπης άρχισε ν’ ανησυχεί. Γιατί κανείς δεν του λέει «Χρόνια πολλά»; Το ξέχασαν μήπως; Ώσπου να προλάβει να τον πιάσει το παράπονο, εμφανίστηκε η μαμά του μ’ ένα πελώριο κουτί, που δε χώραγε καλά καλά από την πόρτα της κουζίνας. Γιούπιιιι! Αυτό ήταν. Δε χωρούσε αμφιβολία. Το ποδήλατο βουνού που είχε ζητήσει!\n«Χρόνια πολλά, χρόνια πολλά» ευχήθηκαν όλοι στον Ακτύπη. Γέμισε η κουζίνα αγκαλιές, φιλιά και χαρτιά περιτυλίγματος. Ο Ακτύπης, ξαναμμένος από χαρά, καβάλησε το ποδήλατο και διέσχισε το σαλόνι, ανάμεσα από τους καναπέδες και τις πολυθρόνες. Όταν η μαμά του είδε την πίσω ρόδα του ποδηλάτου να περνάει ξυστά από το κινέζικο βάζο της, έγινε καταπράσινη! Αλλά δεν είπε τίποτα, γιατί σήμερα ήταν η μέρα του Ακτύπη. Όλο το πρωινό πέρασε με τις ετοιμασίες για το πάρτι γενεθλίων. Τυροπιτάκια ψήνονταν στον φούρνο, πιατέλες με κεφτεδάκια και μπόμπες πηγαινοέρχονταν, χαρτοπετσέτες με τον Σκρουτζ και ποτήρια με τη Μίνι απλώθηκαν στο τραπέζι, ο κήπος καθαρίστηκε, όλα ετοιμάστηκαν όπως έπρεπε. Στις έξι ακριβώς κατέφθασαν οι πρώτοι: ο Άκης και η Παυλίνα. Αμέσως μετά η Λία και η Μαρία, ύστερα ο Γιώργος, ο Γρηγόρης, η Μάνια, ο Ευριπίδης, ώσπου μαζεύτηκαν όλοι... Έπαιξαν πολλά παιχνίδια. Σκυταλοδρομίες, «στρατιωτάκια αμίλητα-ακούνητα-αγέλαστα», κρυφτό, νεροπόλεμο, τυφλόμυγα, πειρατές, κλέφτες κι αστυνόμους, μέλισσα, μήλα, μπαλονομαχίες, μακριά γαϊδούρα, κυνήγι θησαυρού κι ένα καινούριο παιχνίδι που σκαρφίστηκαν εκείνη την ώρα και το ονόμασαν «αμπελοφιλοσοφίες».\nΟ Ακτύπης είχε μεγάλη τύχη. Η ομάδα του νικούσε συνεχώς. Είχε πια νυχτώσει για τα καλά και οι γονείς είχαν έρθει να πάρουν τα παιδιά τους.\n«Ένα μόνο παιχνίδι, μαμά» φώναζε ο Ακτύπης στη μαμά του «μόνο τσουβαλοδρομίες!». Ο ιδρώτας έσταζε από το κούτελό του. Το πουκάμισό του κρεμόταν έξω από το παντελόνι, το γόνατό του είχε γρατσουνιστεί κι έτρεχε λίγο αίμα, αλλά εκείνος χαμπάρι δεν έπαιρνε. «Διαλέγω πρώτος την ομάδα μου!» φώναξε.\n«Γρηγόρης, Γιώργος, Μανόλης, εσείς μαζί μου!» Ο Ευριπίδης τον κοίταξε παρακλητικά: «Κι εμένα, Ακτύπη. Πάρε με στην ομάδα σου!».\nΟ Ακτύπης είπε: «Στον επόμενο γύρο, Ευριπίδη».","word_count":424,"page_number":83,"chapter":"Ενότητα 6 — Οι φίλοι μας, οι φίλες μας"},{"id":"e_dimotikou_b_0001","source_id":"e_dimotikou_b","title":"Η συναυλία αρχίζει","content":"Οι μουσικοί του συγκροτήματος «Παγόβουνα» ήρθαν σήμερα το απόγευμα να εγκαταστήσουν τα μηχανήματά τους. Κάνανε μερικές δοκιμές, κι έδωσαν μάλιστα και μια μικρή συναυλία μόνο για μας. Α! Ήταν φανταστικά, καταπληκτικά! Και είμαι σίγουρος πως θα ’ναι ακόμα καλύτερα σε λίγο που θ’ αρχίσει η κανονική συναυλία.\nΛοιπόν, πρέπει να πάω στο πόστο μου. Έχω αναλάβει την κονσόλα μαζί με έναν φίλο του Τυφλοπόντικα, που είναι ειδικός σε αυτό το μηχάνημα. Εμείς οι δυο θα ρυθμίζουμε τον ήχο και τους φωτισμούς σ’ όλη τη διάρκεια της συναυλίας. Εγώ έχω αγωνία γιατί δεν ξέρω πολλά πράγματα, αλλά ο Ιβ φαίνεται πολύ έμπειρος.\nΟπ! Καταφθάνουν οι πρώτοι θεατές. Ανοίγουμε το μαγνητόφωνο, για να υπάρχει μουσική ως την ώρα της συναυλίας. Από το παρατηρητήριό μου κοιτάζω την αίθουσα, που σιγά σιγά γεμίζει. Ο Σπόρος, που είναι στα εισιτήρια μαζί με την Αννί και τους γονείς του Σουφλέ, έρχεται να μου δώσει αναφορά:\n– Έχουμε κόψει πενήντα!\n– Μόνο;\n– Γιατί; Λίγα είναι; Ακόμα θέλουμε μισή ώρα για ν’ αρχίσουμε. Μη φοβάσαι, σε λίγο δε θα πέφτει καρφίτσα στην αίθουσα.\nΗ αίθουσα όλο και γεμίζει. Σε ένα τέταρτο αρχίζουμε. Φτάνουν ο Κλοντ, ο Φανφάν, ο Μισέλ, ο Πατρίκ και ο Τζιντζίν. Τους κοιτάζω έναν έναν και τους χαμογελάω. Ο Σπόρος έρχεται να μας ενημερώσει.\n– Τριακόσιοι! μου φωνάζει χαμογελώντας.\nΑπό κει και πέρα δεν ξαναέμαθα άλλον αριθμό εισιτηρίων. Πρέπει να περιμένω ως το τέλος για να μάθω πόσοι ακριβώς μπήκαν. Και πώς αντέχουνε ως τότε;\nΟι θεατές που μπαίνουν τώρα είναι ελάχιστοι. Δεν υπάρχουν πια θέσεις. Ο Ιβ μού εξήγησε για τελευταία φορά τι πρέπει να κάνω. Θ’ ανάβω τους προβολείς. Πρέπει να είμαι πολύ προσεκτικός. Ελπίζω να μην τα κάνω θάλασσα.\n– Έτοιμος, μικρέ;\n– ... Ναι...\n– Εμπρός! Πάμε!\nΟ Ιβ κλείνει το μαγνητόφωνο. Με χέρια που τρέμουν, σβήνω τα φώτα της αίθουσας κι ανάβω τους δυο άσπρους προβολείς της σκηνής.\nΟ Φανφάν, ο Μισέλ, ο Κλοντ και ο Πατρίκ βγαίνουν στη σκηνή και παίρνουν τις θέσεις τους. Περιμένω να χτυπήσει ο Κλοντ τα ντραμς για ν’ ανάψω τους κόκκινους προβολείς.\nΠροσοχή... Φύγαμε! Τα ντραμς χτυπούν. Οι προβολείς ανάβουν. Ο Μισέλ πιάνει την κιθάρα του και οι χορδές κοντεύουν να σπάσουν. Ο Πατρίκ αρχίζει κι αυτός. Στις πρώτες σειρές αρχίζουν να χορεύουν. Ο Φανφάν κάνει ένα σόλο κιθάρα. Σ’ αυτό το σημείο ανάβω τους πράσινους προβολείς. Οι κόκκινοι σβήνουν. Ο Τζιντζίν μπαίνει στη σκηνή. Αρπάζει το μικρόφωνο.\nΤο κοινό χορεύει. Αναβοσβήνω τα φώτα στον ρυθμό της μουσικής.\nΤα φώτα αναβοσβήνουν κάτω απ’ τα δάχτυλά μου και δίνουν στο θέαμα μεγαλύτερη λάμψη, περισσότερη ομορφιά. Θα βάλω τα κλάματα απ’ τη χαρά μου.\nΗ συναυλία κρατάει δυο ώρες περίπου. Στο τέλος, ο κόσμος ξαναβγάζει στη σκηνή τους μουσικούς τέσσερις φορές. Κάθε φορά, μέσα σε μια θύελλα από χειροκροτήματα και σφυρίγματα.\nΗ γιορτή έφτασε στο τέλος της κι η αίθουσα αρχίζει ν’ αδειάζει σιγά σιγά. Ήμουν ενθουσιασμένος.","word_count":472,"page_number":9,"chapter":"Ενότητα 7 — Μουσική"},{"id":"e_dimotikou_b_0002","source_id":"e_dimotikou_b","title":"Ποτηρόφωνο","content":"Με τα μουσικά ποτήρια οργανώνονται μουσικές παραστάσεις στην Ευρώπη εδώ και 300 χρόνια. Μάλιστα, είχε εφευρεθεί και ένα όργανο που βασιζόταν σε αυτά από τον Βενιαμίν Φραγκλίνο, το οποίο έγινε γνωστό ως «αρμόνικα γυαλιού». Μεταξύ εκείνων που έγραψαν μουσική για ποτήρια και έδωσαν συναυλίες με αυτά περιλαμβάνονται και μερικοί διάσημοι συνθέτες, όπως και ερασιτέχνες μουσικοί. Ο Μότσαρτ έδωσε την πρώτη του συναυλία με ποτήρια όταν ήταν 17 χρονών.","word_count":68,"page_number":14,"chapter":"Ενότητα 7 — Μουσική"},{"id":"e_dimotikou_b_0003","source_id":"e_dimotikou_b","title":"Αν όλα τα παιδιά της γης","content":"Αν όλα τα παιδιά της γης\nπιάναν γερά τα χέρια\nκορίτσια, αγόρια στη σειρά\nκαι στήνανε χορό,\nο κύκλος θα γινότανε\nπολύ πολύ μεγάλος\nκι ολόκληρη τη γη μας\nθ’ αγκάλιαζε θαρρώ.\n\nΑν όλα τα παιδιά της γης\nφώναζαν τους μεγάλους\nκι αφήναν τα γραφεία τους\nκαι μπαίναν στον χορό,\nο κύκλος θα γινότανε\nακόμα πιο μεγάλος\nκαι δυο φορές τη γη μας\nθ’ αγκάλιαζε θαρρώ.\n\nΘα ’ρχόνταν τότε τα πουλιά,\nθα ’ρχόνταν τα λουλούδια,\nθα ’ρχότανε κι η Άνοιξη\nνα μπει μες στον χορό\nκι ο κύκλος θα γινότανε\nακόμα πιο μεγάλος\nκαι τρεις φορές τη γη μας\nθ’ αγκάλιαζε θαρρώ.","word_count":102,"page_number":18,"chapter":"Ενότητα 7 — Μουσική"},{"id":"e_dimotikou_b_0004","source_id":"e_dimotikou_b","title":"Τα μικρά παιδιά","content":"Τα μικρά παιδιά,\nτα μικρά παιδιά,\nπου κρατούνε στο χέρι τους\nσαν τον ήλιο τον χάρτινο\nτις ελπίδες μας...\n\nΤα μικρά παιδιά,\nτα μικρά παιδιά,\nπου μπερδεύουν τα λόγια τους,\nπου μιλούν με νοήματα\nστα παιχνίδια τους.\n\nΜες σε κήπους και χώματα\nμε λουλούδια ή λάσπη\nέναν κόσμο ζουν,\nτον πιο όμορφο.\n\nΤα μικρά παιδιά,\nτα μικρά παιδιά\nπου κρατούνε στο χέρι τους\nσαν τον ήλιο το χάρτινο\nτις ελπίδες μας...\n\nΈνα φύλλο ή μια μέλισσα,\nένα τόπι ή μια βέργα\nγίνονται αυτοκίνητα, χαρά,\nκόσμος, ζωή.\n\nΤα μικρά παιδιά,\nτα μικρά παιδιά,\nπου κρατούνε στο χέρι τους\nσαν τον ήλιο τον χάρτινο\nτις ελπίδες μας...\n\nΔυο κουτιά σπίρτων γίνηκαν\nο σταθμός και τα τρένα,\nπου μπορούνε να φτάσουνε\nστην άκρη της γης.\n\nΤα μικρά παιδιά,\nτα μικρά παιδιά\nπου κρατούνε στο χέρι τους\nσαν τον ήλιο τον χάρτινο\nτις ελπίδες μας...","word_count":141,"page_number":18,"chapter":"Ενότητα 7 — Μουσική"},{"id":"e_dimotikou_b_0005","source_id":"e_dimotikou_b","title":"Μια βραδιά στο Πόρτο Λίλι","content":"Μια βραδιά στο Πόρτο Λίλι,\nστα δρομάκια τα παλιά\nαντηχήσανε κιθάρες,\nμαντολίνα και βιολιά.\n\nΚι όλοι οι παιδικοί μου φίλοι\nμια βραδιά στο Πόρτο Λίλι\nκάνανε μαζί βαρκάδα\nστη μεγάλη φεγγαράδα.\n\nΜια βραδιά στο Πόρτο Λίλι,\nμια ζεστή, γλυκιά βραδιά\nέτρεξα στην προκυμαία\nνα φωνάξω τα παιδιά.\n\nΚι όλοι οι παιδικοί μου φίλοι\nμια βραδιά στο Πόρτο Λίλι\nγίνανε άστρα και μπαλόνια,\nτρεχαντήρια και τριζόνια.\n\nΜια βραδιά στο Πόρτο Λίλι,\nστα δρομάκια τα παλιά\nαντηχήσανε κιθάρες,\nμαντολίνα και βιολιά.","word_count":79,"page_number":19,"chapter":"Ενότητα 7 — Μουσική"},{"id":"e_dimotikou_b_0006","source_id":"e_dimotikou_b","title":"Χριστουγεννιάτικο δώρο","content":"Πολλοί, όταν μιλάνε για τα Χριστούγεννα, έχουν στον νου τους ένα ζεστό, στολισμένο γιορταστικό δωμάτιο, μ’ ένα τραπέζι φορτωμένο άφθονες και λαχταριστές λιχουδιές, γεμάτο με χαρούμενους ανθρώπους, που αλλάζουν ευχές και δώρα, καθώς ακούγονται τα κάλαντα από τρυφερές παιδικές φωνές.\nΓια τον μικρό Άντη όμως αυτά τα Χριστούγεννα ήταν πολύ διαφορετικά. Ούτε ελατοκορφές στολισμένες με κεράκια και χρυσωπές γυάλινες μπάλες ούτε τζάκι απ’ όπου να ξεχύνεται το άρωμα του ρετσινιού κι η θαλπωρή του πευκοκούτσουρου που καίγεται ούτε γεμιστή με κάστανα γαλοπούλα ούτε καινούρια ρούχα και παιχνίδια. Για μοναδικό δώρο είχε πάρει μια αλλαξιά με μεταχειρισμένα ρούχα.\nΖούσε με τη μητέρα του και άλλες οικογένειες μέσα σε αντίσκηνα, ανίκανα να εμποδίσουν τον άνεμο και τη βροχή να τους περονιάζουν. Στο σχολείο έκανε παρέα με μερικούς συμμαθητές του, προσφυγόπουλα σαν τον ίδιο. Μα νοσταλγούσε τους παλιούς φίλους των ευτυχισμένων ημερών. Η μεγάλη καταστροφή τούς είχε σκορπίσει και τους είχε κάνει να χαθούν. Οι νέοι του σύντροφοι ήταν, όπως ο ίδιος, συγκρατημένοι και διστακτικοί στα παιχνίδια και σε όλες τις εκδηλώσεις, λες και προσπαθούσαν μάταια να ξεδιαλύνουν σε τι είχαν φταίξει και τους τιμώρησαν με σκληρό τρόπο. Για τον μικρό Άντη όμως υπήρχε μια παραπανίσια απώλεια. Στον πόλεμο, που τόσο αναπάντεχα είχε σαρώσει τη χώρα, είχε χαθεί ο πατέρας του...\nΤην παραμονή των Χριστουγέννων ο Άντη καθόταν μόνος. Η μητέρα είχε πάει να πάρει λίγα τρόφιμα, που η κυβέρνηση μοίραζε για τις γιορτές στους πρόσφυγες απ’ τη βοήθεια του ΟΗΕ. Άρχισε να ζωγραφίζει φιγούρες από την αναπαράσταση της Γέννησης: τον Ιωσήφ, τον Χριστό, τη Μαρία, τους Μάγους, τα ζώα, τους αγγέλους. Τι λογής πλάσματα ήταν αλήθεια οι άγγελοι; Τους έβλεπε συχνά ζωγραφιστούς, μα έναν πραγματικό δεν έτυχε ποτέ να ανταμώσει. Απορροφημένος από τις σκέψεις του, δεν άκουσε...","word_count":285,"page_number":25,"chapter":"Ενότητα 8 — Χριστούγεννα"},{"id":"e_dimotikou_b_0007","source_id":"e_dimotikou_b","title":"Φρικαντέλα, η μάγισσα που μισούσε τα κάλαντα","content":"Ήτανε κάποτε μια μάγισσα που τη λέγανε Φρικαντέλα Ζαρζουέλα Σαλμονέλα Στρυφνίνη. Η Φρικαντέλα ήταν κακιά. Τόσο κακιά, που μισούσε αφάνταστα όλα τα καλά. Ακόμα και τις λέξεις που είχανε τις συλλαβές «καλά», κι αυτές τις μισούσε. Για να σας δώσω να καταλάβετε, η μάγισσα Φρικαντέλα δεν έτρωγε ποτέ καλαμαράκια. Έτρωγε μόνο κακαμαράκια. Και στο σπίτι της δεν είχε ούτε καλάθια ούτε μπουκαλάκια. Είχε μόνο κακάθια και μπουκακάκια. Και δεν πήγαινε ποτέ εκδρομή στα Καλάβρυτα. Πήγαινε κάθε χρόνο στα Κακάβρυτα. Και δε χόρευε ποτέ καλαματιανό. Χόρευε μόνο κακαματιανό. Και, βέβαια, δεν της αρέσανε καθόλου τα παραμύθια με καλό τέλος. Έκλεβε από τα παιδιά τα βιβλία με καλό τέλος, έκοβε την τελευταία σελίδα και στη θέση της έβαζε ένα κακό τέλος...\nΑλλά πιο πολύ απ’ όλα η μάγισσα Φρικαντέλα μισούσε τα κάλαντα. Δεν ήθελε να ακούει καθόλου κάλαντα. Ήθελε να ακούει μόνο κάκαντα.\nΜια μέρα, λοιπόν, παραμονή Πρωτοχρονιάς ήταν, η Φρικαντέλα ζύμωνε κουλουράκια με μαγική μαγιά που όποιος τα έτρωγε μεταμορφωνόταν σε σαπουνόφουσκα, όταν άκουσε χαρούμενες φωνές. Ήταν τα παιδιά της γειτονιάς που χτυπούσαν τα τριγωνάκια τους και τραγουδούσαν τα κάλαντα. «Αρχιμηνιά κι Αρχιχρονιά, ψιλή μου δεντρολιβανιά...» Η μάγισσα βγήκε στο μπαλκόνι της και έμπηξε τις φωνές: «Σκασμός, σκουπιδόπαιδα! Αν δε σταματήσετε να λέτε τα κάλαντα, θα το μετανιώσετε πικρά!». Ήταν τώρα έξω φρενών. «Τι να κάνω άραγε για να τα τιμωρήσω;» σκεφτόταν. «Το βρήκα! Θα τα μεταμορφώσω τώρα αμέσως σε βατραχάκια!» Κούνησε πέρα δώθε το μαγικό της ραβδί και μεταμόρφωσε όλα τα παιδιά σε βρεγμένα βατραχάκια. Αλλά αυτά συνέχισαν να κοάζουν με κέφι τα κάλαντα. Πεισμάτωσε και τα μεταμόρφωσε σε γατούλες, αλλά αυτά συνέχισαν να νιαουρίζουν χαδιάρικα τα κάλαντα. Θυμωμένη, με το μαγικό της ραβδί συνέχισε και τα έκανε κατσικάκια, παπάκια, αγελαδίτσες, γαϊδουράκια, αλλά αυτά συνέχισαν με πείσμα να τραγουδούν μελωδικά τα κάλαντα.\nΑπογοητευμένη καθώς ήταν, αποφάσισε να τα ξανακάνει παιδιά, αλλά να κλέψει τις φωνές τους. «Να δούμε μετά πώς θα τραγουδάνε τα κάλαντα χωρίς φωνές» σκέφτηκε. Το ’πε και το ’κανε. Κούνησε κυματιστά το μαγικό ραβδί της και τους έκλεψε τις φωνές και τις φυλάκισε μέσα σε μαγικά μπαλόνια. Σε ροζ μπαλόνια τις φωνές των κοριτσιών και σε γαλάζια των αγοριών. Έτσι, λοιπόν, τα παιδιά έμειναν άφωνα. Ούτε να τραγουδήσουν μπορούσαν ούτε να μιλήσουν ούτε να γελάσουν ούτε να παραπονεθούν. Μόνο να ψιθυρίσουν, κι αυτό τόσο σιγανά, που μόλις ακουγόντουσαν.\nΌταν βράδιασε, τα παιδιά πήγανε στο πέτρινο κάστρο της μάγισσας για να βρούνε τις κλεμμένες φωνές τους. Με δυσκολία κατόρθωσαν να μπουν στο στοιχειωμένο κάστρο. Εκεί είδαν τη μάγισσα να κοιμάται ροχαλίζοντας. Παρ’ όλο που η μάγισσα κοιμόταν του καλού καιρού, κρατούσε σφιχτά στο χέρι της τα μπαλόνια με τις φωνές των παιδιών. Στο κομοδίνο της βρισκόταν το μαγικό ραβδί της. Τα παιδιά κλέβουν το ραβδί και με τα αγκάθια του σκαντζόχοιρου σπάνε τα μπαλόνια. Από την πολλή φασαρία η Φρικαντέλα ξυπνάει και βλέπει μπροστά της τα παιδιά. Αρχίζει να τσιρίζει κι αυτά της λένε ότι θέλουν να της πουν τα κάλαντα. Ψάχνει να βρει το ραβδί της για να τα μεταμορφώσει, αλλά πουθενά. Το βλέπει στα χέρια των παιδιών κι αυτά της υπόσχονται ότι θα της το δώσουν εάν κάτσει φρόνιμα και ακούσει με κατάνυξη τα κάλαντα όπως τα λένε στην Πελοπόννησο, στην Κρήτη, στην Κύπρο, στην Κέρκυρα, στη Θεσσαλία, στη Μακεδονία και στη Μυτιλήνη.\nΈτσι, τα παιδιά τραγουδούσαν όλο το βράδυ στη μάγισσα τα κάλαντα. Κάλαντα μικρά και κάλαντα μεγάλα, κάλαντα από μέρη μακρινά και από μέρη κοντινά, κάλαντα σημερινά και αλλοτινά. Όταν τελείωσαν και τα τελευταία, ξημέρωνε πια. Τα παιδιά έδωσαν στη μάγισσα το μαγικό ραβδί της. «Όχι» είπε «δεν το θέλω, καθόλου δεν το θέλω!» «Δε θέλεις το ραβδί σου; Τι θέλεις τότε;» ρώτησαν απορημένα. «Να ερχόσαστε κάθε Χριστούγεννα και κάθε Πρωτοχρονιά να μου λέτε τα κάλαντα. Τώρα που αναγκάστηκα να τα ακούσω, κατάλαβα πόσο όμορφα είναι». Από τότε η μάγισσα άλλαξε και άρχισαν να της αρέσουν όχι μόνο τα κάλαντα αλλά και όλα τα καλά πράγματα.","word_count":642,"page_number":27,"chapter":"Ενότητα 8 — Χριστούγεννα"},{"id":"e_dimotikou_b_0008","source_id":"e_dimotikou_b","title":"Τα Χριστούγεννα στον κόσμο","content":"Πολωνία\nΗ παραμονή των Χριστουγέννων ονομάζεται Γιορτή του Αστεριού. Εκείνη την ημέρα πολλοί ετοιμάζουν ένα ειδικό γεύμα και κάθονται στο τραπέζι όταν το πρώτο αστέρι βγει στον ουρανό. Στη συνέχεια τραγουδούν τα κάλαντα και ανάβουν κεριά. Σε μερικά σπίτια, τα αγόρια ντύνονται σαν τους τρεις μάγους και προσφέρουν τα δώρα.\nΜεξικό\nΣτο Μεξικό οι άνθρωποι διασκεδάζουν πολύ! Οι γιορτές αρχίζουν στις 16 Δεκεμβρίου με την αναπαράσταση της άφιξης της Μαρίας και του Ιωσήφ στη Βηθλεέμ. Στη συνέχεια, ο κόσμος συγκεντρώνεται στα σπίτια, όπου πάντα υπάρχει μια φάτνη σε μια γωνιά, και γιορτάζουν. Αυτό επαναλαμβάνεται σε διαφορετικό σπίτι κάθε νύχτα, μέχρι τα Χριστούγεννα.\nΑυστραλία και Νέα Ζηλανδία\nΣτην Αυστραλία και στη Νέα Ζηλανδία τα Χριστούγεννα πέφτουν κατακαλόκαιρο. Γι’ αυτό και τα κάλαντα μιλούν για ήλιο και όχι για χιόνι. Πολλοί τρώνε το χριστουγεννιάτικο γεύμα σε πικνίκ στην παραλία, αλλά υπάρχουν και αρκετοί άλλοι που απολαμβάνουν ένα παραδοσιακό γεύμα με γαλοπούλα. Καναδάς\nΣτο Μόντρεαλ κάθε χρόνο γίνεται η μεγάλη παρέλαση του Αϊ-Βασίλη, ο οποίος μέσα σε άρμα «πετάει» πάνω από τα έκπληκτα μάτια των παιδιών. Το έθιμο προτείνει στα παιδιά να αφήνουν μπροστά στο τζάκι γάλα και μπισκότα για τον Αϊ-Βασίλη.\nΓαλλία, Ουγγαρία, Ελλάδα την ημέρα των Φώτων\nΣτη Γαλλία τη μέρα των Θεοφανίων φτιάχνουν μια πίτα και μέσα στη ζύμη κρύβουν ένα φλουρί. Όποιος βρει το φλουρί ονομάζεται βασιλιάς ή βασίλισσα.\nΣτην Ουγγαρία τη μέρα αυτή τα παιδιά μεταμφιέζονται σε μάγους και μεταφέρουν τη φάτνη από πόρτα σε πόρτα ζητώντας ένα μικρό φιλοδώρημα.\nΣτη χώρα μας ρίχνουμε τον σταυρό στη θάλασσα για να τον πιάσει ο καλύτερος και γρηγορότερος κολυμβητής.","word_count":259,"page_number":30,"chapter":"Ενότητα 8 — Χριστούγεννα"},{"id":"e_dimotikou_b_0009","source_id":"e_dimotikou_b","title":"Το δάσος που ταξίδευε","content":"Ήταν ένα δάσος με έλατα που είχε πια βαρεθεί να είναι δάσος. Για την ακρίβεια, είχε αρχίσει να βαριέται από τότε που οι νεράιδες μάζευαν τα μαγικά ραβδιά τους, τους σάκους με τη μαγική χρυσόσκονη και, τέλος πάντων, όλα τα μαγικά τους σύνεργα, κι έφευγαν μια μια γι’ αλλού, έτσι, χωρίς λόγο κι αφορμή. Και τα πουλιά όλο και πιο σπάνια φτεροκοπούσαν στα κλαριά του, ώσπου σταμάτησαν ολότελα να έρχονται. Όσο για τους ανθρώπους, αυτοί ούτε καν υποψιάζονταν ίσως πως υπήρχε. Τόσο απόμακρα είχε φυτρώσει το δάσος με τα έλατα.\nΠλησίαζαν τα Χριστούγεννα, και τα έλατα βαρυγκωμούσαν για την άχαρη τύχη που τους έλαχε τρίζοντας παράξενα τα κλαριά τους. Α, να μπορούσαν, λέει, να ταξίδευαν, να έβλεπαν πολιτείες, κόσμο! Ούτε ένα παιδί δεν είχαν δει ποτέ τους, ούτε μια καμινάδα να καπνίζει, ούτε ένα κοχύλι μικρούλι τόσο δα. Επειδή όμως το ήξεραν πως τα δέντρα μένουν ακίνητα, όλο και πιο πολύ φούντωνε η επιθυμία τους για ταξίδια μακρινά. Είχαν ακουστά για κείνα τα έλατα στα γιορτινά σαλόνια, με τα κλαριά τους φορτωμένα λαμπιόνια και παιχνίδια, μα δεν τα ζήλευαν και πολύ, γιατί σαν τέλειωναν οι γιορτές ξεραίνονταν πεταμένα στον δρόμο. Όχι, καθόλου δεν τα ζήλευαν...\nΜια από κείνες τις νύχτες ήχησαν γλυκά κοντά στο δάσος με τα έλατα τρία καμπανάκια, ντρίγκι, ντριν, ντραν. Ήταν το χρυσό το καμπανάκι, το ασημένιο και το χάλκινο στο έλκηθρο του Αϊ-Βασίλη. Πήγαινε από Κίνα στην Ευρώπη για να μαζέψει ο Αϊ-Βασίλης τα πρωτοχρονιάτικα δώρα. Σταμάτησε να ξαποστάσει λίγο, και το λίγο έγινε πιο πολύ γιατί, καθώς άκουσε τα παραπονιάρικα τριξίματα, πήρε την απόφαση να κάνει κάτι και για τα έλατα που είχαν φυτρώσει τόσο απόμακρα. Και του ήρθε μια φαεινή ιδέα! Από καιρό σκόπευε να αλλάξει το κόκκινο παλτό του με την άσπρη γούνα. Δεν ήταν μόνο που το είχε βαρεθεί, το ίδιο χρόνια και χρόνια, αλλά, να, είχε αρχίσει να παλιώνει κιόλας, κι εκεί στον γιακά και στα μανίκια είχε μετρήσει ο Αϊ-Βασίλης πέντ’ έξι τρύπες. Σκέφτηκε, λοιπόν, πως, αν μίκραιναν τα έλατα και κόλλαγαν στο καινούριο του παλτό, κι αυτός θα φόραγε, επιτέλους, κάτι πιο πρωτότυπο κι εκείνα τις γιορτινές μέρες θα ταξίδευαν μαζί του σ’ ολόκληρη τη γη, απ’ άκρη σ’ άκρη.\nΚι έτσι έγινε. Μίκρυναν τα έλατα, μίκρυναν κι άλλο, κι άλλο, κι ήρθαν και κόλλησαν στο καινούριο παλτό του Αϊ-Βασίλη. «Να ξεκινήσει το έλκηθρο!» πρόσταξε εκείνος.\nΣε μια και μόνη μέρα ταξίδεψαν τα έλατα σε τριακόσιες δυο πολιτείες, σ’ έξι χιλιάδες πεντακόσια δώδεκα χωριά, συνάντησαν αμέτρητα παιδιά κι άκουσαν τα κάλαντα σ’ εκατό διαφορετικές γλώσσες. Την άλλη μέρα είδαν κι άκουσαν ακόμη πιο πολλά. Έτσι κυλούσαν οι μέρες, με το έλκηθρο μια να πετάει πάνω από θάλασσες, και μια να τρέχει σε χιονισμένες πεδιάδες και βουνά. Περνώντας το έλκηθρο από ένα χωριό στην έρημο Σαχάρα, είπε το πιο γέρικο απ’ τα έλατα: «Εγώ θα μείνω εδώ, μου φτάνουν όσα είδα κι άκουσα». Γλίστρησε απ’ το παλτό του Αϊ-Βασίλη και διάλεξε να ριζώσει καταμεσής σε μια κατάξερη πλατειούλα. Κι επειδή οι πιο πολλοί δεν είχαν δει ποτέ τους δέντρο, το γέρικο έλατο πέρασε ζωή χαρισάμενη.","word_count":505,"page_number":31,"chapter":"Ενότητα 8 — Χριστούγεννα"},{"id":"e_dimotikou_b_0010","source_id":"e_dimotikou_b","title":"Ο μαγικός κόσμος των βιβλίων","content":"Τα δυο αδέρφια συνήθιζαν να παίζουν με μια υδρόγειο σφαίρα. Καθώς τη στριφογύριζαν και τη στριφογύριζαν, με κλειστά μάτια, σημάδευαν με το δάχτυλό τους ένα σημείο. Και εάν τύχαινε το σημείο εκείνο να είναι το Πεκίνο ή η Μαδαγασκάρη ή το Μεξικό, τότε έψαχναν στις βιβλιοθήκες να βρουν βιβλία με ιστορίες για τον τόπο που διάλεξαν.\nΑγαπούσαν το διάβασμα. Το χαίρονταν. Το φως στο παραθύρι τους ήταν αναμμένο ως αργά το βράδυ. Με το «φως» των βιβλίων βρέθηκαν να περπατούν στο σινικό τείχος στην Κίνα, ν’ ακούν το τραγούδι του ωκεανού παρέα με τους Βίκιγκς, να ζουν δίπλα στις πυραμίδες της αρχαίας Αιγύπτου, να γλιστρούν με το έλκηθρο στις παγωμένες λίμνες συντροφιά με τους Εσκιμώους, να παίρνουν μέρος στους αγώνες της αρχαίας Ολυμπίας, να στεφανώνονται μ’ ένα κλωνάρι αγριελιάς.\nΌταν τα έπαιρνε ο ύπνος, τα παραμύθια, οι ιστορίες, οι θρύλοι, οι τόποι, οι συγγραφείς, οι ήρωες μπερδεύονταν στα όνειρά τους, καθώς έρχονταν να τους νανουρίσουν απαλά: Ο Αίσωπος διηγιόταν τους μύθους του στη Σεχραζάτ από το πιο ψηλό σημείο του πύργου του Άιφελ, ο Χριστόφορος Κολόμβος άκουγε τον Τομ Σόγερ να του λέει τις σκανταλιές του σ’ ένα ποταμόπλοιο του Μισσισσιππή, η Αλίκη ταξίδευε στη χώρα των θαυμάτων μέσα σ’ ένα έλκηθρο συντροφιά με τη Μαίρη Πόπινς, ο Άντερσεν έλεγε τα δικά του παραμύθια στην αράχνη Ανάνσε έξω από την πυραμίδα.\nΤο παιχνίδι με την υδρόγειο σφαίρα σε συνδυασμό με τα βιβλία διασκέδαζε αφάνταστα τα δυο αδέρφια, γιατί δεν τελείωνε ποτέ. Είχανε βρει έναν τρόπο να γίνουν θαλασσοπόροι κι εξερευνητές μέσα από τις σελίδες τους. Με το «φως» τους κατακτούσαν τον πλανήτη, ζούσαν διάφορους πολιτισμούς, διάφορες εποχές, θαύμαζαν την ποικιλία τους. Με λίγα λόγια, συναντούσαν τη ζωή στο μεγάλο κόσμο, έξω από τη μικρή τους καμαρούλα. Πετούσαν παντού, ταξίδευαν παντού, ονειρεύονταν.\nΚαι βέβαια ξεχνούσαν να κλείσουν το φως!\n– Παιδιά, πότε επιτέλους θα κοιμηθείτε; τους φώναζαν οι γονείς τους. Είναι αργά. Σβήστε το φως!\n– Δεν μπορούμε, τους απαντούσαν. Το «φως» των βιβλίων δε σβήνει ποτέ.","word_count":326,"page_number":35,"chapter":"Ενότητα 9 — Βιβλία - βιβλιοθήκες"},{"id":"e_dimotikou_b_0011","source_id":"e_dimotikou_b","title":"Όταν η Βιβλιοθήκη συναντά τους αναγνώστες","content":"Οι άνθρωποι που είναι αναγνώστες είναι τυχεροί γιατί μέσα από τα κάθε λογής βιβλία αντλούν πληροφορίες, ταξιδεύουν με το πνεύμα και την ψυχή, εξερευνούν νέες καταστάσεις που δε συναντούν στην καθημερινότητά τους. Η Δημόσια Κεντρική Βιβλιοθήκη Πύργου αποτελεί χώρο μάθησης, πληροφόρησης, γνωριμίας και εξοικείωσης με το βιβλίο, τη μελέτη και την αναζήτηση της γνώσης. Απευθύνεται κατά κύριο λόγο στο μεγάλο κομμάτι του πληθυσμού, το οποίο δεν έχει ουσιαστική επαφή με το βιβλίο.\nΣτόχος του παιδικού τμήματος της Βιβλιοθήκης Πύργου είναι να προσφέρει στα παιδιά βιβλία που καλύπτουν τις ανάγκες της ηλικίας τους. Προσπαθεί να τα φέρει από πολύ νωρίς σ’ επαφή με τον έντυπο λόγο και να τα κάνει να αγαπήσουν το βιβλίο και το διάβασμα. Κι όταν οι μικροί αναγνώστες δεν μπορούν να έρθουν στη Βιβλιοθήκη, τότε πηγαίνει η Βιβλιοθήκη να τους συναντήσει! Με τα δυο της ειδικά διαμορφωμένα και εξοπλισμένα βιβλιο-αυτοκίνητα διακινεί βιβλία και οπτικο-ακουστικό υλικό σε δεκάδες δανειστικά κέντρα, κυρίως σχολεία και πολιτιστικούς συλλόγους, σε όλη την Ηλεία και τους γειτονικούς νομούς. Ο δανεισμός, ο οποίος είναι ηλεκτρονικός, γίνεται με την ευθύνη του υπεύθυνου του δανειστικού κέντρου. Το υλικό παραμένει στο δανειστικό κέντρο για όσο διάστημα απαιτηθεί από τους χρήστες (μέσος χρόνος ανανέωσης δανεισμού 2 μήνες). Οι χρήστες, μαθητές και εκπαιδευτικοί, έχουν τη δυνατότητα να ενημερωθούν για παλαιούς αλλά και πολλούς νέους τίτλους όλων των ενδιαφερόντων, νεανική λογοτεχνία, δοκίμια, σχολικά βιβλία, εγκυκλοπαίδειες, βιβλία γενικού ενδιαφέροντος κτλ.","word_count":229,"page_number":42,"chapter":"Ενότητα 9 — Βιβλία - βιβλιοθήκες"},{"id":"e_dimotikou_b_0012","source_id":"e_dimotikou_b","title":"Ανασκαφές στα τυφλά","content":"Ζητωκραυγές ακούστηκαν καθώς το σχολικό λεωφορείο έφτασε στο παλιό μοναστήρι όπου γίνονταν αρχαιολογικές ανασκαφές. Η πέμπτη τάξη έκανε την καλοκαιρινή της εκδρομή. Είχαν καθίσει ώρες στο λεωφορείο —τουλάχιστον έτσι τους φάνηκε — και γι’ αυτό, μόλις έφτασαν, πετάχτηκαν έξω να ξεμουδιάσουν.\nΒγήκαν όλοι, εκτός από το Νίκο και τη Σοφία, που έμειναν στο πίσω κάθισμα. Αυτοί οι δυο βαριούνταν τρομερά. Η αρχαιολογική σκαπάνη δεν ήταν η ιδανική τους διασκέδαση!\n«Τυφλοπόντικες!» φώναξε ο δάσκαλός τους, ο κ. Γεωργίου. «Τυφλοπόντικες, σκάψτε τη γη και βγάλτε στην επιφάνεια ό,τι έχει στα σωθικά της...»\nΌμως, ο Νίκος κι η Σοφία δεν άκουσαν τίποτα, γιατί είχαν μείνει πίσω, ενώ όλοι οι άλλοι σκαρφάλωναν με μεγάλο ενθουσιασμό το φράχτη για να μπουν στο λιβάδι.\nΤΟ ΣΕΝΑΡΙΟ: Σκηνή. Μια τάξη παιδιών κατεβαίνει από το πούλμαν στην είσοδο του παλιού μοναστηριού, όπου έφτασαν για μια ημερήσια εκδρομή. Ο Νίκος κι η Σοφία, II χρονών, μένουν πίσω, καθώς τα υπόλοιπα παιδιά προχωρούν πίσω απ’ τον δάσκαλό τους διασχίζοντας τον αγρό.\nΝίκος: Φαίνεται πως είναι όμορφη μέρα σήμερα. Κρίμα που είναι τόσο βαρετή... Κοίτα! Από αυτή την πλευρά του αγρού μπορείς να δεις τον χώρο όπου γίνεται η ανασκαφή. Ένα είδος ανασκαφής στα χωράφια.\nΣοφία: Α! Είναι απίθανα! Κοίτα πρόβατα, Νίκο! Κοίτα πόσα πρόβατα...\nΝίκος: Ποπό! Πολλά πρόβατα!\nΣοφία: ... και σκηνές! Τι κάνουν στις σκηνές; Διακοπές;\nΝίκος: Μην είσαι ανόητη! Μάλλον είναι οι άνθρωποι που σκάβουν. Πρέπει κάπου να κοιμούνται, έτσι δεν είναι;\nΣοφία: Νόμιζα ότι μόλις ήρθαν, έσκαψαν λίγο και πήγαν...\nΝίκος: Όχι... είναι όλοι φοιτητές που έρχονται και σκάβουν στις διακοπές τους. Και δε σκάβουν.\nΑυτό δεν είναι κανονικό σκάψιμο! Ξεσκεπάζουν αργά, καθαρίζουν ένα σκουπιδάκι την ώρα... με πινέλα ζωγραφικής και κάτι άλλα.\nΣοφία: Ναι, έτσι είναι... Προσεκτικά. Κι έτσι, δε χαλάνε τίποτα.\nΝίκος: Καλά, αλλά εγώ εξακολουθώ να βαριέμαι!\nΣοφία: Τι είναι αυτό;\nΝίκος: Η πόρτα του φράχτη. Προχώρα, υπάρχει άλλη μια που περνάει μέσα απ’ το χωράφι... Οι άλλοι όλοι έχουν φτάσει τώρα κάτω στο ποτάμι...\n(Τα παιδιά σκαρφαλώνουν, πηδούν και διασχίζουν το χωράφι.)\nΣοφία: Είχε δίκιο ο κύριος Γεωργίου για τους τυφλοπόντικες — πρέπει να είναι χιλιάδες από δαύτους. Κοίτα! Τρύπες από τυφλοπόντικες παντού...","word_count":350,"page_number":51,"chapter":"Ενότητα 9 — Βιβλία - βιβλιοθήκες"},{"id":"e_dimotikou_b_0013","source_id":"e_dimotikou_b","title":"Όνειρα για ταξίδια στ’ αστέρια","content":"Τα ταξίδια σε μακρινά άστρα και άλλους γαλαξίες θεωρούνται σήμερα αδύνατα, όμως ο επιστημονικός κόσμος δε χάνει την αισιοδοξία του και προγραμματίζει, θεωρητικά προς το παρόν, τέτοιες αποστολές.\nΜόλις οι μακρινοί μας πρόγονοι έπαψαν να πιστεύουν ότι τα άστρα είναι πατημασιές των θεών και διαπίστωσαν ότι είναι σαν τον Ήλιο μας, άρχισαν να αναρωτιούνται πώς θα φτάσουν εκεί. Εάν κατορθώσουμε να ταξιδέψουμε όχι μόνο έως τη Σελήνη ή έως τον Άρη αλλά τρισεκατομμύρια χιλιόμετρα μακριά, θα μπορέσουμε να φτάσουμε σε άλλα ηλιακά συστήματα. Ωστόσο, ακόμα και για τους πιο ονειροπόλους, το ταξίδι προς τα άστρα είναι προς το παρόν αδύνατο, ενώ καμία κρατική ή ιδιωτική επιχείρηση δεν έχει σκοπό να το τολμήσει.\nΕρευνητές της ΝΑΣΑ μελετούν τρόπους για τη δημιουργία διαστημικών σταθμών που θα εκτελούν κανονικά «δρομολόγια» μεταξύ Γης και Άρη. Καθώς το ταξίδι προς τον ερυθρό πλανήτη θα διαρκεί αρκετούς μήνες, οι διαστημικοί αυτοί σταθμοί θα μοιάζουν περισσότερο με διαστημικά ξενοδοχεία.\nΤο σχέδιο που επεξεργάζονται οι ερευνητές προβλέπει ότι το διαστημικό «ξενοδοχείο» θα κινείται συνεχώς γύρω από τον Ήλιο και θα περνάει πότε κοντά από τη Γη και πότε κοντά από τον Άρη.\nΑν πραγματοποιηθεί το σχέδιο, η επιβίβαση και η αποβίβαση στο διαστημικό «ξενοδοχείο» θα γίνονται με τη βοήθεια ειδικών σκαφών, που θα παίζουν τον ρόλο ταξί: θα πλησιάζουν το «ξενοδοχείο» και θα συνδέονται με αυτό εν κινήσει. Το ταξίδι μέχρι τον Άρη θα διαρκεί έξι με οκτώ μήνες. Εκεί άλλα ταξί θα αναλαμβάνουν να μας οδηγήσουν στον τελικό μας προορισμό.\nΗ ιδέα ότι κάποια στιγμή στο μέλλον τα ταξίδια προς τον Άρη θα είναι θέμα ρουτίνας γίνεται αποδεκτή από το σύνολο σχεδόν της επιστημονικής κοινότητας. Το ερώτημα που απασχολεί τους πάντες δεν είναι το «αν», αλλά το «πότε».","word_count":281,"page_number":55,"chapter":"Ενότητα 10 — Μυστήρια - επιστημονική φαντασία"},{"id":"e_dimotikou_b_0014","source_id":"e_dimotikou_b","title":"Ατλαντίδα","content":"Υποθετικό νησί στον Ατλαντικό ωκεανό. Γι’ αυτή μιλάει πρώτη φορά ο Πλάτωνας*. Οι πληροφορίες προέρχονται από τον Σόλωνα* όταν ταξίδεψε στην Αίγυπτο. Ανάμεσα στα άλλα έμαθε για την ύπαρξη της Ατλαντίδας, νησιού ίσου στο μέγεθος με τη Λιβύη και την Ασία μαζί (δηλαδή τη Βόρεια Αφρική και τη Μικρά Ασία) πέρα από τις Ηράκλειες στήλες (το σημερινό Γιβραλτάρ), που καταποντίστηκε στον ωκεανό 9.000 χρόνια πριν από την εποχή του Σόλωνα, δηλαδή το 9600 π.Χ. περίπου. Πρώτος βασιλιάς της υπήρξε ο Άτλας, γιος του Ποσειδώνα. Οι απόγονοί του ανέπτυξαν στο νησί σπουδαίο πολιτισμό, και η κυριαρχία τους επεκτάθηκε σιγά σιγά μέχρι την Τυρρηνία* και τα αιγυπτιακά σύνορα. Κάποτε οι κάτοικοι της Ατλαντίδας θέλησαν να κατακτήσουν την Ελλάδα και την Αίγυπτο. Αλλά οι Αθηναίοι μπήκαν επικεφαλής στην άμυνα της περιοχής τους και, ύστερα από πολλές περιπέτειες, με ηρωισμό και βαθιά γνώση της πολεμικής τέχνης, νίκησαν τον λαό της Ατλαντίδας κι έσωσαν από την υποδούλωση όσους απειλήθηκαν. Μετά από τα γεγονότα αυτά ακολούθησαν φοβεροί σεισμοί και κατακλυσμοί και, μέσα σε μια μέρα και μια νύχτα, ολόκληρο το νησί της Ατλαντίδας βυθίστηκε στον ωκεανό. Την ίδια εποχή έγιναν και φοβερές καταστροφές στην Ελλάδα.\nΕίναι χαρακτηριστικός ο πλούτος των αγαθών που συγκέντρωνε το νησί των Ατλάντων. Μεταλλεύματα, ξυλεία, πλούσια πανίδα και χλωρίδα κι οτιδήποτε θα μπορούσε να δώσει η φύση στον άνθρωπο υπήρχαν στην Ατλαντίδα υπεράφθονα και καταπληκτικά. Έχοντας τέτοιον πλούτο αγαθών στη διάθεσή τους, οι κάτοικοί της κατασκεύασαν μεγαλοπρεπή τείχη, ιερά, ανάκτορα, λιμάνια και ναύσταθμους. Τείχη με πρόσοψη επενδυμένη με χαλκό, κασσίτερο και ορείχαλκο, ανάκτορα και ναούς επενδυμένους με χρυσό, άργυρο, ορείχαλκο και ελεφαντοστό, χρυσά λατρευτικά αγάλματα. Όσο για τη Μητρόπολη, την κατοικία της μητέρας του Άτλαντα, ήταν ένα μικρό κυκλικό νησί που περιβαλλόταν από κυκλικές ζώνες ξηράς και θάλασσας, ώστε να είναι απόρθητο.\nΗ Ατλαντίδα απασχόλησε τόσο την επιστήμη όσο και τη λογοτεχνία. 60.000 βιβλία και άρθρα έχουν γραφτεί μέχρι σήμερα για το καταποντισμένο νησί. Η σύγχρονη έρευνα έχει αποφασίσει πως τα αναφερόμενα από τον Πλάτωνα δεν είναι ένα παραμύθι αλλά μια παράδοση, γνωστή και στην Αίγυπτο, όπως μαρτυρούν γραπτές πηγές.","word_count":338,"page_number":61,"chapter":"Ενότητα 10 — Μυστήρια - επιστημονική φαντασία"},{"id":"e_dimotikou_b_0015","source_id":"e_dimotikou_b","title":"Η μηχανή του χρόνου","content":"Τετάρτη 23 Οκτωβρίου 2002\nΦανταστείτε ότι έχετε ήδη διαβάσει αυτό το άρθρο και κατόπιν μπαίνετε θαρραλέα σε μια χρονομηχανή η οποία θα σας μεταφέρει στο παρελθόν, ακριβώς τη στιγμή πριν αρχίσετε να διαβάζετε το άρθρο. Τι θα κάνατε; Θα ξαναδιαβάζατε το άρθρο. Σύμφωνα με πολλούς φυσικούς, αν δεχτούμε ότι είναι δυνατό να επιστρέψετε στο παρελθόν, θα σας ήταν αδύνατο να το αλλάξετε. Τελικά μπορούν να πραγματοποιηθούν τα ταξίδια στον χρόνο; Πώς θα μπορούσαμε να κατασκευάσουμε μια χρονομηχανή;\nΟ Αλβέρτος Αϊνστάιν απέδειξε ότι, αν μπορούσαμε να ταξιδέψουμε με την ταχύτητα του φωτός, θα το καταφέρναμε. Κάτι τέτοιο όμως φαίνεται απίθανο, γι’ αυτό τα ταξίδια γίνονται μόνο στη φαντασία των συγγραφέων ή των σεναριογράφων.","word_count":112,"page_number":65,"chapter":"Ενότητα 10 — Μυστήρια - επιστημονική φαντασία"},{"id":"e_dimotikou_b_0016","source_id":"e_dimotikou_b","title":"Παραδοσιακά παιχνίδια","content":"Λοιπόν, παιδιά, τι λέτε; Θέλετε να παίξουμε μαζί; Έχω να σας μάθω πολλά παιχνίδια. Τα έπαιζα μικρός, μαζί με τους γονείς σας. Μας τα έμαθαν κι εμάς οι δικοί μας γονείς...\nΤα παιχνίδια αυτά τα παίζαμε στην αυλή του πατρικού μας σπιτιού, στην αλάνα της γειτονιάς μας, στους ήσυχους και χωρίς αυτοκίνητα και φασαρία δρόμους της συνοικίας μας. Σήμερα θα τα παίξουμε στον πεζόδρομο, στο μικρό πάρκο και στην πλατεία της συνοικίας μας· και ακόμα στο προαύλιο του σχολείου μας, στα διαλείμματα.\nΑς αρχίσουμε λοιπόν!\nΠαιδιά, πριν από κάθε παιχνίδι για να «βγει» αυτός που θα τα φυλάει ή που θα κάνει τη μάνα –σε περίπτωση που δε συμφωνούσαμε– χρησιμοποιούσαμε τα λαχνίσματα, όπως τα λέγαμε, δηλαδή με λαχνό. Αυτά γίνονταν με διαφορετικούς τρόπους. Ένας τρόπος λαχνίσματος γίνεται με την απαγγελία στίχων, άλλος με το κρύψιμο μιας πετρούλας. Σήμερα θα μάθουμε να παίζουμε το «Καλημέρα, βασιλιά».\nΟ βασιλιάς κάθεται σε ένα σκαμνί και απέναντί του, σε μια ευθεία γραμμή, στέκονται άλλα παιδιά. Το παιχνίδι αρχίζει.\nΌλα τα παιδιά μαζί φωνάζουν.\nΠαιδιά: Καλημέρα, βασιλιάαα...\nΒασιλιάς: Βρε, καλώς τα τα παιδιά! Πού ήσαστε τόσο καιρό;\nΠαιδιά: Σε δουλειά.\nΒασιλιάς: Σε τι δουλειά;\nΤότε τα παιδιά αρχίζουν με παντομίμα να μιμούνται όσο μπορούν καλύτερα τις κινήσεις κάποιας δουλειάς, διαφορετικής το καθένα.\nΟ βασιλιάς προσπαθεί να μαντέψει τη δουλειά που κάνει καθένα παιδί. Αν βρει όλες τις δουλειές, πετιέται ξαφνικά και κυνηγάει τα παιδιά. Όποιο παιδί πιάσει, αυτό θα γίνει ο νέος βασιλιάς. Αν, πάλι, δε βρει όλες τις δουλειές, οι άλλοι τον ρωτάνε:\n– Παιδιά, να το πάρει το ποτάμι; (δηλαδή: να σου φανερώσουμε τις δουλειές που δε βρίσκεις;)\nΈτσι και πει ο βασιλιάς ναι, τότε του φανερώνουν το καθένα τη δουλειά του και το παιχνίδι συνεχίζεται με τον ίδιο βασιλιά. Στην περίπτωση που ο βασιλιάς δε δεχτεί... Ε, τότε θα προσπαθήσει για πολλή ώρα ακόμα να μαντέψει σωστά!...","word_count":305,"page_number":71,"chapter":"Ενότητα 11 — Παιχνίδια"},{"id":"e_dimotikou_b_0017","source_id":"e_dimotikou_b","title":"Επιτραπέζια παιχνίδια","content":"Έχεις ταχύτητα, φαντασία, ετοιμότητα; Μπορείς να σκεφτείς άλλες λέξεις εκτός από τις απαγορευμένες για να μαντέψει η ομάδα σου τη «λέξη-κλειδί»;\nO πίνακας τοποθετείται στο κέντρο του τραπεζιού και τα πιόνια στην αρχή του πίνακα, στο βέλος. Οι παίκτες χωρίζονται σε 2 ομάδες, που δε χρειάζεται να είναι ισάριθμες, και αποφασίζουν ποια θα παίξει πρώτη.\nΚάθε κάρτα έχει 2 όψεις και αναγράφει 4 θέματα. Κάθε θέμα έχει διαφορετικό χρώμα και οι παίκτες αποφασίζουν από την αρχή με ποιο θέλουν να παίξουν. Ανακατεύουν τις κάρτες ανάλογα και τις τοποθετούν με την όψη (το χρώμα που επέλεξαν) προς τα κάτω. Κάτω από το θέμα αναγράφονται 4, 5 ή 6 λέξεις που είναι σχετικές με αυτό και οι οποίες απαγορεύεται να αναφερθούν.\nΚάθε ομάδα έχει έναν «ΑΝΑΓΝΩΣΤΗ», που δίνει τα στοιχεία σχετικά με το θέμα στους συμπαίκτες του, για να το βρουν. Όλοι οι παίκτες με τη σειρά γίνονται «ΑΝΑΓΝΩΣΤΕΣ».\nΟ πίνακας έχει θέσεις-τρίγωνα που αναγράφουν τον χρόνο (60΄΄ ή 120΄΄) που έχει κάθε ομάδα στη διάθεσή της όταν παίζει. Το χρονόμετρο-κλεψύδρα διαρκεί κανονικά 60΄΄. Για 120΄΄ οι παίκτες το γυρίζουν ξανά από την αρχή.\nO «ΑΝΑΓΝΩΣΤΗΣ» της ομάδας που παίζει πρώτη σηκώνει μία κάρτα, την οποία βλέπει μόνο αυτός και οι παίκτες της αντίπαλης ομάδας. Μετά γυρίζει το χρονόμετρο για 60΄΄. Με ταχύτητα αρχίζει να αποδίδει το θέμα της κάρτας χρησιμοποιώντας λέξεις και φράσεις, όσο το δυνατόν γρηγορότερα και σαφέστερα. Προσέχει να μη χρησιμοποιεί τις λέξεις που αναφέρονται στην κάρτα, καθώς και λέξεις που έχουν την ίδια ρίζα, είναι παράγωγες ή περιέχονται σ’ αυτές. Παράλληλα, οι παίκτες της ομάδας του αναφέρουν συνέχεια λέξεις, μέχρι να βρουν το θέμα. Όταν η ομάδα του βρει το θέμα, όπως ακριβώς γράφεται στην κάρτα, τους δίνει την κάρτα, τραβάει αμέσως μία νέα και συνεχίζει με τον ίδιο τρόπο, ενώ ο χρόνος τρέχει. Όταν τελειώσει ο χρόνος, η ομάδα μετράει πόσα θέματα βρήκε και προχωράει ανάλογες θέσεις στον πίνακα. Νικητής του παιχνιδιού είναι η ομάδα που θα φτάσει πρώτη στο τέλος του πίνακα.\nΑπαγορεύεται οι παίκτες: Α) Να χρησιμοποιούν λέξεις που έχουν την ίδια ρίζα, είναι παράγωγες, σύνθετες και γενικά αποτελούν μέρος οποιασδήποτε λέξης που υπάρχει στην κάρτα. Π.χ. στο θέμα «καφετιέρα» δεν μπορούν να πουν τη λέξη «καφές», στο θέμα «ειδησεογραφία» τις λέξεις «είδηση» και «γράφω», στο θέμα «υποφέρω», όπου υπάρχει η απαγορευμένη λέξη «βασανίζομαι», δεν μπορούν να πουν «βασανιστήριο» ή «βάσανο» ή στο θέμα «αιώνας» απαγορεύονται οι λέξεις «αιωνιότητα», «αιώνιος», «αιωνόβιος» κτλ.\nΒ) Να χρησιμοποιούν αρκτικόλεξα ή αρχικά, όταν κάποιο γράμμα τους αντιστοιχεί στο θέμα ή σε απαγορευμένη λέξη. Π.χ. στο θέμα «Ταχυδρομείο» δεν μπορούν να πουν ΕΛΤΑ, γιατί ΕΛΤΑ = Ελληνικά Ταχυδρομεία.\nΓ) Να χρησιμοποιούν την εξελληνισμένη μορφή μιας λέξης. Π.χ. Βύρωνας-Μπάιρον.\nΔ) Να χρησιμοποιούν χειρονομίες, μιμήσεις, ήχους, παντομίμα κτλ. για να περιγράψουν ένα θέμα.\nΕπιτρέπεται οι παίκτες να χρησιμοποιούν ονομασίες προϊόντων, ονόματα οικείων προσώπων, ονομασίες τόπων κτλ. για να περιγράψουν ένα θέμα. Π.χ. στο θέμα «ακρωτήριο» μπορούν να αναφέρουν ονομασίες ακρωτηρίων.\nΑκόμη, είναι δυνατό να χρησιμοποιούν λέξεις στην καθημερινή γλώσσα όταν οι απαγορευμένες είναι στην καθαρεύουσα, και το αντίθετο, αρκεί να έχουν διαφορετική ρίζα. Π.χ. μάτι-οφθαλμός, άλογο-ίππος, μαύρο-μελανό κτλ. Δεν επιτρέπεται να χρησιμοποιηθεί η λέξη λιοντάρι-λέων γιατί έχει κοινή ρίζα.\nΓίνεται δεκτή η χρήση ξένων λέξεων που περιλαμβάνονται στο καθημερινό μας λεξιλόγιο, για να αποδώσουν την αντίστοιχη ελληνική, και το αντίθετο. Π.χ. ασανσέρ-ανελκυστήρας, κλαμπ-λέσχη, ταϊμάουτ-διάλειμμα.\nΑκόμη, υπάρχει η δυνατότητα να μπορούν οι παίκτες να συμβουλεύονται λεξικό όταν διαφωνούν. Μπορεί ακόμη να συμφωνηθεί αλλαγή των κανόνων, και να γίνουν πιο ελαστικοί ή πιο αυστηροί, έτσι ώστε να απλοποιηθεί ή να δυσκολέψει ο τρόπος παιξίματος.","word_count":580,"page_number":76,"chapter":"Ενότητα 11 — Παιχνίδια"},{"id":"e_dimotikou_b_0018","source_id":"e_dimotikou_b","title":"Πνευματικά παιχνίδια","content":"Μια φορά κι έναν καιρό, σε έναν μακρινό τόπο –εκεί όπου μόνο η φαντασία μπορεί να φτάσει– ζούσαν δύο ξακουστοί βασιλιάδες: ο Ένας και ο Άλλος. Οι πολιτείες τους, η βόρεια και η νότια, καμάρωναν η μια απέναντι στην άλλη. Μια λίμνη τις στόλιζε, αλλά και τις ένωνε, έτσι που, αν δεν το ήξερες, θα νόμιζες πως και οι δυο μαζί ήταν μια μεγάλη και όμορφη πολιτεία. Τη λίμνη την ονόμασαν «Ειρηνική». Άντρες και γυναίκες συναντιόντουσαν εκεί και τα παιδιά έπαιζαν ξένοιαστα στις όχθες της.\nΟ Ένας και ο Άλλος είχαν πολύ μεγάλη φιλία, τέτοια που μόνο στα παραμύθια βρίσκει κανείς. Όμως κάποιο βράδυ ο Ένας είδε ένα περίεργο όνειρο:\nήταν, λέει, υπηρέτης του Άλλου. Το άλλο πρωί ξύπνησε όλο νεύρα. Ξέχασε ότι όλα αυτά είχαν γίνει στον ύπνο του και αποφάσισε πως οι γείτονές του έπρεπε να τιμωρηθούν. Έτσι, κήρυξε αμέσως πόλεμο στη γειτονική πολιτεία. Οι μάχες θα άρχιζαν σε λίγες μέρες.\nΟι κάτοικοι έπεσαν σε μεγάλη στενοχώρια. Τα παιδιά συναντήθηκαν στις όχθες της Ειρηνικής για να σκεφτούν τι θα μπορούσαν να κάνουν στην παρούσα κατάσταση. Καθισμένοι στα χόρτα, η Φωτεινή, ο Στράτος, η Βασιλική, ο Φάνης, η Ισμήνη κι ο Πέτρος συζητούσαν.\n– Μα πού ακούστηκε πόλεμος για το τίποτα! λέει ο Στράτος. Νομίζουν ότι βρήκαν ένα παιχνίδι για να περνάει η ώρα...\n– Αν πράγματι θέλουν παιχνίδι, θα τους φτιάξουμε εμείς ένα, λέει η Ισμήνη.\n– Κι όταν το ετοιμάσουμε, θα το παρουσιάσουμε και στον Έναν και στον Άλλο και θα τους πούμε: «Πάρτε και παίξτε μ’ αυτό και ξεχάστε τον πόλεμο!».\nΈψαξαν στις κασέλες και στα υπόγεια και το άλλο πρωί συναντήθηκαν πάλι. Έφεραν έναν χάρτη, κοπίδια, μολυβένια ανθρωπάκια, βότανα για να φτιάξουν τα χρώματα, μια ξύλινη τετράγωνη τάβλα, πηλό και υφάσματα, ψαλίδια, νήματα και, τέλος, η Ισμήνη έφερε μια παλιά ζυγαριά της γιαγιάς της.\nΣτην αρχή χάραξαν τους δρόμους για να περπατάνε οι φιγούρες και μετά έφτιαξαν χρώμα λευκό και μαύρο για να τις βάψουν. Στρώθηκαν στη δουλειά. Έφτιαξαν τις φιγούρες που θα έπαιζαν στο παιχνίδι, έτσι που να θυμίζουν τις πολιτείες τους. Μια πολιτεία λευκή και μια μαύρη, και η μια στεκόταν απέναντι από την άλλη. Οι πολιτείες είχαν πύργους. Σκέφτηκαν ότι πόλη δίχως άλογα είναι σαν άμαξα δίχως ρόδες, και τα έπλασαν κι αυτά. Δίπλα τους έβαλαν τους αξιωματικούς. Έντυσαν, ακόμα, έναν βασιλιά και μια βασίλισσα για κάθε πολιτεία και μπροστά απ’ όλους έβαλαν να στέκονται μικρά στρατιωτάκια. Με τη ζυγαριά θα υπολόγιζαν την αξία κάθε φιγούρας.\n– Ενδιαφέρον είναι το παιχνίδι μας, κι όταν ορίσουμε και τους κανόνες...\n– Τι εννοείς μ’ αυτό; ρώτησαν τα παιδιά.\nΆρχισαν να μιλάνε όλοι μαζί για τους κανόνες, κι ακόμα θα μιλούσαν, αν δεν έλεγε ο Φάνης την ιδέα του: Αφού όσα φτιάξανε υπήρχαν στην πραγματικότητα μέσα στις πολιτείες τους, ας πήγαιναν από κοντά να τα παρατηρήσουν. Έτσι κι έγινε. Κάθε παιδί θα παρατηρούσε πώς συμπεριφερόταν κάθε φιγούρα στην πραγματικότητα.\nΤην άλλη μέρα το απόγευμα συναντήθηκαν πάλι, και ο καθένας ανέφερε τις κινήσεις που παρατήρησε. Μετά από πολλή συζήτηση αποφάσισαν για τις κινήσεις που κάθε φιγούρα επιτρέπεται να κάνει στο παιχνίδι.\nΞαφνικά ακούστηκε η δυνατή φωνή του τελάλη, που τους ζητούσε, μόλις πέσει ο ήλιος, να συγκεντρωθούν όλοι στην Ειρηνική για να συζητήσουν για τον πόλεμο. Από τη συγκέντρωση δεν έλειπε κανείς. Ο Ένας και ο Άλλος ήταν σοβαροί και μουτρωμένοι. Στην πραγματικότητα δε θέλανε να γίνει πόλεμος, αλλά ποιος θα έκανε πίσω με τέτοιες ετοιμασίες; Τότε ο Στράτος, αφού κοίταξε καλά γύρω του, τους είπε:\n– Εμείς τα παιδιά δε θέλουμε τον πόλεμο. Αποφασίσαμε να αναλάβουμε ενεργό δράση. Φτιάξαμε, λοιπόν, ένα παιχνίδι που θα σας κάνει να τον ξεχάσετε. Άρχισε να τους εξηγεί το παιχνίδι τους με καμάρι.\nΌταν τελείωσε, όλοι ενθουσιάστηκαν. Ο Ένας και ο Άλλος χαμογέλασαν επιτέλους και αγκαλιασμένοι πήγαν παράμερα να παίξουν μια παρτίδα. Μόνο μια στιγμή σήκωσαν το κεφάλι τους και ρώτησαν τον Στράτο:\n– Δε μας είπες, μικρέ, το όνομα του παιχνιδιού.\nΤα παιδιά κοιτάχτηκαν. Είχαν ξεχάσει να του βρούνε όνομα. Εγώ όμως το γνωρίζω, κι αν ήμουνα εκεί, θα τους το ψιθύριζα:\n«Το όνομά του είναι ΣΚΑΚΙ».","word_count":668,"page_number":83,"chapter":"Ενότητα 11 — Παιχνίδια"},{"id":"e_dimotikou_b_0019","source_id":"e_dimotikou_b","title":"Μαντώ Μαυρογένους","content":"Στις αρχές του Μαΐου του 1821 τέσσερα πλοία βρίσκονταν στο λιμάνι της Μυκόνου. Περίμεναν τη διαταγή να ανοίξουν πανιά για την Τήνο, όπου είχε αποφασιστεί η συγκέντρωση του στόλου του Αιγαίου με αρχηγό τον Τομπάζη. Την ημέρα της αναχώρησης η Μύκονος έμοιαζε με πόλη που πανηγύριζε. Όλος ο κόσμος είχε κατακλύσει τον χώρο του λιμανιού, που ήταν καταστόλιστο με σημαίες και αψίδες από κλαδιά δάφνης και μυρτιάς. Στο κέντρο του παλικάρια και κοπέλες είχαν πιαστεί σε χορό, που τον συνόδευαν τραγούδια και πυροβολισμοί. Οι καμπάνες χτυπούσαν χαρμόσυνα και οι παπάδες, τριγυρισμένοι από ψαλτάδες και εξαπτέρυγα, έκαναν δεήσεις και ευλογούσαν τα πληρώματα. Ξάφνου, στην πρόχειρη εξέδρα που είχε στηθεί για τους επισήμους, μια λεπτή γυναικεία σιλουέτα ξεχώρισε και προχώρησε μπροστά. Μονομιάς σταμάτησαν και βουβάθηκαν όλοι και ένας ομαδικός ψίθυρος άρχισε να σέρνεται ανάμεσα στο πλήθος: «Η Μαντώ! Η Μαντώ!...».\nΝτυμένη στα ολόλευκα, η Μαντώ, κρατώντας στο ένα της χέρι μια μικρή σημαία και στο άλλο ένα μπουκέτο λουλούδια, γύρισε πρώτα κατά τους συγκεντρωμένους και τους χαιρέτησε με μια βαθιά υπόκλιση. Στη στιγμή ακούστηκε ο αντιχαιρετισμός με μια θύελλα από ζητωκραυγές και λογής επευφημίες. Ύστερα εκείνη, απευθυνόμενη στους πολεμιστές μέσα στα πλοία, σήκωσε ψηλά τη σημαία και με τη μελωδική της φωνή είπε δυνατά:\n– Λεβέντες της Μυκόνου! Η Πατρίδα αγωνίζεται και σας καλεί να τη βοηθήσετε. Ανταποκριθείτε στη μεγάλη τιμή που σας γίνεται και φανείτε άξιοι των Σαλαμινομάχων προγόνων μας. Δώστε μας τη χαρά και την περηφάνια ότι και τα δικά μας παλικάρια είναι σαν εκείνα που πολεμούν αυτή την ώρα τον εχθρό. Σας κατευοδώνουμε και σας περιμένουμε νικητές. Ελευθερία ή θάνατος! Εμπρός!\nΤελειώνοντας έριξε στη θάλασσα την ανθοδέσμη που κρατούσε και μαζί με τους πρόκριτους κατευθύνθηκε προς το αρχοντικό της, όπου είχε προγραμματιστεί μαζί τους μια νέα σύσκεψη. Το θέμα που θα συζητούσαν ήταν η ασφάλεια του νησιού. Αυτό όμως απαιτούσε μεγάλα χρηματικά ποσά, που η εξοικονόμησή τους φαινόταν δύσκολη. Στέκονταν όλοι σκεφτικοί και αμήχανοι, μέχρι τη στιγμή που σηκώθηκε η Μαντώ για να δώσει λύση στο πρόβλημα και να καταπλήξει όλους λέγοντας:\n– Πατριώτες! Μπήκα στην Επανάσταση αποφασισμένη να της δώσω ό,τι έχω. Ξέρετε πως είμαι πλούσια. Σας δηλώνω λοιπόν ότι από σήμερα τα πλούτη μου δεν είναι δικά μου. Είναι της Πατρίδας! Θα τα ξοδέψω όλα για την ελευθερία της. Κι όταν πια δε θα μου έχει μείνει τίποτε, θα πάω μ’ αυτούς που πολεμούν τον εχθρό να δώσω και τη ζωή μου!\nΠήγε ύστερα αργά στο γραφείο της, τράβηξε ένα σακουλάκι γεμάτο χρυσά νομίσματα και το ακούμπησε μπροστά στους πρόκριτους.\n– Ορίστε, είπε. Πάρτε όσα χρειάζονται για τα έξοδα των φρουρών και στείλτε αμέσως ανθρώπους μ’ ένα καΐκι στον Πειραιά να αγοράσουν όπλα, που έμαθα πως έχουν φέρει πλοία από την Ευρώπη.\nΟι πρόκριτοι έμειναν για λίγο άφωνοι και ακίνητοι, σαν να τους είχε χτυπήσει κεραυνός. Μόλις συνήλθαν, σηκώθηκαν και, χλωμοί από την έκπληξη και τη συγκίνηση, της έσφιξαν ένας ένας το χέρι.\n– Αρχηγός της φρουράς εσύ! της φώναξαν ύστερα μ’ ένα στόμα.\n– Σας ευχαριστώ, είπε εκείνη και έκλεισε τη σύσκεψη με τη φοβερή φράση: Και μην ξεχνάτε ότι τούτη η φωτιά που άναψε στο Αιγαίο δε θα σβήσει αν δεν κάψει ή τους τυράννους μας ή εμάς!...","word_count":523,"page_number":93,"chapter":"Ενότητα 12 — 25η Μαρτίου"},{"id":"e_dimotikou_g_0001","source_id":"e_dimotikou_g","title":"Ανάσταση","content":"Άκου τον ξάστερο ουρανό πώς οι καμπάνες σειούνε.\nΌπου καρδιά, χαρμόσυνες λαχτάρες απαντούνε.\n\nΑνάστασ’ είναι σήμερα! Παιδιά, γυναίκες, γέροι\nκόκκινο αυγό στην τσέπη τους, χρυσό κερί στο χέρι.\n\nΌσ’ άστρα ’ναι στον ουρανό, τόσα στον κάμπο κρίνα.\nΌλα έχουνε στην καθαρή ψυχήν Απρίλη μήνα.\n\nΤης εκκλησίας φουντώσανε δάφνη πολλήν οι στύλοι.\nΕιρήνη! Ειρήνη! Φιληθείτε, οχτροί μαζί και φίλοι...","word_count":58,"page_number":29,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"e_dimotikou_g_0002","source_id":"e_dimotikou_g","title":"Μαριάμ","content":"Η Μαριάμ ένιωσε πως κάποιος μπήκε στην αυλή της, κι ανοίγοντας τα μάτια, είδε μπροστά της τον Ιωάννη, που ανάσαινε με κομμένη αναπνοή και μιλούσε με την ψυχή στα δόντια.\n– Πού ήσουνα, της λέει, και δεν ήρθες να δεις τι έγινε;\n– Τι έγινε; ρώτησε και εκείνη και πετιέται ολόρθη, κατεβάζοντας τη μαντίλα της.\n– Έπιασαν τον γιο σου και διδάσκαλό μου και πάνε να τονε σταυρώσουν!\nΤότες η Μάνα σήκωσε τα χέρια της ψηλά και ξεφώνισε:\n— Παιδί μου, παιδί μου! Τι κακό έκαμες και θέλουνε να σε σταυρώσουν;\nΚαι με τον νου θολωμένο, όρμησε έξω από το σπίτι της και πήρε τον δρόμο κλαίοντας, κι αμέσως ο έρημος δρόμος γέμισε από θρήνους γυναικών, που έτρεχαν βγαίνοντας από τα σπίτια τους όπως όπως, κι ανάμεσα σε αυτές την ακολουθούσαν από κοντά η Μάρθα και η Μαρία η Μαγδαληνή και η Σαλώμη, και πλήθος άλλα κορίτσια, και δίπλα της την επαράστεκε ο Ιωάννης, χλωμός, πηγαίνοντας με χαμηλωμένα βλέφαρα, ώσπου τέλος έφτασαν στο μέρος όπου ήταν ο όχλος, και ο ένας έσπρωχνε τον άλλον για να δει και βλαστημούσαν κι έφτυναν και ούρλιαζαν και ο αναβρασμός ήτανε μεγάλος και βουερός.\nΤότες η Μαρία, κοιτάζοντας σαστισμένη, ρωτά τον Ιωάννη:\n— Πού είναι ο γιος μου;\n— Να, της αποκρίνεται. Βλέπεις εκείνον εκεί που φορεί ένα αγκάθινο στεφάνι και του έχουν δέσει τα χέρια; Αυτός είναι!\nΚαι καθώς έκανε έτσι η Θεοτόκος ψάχνοντας με το μάτι και τον αντίκρισε, ο κόσμος έσβησε γύρω της κι έπεσε καταγής χωρίς πνοή.","word_count":247,"page_number":30,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"e_dimotikou_g_0003","source_id":"e_dimotikou_g","title":"Έθιμα του Πάσχα","content":"Το Πάσχα είναι η μεγαλύτερη γιορτή του χριστιανισμού. «Εορτών εορτή και πανήγυρις εστί πανηγύρεων» λέει το τροπάριο. Προέρχεται από το εβραϊκό Πάσχα, που και αυτό έχει τις ρίζες του στην αρχαία Αίγυπτο. Με το «Πισάχ» (η λέξη σημαίνει διάβαση, πέρασμα) οι Αιγύπτιοι γιόρταζαν το πέρασμα του Ήλιου από τον ισημερινό, την εαρινή δηλαδή ισημερία, και μαζί της τον ερχομό της άνοιξης. Οι Εβραίοι καθιέρωσαν και αυτοί τη γιορτή σε ανάμνηση της απελευθέρωσής τους από τους Αιγυπτίους και της διάβασης της Ερυθράς Θάλασσας. Παράλληλα όμως και για να χαιρετίζουν το τέλος του χειμώνα και την αρχή της άνοιξης.\nΣτη χριστιανική γιορτή δόθηκε το όνομα «Πάσχα» και με απόφαση της Α΄ Οικουμενικής Συνόδου το 325 μ.Χ. ορίστηκε να γιορτάζεται την πρώτη Κυριακή μετά από την πανσέληνο της εαρινής ισημερίας. Το Πάσχα, ο λαός, μαζί με την «εκ νεκρών Ανάσταση» του Χριστού, τη νίκη δηλαδή ενάντια στον θάνατο, γιορτάζει και την ανάσταση της άνοιξης, το ξύπνημα της φύσης μετά τη νάρκη του χειμώνα.\nΜε τη λέξη Πάσχα, Λαμπρή και Λαμπρά (στην Κύπρο) εννοούμε δυο βδομάδες που αρχίζουν από την Ανάσταση του Λαζάρου και τελειώνουν την Κυριακή του Θωμά. Τη βδομάδα των Παθών και τη βδομάδα της Λαμπρής ή Λαμπροβδομάδα.\nΑπό τα βυζαντινά ακόμα χρόνια οι χριστιανοί προετοιμάζονταν καιρό πριν για τις πασχαλινές γιορτές. Έβαφαν τα σπίτια τους, έστρωναν στο πάτωμα κλαδιά από αρωματικά φυτά, δάφνη, μυρσίνη, δενδρολίβανο, λεμονιά, έφτιαχναν καινούρια ρούχα, τα λαμπριάτικα.\nΑνήμερα το Πάσχα όλοι αντάλλασσαν δώρα και ασπασμούς και εύχονταν «Καλό Πάσχα», ενώ τη νύχτα οι δρόμοι και τα σπίτια ήταν φωταγωγημένα.\nΤον καιρό της Τουρκοκρατίας το Πάσχα είχε εντελώς ιδιαίτερη σημασία για τους Έλληνες. Μαζί με τα Πάθη του Χριστού και την Ανάσταση, ζωντάνευαν και τα πάθη του λαού και μεγάλωναν οι ελπίδες για την Ανάσταση του Γένους.","word_count":289,"page_number":31,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"e_dimotikou_g_0004","source_id":"e_dimotikou_g","title":"Μερικά από τα έθιμα της Μεγάλης Πέμπτης","content":"Τα πασχαλινά έθιμα αρχίζουν κυρίως από τη Μεγάλη Πέμπτη, επειδή από την ημέρα αυτή αρχίζουν οι ετοιμασίες για το Πάσχα.\nΑπό το πρωί οι γυναίκες καταγίνονται με το ζύμωμα. Ζυμώνουν τις κουλούρες της Λαμπρής. Τις ζυμώνουν με διάφορα μυρωδικά και τις στολίζουν με ξηρούς καρπούς και με στολίδια από ζυμάρι. Τα ονόματά τους ποικίλλουν, ανάλογα με το σχήμα που τους δίνουν. Λέγονται κουτσούνες, κουζουνάκια, κοφίνια, καλαθάκια, δοξάρια, αυγούλες, λαζαράκια κτλ.\nΑναφέρω τον τρόπο του ζυμώματος που συνηθίζεται στην Κορώνη. Εκεί τις λαμπριάτικες κουτσούνες τις ζυμώνουν με λάδι, μύγδαλα και γλυκάνισο. Τις κουτσούνες τις πλάθουνε στρογγυλές σαν κουλούρες ή μακρουλές και τις περιπλέχουνε (στολίζουνε) μέσα σε ζυμάρι. Βάζουνε στη μέση το κόκκινο το αυγό και στολίζουνε την κουτσούνα με αγκιναρίτσες, με πουλάκια, με μύγδαλα και σουσάμι. Αυτές που είναι να τις μεράσουνε σε μικρά παιδιά τις κάνουνε σωστές κουτσουνίτσες, με πόδια, με χέρια, με κεφάλι.\nΤότε ζυμώνουν και κουλούρι για την Πρωτομαγιά.\nΆλλη ασχολία της ημέρας αυτής είναι το βάψιμο των αυγών. Πάσχα χωρίς κόκκινα αυγά δε νοείται. Γι’ αυτό και η Μεγάλη Πέμπτη λέγεται κοινά Κόκκινη Πέφτη ή Κοκκινοπέφτη.\nΣτην Καστοριά απλώνουν στα παράθυρα κόκκινες βελέντζες και κόκκινα μαντίλια.\nΣτην Αγιάσο Λέσβου στα Δώδεκα Ευαγγέλια παίρνανε οι γυναίκες κερί, κι ένα ένα Ευαγγέλιο που τελείωνε, κάνανε από το κερί με ένα κομματέλι έναν σταυρό. Μαζεύανε δώδεκα σταυρέλια και τα πηγαίνανε στο σπίτι να τα κολλήσ’νε παντού στ’ αντιγώνια του σπιτιού, για να ψοφήσ’νε οι ψύλλοι, οι κοριοί κτλ.","word_count":238,"page_number":31,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"e_dimotikou_g_0005","source_id":"e_dimotikou_g","title":"ΤΑ ΘΕΤΙΚΑ...","content":"Οι Ολυμπιακοί Αγώνες στην τηλεόραση «Οι Ολυμπιακοί Αγώνες της Αθήνας είναι θαυμάσιοι» δήλωσε χθες ο πρόεδρος της ΔΟΕ Ζακ Ρογκ επισκεπτόμενος τις εγκαταστάσεις της ΕΡΤ Α.Ε. στο Διεθνές Κέντρο Ραδιοτηλεόρασης.\n«Είμαι ευτυχής διότι μπορείτε να δείξετε περισσότερα αθλήματα και όλοι οι Έλληνες μπορούν να δουν τους Αγώνες» είπε ο πρόεδρος της ΔΟΕ, ο οποίος παρακολουθεί κάθε βράδυ –όπως αποκάλυψε– την περίληψη της αθλητικής δραστηριότητας που μεταδίδει η ΕΤ3.\n«Καθημερινά υπάρχουν 3,7 δισ. άνθρωποι σε όλο τον κόσμο που παρακολουθούν τα αθλήματα. Συγχαρητήρια στην Ελλάδα γι’ αυτό» σημείωσε ο κ. Ρογκ.","word_count":90,"page_number":37,"chapter":"Ενότητα 15 — Τηλεόραση"},{"id":"e_dimotikou_g_0006","source_id":"e_dimotikou_g","title":"ΚΑΙ ΤΑ ΑΡΝΗΤΙΚΑ...","content":"Επτά ημέρες χωρίς τηλεόραση: κάν’ το κι εσύ Εσείς πόσες ώρες στηθήκατε σήμερα μπροστά στην τηλεόραση; Μία, τρεις ή παραπάνω; Θα μπορούσατε να ζήσετε μία εβδομάδα χωρίς να την ανοίξετε καθόλου; Η πρόταση μιας μη κερδοσκοπικής οργάνωσης είναι να την κλείσουμε εντελώς για επτά ολόκληρες μέρες.\nΔεν είναι η πρώτη φορά που γίνεται μποϊκοτάζ* στο χαζοκούτι. Τον περασμένο χρόνο, περισσότεροι από 7 εκατομμύρια άνθρωποι έβγαλαν την τηλεόραση από την πρίζα.\nΟ μέσος Αμερικανός παρακολουθεί περισσότερες από τέσσερις ώρες τηλεόραση ημερησίως. Και μαζί τρώει παραπάνω, πίνει και καπνίζει. Τα χιλιάδες διαφημιστικά τον σπρώχνουν να καταναλώσει περισσότερες σοκολάτες, καραμέλες, χάμπουργκερ, αναψυκτικά.\nΟ αριθμός των διαφημίσεων που «καταβροχθίζουν» τα παιδιά έχει διπλασιαστεί από τη δεκαετία του ’70, ξεπερνώντας σήμερα τις 40.000 τον χρόνο. Τα παιδιά στην Αμερική περνούν περισσότερη ώρα στην τηλεόραση (1.023 ώρες) παρά στο σχολείο (900 ώρες). Και μη νομίζετε πως στην Ελλάδα τα πράγματα είναι διαφορετικά.\nΚαιρός να επαναστατήσουμε λοιπόν. Στόχος της εκστρατείας είναι να ανακαλύψουμε τι μπορούμε να κάνουμε όταν δε βλέπουμε τηλεόραση. Και φυσικά δεν εννοούμε να «σερφάρουμε» στο διαδίκτυο ή να παίζουμε ηλεκτρονικά παιχνίδια. Όταν την κλείνεις, ανακαλύπτεις με έκπληξη πόσα ενδιαφέροντα πράγματα υπάρχουν για να κάνεις.","word_count":190,"page_number":38,"chapter":"Ενότητα 15 — Τηλεόραση"},{"id":"e_dimotikou_g_0007","source_id":"e_dimotikou_g","title":"Ο αθλητισμός στην αρχαία Ελλάδα","content":"Τα δυο έπη του Ομήρου, η Οδύσσεια και η Ιλιάδα, μας φέρνουν σε επαφή με μια κοινωνία όπου ο αθλητισμός έχει εισδύσει* σε όλες τις εκδηλώσεις της ζωής, δημόσιας και καθημερινής. Η αγάπη για την άθληση κυριαρχεί παντού: νέοι άνθρωποι χαίρονται την έντονη σωματική προσπάθεια, τρανοί αρχηγοί και ήρωες αγωνίζονται να έρθουν πρώτοι, ενώ γύρω ένα πλήθος –λαός ή στρατός– δονείται από ενθουσιασμό παρακολουθώντας τις επιδόσεις τους. Με λίγα λόγια, βρισκόμαστε μπροστά σε μια κοινωνία που, παράλληλα με τα ηρωικά της ιδανικά, χαρακτηρίζεται και από ένα γνήσιο αθλητικό πνεύμα.\nΗ έφεση* για άθληση είναι διάχυτη* και στην Ιλιάδα και στην Οδύσσεια. Τη συναντάμε στις περιγραφές των αγώνων που έγιναν για να τιμηθεί ο νεκρός Πάτροκλος, αλλά και στους αγώνες που οργάνωσαν οι Φαίακες για να διασκεδάσουν τη θλίψη του Οδυσσέα. Όλοι οι ομηρικοί ήρωες λαχταρούν να διακριθούν στους αγώνες: κάθε ήρωας είναι και ένας αθλητής που προσπαθεί να ξεπεράσει τους άλλους.\nΟ ιδανικός ήρωας, όπως φαίνεται στα ομηρικά έπη, διαθέτει σωματική και ψυχική αλκή* και είναι έξυπνος και ανδρείος. Οι αγώνες δίνουν την ευκαιρία στους ήρωες-αθλητές να κάνουν επίδειξη υπεροχής, να εκδηλώσουν τη λαχτάρα τους για τη νίκη, να χαρούν τον ίδιο τον αγώνα. Ωστόσο, η έντονη επιθυμία να νικήσουν δεν τους οδηγεί σε βιαιότητες. Το αθλητικό πνεύμα και οι εκδηλώσεις μεγαλοψυχίας δε λείπουν από τους αντιπάλους.\nΗ αφορμή των αγώνων είναι διαφορετική στα δυο έπη: Στην Ιλιάδα είναι ένα ταφικό έθιμο και οι αγώνες σχετίζονται με θρησκευτικές εκδηλώσεις. Στην Οδύσσεια γίνονται για να τιμηθεί ένας ξένος.\nΤα αθλήματα που περιγράφονται στην Ιλιάδα είναι με τη σειρά: η αρματοδρομία, η πυγμαχία, η πάλη, ο δρόμος, η τοξοβολία με στόχο και το ακόντιο. Τα έπαθλα τα προσφέρει ο ίδιος ο Αχιλλέας. Βραβεία δίνονται και στους νικητές και στους νικημένους. Για τους Φαίακες η απλή χαρά της σωματικής προσπάθειας και η επιδίωξη της νίκης φαίνονται να είναι τα κυρίαρχα στοιχεία των αγώνων. Αξιοσημείωτο είναι ότι στους αγώνες αυτούς έπαθλα δε δίνονται. Η ανταμοιβή του αθλητή είναι η ικανοποίηση ότι ήρθε πρώτος.\nΔυο σημεία αξίζει ιδιαίτερα να τονίσουμε. Οι ομηρικοί ήρωες ξέρουν να εκτιμούν την αξία της άσκησης. Οι Φαίακες συχνά τονίζουν: «ο Οδυσσέας δείχνει έμπειρος» και «φαίνεται να ξέρει από αγωνίσματα». Αυτό το συμπεραίνουν από τη ρωμαλέα κορμοστασιά του, από τα δυνατά μπράτσα του και τις γερές κνήμες του. Ο ίδιος ο Οδυσσέας παινεύεται ότι αθλείται από τα νιάτα του και πως και τώρα, μετά από τόσα βάσανα, μπορεί να τους νικήσει στην πάλη και στην πυγμή, στο τόξο και στο δίσκο.\nΤο δεύτερο και πιο σημαντικό στοιχείο είναι η υψηλή εκτίμηση με την οποία η ομηρική κοινωνία περιβάλλει τον αθλητισμό και τους αθλητές. Στην Ιλιάδα όλοι οι αρχηγοί του στρατού, ακόμα και ο ίδιος ο Αγαμέμνονας, αθλούνται. Οι Φαίακες θεωρούν ότι το σημαντικότερο για έναν πολίτη, σπουδαιότερο και από το εμπόριο και τα πλούτη, είναι «αυτό που μπορεί να επιτύχει κανείς με τα χέρια και τα πόδια του», δηλαδή αθλητικές επιδόσεις, που αποσπούν τον άνθρωπο από την καθημερινότητα και τον ανεβάζουν στη σφαίρα των υψηλών ιδανικών.\nΣτο ρωμαλέο ομηρικό κόσμο δεν υπάρχει θέση για ήρωες που δεν είναι αθλητές.","word_count":508,"page_number":59,"chapter":"Ενότητα 16 — Αθλήματα - σπορ"},{"id":"e_dimotikou_g_0008","source_id":"e_dimotikou_g","title":"Και τα παιδιά αθλούνται...","content":"Ο Αλσέστ έδωσε ραντεβού στους φίλους από την τάξη για σήμερα τ’ απόγευμα, σ’ ένα έρημο οικόπεδο, κοντά στα σπίτια μας.\nΟ Αλσέστ είναι φίλος μου, του αρέσει πολύ το φαΐ και μας έδωσε ραντεβού γιατί ο μπαμπάς του του έκανε δώρο μια μπάλα ποδοσφαίρου ολοκαίνουρια. Θα παίζαμε ένα ματς τρομερό, ο Αλσέστ είναι απίθανος!\nΒρεθήκαμε όλοι στο οικόπεδο στις τρεις το απόγευμα. Ήμασταν δεκαοχτώ, έπρεπε ν’ αποφασίσουμε να χωριστούμε σε δύο ομάδες με τον ίδιο αριθμό παικτών για την καθεμιά.\nΓια τον διαιτητή ήταν πολύ εύκολο. Διαλέξαμε τον Ανιάν. Ο Ανιάν είναι ο πρώτος μαθητής στην τάξη, δεν τον αγαπάμε και τόσο, αλλά, μια και φοράει γυαλιά, δεν μπορούμε να τον δέρνουμε συχνά, πράγμα που είναι ό,τι πρέπει για έναν διαιτητή.\nΈπειτα χρειάστηκε να χωρίσουμε τις ομάδες. Δεν υπήρχε πρόβλημα, εκτός απ’ τον Εντ. Κι ο Γκοφρουά κι εγώ θέλαμε τον Εντ. Δεν παίζει πολύ καλά, αλλά όλοι τον φοβούνται.\nΡίξαμε κλήρο με το κοντό και το μακρύ στάχυ, που το κέρδισε ο Γκοφρουά και μαζί και τον Εντ. Ο Γκοφρουά έβαλε τον Εντ τερματοφύλακα, γιατί είπε πως έτσι κανείς δε θα τολμούσε να πλησιάσει το τέρμα τους. Ο Εντ είναι αλήθεια πως θυμώνει εύκολα. Ο Αλσέστ έτρωγε μπισκότα καθισμένος στο τέρμα του, αλλά δεν έδειχνε και πολύ ευχαριστημένος. «Λοιπόν, τι θα γίνει, θ’ αρχίσουμε καμιά φορά;» φώναξε.\nΠήραμε τις θέσεις μας στο γήπεδο. Καθώς ήμασταν οχτώ από κάθε ομάδα, εκτός απ’ τους τερματοφύλακες, το πράγμα ξανάμπλεξε. Σε κάθε ομάδα άρχισαν να τσακώνονται για το ποιος θα είναι ο σέντερ φορ. Όλοι θέλανε να παίξουν στην επίθεση. Στην ομάδα του Γκοφρουά τα πράγματα ήταν πιο εύκολα, γιατί ο Εντ μοίρασε ένα σωρό γροθιές στις μύτες και οι παίκτες πήρανε τις θέσεις τους χωρίς πολλές διαμαρτυρίες, τρίβοντας τις μύτες τους. Είναι, βλέπετε, πολύ δυνατά τα χτυπήματα του Εντ! Στην ομάδα μου δεν καταφέρναμε να καταλήξουμε σε συμφωνία, μέχρι που ο Εντ μάς είπε πως θα ’ρχότανε να μοιράσει μερικές γροθιές και στις δικές μας μύτες. Αμέσως πήραμε τις θέσεις μας.\nΟ Γκοφρουά όμως είπε: «Δεν είστε εντάξει, μας έχει στραβώσει ο ήλιος! Δεν υπάρχει κανένας λόγος να παίζουμε απ’ την πλευρά αυτή εμείς!».\nΕγώ του απάντησα πως, αν τον ενοχλούσε ο ήλιος, δεν είχε παρά να κλείσει τα μάτια, ίσως μάλιστα να ’παιζε καλύτερα έτσι. Πιαστήκαμε στο ξύλο.\n«Ε, παιδιά!» φώναξε ο Αλσέστ απ’ το τέρμα του.\nΑλλά κανείς δεν του έδωσε σημασία. Εγώ συνέχιζα να παίζω ξύλο με τον Γκοφρουά, του είχα σκίσει το φανελάκι του, που ήταν ολοκαίνουριο κι είχε κόκκινο, μπλε κι άσπρο χρώμα, κι εκείνος έλεγε: «Μπα, δεν πειράζει! Ο μπαμπάς μου θα μου πάρει ένα σωρό άλλα!» και μου ’δινε κλοτσιές στο καλάμι. Ο Ρούφους κυνηγούσε τον Ανιάν, που φώναζε: «Φοράω γυαλιά, φοράω γυαλιά!». Ο Εντ, που τόση ώρα είχε μείνει ήσυχος στο τέρμα του, αγανάκτησε κι άρχισε να μοιράζει γροθιές στις μύτες που βρίσκονταν πιο κοντά του, δηλαδή στους συμπαίκτες του. Όλοι φωνάζανε, τρέχανε. Διασκεδάζαμε πολύ, ήταν απίθανο!\n«Σταματήστε, παιδιά!» φώναξε ο Αλσέστ πάλι.\nΤότε ο Εντ θύμωσε. «Βιαζόσουνα να παίξεις» είπε στον Αλσέστ. «Ωραία, λοιπόν παίζουμε. Αν έχεις να πεις κάτι, να περιμένεις στο ημίχρονο!»\n«Σε ποιο ημίχρονο;» ρώτησε ο Αλσέστ. «Τώρα θυμήθηκα πως δεν έχουμε μπάλα, την ξέχασα σπίτι!»","word_count":527,"page_number":68,"chapter":"Ενότητα 16 — Αθλήματα - σπορ"},{"id":"e_dimotikou_g_0009","source_id":"e_dimotikou_g","title":"Τι βλέπουμε από το διάστημα","content":"Υπάρχει ένας παλιός μύθος ότι το Σινικό Τείχος στην Κίνα είναι το μοναδικό ανθρώπινο κατασκεύασμα που μπορεί κανείς να δει από το διάστημα. Στην πραγματικότητα, πολλές ανθρώπινες κατασκευές φαίνονται από περίγεια* τροχιά.\nΟι αστροναύτες σε περίγεια τροχιά στο διαστημικό λεωφορείο μπορούν να δουν λεωφόρους, αεροδρόμια, φράγματα, ακόμα και μεγάλα οχήματα, από ύψος γύρω στα 217 χιλιόμετρα.\nΟι πόλεις ξεχωρίζουν καθαρά, και αυτό ισχύει ακόμα και για την ανώτερη τροχιά του Διεθνούς Διαστημικού Σταθμού, ο οποίος περιφέρεται γύρω από τον πλανήτη σε ύψος 400 χιλιομέτρων.\n«Μπορείς να δεις πάρα πολλά πράγματα από το διάστημα» λέει ο αστροναύτης Εντ Λου, ο επιστήμονας της Αποστολής Επτά πάνω στον σταθμό. «Μπορείς να δεις τις πυραμίδες, ειδικά με ένα ζευγάρι κιάλια. Είναι λίγο δύσκολο να τις διακρίνεις με γυμνό μάτι».","word_count":125,"page_number":80,"chapter":"Ενότητα 17 — Ταξίδια στο διάστημα"},{"id":"e_dimotikou_g_0010","source_id":"e_dimotikou_g","title":"Φανταστικά ταξίδια στο διάστημα","content":"Ο Πότης Ράτος ζούσε στα 1880 μαζί με τη γυναίκα του και τα παιδιά του κάπου στην Ελλάδα. Λαχταρούσε να κάνει ένα ταξίδι στον χρόνο. Όχι στο παρελθόν, αλλά στο μέλλον. Και μάλιστα στο πολύ μακρινό. Μαζί με τον γιο του Σταύρο, τους φίλους και συμμαθητές του γιου του Βασιλική και Μιχάλη και τον Γάλλο συγγραφέα Ιούλιο Βερν αποφάσισαν να πραγματοποιήσουν ένα ταξίδι στο διάστημα με τη βοήθεια του παράξενου φίλου τους, του Σοφούλη του Ψαλιδούλη, που πραγματοποιούσε στη στιγμή κάθε τους επιθυμία.\nΜετά από μια μεγάλη περιήγηση, το διαστημόπλοιο τυλίχτηκε σ’ ένα γαλάζιο σύννεφο και μαζί με τους χρονοταξιδιώτες βρέθηκε σε χρόνο ρεκόρ από τη Σελήνη στον πλανήτη Άρη. Όμως αυτή τη φορά είχαν και παρέα. Στα μέλη προστέθηκε ο Μάρσμαν. Αυτός δεν ήταν καθόλου άγριος ούτε τρομακτικός. Μάλλον ήταν πολύ αστείος.\n«Δε νομίζετε ότι είναι ώρα να εξερευνήσουμε τον νέο μας πλανήτη, τον Άρη; Υπάρχουν τόσα πράγματα που η ανθρωπότητα θα ήθελε να γνωρίσει γι’ αυτόν!» είπε ο Πότης Ράτος, που τον είχε κυριεύσει μια περίεργη ανυπομονησία να βγει έξω και να αιωρηθεί ή να περπατήσει στο κοκκινωπό έδαφος.\n«Εξάλλου τώρα έχουμε και το Μάρσμαν μαζί μας. Θα μας φανεί χρήσιμος, γιατί όλο και κάτι θα ξέρει για τον πλανήτη, αφού κατοικεί στον Άρη» απάντησε αμέσως η Βασιλική.\nΜετά από λίγο το διαστημόπλοιο «ΦΟΥΨΑ» κάθισε μαλακά στο κοκκινωπό έδαφος του Άρη. Η πόρτα κάτω από την κοιλιά του σκάφους άνοιξε και μια αυτόματη ατσάλινη σκάλα έκανε την εμφάνισή της. Απ’ αυτήν κατέβηκαν οι πέντε φίλοι μας. Άρχισαν να περπατούν με μικρά αργά βήματα. Ακολουθούσαν τον Μάρσμαν, που έπαιζε τον ρόλο του ξεναγού.\nΣε λίγο βρέθηκαν σε μια απέραντη κοιλάδα, μακριά από το σκάφος. Ήταν τελείως έρημη και στο βάθος διακρίνονταν κάτι περίεργοι στρογγυλοί βράχοι, με πολλές ανάγλυφες πτυχές ανάμεσά τους. Είχαν χρώμα βαθύ καστανό, που, καθώς το χτυπούσε το φως του ήλιου, έπαιρνε κοκκινωπές αποχρώσεις. Λευκοί καπνοί αναβλύζανε από κάτι άλλους χαμηλούς λόφους, ενώ το έδαφος έπαιρνε μια πρασινωπή χροιά.\nΠουθενά δεν υπήρχε νερό ούτε κάποιο άλλο είδος βλάστησης. Οι ερωτήσεις έπεφταν βροχή στον Αρειανό. Αλλά για να δούμε μια ερώτηση που έκανε ο Ιούλιος Βερν.\n«Δε βλέπω να υπάρχει πουθενά νερό. Η μήπως υπάρχει κάπου και δεν το βλέπουμε;» «Για κοιτάξτε εδώ μέσα, κύριε Βερν» είπε ο Μάρσμαν, και αμέσως η κοιλιά του μετατράπηκε σε έγχρωμη οθόνη. «Ο Άρης έχει κι αυτός δύο πόλους, οι οποίοι καλύπτονται με χιόνια και έχουν πολύ χαμηλές θερμοκρασίες. Προς το παρόν δεν υπάρχει νερό. Όταν όμως σε περίπου πεντακόσια χρόνια από σήμερα η ατμόσφαιρα αραιώσει πάρα πολύ από διάφορους επιβαρυντικούς παράγοντες, όπως η μόλυνση του περιβάλλοντος, τότε οι αχτίδες του ήλιου θα βρουν πέρασμα και θα θερμάνουν υπερβολικά τον Άρη. Κάτι τέτοιο έχει αρχίσει να συμβαίνει στη Γη τον εικοστό πρώτο αιώνα, αλλά ευτυχώς δεν έχει πάρει ακόμα διαστάσεις. Αιτία γι’ αυτό το φαινόμενο, που ονομάζεται “φαινόμενο του θερμοκηπίου”, είναι η τρύπα στο όζον της ατμόσφαιρας, που όλο μεγαλώνει. Με τις διάφορες καταστροφές που έχει κάνει ο άνθρωπος στο περιβάλλον, η ατμόσφαιρα της Γης βλάπτεται ανεπανόρθωτα. Όλοι οι πάγοι θα λιώσουν και θα μετατραπούν σε λίμνες, ποτάμια και βροχή. Αυτό όσο κακό φαντάζει για τη Γη, που θα πνιγεί με τα τόσα νερά, τόσο καλό θα είναι για τον Άρη. Έτσι, θα μπορούν οι κάτοικοι του Άρη να εκμεταλλευτούν τις ενεργειακές πηγές του πλανήτη».\nΌταν ο Αρειανός έλεγε αυτά τα λόγια, μεγάλοι και παιδιά κοίταζαν με το στόμα ορθάνοιχτο την εικόνα του πλανήτη Άρη μέσα στην οθόνη, καθώς μετατρεπόταν σε πλανήτη που έμοιαζε όλο και περισσότερο με τη Γη.","word_count":578,"page_number":84,"chapter":"Ενότητα 17 — Ταξίδια στο διάστημα"},{"id":"e_dimotikou_g_0011","source_id":"e_dimotikou_g","title":"Ταξίδι στο διάστημα","content":"Ένας νεαρός επιστήμονας, ο Μιχάλης, κατασκευάζει μια συσκευή η οποία προκαλεί το ενδιαφέρον εξωγήινων, που τον παίρνουν μαζί τους για να του δείξουν τα μυστικά του περίεργου πλανήτη από τον οποίο προέρχονται.\nΌσο κι αν αυτό φαίνεται παράξενο, δεν αισθανόμουν πια ούτε φόβο ούτε αγωνία για την κατάσταση όπου βρισκόμουν. Ποια στιγμή απογειωθήκαμε δεν το ’νιωσα. Μόνο τη Σελήνη είδα ξαφνικά στην οθόνη μπροστά μου. Ο Άνον πάτησε κι άλλα κουμπιά. Μ’ ένα απ’ αυτά έπιασε κάποια αόρατα ραδιοκύματα που πλημμύρισαν την καμπίνα μας.\nΎστερα έχασα και τη Σελήνη, το μόνο νήμα που με κρατούσε δεμένο ακόμα με τη Γη. Το ’χασα και βρέθηκα χαμένος στο χάος. Όλοι πλέαμε στο κοσμικό χάος. O δίσκος μας κι εμείς. Ο Άνον δε μιλούσε. Ίσως με άφηνε να γεμίζω εντυπώσεις. Ίσως πάλι το ταξίδι να ήταν τόσο μακρύ, ώστε είχε καιρό για χρήσιμες κουβέντες. Αφέθηκα λοιπόν στη γαλήνη μας...\nΟ Άνον πάτησε δυο κουμπιά κι οι πλαϊνοί αντικριστοί μεταλλικοί τοίχοι σηκώθηκαν. Το θέαμα με κάρφωσε στη θέση μου. Από τη μια μεριά του δίσκου όπου βρισκόταν ο Ήλιος ήταν μέρα ακόμα· από την άλλη βασίλευε νύχτα. Διαχωριστική γραμμή δεν υπήρχε. Το φως χανόταν μες στο σκοτάδι, σαν κάπου εκεί να συναντούσε το σούρουπο. Μπροστά και πάνω μας ο κατάμαυρος ουρανός, σπαρμένος με μυριάδες αστέρια, άλλα μεγαλύτερα και άλλα μικρότερα, σαν κεφαλάκια καρφίτσας, μα πολύ φωτεινά, με απαλές αποχρώσεις στο άσπρο, το γαλανό, το κίτρινο, το κοκκινωπό. Ο νυχτερινός ουρανός έμοιαζε τώρα μαύρος βελούδινος πελώριος θόλος που στην εσωτερική του επιφάνεια ήταν καρφωμένα τ’ αστέρια. Άλλες στιγμές φάνταζε σαν ένα κλειστό ημισφαίριο με έντονο περίγραμμα. Ύστερα πρόσεξα πως τ’ αστέρια δεν ήταν καρφωμένα στον ουρανό όπως φαίνονται από τη Γη, αλλά κρέμονταν μέσα στο χάος.\nΟ Άνον άφησε από τα χέρια του κάποιο είδος μοχλού: «Δε χρειάζεται πια να κυβερνήσει κανείς το σκάφος μας. Η πορεία του ρυθμίζεται εντελώς αυτόματα. Εκείνη η χειρολαβή βάζει σε κίνηση το περισκόπιο. Κοίταξε, να η Γη σας! Έχει μείνει πίσω στ’ αριστερά».\nΗ θέα της μάνας Γης που έμοιαζε με φωτεινό γαλάζιο δίσκο με συγκλόνισε. Συνειδητοποίησα ότι ταξιδεύαμε σε μια απύθμενη άβυσσο κι ίσως να μην ξαναγύριζα πίσω ποτέ πια. Ο Άνον με επανέφερε στην πραγματικότητα. Άνοιξε ένα μεταλλικό συρτάρι και έβγαλε δύο πελώρια χάπια.\n— Το πρωινό μας, όπως θα λέγατε και στη Γη.","word_count":377,"page_number":89,"chapter":"Ενότητα 17 — Ταξίδια στο διάστημα"},{"id":"g_dimotikou_0001","source_id":"g_dimotikou","title":"Θαλασσινό σχολείο","content":"Πώς θα ’θελα η θάλασσα\nνα ήταν το σχολειό μου\nκαι του σχολειού μου η φορεσιά\nνα ’τανε… το μαγιό μου.\n\nΝα ’χα τα βότσαλα χαρτί,\nτα φύκια συνδετήρι,\nκοχύλια τα μολύβια μου\nκι ο αστερίας σβηστήρι.\n\nΣτην άμμο η ορθογραφία μου\nνα ήτανε γραμμένη\nνα ’ρχεται κύμα γρήγορα\nτα λάθη μου να παίρνει.\n\nΚαι να ’χα για δασκάλες μου\nτις βάρκες π’ αρμενίζουν\nνα μ’ έπαιρναν κάθε πρωί\nστη Γη να με γυρίζουν.","word_count":74,"page_number":11,"chapter":"Πάλι μαζί!"},{"id":"g_dimotikou_0002","source_id":"g_dimotikou","title":"Δημοτικό Σχολείο Τρικάλων Ημαθίας","content":"Ένα σχολείο παρουσιάζεται στο διαδίκτυο.\nTο σχολείο μας είναι σχετικά καινούριο. Βρίσκεται στο κέντρο του χωριού, απέναντι από τη μεγάλη πλατεία του και μπροστά από το παλιό κτίριο που έχει ιστορία σχεδόν ενός αιώνα. Έχει χτιστεί το 1998 και αποτελείται από έξι αίθουσες διδασκαλίας, κατάλληλα εξοπλισμένη αίθουσα ολοήμερου σχολείου, κουζίνα, βοηθητικές αίθουσες προβολών, ηλεκτρονικών υπολογιστών, φυσικών επιστημών, αίθουσα γυμναστηρίου και τα γραφεία του διευθυντή και των δασκάλων.\nΣτην τεράστια αυλή του υπάρχουν γήπεδα για τις αθλητικές δραστηριότητες. Στα διαλείμματα οι μαθητές και οι μαθήτριες διασκεδάζουν παίζοντας στις κούνιες, την τσουλήθρα και τα μονόζυγα που υπάρχουν μέσα σ’ αυτή. Ο χώρος του πράσινου καταλαμβάνει τη μεγαλύτερη έκταση της αυλής του σχολείου μας. Πρόσφατα έχει δεντροφυτευτεί από τα παιδιά του σχολείου, και σύντομα η ομορφιά της θα γίνει ακόμα μεγαλύτερη.","word_count":128,"page_number":19,"chapter":"Πάλι μαζί!"},{"id":"g_dimotikou_0003","source_id":"g_dimotikou","title":"Δεν είναι τρελοί οι δίδυμοι!","content":"Οι αδερφοί Φουσκάλες είναι δίδυμοι. Δεν μπορείς να τους ξεχωρίσεις, μοιάζουν σαν δύο σταγόνες νερό. Στο σχολείο πηγαίνουν σε διαφορετικά τμήματα.\n\nΟι δίδυμοι Φουσκάλες συμπληρώνουν θαυμάσια ο ένας τον άλλο. Ο Ντε λατρεύει τη Γυμναστική και τα Μαθηματικά. Ο Μπε προτιμάει τα Γαλλικά και τη Γεωγραφία. Όταν έρχεται η ώρα\nγια το μάθημα της Φυσικής Αγωγής ή των Μαθηματικών για τον Μπε και των Γαλλικών ή της\nΓεωγραφίας για τον Ντε, οι δίδυμοι απλώς αλλάζουν τμήμα. Είναι το ίδιο απλό σαν να λες καλημέρα.\nΜόλις χτυπήσει το κουδούνι για το\nδιάλειμμα, ο Μπε και ο Ντε τρέχουν\nστις τουαλέτες. Γρήγορα γρήγορα\nγδύνονται και φοράνε ο ένας τα\nρούχα του άλλου. Αυτή είναι η\nσυνηθισμένη τους μέθοδος. Σε\nδύο λεπτά και με τρεις κινήσεις ο Μπε γίνεται Ντε. Και\nο Ντε είναι τώρα Μπε. Στο\nτέλος του διαλείμματος,\nσαν να μη συμβαίνει τίποτα, μπαίνει ο ένας στην τάξη\nτου άλλου.\nΈτσι, οι μεγάλοι βλέπουν τους\nδιδύμους να ενδιαφέρονται και\nνα ασχολούνται με επιτυχία με\nτον αθλητισμό και να έχουν,\nπαράλληλα, εξαιρετικές επιδόσεις στα μαθήματα. Και οι δυο\nτους.\nΚολυμπάνε σαν\nψάρια, τρέχουν σαν\nγαζέλες και κάνουν\nπατινάζ σαν πραγματικοί επαγγελματίες. Και οι\nδυο τους.\n\nΠολύ σπάνια κάνουν ορθογραφικά λάθη και ξέρουν μάλιστα να γράφουν την πιο μεγάλη λέξη\nπου υπάρχει μέσα σ’ αυτό το βιβλίο χωρίς το παραμικρό λαθάκι. Και οι δυο τους… Υποδειγματικοί μαθητές! Και πολύ προικισμένοι.\nΚάνουν τους γονείς τους περήφανους. Οι δίδυμοι βέβαια ξέρουν γιατί έχουν πάντα επιτυχίες\nσε όλα τα μαθήματα. Δεν έχουν σκοπό όμως να βγουν να το διαλαλήσουν σε όλο τον κόσμο.\nΔεν είναι τρελοί οι δίδυμοι!","word_count":262,"page_number":22,"chapter":"Πάλι μαζί!"},{"id":"g_dimotikou_0004","source_id":"g_dimotikou","title":"Αγαπητό μου ημερολόγιο","content":"Από το ημερολόγιο του Αριστείδη\nΑγαπητό μου ημερολόγιο, Κυριακή, 24 Οκτωβρίου\nΣήμερα βρέχει και δεν μπορώ να βγω να παίξω με τους φίλους μου. Όταν είμαι στο σπίτι παίζω συνήθως με την αδελφή μου, αλλά δεν είναι το ίδιο.\nΟι καλύτεροί μου φίλοι είναι ο Σάκης και ο Θανάσης. Μ’ αρέσει πολύ να βγαίνω να παίζω στον δρόμο μαζί τους, αλλά με το σχολείο και την τηλεόραση δε μου μένει καιρός. Κοίτα. Ο Σάκης βλέπει την Τρίτη τα «Παπουτσάκια» κι ο Θανάσης βλέπει την Τετάρτη τον «Άνθρωπο Κατσαρίδα». Αυτό το βλέπω κι εγώ. Τη Δευτέρα έχω Αγγλικά, και την Παρασκευή. Την\nΠέμπτη και το Σάββατο έχω πιάνο. Μένει μόνο η\nΚυριακή για να παίξουμε. Αλλά πολλές φορές την Κυριακή ο Σάκης έχει προπόνηση στο μπάσκετ. Και άλλες φορές ο Θανάσης πηγαίνει με τη μαμά και τον μπαμπά του επίσκεψη στη γιαγιά του.\nΣτις διακοπές, όμως, βγαίνω έξω κάθε μέρα. Γνωρίζω καινούριους φίλους και όλοι μαζί είμαστε μια αγαπημένη παρέα. Αλλά οι διακοπές είναι τόσο λίγες! Ξέρεις, αγαπητό μου ημερολόγιο, ότι έχουμε σχολείο διακόσιες είκοσι μία ημέρες τον χρόνο;\nΠες μου, αγαπητό μου ημερολόγιο, εσύ θα άντεχες;","word_count":186,"page_number":29,"chapter":"Πάλι μαζί!"},{"id":"g_dimotikou_0005","source_id":"g_dimotikou","title":"Η φίλη μας η Αργυρώ","content":"Η Αργυρώ γελάει, η Αργυρώ τραγουδάει.\nΗ Αργυρώ στα χέρια του μπαμπά πετάει,\nη Αργυρώ κάνει κούνια και χαμογελάει.\nΗ Αργυρώ είναι καλή, η Αργυρώ είναι πονηρή,\nη Αργυρώ είναι χαρούμενη, η Αργυρώ είναι λυπημένη.\nΗ Αργυρώ χορεύει, η Αργυρώ ιππεύει.\nΗ Αργυρώ στη θάλασσα κοίτα πώς κολυμπάει,\nη Αργυρώ στα βράχια κρύβεται και μας γελάει.\nΗ Αργυρώ κρύβεται, η πονηρή!\nΗ Αργυρώ φανερώνεται με δυνατή φωνή.\nΗ Αργυρώ είναι άγρια και θυμωμένη,\nη Αργυρώ είναι περήφανη κι ευχαριστημένη.\nΗ Αργυρώ τσαλαβουτάει, η Αργυρώ στριφογυρνάει.\nΗ Αργυρώ από το αυτοκίνητο μας χαιρετάει.\nΗ Αργυρώ μες στο μουσείο βόλτα πάει.\n\nΗ Αργυρώ λύνει σωστά την άσκηση,\nη Αργυρώ τη λύνει λάθος.\nΗ Αργυρώ νιώθει αδύναμη και κλαίει,\nη Αργυρώ νιώθει δυνατή και τίποτα δε λέει. […]\nΗ Αργυρώ με πινέλα χαίρεται να ζωγραφίζει\nκι ύστερα τις ζωγραφιές πετά ή τις χαρίζει.\nΗ Αργυρώ το σκοτάδι νιώθει γύρω της και το φοβάται,\nαγκαλιές θέλει για να ζεσταθεί\nκαι παραμύθια για να κοιμηθεί.\n\nΑυτή είναι η Αργυρώ:\nένα παιδάκι σαν εμένα,\nένα παιδάκι σαν κι εσένα.","word_count":173,"page_number":33,"chapter":"Στο σπίτι και στη γειτονιά"},{"id":"g_dimotikou_0006","source_id":"g_dimotikou","title":"Τα παιδικά μου παιχνίδια","content":"Κάποιο απόγευμα, καθώς παίζαμε στην πλατεία του Μέτελα, πλάι στον γιαλό, μια κυρία μάς φώναξε απ’ το παράθυρο του σπιτιού της και μας κάλεσε ν’ ανεβούμε να μας κεράσει τσάι με βουτήματα. Όλη η παρέα, θα ’μαστε τέσσερις πέντε, ανεβήκαμε γρήγορα τις σκάλες που οδηγούσαν στο διαμέρισμα της μυστηριώδους κυρίας. Τη θυμάμαι ακόμη, καθώς είχε τα άσπρα της μαλλιά χτενισμένα προσεκτικά προς τα πίσω σε κότσο, με πρόσχαρο, ευγενικό πρόσωπο. Εκείνο που με εντυπωσίασε ήταν το επίσημο φόρεμά της και οι ευγενικοί της τρόποι.\nΜας έβαλε να καθίσουμε γύρω γύρω από ένα μεγάλο καρυδένιο τραπέζι και σε λίγο έφτασε με τα σερβίτσια, το τσάι, τα βούτυρα, τις μαρμελάδες και τα βουτήματα. Όλα, φυσικά, ήταν ευρωπαϊκά, από το εξωτερικό, μιας και ήταν, όπως οι περισσότερες από το Αργοστόλι, γυναίκα και μάνα καπετάνιου.\nΜας περιποιόταν με μεγάλη στοργή και φαινόταν καθαρά πως έπαιρνε χαρά απ’ τα χαρούμενα πρόσωπά μας…\nΌταν τελειώσαμε και ετοιμαζόμασταν να φύγουμε, τότε, προφανώς για να παρατείνει την παρουσία μας, έβγαλε απ’ το κομοδίνο ένα μεγάλο ξύλινο κουτί ζωγραφιστό, το τοποθέτησε στο τραπέζι και το άνοιξε. Δεκάδες πολύχρωμα γραμματόσημα μαγέψανε τα μάτια μας. «Κάθε φορά που θα έρχεστε, θα σας κάνω δώρο από δέκα γραμματόσημα στον καθένα».\nΕγώ, αμέσως μετά, αγόρασα ένα χοντρό τετράδιο και άρχισα να κατατάσσω τα γραμματόσημά μου κατά χώρα και κατά σειρά. Μυήθηκα στα μυστικά του συλλέκτη και θυμάμαι ότι κάθε μέρα μετά το σχολείο και πριν βγω στη γειτονιά για να παίξω ήμουν καθισμένος μπροστά στην αγαπημένη μου συλλογή τουλάχιστον για μία ώρα. Διατήρησα αυτήν τη μανία έως ότου τελείωσα το Γυμνάσιο. Σήμερα το τετράδιο αυτό -δώρο στα εγγόνια μου- βρίσκεται φυλαγμένο στο σπίτι της κόρης μου της Μαργαρίτας.","word_count":275,"page_number":37,"chapter":"Στο σπίτι και στη γειτονιά"},{"id":"g_dimotikou_0007","source_id":"g_dimotikou","title":"Στη νέα μας γειτονιά","content":"Η Ελένη με την οικογένειά της μόλις μετακόμισε.\nΑς γνωρίσουμε τη νέα της γειτονιά.\nΤο σπίτι στον Άγιο Δημήτρη θεωρήθηκε μικρό για την εξαμελή μας οικογένεια. […] Το καινούριο μας σπίτι ήταν κι αυτό μέσα σε κτήμα, μαζί μ’ άλλα δυο σπίτια, χτισμένα μακριά το ένα από το άλλο. Είχε λίγα οπωροφόρα, αρκετά κυπαρίσσια και πευκάκια. Στη μέση του δέσποζε με τη θεόρατη κορμοστασιά του το μεγαλύτερο πεύκο που έχετε δει. Τέσσερις φορές ψηλότερο από τη στέγη του σπιτιού, μ’ απλωμένα τα χοντρά κλαδιά του σαν ομπρέλα. Ήταν το καμάρι της γειτονιάς. Αμέσως, στο μεγάλο πρώτο κλαδί του, κρέμασε με γερές αλυσίδες ο πατέρας μου την κούνια.\nΣτο μεγαλύτερο από τα τρία σπίτια έμεναν οι ιδιοκτήτες. Ο κύριος Σταμάτης με τη γυναίκα του, την κυρία Ειρήνη, και τον γιο τους, τον Παρασκευά. Ήταν συνομήλικός μου, κι απ’ την πρώτη στιγμή γίναμε φίλοι και παραμένουμε μέχρι σήμερα, με τις οικογένειές μας, το ίδιο δεμένοι.\nΣτο τρίτο, το μικρότερο σπίτι, έμενε ο κυρ Φάνης, ο κουρέας, με τη γυναίκα του, την κυρία Οδύσσεια. Όλοι εξαιρετικοί άνθρωποι, ιδιαίτερα ο κυρ Σταμάτης. Σοβαρός, καλόψυχος κι υπομονετικός. Ποτέ δε μας μάλωσε. Πάντα μας συμβούλευε. Ήταν -ας πούμε- ο σοφός της γειτονιάς μας.\nΗ καινούρια παιδική μας ομάδα σε λίγες μέρες ήταν έτοιμη. Σχεδόν όλα τα παιδιά ήμασταν συνομήλικα. Μεταξύ μας υπήρχε διαφορά ένα το πολύ δύο χρόνια πάνω ή κάτω από την ηλικία μου. Η Βαρβάρα, η Αργυρώ, ο Αντώνης, ο Αλέκος, ο Στέλιος, ο Παρασκευάς κι εγώ γίναμε επτά. Πότε πότε έμπαινε στην παρέα μας κι ο Βασιλάκης -ο αδερφός μου- και ο Γιάγκος -ο αδερφός του Στέλιου- που ήτανε λίγο μικρότεροι.","word_count":268,"page_number":41,"chapter":"Στο σπίτι και στη γειτονιά"},{"id":"g_dimotikou_0008","source_id":"g_dimotikou","title":"Σπίτι με κήπον","content":"Ήθελα να ’χω ένα σπίτι εξοχικό\nμ’ έναν πολύ μεγάλο κήπο - όχι τόσο\nγια τα λουλούδια, για τα δέντρα, και τες πρασινάδες\n(βέβαια να βρίσκονται κι αυτά· είν’ ευμορφότατα*)\nαλλά για να ’χω ζώα. Α να ’χω ζώα!\nΤουλάχιστον επτά γάτες - οι δυο κατάμαυρες,\nκαι δυο σαν χιόνι κάτασπρες, για την αντίθεση.\nΈναν σπουδαίο παπαγάλο, να τον αγροικώ*\nνα λέγει πράγματα μ’ έμφαση και πεποίθησην*.\nΑπό σκυλιά, πιστεύω τρία θα μ’ έφθαναν.\nΘα ’θελα και δυο άλογα (καλά είναι τ’ αλογάκια).\nΚι εξάπαντος* τρία, τέσσερα απ’ τ’ αξιόλογα\nτα συμπαθητικά εκείνα ζώα, τα γαϊδούρια,\nνα κάθονται οκνά*, να χαίροντ’ οι κεφάλες των.","word_count":104,"page_number":47,"chapter":"Στο σπίτι και στη γειτονιά"},{"id":"g_dimotikou_0009","source_id":"g_dimotikou","title":"Οι ακροβάτες της θάλασσας","content":"Ταξιδεύοντας στις ελληνικές θάλασσες, ίσως έχετε δει δελφίνια να συνοδεύουν το καράβι παίζοντας με τα κύματα. Υπάρχουν διάφορα είδη δελφινιών, τα οποία ζουν σε όλες τις θάλασσες της γης. Ξεχωρίζουν από το πτερύγιο της ράχης τους που μοιάζει με μισοφέγγαρο και από το σχήμα των σαγονιών τους που δίνει την εντύπωση πως χαμογελούν. Το δυνατό τους σώμα έχει μήκος δύο με τέσσερα μέτρα. Το δέρμα τους είναι λείο και έχει συνήθως χρώμα γκρίζο.\nΤα δελφίνια, επειδή δεν είναι ψάρια αλλά θηλαστικά, ανεβαίνουν στην επιφάνεια του νερού για να αναπνεύσουν. Το μοναδικό τους ρουθούνι, ο φυσητήρας, βρίσκεται ψηλά στο κεφάλι τους. Κολυμπούν με μεγάλη ταχύτητα και καταδύονται σε μεγάλα βάθη. Αγαπημένες τους λιχουδιές είναι τα μικρά ψάρια, τα καλαμάρια και οι σουπιές.\nΤα δελφίνια, οι ακροβάτες της θάλασσας, χαίρονται να βουτούν, να πηδούν ψηλά και να παραβγαίνουν στο κολύμπι ακόμα και με μεγάλα πλεούμενα. Μερικές φορές τα δελφίνια έρχονται κοντά στους ανθρώπους για συντροφιά. Δεκάδες ιστορίες λέγονται για δελφίνια που έχουν σώσει ναυαγούς ή έχουν οδηγήσει βάρκες που είχαν χαθεί στην καταιγίδα.\nΤα δελφίνια ζουν σε ομάδες και γεννούν ένα μωρό κάθε ένα με δύο χρόνια. Ζουν 20 ως 40 χρόνια και έχουν ελάχιστους φυσικούς εχθρούς. Ο αριθμός τους όμως στη Μεσόγειο θάλασσα έχει μειωθεί σημαντικά. Κύριες αιτίες: η θαλάσσια ρύπανση και τα δίχτυα των ψαράδων που τα παγιδεύουν κάτω από το νερό.","word_count":222,"page_number":54,"chapter":"Στη γη και στη θάλασσα"},{"id":"g_dimotikou_0010","source_id":"g_dimotikou","title":"Γη και θάλασσα","content":"Η γη είναι καλή με τους χειμώνες της, τα δάση,\nτις μεγάλες πολιτείες, τα χωράφια, τα εργοστάσια…\nΗ θάλασσα είναι καλή με τα υπερωκεάνια,\nτα κοπάδια τα χέλια που ψάχνουν τις πόρτες των ποταμιών,\nμε τις βαρκούλες στα μικρά λιμάνια, τις φουρτούνες,\nτα πουλιά που χτενίζουν τα άγρια μαλλιά της…\nΔες τα παιδιά καθώς τις ζωγραφίζουν\nμ’ ένα χοντρό καταγάλαζο κραγιόνι.\nΗ γη κι η θάλασσα μητέρα\nενώνουν τους ανθρώπους.","word_count":70,"page_number":57,"chapter":"Στη γη και στη θάλασσα"},{"id":"g_dimotikou_0011","source_id":"g_dimotikou","title":"Οι μικροί ταξιδιώτες ανεβαίνουν στο βουνό","content":"Σαν έφτασαν σε μια ράχη, τους καλωσόρισε ο κρύος αέρας. Αυτός ο αέρας είχε περάσει από κάθε κορφή και κάθε λαγκαδιά. Τον πήραν με βαθιά αναπνοή.\nΠουλάκια με άσπρη τραχηλιά κουνούσαν την ουρά τους στους θάμνους κι ύστερα έφευγαν με γοργό λαρυγγισμό. Ένα κατσίκι κατάμαυρο έστεκε στην κόψη του βράχου.\nΟι βράχοι σχημάτιζαν σχήματα σαν θεόρατα σπίτια, που δεν ξέρεις ποιος τα κατοικεί. Οι γκρεμοί ήταν φυτεμένοι με πουρνάρια και κουμαριές. Αλλού κατέβαιναν γυμνοί και απότομοι, σαν να τους είχες κόψει με σπαθί.\nΟ βράχος απάνω στον βράχο, ο λόφος απάνω στον λόφο σχημάτιζαν το βουνό. Πελώρια ήταν όλα. Και σ’ αυτό το ύψος ανέβαινε με στροφές, όλο ανέβαινε, ο δρόμος.\nΕυτυχισμένοι σε τούτο το θέαμα οι μικροί ταξιδιώτες, κοίταξαν προς τις κορφές. Ένας τους φώναξε: «Γεια σας, ψηλά βουνά!».","word_count":130,"page_number":60,"chapter":"Στη γη και στη θάλασσα"},{"id":"g_dimotikou_0012","source_id":"g_dimotikou","title":"Τα χαρτιά ανακυκλώνονται!","content":"Τι είναι αυτή η φασαρία που ακούγεται μέσα από τον Κάδο Ανακύκλωσης;\nΑς πλησιάσουμε λίγο…\nΆουτς!… Κρατς!…\nΜπαμ μπουμ!… Χρατς χρουτς!… Ωχ, ωχ!…\nΚάδος: Ε, σταματήστε επιτέλους τη φασαρία! Μου πήρατε τ’ αυτιά! Τίποτα δε σέβεστε πια!\nΕφημερίδα: Μα, κύριε Κάδε, υπάρχει πολύς συνωστισμός εδώ μέσα, θα σκάσουμε. Πώς να το ανεχτώ αυτό εγώ, μια σοβαρή Εφημερίδα μεγάλης κυκλοφορίας;\nΤετράδιο: Α, για να σας πω, αρκετά σας ανέχτηκα! Για να τσακωνόμαστε μας έφεραν εδώ; Χαρτί γραφομηχανής: Γκουχ γκουχ! (βήχει). Μη φωνασκείτε, περικαλώ! Εγώ θα σας εξηγήσω: ευρισκόμεθα εδώ διά να περισυλλεγώμεν, να διαλεχθώμεν, να ανακυκλωθώμεν και να ξαναγίνομεν χρήσιμα εις την κοινωνίαν χαρτοπροϊόντα!\nΑυγοθήκη: Ποπό, μόρφωση! Αυτό θα πει να έχεις θείτσα γραφομηχανή.\nΒιβλίο: Προς το παρόν, κυρία Αυγοθήκη μου, πείτε στην ξαδέρφη σας να μην ανησυχεί. Όλα εμείς τα χαρτοπροϊόντα θα πάμε για ανακύκλωση. Ο κυρ Κάδος μάς φιλοξενεί προσωρινά. Θα έρθουν οι φίλοι μας από την Οικολογική Ομάδα, θα μας φορτώσουν στο φορτηγάκι τους και μετά…\nΦάκελος αλληλογραφίας: Μετά… τέρμα η ξάπλα αγκαλιά με το Γραμματόσημο!\nΒιβλίο: Μη με διακόπτεις, Φάκελε! Μετά θα μας πάνε στην αποθήκη, θα ξεχωρίσουν τα λευκά χαρτιά από τα σκούρα και τα χρωματιστά, τα χοντρά χαρτόνια από τα λεπτά, τα εξώφυλλα των βιβλίων από τις εσωτερικές τους σελίδες. Θα ξεχωρίσουν, επίσης, τα γυαλιστερά χαρτιά περιτυλίγματος, τις αφίσες και τα χαρτιά συσκευασίας, γιατί αυτά δεν μπορούν να ανακυκλωθούν, και μετά…\nΧαρτοσακούλα: Μετά τη διαλογή, θ’ αλλάξουμε ζωή; Αχ, τι καλά! Πάντοτε ήθελα από Χαρτοσακούλα να γίνω μια τσαχπίνα Σερπαντίνα!\nΒιβλίο: Σωπάστε επιτέλους να ολοκληρώσω, γιατί θα με πιάσουν τα νεύρα μου και θα γίνει…\nτου Χαρτοπόλεμου εδώ μέσα! Λοιπόν, μετά τη διαλογή, θα μας πάνε στο εργοστάσιο χαρτοποιίας, θα μας κάνουν χαρτοπολτό και, αφού καθαριστούμε και ξαναγίνουμε χαρτί, τότε… θ’ αναλάβουμε καινούρια αποστολή. Ουφ, τα είπα όλα και… καθάρισα!\nΧαρτόκουτο: Υπέροχα, από μικρός ήθελα να διορθώσω τη σιλουέτα μου! Αυτή η γραμμή δε με κολακεύει καθόλου! Λύστε μου όμως μια απορία: σε τι βοηθάει η ανακύκλωση τους ανθρώπους;\nΕφημερίδα: Μα πού ζεις εσύ; Δεν ξέρεις ότι, ανακυκλώνοντας το χαρτί, οι άνθρωποι προστατεύουν τα δάση, και γενικότερα τη φύση, και απολαμβάνουν καθαρότερες τις γειτονιές και τις πόλεις τους; Δεν ξέρεις ότι όλα εμείς τα χαρτοπροϊόντα είμαστε παιδιά των δέντρων κι ότι, αν οι άνθρωποι συνεχίσουν να τα κόβουν για να μας φτιάξουν, στο τέλος δε θα βρίσκουν οξυγόνο ν’ αναπνεύσουν;\nΧαρτόκουτο: Φτάνει, φτάνει, κατάλαβα! Όλοι μαζί (τραγουδιστά):\nΘα σε πάρω να φύγουμε σ’ άλλη γη, σ’ άλλα μέρη αγκαλιά για να λιώσουμε χαρτοσούπα να γίνουμε και τα δάση να σώσουμε χαρτονένιο μου ταίρι!\nΑλουμινόκουτο: Ε, ψιτ! Πού πάτε και μας αφήνετε; Τι θ’ απογίνουμε εμείς τ’ Αλουμινόκουτα των αναψυκτικών κι οι ξαδέρφες μας οι Κονσέρβες;\nΧαρτιά (όλοι μαζί): Ααα, το καλό που σας θέλουμε! Εσείς να γυρίσετε στους κάδους σας και να πείτε να σας γράψουν ένα δικό σας έργο. Αυτό ήταν το δικό μας!","word_count":470,"page_number":69,"chapter":"Ο κόσμος γύρω μας"},{"id":"g_dimotikou_0013","source_id":"g_dimotikou","title":"Το τετράδιο ζωγραφικής","content":"– Άμα μεγαλώσω, θα γίνω ζωγράφος, έλεγε πάντα η Καιτούλα.\nΚι όλο έφτιαχνε στο τετράδιό της διάφορα σχέδια και γέμιζε τα φύλλα με χρώματα. Πράσινα, κίτρινα, κόκκινα και μπλε. Ήξερε και να τ’ ανακατεύει. Να βάζει λίγο κίτρινο ή άσπρο για να ξανοίξει μια φιγούρα. Κι άμα ήθελε να τη σκουρύνει, έβαζε καφέ ή μαύρο. Σαν σωστός ζωγράφος. Να δεις που, άμα ανακάτευε το πράσινο με το μπλε, γινόταν ένα παράξενο χρώμα, πολύ παράξενο! Ήξερε πολλά τέτοια ανακατώματα στα χρώματα. Και της άρεσαν όλα τούτα τόσο πολύ, που ξεχνιόταν εντελώς. Πέρναγε ατέλειωτες ώρες σκυμμένη στο τετράδιό της. Κι η μαμά της έβρισκε την ευκαιρία να κάνει του κόσμου τις δουλειές.\n– Τι είναι αυτό; τη ρώτησε σαν πήγε κοντά της.\n– Θάλασσα, δεν τη βλέπεις; Έγινε λίγο σκούρα, γι’ αυτό δεν τη γνώρισες. Τι να γίνει! Χύθηκε μέσα πετρέλαιο. Πολύ πετρέλαιο, από ένα καράβι που ναυάγησε. Γι’ αυτό έχει τέτοιο χρώμα. Τα ψάρια πέθαναν όλα, δεν έμεινε τίποτα ζωντανό. Είναι μια νεκρή θάλασσα, έτσι την είπε ο μπαμπάς.\n– Κι αυτό το κόκκινο τι είναι; ξαναρώτησε η μαμά της.\n– Βαρκούλα.\n– Δεν ξεχωρίζει και τόσο. Γιατί δε βάζεις κι έναν άνθρωπο μέσα;\nΤι ζωγράφος θα γίνεις;\n– Άνθρωπος μέσα σ’ αυτήν τη βάρκα, τι να κάνει; Ούτε να ψαρέψει μπορεί ούτε να κολυμπήσει σε τέτοια νερά.\n– Να πάει περίπατο.\n– Δεν του κάνει όρεξη, σου λέω. Δε θέλει να κάνει βόλτα στη νεκρή θάλασσα, είπε θυμωμένη η Καιτούλα.\n– Τότε να πάρει τη βάρκα του και να πάει σ’ άλλη θάλασσα, καθαρότερη.\n– Εύκολο σου φαίνεται να φύγει; Εδώ έχει τους δικούς του, το σπίτι του και τη δουλειά του. Τον αγαπάει τον τόπο του, καταλαβαίνεις; Πώς να τ’ αφήσει όλ’ αυτά;\nΚάθεται μόνος του στην παραλία και κλαίει.\n– Πού είναι; Εγώ δεν τον βλέπω πουθενά, είπε η μαμά της.\n– Να τος, της απάντησε, και στο λεπτό τον ζωγράφισε. Κάθεται μαζεμένος και δε φαίνεται καλά. Θυμάται τη θάλασσα όπως ήταν πριν και λυπάται που τη βλέπει τώρα έτσι.","word_count":332,"page_number":73,"chapter":"Ο κόσμος γύρω μας"},{"id":"g_dimotikou_0014","source_id":"g_dimotikou","title":"Η σημαία","content":"Ύμνος της σημαίας\n\nΑυτό είναι το ιερό πανί το γαλανό και τ’ άσπρο,\nκομμάτι από ανοιξιάτικο και ξάστερο ουρανό,\nπου είναι λευκό σαν τον αφρό του κύματος που ανθίζει\nσε περιγιάλι ολόγλυκο, σε πέλαο μακρινό.\nΑυτό είναι το ιερό πανί, που, όταν περνάει μπροστά μας,\nυγραίνονται τα βλέφαρα και σπαρταρά η καρδιά μας.","word_count":53,"page_number":79,"chapter":"Ο κόσμος γύρω μας"},{"id":"g_dimotikou_b_0001","source_id":"g_dimotikou_b","title":"Η πόλη χάθηκε στο χιόνι","content":"Το πρωί εκείνο τον ξύπνησε η σιωπή. Ο Μαρκοβάλντο σηκώθηκε από το κρεβάτι του νιώθοντας κάτι παράξενο στον αέρα. Δεν καταλάβαινε τι ώρα ήταν. Το φως που περνούσε από τις περσίδες των παραθυρόφυλλων ήταν εντελώς διαφορετικό από οποιαδήποτε άλλη ώρα της ημέρας ή της νύχτας. Άνοιξε το παράθυρο. Η πόλη είχε χαθεί, είχε αντικατασταθεί από ένα λευκό χαρτί. Ζαρώνοντας τα μάτια, διέκρινε μες στην ασπράδα μερικές αχνές γραμμές στη θέση της εικόνας που συνήθως έβλεπε. Τα παράθυρα, οι στέγες και οι κολόνες του δρόμου ήταν εκεί, αλλά είχαν σκεπαστεί από το χιόνι που είχε πέσει τη νύχτα. [...] Πήγε στη δουλειά με τα πόδια. Τα τραμ είχαν ακινητοποιηθεί εξαιτίας του χιονιού. Καθώς περπατούσε και άνοιγε ο ίδιος τον δρόμο του, ένιωθε πιο ελεύθερος παρά ποτέ. Στους δρόμους της πόλης δεν υπήρχε πια διαφορά ανάμεσα στο πεζοδρόμιο και στο οδόστρωμα. Τα αυτοκίνητα δεν μπορούσαν να περάσουν. Ο Μαρκοβάλντο, παρόλο που σε κάθε του βήμα βούλιαζε στο χιόνι ως τα μισά της γάμπας και το ένιωθε να του μουσκεύει τις κάλτσες, είχε γίνει δεξιοτέχνης στο να περπατάει στη μέση του δρόμου, να ποδοπατάει τις πρασιές, να προχωρεί με ζικ ζακ.\nΟι δρόμοι και οι λεωφόροι ανοίγονταν έρημοι και απέραντοι σαν ολοκάθαρα περάσματα ανάμεσα στους βράχους των βουνών. Ποιος ξέρει αν η πόλη είχε μείνει ίδια κάτω από τον μανδύα που την έκρυψε ή αν μια άλλη πόλη είχε πάρει τη θέση της; Ποιος ξέρει αν κάτω από εκείνα τα άσπρα βουναλάκια υπήρχαν ακόμη τα περίπτερα, οι στάσεις του τραμ ή αν δεν ήταν παρά μόνο σωροί από χιόνι;\nΚαθώς ο Μαρκοβάλντο περπατούσε, ονειρευόταν ότι είχε χαθεί σε μια διαφορετική πόλη. Όμως τα βήματά του τον οδήγησαν ίσια στο μέρος όπου δούλευε κάθε μέρα, στη συνηθισμένη αποθήκη.\nΜόλις ο αχθοφόρος έφτασε στο κατώφλι, ένιωσε έκπληξη που ξαναβρέθηκε ανάμεσα στους ίδιους πάντα τοίχους, λες και η αλλαγή, που είχε σβήσει τον έξω κόσμο, είχε αφήσει μόνο την επιχείρησή του. Εκεί καθόταν και τον περίμενε ένα φτυάρι πιο ψηλό από το μπόι του. Ο αρχιαποθηκάριος, ο κύριος Βιλιτζέλμο, του το έδωσε και είπε:\n- Ο καθαρισμός του πεζοδρομίου μπροστά στην εταιρεία είναι δική μας δουλειά, δηλαδή δική σου.\nΟ Μαρκοβάλντο αγκάλιασε το φτυάρι και γύρισε να βγει έξω. Το φτυάρισμα του χιονιού δεν είναι παιχνίδι, ιδίως για όποιον δουλεύει με αδειανό στομάχι. Όμως ο Μαρκοβάλντο ένιωθε ότι το χιόνι ήταν φίλος του και στρώθηκε πρόθυμα στη δουλειά πετώντας μεγάλες φτυαριές χιόνι από το πεζοδρόμιο στη μέση του δρόμου.","word_count":403,"page_number":9,"chapter":"Πολιτείες ντυμένες στα λευκά"},{"id":"g_dimotikou_b_0002","source_id":"g_dimotikou_b","title":"Η πόλη χάθηκε στο χιόνι (συνέχεια)","content":"Ο Μαρκοβάλντο είχε ήδη στρίψει στη γωνία και φτυάριζε στην αυλή. Τα παιδιά της αυλής είχαν φτιάξει έναν χιονάνθρωπο.\n- Του λείπει μια μύτη! είπε ένα τους.\n- Τι να του βάλουμε; Ένα καρότο! Και έτρεξε το καθένα στην κουζίνα του να μαζέψει ζαρζαβατικά*.\nΟ Μαρκοβάλντο κοίταζε τον χιονάνθρωπο. «Να, κάτω από το χιόνι δε φαίνεται τι είναι από χιόνι και τι είναι απλώς θαμμένο μέσα του».\nΑπορροφημένος στις σκέψεις του, δεν πρόσεξε ότι δύο άντρες πάνω στη σκεπή τού φώναζαν: -Έι, κύριος, φύγε λίγο αποκεί!\nΉταν εκείνοι που καθάριζαν το χιόνι από τα κεραμίδια. Και ξαφνικά μια μεγάλη ποσότητα χιονιού έπεσε ακριβώς επάνω του.\nΤα παιδιά ξαναγύρισαν με τα λάφυρά* τους σε καρότα.\n- Α! κάποιος έφτιαξε ακόμα έναν χιονάνθρωπο!\nΣτη μέση της αυλής υπήρχαν δύο ίδια ομοιώματα πλάι πλάι.\n- Να βάλουμε μύτη και στους δύο! και βύθισαν δύο καρότα στα κεφάλια των δύο χιονανθρώπων.\nΟ Μαρκοβάλντο, περισσότερο πεθαμένος παρά ζωντανός, ένιωσε την τροφή να του ’ρχεται μέσα από το περίβλημα* του χιονιού που τον είχε θάψει και καταψύξει. Και μάσησε.\n- Μαμά μου! Χάθηκε το καρότο!\nΤα παιδιά είχαν κατατρομοκρατηθεί. Το πιο τολμηρό δε λιγοψύχησε*. Είχε μια ανταλλακτική μύτη, μια πιπεριά και την έβαλε στον χιονάνθρωπο. Ο χιονάνθρωπος και πάλι την καταβρόχθισε.\nΤότε δοκίμασαν να του βάλουν ένα κομματάκι κάρβουνο, από εκείνα που μοιάζουν με ραβδάκια, για μύτη. Ο Μαρκοβάλντο το έφτυσε με όλη του τη δύναμη.\n- Βοήθεια! Είναι ζωντανός! Είναι ζωντανός!\nΤα παιδιά το έβαλαν στα πόδια.\nΣε μια γωνιά της αυλής υπήρχε μια σχάρα απ’ όπου έβγαινε ένα σύννεφο ζέστης. Ο Μαρκοβάλντο, με το βαρύ βήμα του χιονάνθρωπου, πήγε και στάθηκε εκεί. Το χιόνι έλιωσε πάνω του, κύλησε ρυάκια στα ρούχα του. Εμφανίστηκε ένας Μαρκοβάλντο με μια μύτη πρησμένη και βουλωμένη από το κρυολόγημα.\nΠήρε το φτυάρι του, περισσότερο για να ζεσταθεί, και βάλθηκε να δουλεύει στην αυλή. Είχε ένα φτέρνισμα που στεκόταν στην κορυφή της μύτης, στεκόταν εκεί και δεν έλεγε να βγει έξω. Ο Μαρκοβάλντο φτυάριζε με τα μάτια μισόκλειστα και με το φτέρνισμα κουρνιασμένο στην κορυφή της μύτης του. Και ξαφνικά το «Αααααψιού...» ακούστηκε σχεδόν σαν βροντή. Το ρεύμα του αέρα τίναξε τον Μαρκοβάλντο πάνω στον τοίχο...\nΌταν ο Μαρκοβάλντο άνοιξε τα μάτια του μετά τη λιποθυμία του, η αυλή ήταν εντελώς καθαρή, δίχως μια νιφάδα χιόνι. Στα μάτια του ξαναεμφανίστηκε η αυλή που ήξερε, με τους γκρίζους τοίχους, τα κιβώτια στην αποθήκη, τα πράγματα που έβλεπε κάθε μέρα.","word_count":398,"page_number":12,"chapter":"Πολιτείες ντυμένες στα λευκά"},{"id":"g_dimotikou_b_0003","source_id":"g_dimotikou_b","title":"Ο χιονάνθρωπος και το κορίτσι","content":"Χειμώνας σε μια πλατεία. Χιονίζει σιωπηλά. Την ησυχία του τοπίου διαταράσσουν φωνές και γέλια\nπαιδιών. Μπαίνουν στη σκηνή τρία παιδιά: τα δίδυμα, ο Θανούλης και ο Φανούλης, και η αδελφή\nτους η Μαριάννα.\n\nΘανούλης: Kρύο που κάνει!\nΜαριάννα: Κοίτα! Κοίτα την ανάσα μου! Γίνεται αχνός*!\n\nΜαριάννα: Σαν κρέμα σαντιγί!\nΘανούλης: Τι γρήγορα που το ’στρωσε! [...]\nΜαριάννα: Τι λέτε; Φτιάχνουμε χιονάνθρωπο;\nΦανούλης: Ναι! Έναν όμορφο! Έναν κούκλο!\nΘανούλης: Έναν απίθανο χιονάνθρωπο!\n\n(Αρχίζουν να μαζεύουν χιόνι και να φτιάχνουν\nέναν χιονάνθρωπο τραγουδώντας.)\n\nΘανούλης: Έτοιμος!\nΜαριάννα: Όμορφος είναι!\nΦανούλης: Πώς να τον λέμε;\n\nΤουρτούρι σε λένε!\nΘανούλης: Καλημέρα, Τουρτούρι!\nΦανούλης: Καλημέρα! [...]\n\n(Ακούγεται μια φωνή από τα παρασκήνια*.)\n\nΦωνή: Θανούλη! Φανούλη!\nΜαριάννα!\nΦανούλης: Μας φωνάζει η μαμά!\nΕρχόμαστε!\n\n(Τα δίδυμα βγαίνουν τρέχοντας. Η Μαριάννα\nκάνει να φύγει. Κοντοστέκεται. Κοιτάζει τον\nχιονάνθρωπο, που έχει ύφος θλιμμένο).\n\nΜαριάννα: Δε θέλεις να σ’ αφήσουμε μόνο σου, ε;\n\nΜαριάννα: Πες μου κάτι! Σ’ αρέσει που σε φτιάξαμε;\n\nΜαριάννα: Τουρτούρι...\n\nΜαριάννα: Θα μου κάνεις μια χάρη;\n\nΜαριάννα: Να μη λιώσεις ποτέ! Να ζήσεις για πάντα!\nΤουρτούρι: Πάντα; Πόσο μεγάλο είναι ένα «πάντα»;\n\nΤουρτούρι: Ωραία! Θα ζήσω για πάντα! Δε θα λιώσω ποτέ!\nΜαριάννα: Έτσι μπράβο! Θέλεις να σου χαρίσω κάτι;\nΤουρτούρι: Γιατί; Έχω κιόλας τα γενέθλιά μου;\n\nΤουρτούρι: Τι ωραίο δαχτυλίδι!\nΜαριάννα: Έχει δυο ψεύτικες γαλάζιες πετρούλες!\nΤουρτούρι: Ναι! Γαλάζιες είναι!... Σαν τα μάτια σου! Ευχαριστώ!\nΜαριάννα: Έτσι μου ’ρχεται να σε φιλήσω! Θέλεις;\nΤουρτούρι: Θέλω λέει!...\n(Ακούγεται η φωνή της μαμάς από τα παρασκήνια.)\nΦωνή: Μαριάννα! Πού είσαι Μαριάννααα;\nΜαριάννα: (Βιαστικά). Πρέπει να φύγω! Αύριο θα ξανάρθω και θα σου πω όλα τα μυστικά\nμου! Όλα! Περίμενε εδώ! Εντάξει;\nΤουρτούρι: Εντάξει!... Αλλά πες μου...\n(Ακούγεται πάλι η φωνή της μαμάς από τα παρασκήνια.)\nΦωνή: Μαριάννα!\n\nποτέ; Θα με ξαναφιλήσει; Τι λέτε;","word_count":285,"page_number":21,"chapter":"Πολιτείες ντυμένες στα λευκά"},{"id":"g_dimotikou_b_0004","source_id":"g_dimotikou_b","title":"Κάτω απ’ το χιόνι","content":"Σκέψου - τι πράματα γλυκά\nκοιμούνται κάτωθε απ’ το χιόνι.\nΚοιμάται ο σπόρος, μυστικά,\nκαθώς το φύτρο του φυτρώνει.\n\nΚοιμούνται αμέτρητα σπαρτά\n- κι όλο ονειρεύονται τα στάχυα.\nΤ’ άγρια μπουμπούκια, σφαλιστά,\nύπνος τα παίρνει, μες στα βράχια.\n\nΈχει όλ’ η πλάση κοιμηθεί\nκάτω απ’ το κάτασπρο σεντόνι,\nωσότου να της πει στ’ αυτί\nμια συλλαβή το χελιδόνι.\n\nΚαι τότες! Ρόδα, γιασεμιά,\nγλυκά κεράσια, χρυσά στάχυα,\nκι η αγαπημένη η κυκλαμιά\n«Ευχαριστώ» θα πει στα βράχια.","word_count":76,"page_number":26,"chapter":"Ιστορίες του χειμώνα"},{"id":"g_dimotikou_b_0005","source_id":"g_dimotikou_b","title":"Το χαρούμενο λιβάδι","content":"Η Μελίνα απολαμβάνει τα δώρα του Ελτόν.\nΤρώει τη σοκολάτα της και διαβάζει το βιβλίο που της δώρισε.\nΚάποτε, λίγο πιο μακριά από το μέρος που μένουμε, υπήρχε ένα λιβάδι. Όλοι έλεγαν πως ήταν το ωραιότερο λιβάδι που είχαν δει ποτέ. Ήταν γεμάτο κάτασπρες μαργαρίτες. Οι μαργαρίτες ήταν πολύ αγαπημένες και περνούσαν όμορφα μαζί. Ώσπου μια μέρα μια παπαρούνα φύτρωσε δίπλα τους. Σε λιγάκι μαζεύτηκαν όλες οι μαργαρίτες γύρω από το καινούριο φυτό. Άλλες το κοίταζαν με περιέργεια, άλλες με θαυμασμό κι άλλες του γύριζαν την πλάτη, γιατί δεν το ήθελαν στο λιβάδι τους.\n- Αυτή είναι κατακόκκινη κι εμείς ολόασπρες, είπε μια ψηλομύτα μαργαρίτα. Κοίτα πώς διαφέρει από εμάς! Κοιτάξτε τα φύλλα της πόσο άγρια είναι! Και το κοτσάνι της είναι όλο αγκάθια! Μας χαλάει την ομορφιά του λιβαδιού. Αδύνατο να ανεχτώ εγώ, μια άσπρη, κάτασπρη μαργαρίτα, να μείνω μαζί της. Δε θέλω ένα τέτοιο λουλούδι δίπλα μου.\n- Τι είναι αυτά που λέτε; είπε η γιαγιά μαργαρίτα, που τη φώναζαν Γιαγιά Μαργαριτένια και που όλες οι μαργαρίτες άκουγαν τη γνώμη της γιατί ήταν σοφή. Ο παππούς σας, που είχε πολλούς φίλους, μου έλεγε πως υπάρχουν κι αλλού λιβάδια που έχουν μαργαρίτες και παπαρούνες μαζί. Αυτός και οι φίλοι του περνούσαν πολύ ωραία εκεί, γιατί και οι παπαρούνες είναι λουλούδια σαν κι εμάς. Γι' αυτό, εγώ σας λέω να την αφήσουμε να μείνει μαζί μας. Δεν πρόκειται να μας κάνει κανένα κακό.\n- Τι λες; έκανε θυμωμένα μια άλλη μαργαρίτα. Κι αν δίπλα σ’ αυτή την παπαρούνα ξεφυτρώσει κι άλλη και κάνουν παπαρουνάκια, τότε θα γεμίσει το λιβάδι μας με παπαρουνοπαιδάκια. Δε θέλω τα μαργαριτάκια μου να παίζουν μαζί τους.\n- Αυτή διαφέρει από εμάς. Πώς μπορούμε να ταιριάξουμε;\n- Κι εμείς οι μαργαρίτες διαφέρουμε μεταξύ μας κι όμως ταιριάξαμε, είπε η Μαργαρίτα-Ρίτα, μια άλλη μαργαρίτα που από την αρχή κοίταζε με συμπάθεια την παπαρούνα.\n- Πώς διαφέρουμε μεταξύ μας, αφού είμαστε όλες άσπρες; απόρησαν οι υπόλοιπες μαργαρίτες.\nΚι άρχισαν να μετρούν τα φύλλα τους, τα κοτσάνια τους και τις ρίζες τους. Κατάλαβαν ότι είχαν αρκετές διαφορές. Έτσι με τον καιρό, άρχισαν να γίνονται φίλες με την παπαρούνα. Περνούσαν πολύ καλά όλες παρέα. Η παπαρούνα είχε γίνει μέλος της ομάδας τους, κι ας ήταν κόκκινη. Κατάλαβαν πως ούτε το φαγητό τους τρώει ούτε τον ήλιο τους παίρνει. Έφταναν όλα για όλους. Είχαν ακούσει μάλιστα τους ανθρώπους να λένε πως, τώρα που το λιβάδι ήταν ασπροκόκκινο, τους άρεσε περισσότερο.","word_count":399,"page_number":50,"chapter":"Έλα στην παρέα μας!"},{"id":"g_dimotikou_b_0006","source_id":"g_dimotikou_b","title":"Το ηλιακό λεωφορείο","content":"Ήταν κάποτε μια μικρή, ονειρεμένη πολιτεία, η Λιλιπούπολη,\nπου στους δρόμους της ταξίδευε ένα αλλιώτικο λεωφορείο.\n\nΈνα λεωφορείο που το λένε Ηλιοτρόπιο,\nμε πεταλούδες άσπρες και ροζ,\nκάνει κάθε μέρα κι ένα δρομολόγιο\nπάνω σε μια γραμμή από φως.\n\nΤρέχα, ηλιακό μου λεωφορείο,\nπέρνα σαν αστραπή πορτοκαλιά\nκι απ' την εξάτμισή σου πέτα γύρω γύρω\nηλιόσπορους να τρώνε τα πουλιά.\n\nΜ’ ένα λεωφορείο που το λένε Ηλιοτρόπιο\nγεμάτο γέλια και μουσικές,\nπάμε κάθε μέρα κι ένα δρομολόγιο\nστις φωτεινές μας Λιλιγειτονιές.","word_count":81,"page_number":65,"chapter":"Άνθρωποι και μηχανές"},{"id":"g_dimotikou_b_0007","source_id":"g_dimotikou_b","title":"Να ’μουν του στάβλου έν’ άχυρο","content":"Να ’μουν του στάβλου εν’ άχυρο, ένα φτωχό κομμάτι, την ώρα π’ άνοιξε ο Χριστός στον ήλιο του το μάτι! Να ιδώ την πρώτη του ματιά και το χαμόγελό του, το στέμμα των ακτίνων του γύρω στο μέτωπό του. Να λάμψω από τη λάμψη του κι εγώ σαν διαμαντάκι κι από τη θεία του πνοή να γίνω λουλουδάκι, να μοσχοβοληθώ κι εγώ από την ευωδία, που άναψε στα πόδια του των Μάγων η λατρεία.\nΝα ’μουν του στάβλου έν’ άχυρο, ένα φτωχό κομμάτι, την ώρα π’ άνοιξ’ ο Χριστός στον ήλιο του το μάτι...","word_count":94,"page_number":75,"chapter":"Άνθρωποι και μηχανές"},{"id":"g_dimotikou_b_0008","source_id":"g_dimotikou_b","title":"Η καταστροφή των Ψαρών","content":"Το 1824, κατά τη διάρκεια της ελληνικής επανάστασης, ο σουλτάνος απειλεί το μικρό νησί των Ψαρών επειδή ενισχύει σημαντικά τον ιερό αγώνα.\nΟι κάτοικοι αποφασίζουν να αμυνθούν στη στεριά παρά την αντίθετη γνώμη Ψαριανών, όπως ο πυρπολητής Κανάρης, που ήθελαν να δώσουν τη μάχη στη θάλασσα. Η αντίσταση στην πολιορκία είναι γενναία, αλλά οι τουρκικές δυνάμεις υπερισχύουν. Οι περισσότεροι κάτοικοι θυσιάζονται στον βωμό της ελευθερίας, και το ηρωικό νησί καταστρέφεται ολοκληρωτικά. Το ολοκαύτωμα των Ψαρών συγκλονίζει τον ελληνισμό.","word_count":78,"page_number":79,"chapter":"Άνθρωποι και μηχανές"},{"id":"g_dimotikou_b_0009","source_id":"g_dimotikou_b","title":"Ο εγωιστής Γίγαντας (συνέχεια)","content":"Ένα πρωί που ο Γίγαντας ήταν ξαπλωμένος στο κρεβάτι του, άκουσε μια υπέροχη μελωδία. Τόσο γλυκά χάιδεψε τ’ αυτιά του, που για μια στιγμή νόμισε πως ήταν οι μουσικοί του Βασιλιά που περνούσαν από τα μέρη του. Ήταν ένας μικρούλης σπίνος που τραγουδούσε έξω από το παραθύρι του. Είχε όμως τόσον καιρό ν’ ακούσει πουλί να κελαηδάει στον κήπο του, που του φάνηκε πως ήταν η πιο γλυκιά μελωδία στον κόσμο. Εκείνη την ώρα το Χαλάζι έπαψε να χορεύει πάνω από το κεφάλι του κι ο Βοριάς έπαψε να βρυχάται, κι ένα υπέροχο μεθυστικό άρωμα ξεχύθηκε από το ανοιχτό παραθυρόφυλλο. «Μου φαίνεται πως επιτέλους ήρθε η Άνοιξη» είπε ο Γίγαντας. Πετάχτηκε από το κρεβάτι του και κοίταξε έξω. Και τι να δει; Μπροστά στα μάτια του παρουσιάστηκε το πιο υπέροχο θέαμα. Μέσα από μια μικρή σχισμή στον τοίχο είχαν ξεγλιστρήσει τα παιδιά στον κήπο και κάθονταν πάνω στα κλαδιά του δέντρου. Σε κάθε δέντρο, όσο έβλεπε το μάτι του, καθόταν κι ένα μικρό παιδάκι. Και τα δέντρα έκαναν τέτοιες χαρές που είχαν γυρίσει πίσω τα παιδιά, που γέμισαν μπουμπούκια και κουνούσαν τα κλαδιά τους τρυφερά πάνω από τα παιδικά κεφαλάκια. Τα πουλιά φτερούγιζαν ολόγυρα κελαηδώντας ευτυχισμένα, και τα λουλούδια ανασήκωναν τα κεφάλι τους ανάμεσα στο πράσινο γρασίδι και γελούσαν. Ήταν μια υπέροχη σκηνή, μονάχα που σε μια γωνιά του κήπου ήταν ακόμα χειμωνιά. Ήταν η πιο απομακρυσμένη γωνιά του κήπου, κι εκεί καθόταν ένα μικρό αγοράκι. Ήταν τόσο μικρό, που δεν έφτανε να σκαρφαλώσει στα κλαδιά του δέντρου, κι έκανε κύκλους γύρω από αυτό, κλαίγοντας πικρά. Το δέντρο το καημένο ήταν ακόμα σκεπασμένο από χιόνι και παγωνιά, κι ο Βοριάς φυσούσε μανιασμένα πάνω του. «Σκαρφάλωσε, μικρό αγόρι!» έλεγε το Δέντρο, κι έγερνε τα κλαδιά του όσο πιο χαμηλά μπορούσε. Άδικος κόπος, το αγόρι ήταν πολύ μικροκαμωμένο.\nΚοιτάζοντας έξω, ο Γίγαντας ένιωσε την καρδιά του να ραγίζει. «Τι εγωιστής που ήμουν!» είπε. «Τώρα καταλαβαίνω γιατί δεν ερχόταν η Άνοιξη εδώ. Θ’ ανεβάσω τούτο το αγοράκι πάνω στο δέντρο κι ύστερα θα γκρεμίσω τον τοίχο, κι ο κήπος μου θα ’ναι για πάντα ο παιχνιδότοπος των παιδιών». Στ’ αλήθεια, είχε πολύ στενοχωρηθεί για ό,τι είχε κάνει.\nΚι έτσι, κατέβηκε τις σκάλες, άνοιξε απαλά την πόρτα και βγήκε στον κήπο. Όμως, σαν τον είδαν τα παιδιά φοβήθηκαν τόσο πολύ, που έτρεξαν μακριά και στον κήπο ξαναγύρισε ο Χειμώνας. Μονάχα το μικρό αγόρι δεν έτρεξε να σωθεί, γιατί τα μάτια του ήταν τόσο γεμάτα δάκρυα, που δεν είδε τον Γίγαντα που πλησίαζε. Ο Γίγαντας ζύγωσε στα κλεφτά, το πήρε τρυφερά στο χέρι του και το ακούμπησε πάνω στο δέντρο. Κι ευθύς το δέντρο άνθισε και τα πουλιά ήρθαν να κελαηδήσουν στα κλαδιά του, και το μικρό αγόρι άνοιξε τα δυο του χέρια, αγκάλιασε τον λαιμό του Γίγαντα και τον φίλησε. Και τ’ άλλα παιδιά, σαν είδαν πως ο Γίγαντας δεν ήταν πια κακός, γύρισαν πίσω τρέχοντας και μαζί τους γύρισε κι η Άνοιξη. «Δικός σας είναι πια τούτος ο κήπος, παιδιά μου» είπε ο Γίγαντας, και μ’ ένα τεράστιο τσεκούρι γκρέμισε τον τοίχο. Και το καταμεσήμερο, που πήγαιναν οι άνθρωποι στην αγορά, είδαν τον Γίγαντα να παίζει με τα παιδιά στον πιο όμορφο κήπο που είχαν δει ποτέ τους.","word_count":525,"page_number":87,"chapter":"Άνθρωποι και μηχανές"},{"id":"g_dimotikou_g_0001","source_id":"g_dimotikou_g","title":"Τα ταξίδια του παππού μου","content":"Και τι δε μου έλεγε εμένα ο παππούλης μου όταν ήμουνα μικρός. Ώρες ολόκληρες έλεγε, έλεγε, κι εγώ δε χόρταινα να τον ακούω. Για χώρες μακρινές, για μέρη άγνωστα κι αλαργινά*, που δεν τα βάνει ο νους του ανθρώπου. Για της θάλασσας τον αφαλό, που καταπίνει τα καράβια, και για τη χώρα των Σκυλοκέφαλων, κι ακόμα για τη Γοργόνα, την αδελφή του Μεγαλέξαντρου, και γι' άλλα τέτοια φοβερά και τρομερά που κρύβει τούτη η πλάση.\n- Αλήθεια, παππού; τον ρωτούσα.\n- Αλήθεια, ψυχή μου, απαντούσε εκείνος.\nΒασιλοπούλες όμορφες περίμεναν μέσα σε πλουμιστά παλάτια το ραφτόπουλό τους, κι εγώ δεν έβλεπα την ώρα να μεγαλώσω λίγο και να φύγω απ' το χωριό, να βγω στον κόσμο, να πάω στην Πόλη* και στην Αγια-Σοφιά. Δεν άργησε να ’ρθει αυτή η ώρα. Η μάνα μού ετοίμασε το μπογαλάκι* μου και μ’ έστειλε στην Πόλη, σ' έναν ράφτη σπουδαίο και τρανό.\n- Να πας να μάθεις την τέχνη, να γίνεις ραφτόπουλο, να βγάζεις το ψωμί σου. Έτσι μου είπε. Πήγα, λοιπόν, κι εγώ στην Πόλη κι είδα την Αγια-Σοφιά, κι είδα τον Βόσπορο, και θαμπώθηκα απ' την ομορφιά. Όμως, η δουλειά στο ραφτάδικο ήτανε σκληρή και το αφεντικό δε χωράτευε*. Είχε και μια πήχη*, κι άμα τεμπέλιαζε κανένα από τα ραφτόπουλα, μ' αυτή μας βάραγε για να στρωθούμε στη δουλειά. Κι όσο για βασιλοπούλες, που έλεγε ο παππούς, αυτές δεν τις είδα πουθενά!\n- Αχ, παππούλη, έλεγα μέσα μου, αναστενάζοντας, με τη μέση μου πιασμένη απ' το ράψιμο. Πότε θα ’ρθει κι εμένα η βασιλοπούλα μου, να φύγουμε απ' το ραφτάδικο, να πάμε να χτίσουμε το παλάτι μας και στο τέλος να ζούνε αυτοί καλά κι εμείς καλύτερα!","word_count":274,"page_number":9,"chapter":"Ήτανε μια φορά"},{"id":"g_dimotikou_g_0002","source_id":"g_dimotikou_g","title":"Τα ταξίδια του παππού μου (συνέχεια)","content":"Μια μέρα ήρθε ο Θύμιος, ο υπηρέτης του παππού, και με γύρευε. Ο παππούς ήτανε, λέει, άρρωστος βαριά και ζητούσε να με δει. [...]\n- Ήρθες, ψυχή μου; φώναξε ο παππούς μόλις με είδε.\nΟ παππούλης μου ήταν καλά! Η χαρά μου δε λεγόταν! Αγκαλιαστήκαμε και φιληθήκαμε ώρα πολλή, κι εγώ άρχισα να του λέω για την Πόλη και για τα καλά της, για τα καράβια που έπλεαν στον Βόσπορο, για την Προποντίδα και την Αγια-Σοφιά.\nΕκείνος όμως με έκοψε και μου είπε:\n- Άσ' τα αυτά! Πέρασες απ’ τη χώρα που ψήνει ο ήλιος το ψωμί; Και είδες τους Σκυλοκέφαλους;\n- Όχι, παππού, δεν τους είδα. [...]\n- Πέρασες, τότε, απ' της θάλασσας τον αφαλό, εκεί που το νερό γυρίζει γύρω-γύρω και καταπίνει τα καράβια;\n- Όχι παππού, δεν πέρασα.\n- Ωχ, ψυχή μου! Δεν είδες τίποτε λοιπόν! [...]\n- Να δεις, παππού, τι μεγάλη που είναι η Πόλη! Και τι πολλοί άνθρωποι που είναι εκεί και...\n- Άσ' τα αυτά! με διέκοψε ο παππούς. Είδες τον τόπο που είναι οι άνθρωποι οι μαρμαρωμένοι;\n- Όχι, παππού! Δεν τον είδα!\n- Αχ, ψυχή μου! Τίποτα δεν είδες στη ζωή σου, τίποτα!\nΕγώ τον άκουγα και στεναχωριόμουν που δεν ήθελε να με ακούσει κι όλο έλεγε και μου ξανάλεγε: «Άσ' τα αυτά, άσ' τα αυτά!». Όμως καμάρωνα κιόλας, που είχα έναν παππού τόσο ταξιδεμένο.\n- Πολλά ταξίδια θα έκανες στη ζωή σου, παππού! του είπα.\n- Ποιος, εγώ; είπε ξαφνιασμένος ο παππούς, που δεν περίμενε την ερώτηση. Εγώ όχι, ψυχή μου, συνέχισε μετά, η γιαγιά σου, η Χρουσή, αυτή έκανε τα ταξίδια! [...]\n- Και στη χώρα που ψήνει ο ήλιος το ψωμί, πότε πήγες, παππού; τον ρώτησα εγώ, απογοητευμένος.\n- Ω! είπε τότε εκείνος. Αυτού, ψυχή μου, δεν επήγα, με τ’ αφηγήθηκε η γιαγιά μου, όταν ήμουνα μικρός.\n- Και στη Γοργόνα, την αδελφή του Μεγαλέξαντρου, και στη χώρα των Σκυλοκέφαλων, ούτε κι εκεί επήγες;\n- Όχι, ψυχή μου! Δεν τους είδα τους Σκυλοκέφαλους. Η γιαγιά μου με τ’ αφηγήθηκε, η γιαγιά μου.\n- Κι οι βασιλοπούλες, παππού; Αυτές που ερωτεύονται τα ραφτόπουλα κι από τον έρωτά τους αρρωσταίνουν, και τρέχει ο μπαμπάς τους ο βασιλιάς και τα παρακαλεί;\n- Αχ, ψυχή μου! κι αυτό η γιαγιά μου με τ’ αφηγήθηκε. Μα θαρρώ πως μήτε κείνη το είδε με τα μάτια της!","word_count":383,"page_number":12,"chapter":"Ήτανε μια φορά"},{"id":"g_dimotikou_g_0003","source_id":"g_dimotikou_g","title":"Μια αληθινή ιστορία","content":"Επειδή είχα βαρεθεί όλο τα ίδια και τα ίδια, ναύλωσα μια μέρα ένα καλό καράβι και βγήκα στο πέλαγο να γνωρίσω τον κόσμο. Για πλήρωμα πήρα νέους διαλεχτούς, στην ηλικία μου, και καπετάνιο βρήκα τον καλύτερο, αφού, δίχως να κάνω τσιγκουνιές, του έταξα τον μισθό που μου ζήτησε.\nΞάφνου, κατά το μεσημεράκι, σηκώθηκε τυφώνας δυνατός, που μας πήρε και μας σήκωσε με όλο το καράβι ψηλά, στον αέρα. Με φουσκωμένα τα πανιά αεροδρομούσαμε εφτά μερόνυχτα, ταξίδι δύσκολο για πλοίο, αλλά ευτυχώς ο καπετάνιος άξιζε τον μισθό του και με το παραπάνω. Έτσι, την όγδοη μέρα αράξαμε στο φεγγάρι, που ήταν ένα λαμπερό νησί στον αέρα. Μόλις νύχτωσε, είδαμε αμέτρητα άλλα νησάκια σκορπισμένα εδώ κι εκεί. Ένα από αυτά είχε πάνω του δάση και πολιτείες και θάλασσες απέραντες. Κάποιος είπε ότι ήταν η γη που κατοικούσαμε, πράγμα που μας έκανε μεγάλη εντύπωση. Αντί όμως να φοβηθούμε, αποφασίσαμε να προχωρήσουμε πιο πέρα.\nΔεν προφτάσαμε ωστόσο να πάμε μακριά, γιατί μας σταμάτησαν οι Ιππόγυποι και μας οδήγησαν στον βασιλιά τους τον Ενδυμίωνα. Οι Ιππόγυποι ήταν τεράστιοι γύπες που τους οδηγούσαν άντρες. Δουλειά τους ήταν να προστατεύουν το φεγγάρι από ανεπιθύμητους επισκέπτες.\n- Μήπως είστε Έλληνες; μας ρώτησε ο Ενδυμίωνας μόλις μας είδε.\n- Ναι.\n- Και πώς καταφέρατε να περάσετε όλο τον αέρα και να φτάσετε ίσαμε δω;\nΕμείς του τα είπαμε όλα χαρτί και καλαμάρι και τότε εκείνος μας διηγήθηκε τα δικά του.\n- Κατοικούσα κι εγώ σαν άνθρωπος στη γη, ώσπου μια μέρα με πήρε ένας αέρας και με σήκωσε και μ' έφερε εδώ πέρα. Μην έχοντας σε τούτο το μέρος τι άλλο να κάνω, αποφάσισα να γίνω βασιλιάς.\nΏρες πολλές καθίσαμε παρέα με τον Ενδυμίωνα και τα λέγαμε, για τη ζωή στο φεγγάρι και για όλα τα παράξενα κι αλλόκοτα πλάσματα που ζούσαν σε κείνο το μέρος. Εκείνος, χαρούμενος που βρήκε ελληνική παρέα στο φεγγάρι, μας μιλούσε με ευχαρίστηση για πράγματα που, αν δεν τα δει κανείς με τα ίδια του τα μάτια, δύσκολα τα πιστεύει.","word_count":326,"page_number":16,"chapter":"Ήτανε μια φορά"},{"id":"g_dimotikou_g_0004","source_id":"g_dimotikou_g","title":"Στο νησί του Αιόλου","content":"Την επόμενη μέρα κινήσαμε και πάλι για το πολύπαθο ταξίδι μας. Αυτή τη φορά στον δρόμο μας συναντήσαμε το νησί του Αιόλου. Σ’ αυτόν είχαν αναθέσει οι θεοί να φυλά τους ανέμους. Ο Αίολος μας φιλοξένησε κοντά του έναν ολόκληρο μήνα, μ' όλες τις τιμές. Όλον αυτόν τον καιρό το παλάτι του αντηχούσε από τραγούδια, γέλια και χορούς. Και εγώ για ατέλειωτες ώρες τις νύχτες τού ιστορούσα τις περιπέτειες που είχαμε περάσει στον πόλεμο της Τροίας και μετά.\nΌταν έφτασε πια ο καιρός για να φύγουμε, αφού μας ετοίμασε με στοργή όλες τις λεπτομέρειες του ταξιδιού, στο τέλος μού έδωσε ένα ασκί δεμένο πολύ σφιχτά και μου είπε: «Πρόσεξε καλά, Οδυσσέα! Κανείς, μα κανείς, δεν πρέπει να λύσει αυτό το ασκί, γιατί εδώ μέσα έχω φυλακίσει την οργή όλων των δυνατών ανέμων. Το ασκί, λοιπόν, θα το φυλάς σαν τα μάτια σου. Σαν τα μάτια σου και ακόμα καλύτερα...», και μ' αυτές τις κουβέντες μάς αποχαιρέτησε...\nΑυτή τη φορά παρέα με τον Ζέφυρο κάναμε ένα ευτυχισμένο ταξίδι. Εννιά μέρες αρμενίζαμε σε μια καταγάλανη θάλασσα, που τα κύματά της παιχνίδιζαν και χρύσιζαν κάτω από έναν γελαστό ήλιο. Τη δέκατη με χτυποκάρδι ανακάλυψα πως άρχισαν να φαίνονται σκοτεινοί όγκοι απ' τα βουνά της Ιθάκης και ανέβαιναν ψηλά καπνοί από τα τζάκια των σπιτιών της πατρίδας μου. Σ’ αυτή τη χαρά που δεν περιγράφεται με λόγια χαλάρωσα τόσο απ' την κούραση και την αγωνία του ταξιδιού, ώστε ούτε κατάλαβα πότε αποκοιμήθηκα. Αμέσως οι σύντροφοί μου, που όλες αυτές τις μέρες τους κατάτρωγε η περιέργεια για το τι περιείχε το ασκί, νομίζοντας πως είχε χρυσάφι που θα το ’παιρνα μόνο εγώ, το έλυσαν γρήγορα γρήγορα και έσκυψαν πάνω του.\nΤότε ουρλιάζοντας ανατριχιαστικά ξεχύθηκαν αμέσως όλα τα στοιχεία της φύσης και τους χτύπησαν καταπρόσωπο. Εγώ ξύπνησα αλαφιασμένος* από τους κεραυνούς, που έπεφταν στο μεταξύ κοπαδιαστά με τρομαχτικό κρότο, και τον σάλο που ξεσήκωναν τα κύματα καθώς χτύπαγαν με λύσσα το πλοίο μας. Για δευτερόλεπτα νόμιζα πως έχανα τα λογικά μου στο μέγεθος της αποκοτιάς* τους. Όμως, θέλοντας και μη, βάλθηκα στο τέλος να παλεύω μ' όλη αυτή την αντάρα*, που είχε ξεσπάσει εξαιτίας τους.\nΚάποτε βρεγμένοι ως το κόκαλο και τσακισμένοι από κούραση βγήκαμε και πάλι στο νησί του Αιόλου. Αλλά αυτή τη φορά μας έδιωξε οργισμένος. Μπήκαμε στα καράβια με τσακισμένο ηθικό και αρμενίσαμε χαμένοι απ' τον προσανατολισμό μας δέκα μέρες και δέκα νύχτες.","word_count":390,"page_number":20,"chapter":"Ήτανε μια φορά"},{"id":"g_dimotikou_g_0005","source_id":"g_dimotikou_g","title":"Γεια σου χαρά σου Βενετιά","content":"Γεια σου χαρά σου Βενετιά\nπήρα τους δρόμους του νοτιά\nκι απ' το κατάρτι το ψηλό\nτον άνεμο παρακαλώ.\n\nΦύσα αεράκι φύσα με\nμη χαμηλώνεις ίσαμε\nνα δω γαλάζια εκκλησιά\nΤσιρίγο και Μονεμβασιά.\n\nΓεια σου χαρά σου Βενετιά\nβγήκα σε θάλασσα πλατιά\nκαι τραγουδώ στην κουπαστή\nσ’ όλον τον κόσμο ν' ακουστεί.\n\nΦύσα αεράκι φύσα με\nμη χαμηλώνεις ίσαμε\nνα δω στην Κρήτη μια κορφή\nπόχω* μανούλα κι αδελφή.","word_count":69,"page_number":24,"chapter":"Ήτανε μια φορά"},{"id":"g_dimotikou_g_0006","source_id":"g_dimotikou_g","title":"Το πιο γλυκό ψωμί","content":"Κάποτε ήταν ένας πλούσιος βασιλιάς, πολύ πλούσιος, που ό,τι επιθυμούσε η καρδιά του το ’χε. Όλα τα είχε, και τον έλεγαν ευτυχισμένο, ώσπου έπαθε μια παράξενη ανορεξία και δεν είχε όρεξη να βάλει τίποτα στο στόμα του. Σιγά σιγά αδυνάτιζε κι άρχισε να γίνεται γκρινιάρης και παράξενος. Πολλοί γιατροί επήγαιναν και τον έβλεπαν, μα τα γιατρικά τους τίποτα δεν μπορούσαν να του κάμουν. Η ανορεξιά του βασιλιά όλο και κρατούσε, κι εκείνος αδυνάτιζε μέρα με την ημέρα. Τίποτα δε λαχταρούσε να φάει. ούτε «του πουλιού το γάλα», που λέει ο λόγος.\nΌπου κάποια μέρα έτυχε να περνάει από το παλάτι του ένας ασπρομάλλης γέροντας φτωχός, που ήτανε όμως σοφός κι ήξερε από γιατρικά. Του είπανε λοιπόν για τον βασιλιά, κι ανέβηκε να τον δει.\n- Μήπως κουράζεσαι, βασιλιά μου; τον ρώτησε.\n- Τι λες, γιατρέ μου, του λέει ο βασιλιάς· όλη μέρα ξαπλωμένος απάνου στον θρόνο μου, ούτε το μικρό μου δαχτυλάκι δεν κουνώ.\n- Μήπως έχεις έγνοιες και σκοτούρες για τον λαό σου;\n- Όχι, κάθε άλλο. Εγώ ζω ξέγνοιαστος και καρφάκι δε μου καίγεται για κανέναν!\n- Μήπως επιθύμησες ποτέ σου κάτι και δεν μπόρεσες να το ’χεις;\n- Ούτε κι αυτό! Βασιλιάς είμαι κι ό,τι γυρέψω το βλέπω μπροστά μου!...\nΣκέφτηκε, σκέφτηκε λίγο ο γέροντας, ύστερα γυρίζει και λέει του βασιλιά: «Άκουσε, βασιλιά μου. Καθώς βλέπω, δεν έχεις τίποτα σοβαρό. Εκείνο που φταίει και δεν έχεις όρεξη να τρως είναι το ψωμί που σου δίνουν στο παλάτι! Να διατάξεις να σου φέρουν να φας το πιο γλυκό ψωμί του κόσμου. Αν μπορέσεις να το ’χεις αυτό, τότε θα γιατρευτείς!»\nΑπό την ίδια μέρα ο βασιλιάς έδωσε διαταγή στους φουρναραίους του παλατιού να ζυμώσουν και να του ψήσουν «το πιο γλυκό ψωμί του κόσμου!» Έπεσαν με τα μούτρα στη δουλειά οι ψωμάδες σ' όλο το βασίλειο, ποιος θα κάμει στον βασιλιά το γλυκό ψωμί! Ζύμωσαν με ζάχαρη κι ανθόγαλα κάθε λογής ψωμιά και του τα ’φερναν στο παλάτι να τα δοκιμάσει. Ούτε κι ήθελε να τα φάει. Το ’να του μύριζε, τ’ άλλο του βρομούσε. Ώσπου μια μέρα, έξω φρενών ο βασιλιάς, έστειλε ανθρώπους του να πάνε να βρούνε τον γέροντα και να τον ξαναφέρουνε μπροστά του. Έτσι λοιπόν κι έγινε.\n- Θα σε κρεμάσω που με ξεγέλασες! του φώναξε ο βασιλιάς μόλις τον είδε.\n- Γιατί, βασιλιά μου; τον ρώτησε ο γέροντας.\n- Γιατί το ψωμί που είπες να μου φτιάξουνε να φάω δε μου έκανε τίποτα!\n- Μπα; έκαμε ο γέροντας, φαίνεται πως το ψωμί που σου ζύμωσαν, δεν ήταν τόσο γλυκό όσο έπρεπε! Ο βασιλιάς ήταν πάλι έτοιμος ν' αγριέψει, μα είδε τον γέρο που κάτι συλλογιζότανε, και περίμενε.\n- Άκουσε, βασιλιά μου, του λέει ο γέροντας ύστερ’ από λίγο. Αν θέλεις να δοκιμάσεις στ’ αληθινά το ψωμί που θα σε γιατρέψει, πρέπει να ’ρθεις μαζί μου για τρεις μέρες μονάχα και να κάνεις ό,τι σου λέω. Αν δε γίνεις καλά, είσαι ελεύτερος να μου πάρεις το κεφάλι!\nΚι ο βασιλιάς, παιδί μου, θέλοντας και μη, δέχτηκε να πάει μαζί με τον παράξενο γέροντα εκεί που του ’λεγε.","word_count":503,"page_number":29,"chapter":"Ήτανε μια φορά"},{"id":"g_dimotikou_g_0007","source_id":"g_dimotikou_g","title":"Το πιο γλυκό ψωμί (συνέχεια)","content":"Φόρεσε ο βασιλιάς φτωχικά ρούχα και παλιοπάπουτσα, πήρε κι ένα μπαστούνι στα χέρια του κι έφυγε κρυφά από το παλάτι, μακριά, κι επήγανε στον κάμπο, εκεί που καθόταν ο γέροντας, σε μια καλύβα, μέσα σ’ ένα χωράφι σπαρμένο.\nΞημερώνοντας, έδωκε ο γέροντας στον βασιλιά ένα δρεπάνι και του λέει: «Έλα να θερίσουμε!». Έπιασε ο βασιλιάς και θέριζε μες στο λιοπύρι ολάκερη μέρα. Έκαμε καμιά σαρανταριά δεμάτια στάχυα. Ήρθε το βράδυ, πέσανε ξεροί να κοιμηθούνε. Ούτε φαΐ όλη μέρα ούτε τίποτα. Έμενε, βλέπεις, κι ο γέροντας νηστικός.\nΤην άλλη μέρα, πρωί πρωί, ξύπνησε ο γέροντας τον βασιλιά και του λέει: «Σήκω τώρα να πάρουμε όλ' αυτά τα δεμάτια, να πάμε στ’ αλώνι να τ’ αλωνίσουμε!». Κουβάλησε στην πλάτη του ο βασιλιάς περισσότερ’ από τα μισά, κι ύστερα όλη μέρα, γκαπ γκουπ, τα κοπάνιζε με τον δάρτη*, ώσπου κάμανε το στάρι σωρό, τ’ ανεμίσανε και το βάλανε στο σακί. Κι όλη μέρα την περάσανε πάλε έτσι, νηστικοί κι οι δυο τους, μόνο λίγο νερό ήπιανε από τη στέρνα, που ήτανε κοντά στην καλύβα. Πέσανε πάλι κουρασμένοι το βράδυ και κοιμηθήκανε.\nΤην τρίτη μέρα, το χάραμα, ο γέροντας σήκωσε τον βασιλιά: «Ξύπνα» του λέει «τώρα, να πάμε το στάρι μας στον μύλο να τ’ αλέσουμε! Πάρ’ το εσύ στην πλάτη σου, γιατί εγώ δεν μπορώ, και πάμε εκεί στην κορφή του βουνού, που ’ναι ο μύλος». Τι να κάμει ο βασιλιάς, αφού έτσι ήτανε η συμφωνία, φορτώνεται το σακί στην πλάτη, και κουρασμένος κι ελεεινός το κουβάλησε στην κορυφή. Τώρα αρχίνησε και να πεινάει, μα δεν έλεγε ακόμα τίποτα.\nΑλέσανε το στάρι τους και, για να μην τα πολυλογούμε, γυρίσανε κατά το μεσημέρι στην καλύβα, πάλι ο βασιλιάς φορτωμένος τ’ αλεύρι. «Έλα τώρα να ζυμώσουμε» του λέει ο γέρος. Ξεχώρισε ως δέκα λίτρες αλεύρι, το ’ριξε στη σκάφη κι έβαλε τον βασιλιά να ζυμώνει. Ύστερα τον έστειλε στον λόγγο να κόψει ξύλα, κι αργά κατά το βράδυ βάλανε κι εκάψανε τον φούρνο, για να ψήσουνε τρία τέσσερα καρβέλια. Ο βασιλιάς τώρα πεινούσε κι επερίμενε πότε να ψηθούν τα ψωμιά για να φάει! Μα πιο πολύ τα λιμπιζόταν* όταν άρχισε να βγαίνει από τον φούρνο η μυρωδιά τους. «Πεινάω πολύ» λέει του γέρου. «Περίμενε και θα φας!» του απάντησε εκείνος.\nΣε λίγο βγήκανε τα καρβέλια, αχνιστά και ροδοψημένα. Σαν πεινασμένος λύκος τότε ο βασιλιάς άρπαξε το καρβέλι, το έκοψε με τα χέρια του κι άρχισε να τρώει.\nΜα με την πρώτη μπουκιά που κατάπιε, το πρόσωπό του έγινε κόκκινο από χαρά και φώναξε: «Μάλιστα! Αυτό είναι το πιο γλυκό ψωμί του κόσμου! Κι όμως ούτε μια κουταλιά ζάχαρη δεν έριξα στο ζυμάρι του!». Τότε ο γέροντας χαμογέλασε και του είπε: «Βασιλιά μου, πρέπει να ξέρεις πως η ζάχαρη του ψωμιού σου ήταν ο ίδρωτας που έχυσες για να το φτιάξεις. Τώρα είσ’ ελεύτερος να ξαναπάς στο παλάτι σου. Κοίτα μονάχα να δουλεύεις αποδώ κι εμπρός και θα δεις πως η όρεξη δε θα σου λείψει».\nΟ βασιλιάς ακολούθησε την ορμήνια* του γέροντα. Όταν γύρισε στο παλάτι του, δούλευε κάθε μέρα για τον λαό του. Εκατέβαινε και στον κήπο του γι' άλλες δουλειές, κι από τότε γιατρεύτηκε από την ανορεξιά κι έτρωε καλά. Μακάρι να τρώγαμε κι εμείς έτσι!","word_count":524,"page_number":33,"chapter":"Του κόσμου το ψωμί"},{"id":"g_dimotikou_g_0008","source_id":"g_dimotikou_g","title":"Ψωμί","content":"Καλόδεχτο το φόρτωμα που θα ’ρθει από τον μύλο,\nπρωτόσταλτο, πρωτάλεστο, πρώτη χαρά της σκάφης.\n\nΖυμώνουν τ’ ανασκουμπωτά της πρωτονύφης χέρια\nκαι πλάθουν τα πρωτόπλαστα ψωμιά με τις παλάμες\nμες στην καλοπελεκητή πινακωτή* -προικιό της.\nΤον φούρνο καίει τεχνίτισσα στον φούρνο η γριά κυρούλα,\nξανανιωμένη, αφήνοντας τη συντροφιά της ρόκας*.\n\nΩ, βραδινό συμμάζεμα στο σπιτικό κατώφλι,\nκαρτέρεμα ανυπόμονο του πυρωμένου φούρνου!\nΚι ω, μέθυσμα απ' τη μυρωδιά πρώτου ψωμιού, που αχνίζει\nκομμένο από τον γέροντα παππού, χωρίς μαχαίρι,\nκαι μοιρασμένο στα παιδιά, στις νύφες και στ’ αγγόνια!\n\nΚαι συ, θυσία των ταπεινών στη Θεία την καλοσύνη,\nσημαδεμένο ανάμεσα με του σταυρού τη βούλα,\nκαλοπλασμένο πρόσφορο, της Εκκλησιάς μεράδι*,\nπου θα κοπείς την Κυριακή μες στ’ αργυρό αρτοφόρι\nκαι στ’ άγιο δισκοπότηρο με το κρασί θα σμίξεις!","word_count":126,"page_number":38,"chapter":"Του κόσμου το ψωμί"},{"id":"g_dimotikou_g_0009","source_id":"g_dimotikou_g","title":"Καλή όρεξη!","content":"«Φάε την μπουκιά σου, μην αφήνεις τη δύναμή σου!»\nμας λένε οι δικοί μας, όταν αφήνουμε ένα κομμάτι ψωμί\nστο τραπέζι. Και δεν έχουν άδικο!\nΤο ψωμί είναι μια από τις βασικές τροφές που δίνει δύναμη\nστο κορμί και στο μυαλό μας.\n\nΟι παππούδες και οι γιαγιάδες μας,\nόταν ήταν μικροί, μπορεί να μη γνώριζαν την πυραμίδα της διατροφής, έτρωγαν όμως σύμφωνα με αυτήν.\nΚατανάλωναν καθημερινά τις τροφές\nπου βρίσκονται στη βάση της πυραμίδας, δηλαδή ψωμί, ζυμαρικά, όσπρια,\nγαλακτοκομικά, λαχανικά και φρούτα.\nΧρησιμοποιούσαν ελαιόλαδο στο μαγείρεμα. Οι τροφές αυτές μας χορταίνουν\nκαι μας δυναμώνουν.\nΜερικές φορές την εβδομάδα έτρωγαν\nψάρια, πουλερικά, αυγά και κρέας,\nτροφές χρήσιμες και υγιεινές.\nΠιο αραιά κατανάλωναν\nγλυκίσματα ή αναψυκτικά, τα\nοποία σε μεγάλες ποσότητες\nμπορεί να προκαλέσουν\nπαχυσαρκία και προβλήματα υγείας.\n\nΛίγες φορές\nτο μήνα\n\nΜερικές φορές\nτην εβδομάδα\n\nΚαθημερινά\nΟι παγίδες της διατροφής μας!","word_count":140,"page_number":41,"chapter":"Του κόσμου το ψωμί"},{"id":"g_dimotikou_g_0010","source_id":"g_dimotikou_g","title":"Ο Καραγκιόζης φούρναρης","content":"(Μουσική. Χορός του Καραγκιόζη με τα παιδιά του.)\n\nΚΑΡΑΓΚΙΟΖΗΣ: Αα! Αυτό θα πει χορός! Ξεποδαριάστηκα. Αξιότιμοι κύριοι, κυρίες και παιδιά, η\nπαράστασή μας θα είναι ο Καραγκιόζης φούρναρης. Καθίστε, θα ξεποδαριαστούμε στο\nγλέντι. Κολλητήρη, δώσε μου γρήγορα τη σκούφια του φούρναρη.\nΚΟΛΛΗΤΗΡΗΣ: Την έχει η μαμά και γεννάει η κότα.\nΚΑΡΑΓΚΙΟΖΗΣ: Κοτοφωλιά την κάνατε, μωρέ; Φέρε και την ποδιά.\nΚΟΛΛΗΤΗΡΗΣ: Το νυχτικό της γιαγιάς;\nΚΑΡΑΓΚΙΟΖΗΣ: Μωρέ άντε και θα πλακώσει πελατεία και έχω ανάψει και τον φούρνο. Να,\nέρχεται κι ο Χατζατζάρης. (Μουσική).\nΧΑΤΖΗΑΒΑΤΗΣ: Αα! Άναψε τον φούρνο ο Καραγκιόζης. Μα δεν είναι εδώ. Πάει σπίτι του.\n(Χτυπά την πόρτα.) Καραγκιόζη! Βρεε!\n\nΧΑΤΖΗΑΒΑΤΗΣ: Έλα παιδάκι μου, τι κάνεις μες στην παράγκα;\nΚΑΡΑΓΚΙΟΖΗΣ: Παίζω ποδόσφαιρο με τους ποντικούς στο ταβάνι. Τι φωνάζεις, μωρέ;\nΧΑΤΖΗΑΒΑΤΗΣ: Καλώς τον. Μα δεν είναι και σπίτι αυτό που κάθεσαι, ματάκια μου. Ούτε\nπόρτες έχει ούτε και παραθύρια.\n\nλουμε να καθόμαστε σε\nκλίμα ευάερο.\n\nέτοιμο να πέσει και να σε\nπλακώσει. Το κυριότερο,\nδεν έχει ούτε κεραμίδια.\nΉθελα να ήξερα τι κάνετε\nόταν πιάνει βροχή.\nΚΑΡΑΓΚΙΟΖΗΣ: Ε, όταν πιάνει\nβροχή βγαίνουμε όλοι\nέξω για να μη βραχούμε.\nΧΑΤΖΗΑΒΑΤΗΣ: Χα, χα, χα,\nχα, χα!\n\nΚΑΡΑΓΚΙΟΖΗΣ: (Του δίνει μια ξυλιά.) Να! Να μη γελάς, μαλαγάνα*.\nΧΑΤΖΗΑΒΑΤΗΣ: Ποπό! και μου ’σπασες τα δόντια.\nΚΑΡΑΓΚΙΟΖΗΣ: Εκεί είναι η τζαμαρία. Πήγαινε, μωρέ, να φέρεις κόσμο κι\nεγώ να ετοιμάζω τα φουρνόξυλα και τις πινακωτές.\nΧΑΤΖΗΑΒΑΤΗΣ: Γεια σου, Καραγκιόζη, και καλές δουλειές.\nΚΑΡΑΓΚΙΟΖΗΣ: Γεια σου και καλές ξυλιές. Και πάρε την πρώτη φουρνοξυλιά. Άντε! (Του δίνει μία.)\nΧΑΤΖΗΑΒΑΤΗΣ: Αχ! Τρομάρα μου!\nΚΑΡΑΓΚΙΟΖΗΣ: Ωραία! Ο φούρνος άναψε. Έκαψε. Είναι έτοιμος να ρίξω\nμέσα τα πρωινά ψητά: του θείου μου το αρνί. Αυτό θα το φάω πρώτο.\nΑυτό είναι του Μορφονιού το ψάρι. Τούτο είναι του Νιόνιου που\nχύθηκαν οι κολοκυθοπατάτες που τις έλεγε κομιντόρα. Χα, χα, χα! Α, και του Σταύρακα οι\nντομάτες. Να, κι άλλος έρχεται. Άλλος στον καλό τον φούρναρη εδώ! (Μουσική)\nΜΠΕΗΣ: Καλημέρα φούρναρη! Σου έφερα ένα ψητό εξαίρετο.\nΚΑΡΑΓΚΙΟΖΗΣ: Για να το δω ... Τι είναι αυτό;\nΜΠΕΗΣ: Χήνα παραγεμισμένη με κουκουνάρια και διάφορα μπαχαρικά.\nΚΑΡΑΓΚΙΟΖΗΣ: Ε, ρε μανούλα μου! (Τη μυρίζει.) Ααα! Μυρουδιά που την έχει!\nΜΠΕΗΣ: Αυτό το φαŻ το τρώνε μόνο αγάδες σαν κι αυτούς που έχω καλεσμένους σήμερα στο\nσπίτι μου.\nΚΑΡΑΓΚΙΟΖΗΣ: Μπα, θα φάνε αυγουλάδες; Μωρέ, άσ’ το και θα το περιποιηθώ εγώ.\nΜΠΕΗΣ: Μην την κάψεις φούρναρη. Μόνο ροδοκοκκίνισμα να της κάνεις. Το μεσημέρι θα\nέρθω να την πάρω στις δώδεκα. Αντίο.\nΚΑΡΑΓΚΙΟΖΗΣ: Μωρέ, όλα τα ψητά θα τα φάω όχι τα δύο. Άλλος στον καλό τον φούρναρη εδώ!\nΌποιος ψήσει σήμερα δε θα ξεψήσει.","word_count":421,"page_number":45,"chapter":"Του κόσμου το ψωμί"},{"id":"g_dimotikou_g_0011","source_id":"g_dimotikou_g","title":"Βοηθάμε να γίνει καλύτερος ο κόσμος μας","content":"Κάθε φορά που γίνεται πόλεμος, συμβαίνει κάποια φυσική καταστροφή ή ξεσπούν επιδημίες, οργανώσεις και εθελοντές από όλο τον κόσμο είναι έτοιμοι να βοηθήσουν όσους έχουν ανάγκη.\nΗ UNICEF (Γιούνισεφ) ιδρύθηκε το 1946 από τον Οργανισμό Ηνωμένων Εθνών (Ο.Η.Ε.) για να προστατεύσει τα παιδιά όλου του κόσμου. Η UNICEF βοηθάει προσφέροντας φάρμακα, εμβόλια, τρόφιμα και καθαρό νερό αλλά και τετράδια, μολύβια και βιβλία.\nΜετά τον Β΄ παγκόσμιο πόλεμο (1940-1945), η UNICEF προσέφερε σημαντική βοήθεια για να κάνει καλύτερη τη ζωή των παιδιών της κατεστραμμένης τότε χώρας μας.\nΣήμερα χιλιάδες Έλληνες και πολλά σχολεία ενισχύουν και υποστηρίζουν το έργο της\nΟι μαθητές της Γ΄ τάξης του Δημοτικού Σχολείου Δρεπάνου Κοζάνης παρουσιάζουν το αναμνηστικό δίπλωμα που τους έστειλε η UNICEF για τη συμμετοχή τους στο πρόγραμμα «ΣΧΟΛΕΙΑ ΥΠΕΡΑΣΠΙΣΤΕΣ ΤΩΝ ΠΑΙΔΙΩΝ».\nΗ ActionAid (Άκσιον Έιντ) είναι μια διεθνής εθελοντική οργάνωση που ιδρύθηκε το 1972 με σκοπό να στηρίξει φτωχές οικογένειες σε πάνω από 40 χώρες του κόσμου. Από το 1998 η οργάνωση δραστηριοποιείται και στη χώρα μας.\nΤο σχολείο μας, θέλοντας να βοηθήσει στην προσπάθεια της ActionAid για ένα καλύτερο μέλλον για τα παιδιά όλου του κόσμου, αποφάσισε να γίνει ανάδοχος ενός αγοριού, του μικρού Γιακόλα, από το χωριό Γιαμπέλο της Αιθιοπίας. Τα περισσότερα παιδιά της περιοχής δεν πηγαίνουν σχολείο, επειδή αυτό βρίσκεται μακριά και γιατί εργάζονται στα χωράφια για να βοηθήσουν την οικογένειά τους. Η περιοχή έχει πρόβλημα νερού και δεν υπάρχει ιατρική περίθαλψη για τους κατοίκους.\nΩς ανάδοχοι του παιδιού θα έχουμε επικοινωνία μαζί του (με επιστολές, κάρτες ή ζωγραφιές) και θα ενημερωνόμαστε για τα προγράμματα που εφαρμόζονται στην περιοχή, ώστε να βελτιωθεί η ζωή των κατοίκων. Υποχρέωσή μας είναι να προσφέρουμε ένα ποσό κάθε μήνα που θα συγκεντρώνεται από τις δραστηριότητες του σχολείου (κυλικείο, πώληση εφημερίδων) και από τις εθελοντικές εισφορές των μαθητών.","word_count":292,"page_number":54,"chapter":"Όλοι μια αγκαλιά"},{"id":"g_dimotikou_g_0012","source_id":"g_dimotikou_g","title":"Η πτήση των γερανών","content":"Σ’ ευχαριστώ που με επισκέφτηκες και μου έφερες αυτό το υπέροχο χαρτί. Μακάρι να μπορούσα να φτιάξω γρηγορότερα τους γερανούς, αλλά είμαι τόσο κουρασμένη αυτές τις μέρες που μου είναι πολύ δύσκολο να τους δώσω σχήμα. Η τέχνη του οριγκάμι -η γιαπωνέζικη τέχνη τυλίγματος χαρτιών- είναι αρχαία. Τυλίγοντας χαρτιά, μπορείς να φτιάξεις όλων των ειδών τα σχήματα, όπως βατράχους και δράκους και πουλιά. Ο γερανός είναι ιερός στην πατρίδα μου και μεταφέρει τις επιθυμίες μας στο ουράνιο βασίλειο.\nΤώρα φτιάχνω τη δεύτερη σειρά από χίλιους γερανούς και εύχομαι να πραγματοποιηθεί η επιθυμία μου. Υπάρχει μια παράδοση στην Ιαπωνία: αν ένας άρρωστος τυλίξει χίλιους γερανούς κι ευχηθεί να γίνει καλά, τότε θα πραγματοποιηθεί η ευχή του. Η μητέρα μου έκανε μια ευχή για μένα και για την άλλη κοπέλα, την Κίγιο, όταν μας έβαλαν μαζί σ’ αυτόν τον θάλαμο του νοσοκομείου. Ύστερα κάποια κορίτσια από το γυμνάσιο έστειλαν αμέτρητους γερανούς σε όσους από εμάς πάσχουμε από ασθένειες που προέρχονται από την ατομική βόμβα. Εγώ έλαβα μία σειρά, όχι όμως και η Κίγιο. Έτσι, αποφασίσαμε να φτιάξουμε χίλιους γερανούς μαζί μήπως πραγματοποιηθεί η επιθυμία μας και γίνουμε καλά κι οι δυο μας. Η ευχή της Κίγιο πραγματοποιείται, η δική μου όμως όχι\n- κι έτσι προσπαθώ ξανά. Έχω αντέξει περισσότερο απ' ό,τι θα περίμενε κανείς. Ίσως λοιπόν αυτή τη φορά...\nΈχω φτιάξει πάνω από εξακόσιους μέχρι τώρα και για λίγο έγινα καλύτερα. Αλλά τώρα, δεν ξέρω...\nΣαντάκο Σασάκι, Χιροσίμα Στις 5 Οκτωβρίου 1955, η δωδεκάχρονη Σαντάκο έπεσε για ύπνο και δεν ξύπνησε ποτέ ξανά. Είχε ολοκληρώσει 644 γερανούς. Οι συμμαθητές της δούλεψαν όλοι μαζί για να φτιάξουν 356 γερανούς ακόμα, έτσι ώστε η φίλη τους να μπορέσει να θαφτεί με χίλιους γερανούς τριγύρω της.\nΝέοι άνθρωποι απ' όλη την Ιαπωνία μάζεψαν αρκετά χρήματα για να φτιάξουν ένα άγαλμα της Σαντάκο. Τα αποκαλυπτήρια έγιναν το 1958 στο Πάρκο της Ειρήνης, στη Χιροσίμα. Το άγαλμα δείχνει ένα κορίτσι που στέκεται πάνω σε μια γρανιτένια βάση που έχει το σχήμα ενός βουνού του παραδείσου. Τα χέρια της είναι ανασηκωμένα ψηλά κρατώντας έναν τεράστιο χρυσό γερανό. Για να διαδώσουν την επιθυμία της Σαντάκο για παγκόσμια ειρήνη, παιδιά από όλο τον κόσμο στέλνουν κάθε χρόνο χιλιάδες χάρτινους γερανούς, που τοποθετούνται στη βάση του αγάλματος. Χαραγμένη εκεί είναι η επιθυμία που μοιράζονται όλα αυτά τα παιδιά:\n«Αυτή είναι η φωνή μας, αυτή είναι η προσευχή μας, ειρήνη στον κόσμο».","word_count":391,"page_number":57,"chapter":"Όλοι μια αγκαλιά"},{"id":"g_dimotikou_g_0013","source_id":"g_dimotikou_g","title":"Ο Μάης με τα στεφάνια","content":"Φέτος τον είδα να έρχεται μ' ένα μόνιππο* στολισμένο με τριαντάφυλλα. Αυτός πατούσε σε μια πολύχρωμη κουρελού από μαργαρίτες, βιολέτες και κρινάκια του αγρού. Ήταν κεφάτος και τραγουδούσε:\nΜοσχοβολά η αγράμπελη, το πρίνο σπαρταρίζει κρυμμένο μέσα στα κλαδιά το λέει γλυκά τ' αηδόνι.\nΣτο καπέλο του ανέμιζαν παπαρούνες και από τη ζώνη του κρέμονταν κατακόκκινα κεράσια.\n- Γεια σου, Κερασάρη! του φώναξε ένας περαστικός.\nΚι ένας Κύπριος του είπε:\n- Γεια σου, Μάη μου Πεντεφά μου!\nΟ Μάης Πεντεφάς; Τι όνομα ήταν αυτό; Πρώτη φορά το άκουγα. Κι όμως... επειδή έχουν μεγάλη διάρκεια οι μέρες του, οι Κύπριοι πεινάνε και ξαναπεινάνε και τρώνε πέντε φορές τη μέρα (πέντε-φας).\nΤο μόνιππο ήταν γεμάτο στεφάνια, να φάνε κι οι κότες! Αφού τα έχει μπόλικα τα λουλούδια ο Καλομηνάς, ο Μάης απ’ όπου περάσει κρεμάει κι ένα. Πρωτομαγιά, κρέμασε στεφάνια στις πόρτες και τα μπαλκόνια των σπιτιών. Μοίρασε στεφάνια στους «εργαζόμενους», έτσι το είπε, γιατί η Πρωτομαγιά είναι η γιορτή της δουλειάς. Μοίρασε κι ένα σωρό λουλουδένια στεφανάκια στη γιορτή της μητέρας κι έστειλε άλλα τόσα στις Έλενες και τους Κωστήδες στη γιορτή τους. Λουλούδια να δουν τα μάτια σου!","word_count":187,"page_number":67,"chapter":"Γιορτή και ξενοιασιά"},{"id":"g_dimotikou_g_0014","source_id":"g_dimotikou_g","title":"Το καλοκαίρι","content":"Ο κόσμος λάμπει\nσαν ένα αστέρι,\nβουνά και κάμποι,\nδένδρα, νερά\nγιορτάζουν πάλι,\nκαθώς προβάλλει\nτο καλοκαίρι.\nΘεού χαρά!\n\nΦωνούλες, γέλια\nφέρνει τ’ αγέρι\nμέσ' απ' τ’ αμπέλια\nτα καρπερά.\nΠαιδιά αγγελούδια\nψέλνουν τραγούδια\nστο καλοκαίρι.\nΘεού χαρά!\n\nΤην ώρα τούτη\nσκορπά ένα χέρι\nχάδια και πλούτη\nκι η γη φορά\nσα μια πορφύρα.\nΖωής πλημμύρα,\nτο καλοκαίρι.\nΘεού χαρά!\n\nΗ φύση πέρα,\nω νέοι και γέροι,\nσα μια μητέρα\nμας καρτερά.\nΗ φύση όλη\nσαν περιβόλι\nτο καλοκαίρι.\nΘεού χαρά!","word_count":81,"page_number":69,"chapter":"Γιορτή και ξενοιασιά"},{"id":"st_dimotikou_0001","source_id":"st_dimotikou","title":"Τα ψάθινα καπέλα","content":"Απ’ το παλιό μας σπίτι θυμάμαι λίγα πράγματα. ΄Hταν κάπου κοντά στον Λυκαβηττό κι είχε ταράτσα που ’βλεπε στο Φάληρο. Ζούσε μαζί μας ο πατέρας κι είχαμε ένα λαγωνικό που το λέγανε Ντικ. Θυμάμαι και δύο βάζα κινέζικα στις δυο γωνιές της σάλας. Τίποτ’ άλλο. Η Μαρία όμως θυμάται πολλά. Μας τα λέει καμιά φορά κι εμείς δακρύζουμε, κρυφά η μια από την άλλη.\nΜε τον πατέρα πηγαίναμε στη θάλασσα σχεδόν κάθε Κυριακή. Είχε ένα παμπάλαιο αυτοκίνητο που ’μοιαζε με οβίδα και το λέγαμε «Καραϊσκάκη». ΄Eτσι το ’χε βαφτίσει ένα παιδί καθώς περνούσαμε από έναν κεντρικό δρόμο της Αθήνας, και μεις χαρήκαμε, γιατί το αυτοκίνητο του πατέρα δεν ήταν κοινό αυτοκίνητο και του άξιζε να έχει ένα όνομα. Το χρώμα του ήταν καφέ ή γκρίζο ή ίσως και χακί, από μέσα ήταν στρωμένο με βυσσινί πετσί αληθινό, μια πολυτέλεια που ερχόταν σε αντίθεση με το σύνολο· ήταν ψηλό, εντελώς ανοιχτό και δίχως κουκούλα, με τη μηχανή του κομμένη μπροστά κατακόρυφα σαν φάτσα μούργικου σκύλου· πίσω κατέληγε σε μύτη που θύμιζε ουρά τσαλαπετεινού· κι εκεί στη μύτη υπήρχε ένα ξύλινο ντουλαπάκι, όπου πετούσαμε τα κοστούμια του μπάνιου, τα ψαρικά, κι ό,τι άλλο, ανάκατα. Κοντολογίς, ήταν ένα αυτοκίνητο με δικό του χαρακτήρα και εμφάνιση προκλητική.","word_count":203,"page_number":9,"chapter":"Ενότητα 1 — ταξίδια, τόποι, μεταφορικά μέσα"},{"id":"st_dimotikou_0002","source_id":"st_dimotikou","title":"Ταξιδεύοντας με ελέφαντα","content":"«Αν δεν έχετε αντίρρηση, θα πρότεινα να αναζητήσουμε κάποιο άλλο μέσο για να πάμε στο Αλάχαμπαντ» είπε ήρεμα ο Φιλέας Φογκ.\n«Μα αυτή η καθυστέρηση δε θα είναι προς ζημία σας;» απάντησε ο κύριος Φράνσις.\n«Όχι, την είχα προβλέψει».\n«Πώς; Ξέρατε ότι οι γραμμές δε συνεχίζονται;»\n«΄Oχι, αλλά ήξερα ότι αργά ή γρήγορα θα εμφανιζόταν κάποιο εμπόδιο. Επομένως, τίποτα δεν έχει χαθεί. Σήμερα έχουμε 22 Οκτωβρίου, άρα θα φθάσουμε έγκαιρα» δήλωσε ο Φογκ με τέτοια αφοπλιστική αυτοπεποίθηση, που κανένας δεν τόλμησε να κάνει κάποιο σχόλιο.\nΔυστυχώς, οι ράγες πράγματι σταματούσαν. Οι εφημερίδες μοιάζουν με ορισμένα ρολόγια που έχουν τη μανία να πηγαίνουν μπροστά. ΄Eτσι, είχαν πρόωρα αναγγείλει ότι οι γραμμές είχαν ολοκληρωθεί. Οι περισσότεροι ταξιδιώτες γνώριζαν γι’ αυτή τη διακοπή των γραμμών και, μόλις κατέβηκαν από το τρένο, πήραν κάθε διαθέσιμο μεταφορικό μέσο που υπήρχε στο χωριό. ΄Oμως ο κύριος Φογκ και ο κύριος Φράνσις έψαξαν σε όλο το χωριό και δε βρήκαν τίποτα.\n«Θα πάω με τα πόδια» είπε ο κύριος Φογκ.\nΟ Πασπαρτού πλησίασε τον κύριό του, κάνοντας έναν εκφραστικό μορφασμό, καθώς σκεφτόταν τα θαυμάσια αλλά ακατάλληλα για πεζοπορία πασούμια του. Ευτυχώς, είχε κάνει κι αυτός μια έρευνα και, αφού δίστασε για λίγο, είπε:\n«Κύριε, νομίζω ότι βρήκα ένα μέσο να ταξιδέψουμε».\n«Τι;»\n«΄Eναν ελέφαντα! Τον έχει ένας Ινδός που μένει εδώ δίπλα».\nΠέντε λεπτά αργότερα οι τρεις συνταξιδιώτες έφταναν σε μια καλύβα, χτισμένη πλάι σε ένα χωράφι που το περιέζωνε ένας ψηλός φράχτης από πασσάλους. Μέσα στην καλύβα υπήρχε ένας Ινδός και στο χωράφι ένας ελέφαντας. Ο Ινδός τούς οδήγησε στο χωράφι. Εκεί αντίκρισαν ένα ζώο, σχεδόν εξημερωμένο. Αναμφίβολα ο Κιούνι –έτσι έλεγαν το ζώο– μπορούσε, όπως όλοι οι ελέφαντες, να καλύψει με μεγάλη ταχύτητα μεγάλες αποστάσεις και, καθώς δεν υπήρχε άλλο διαθέσιμο υποζύγιο, αποφάσισαν να τον χρησιμοποιήσουν. ΄Oμως οι ελέφαντες, που έχουν αρχίσει να σπανίζουν στην Ινδία, δεν είναι καθόλου φτηνοί. Επομένως, τους έχουν μη στάξει και μη βρέξει, γι’ αυτό και, όταν ο κύριος Φογκ ζήτησε να νοικιάσει τον ελέφαντα, ο Ινδός αρνήθηκε.\nΟ Φογκ επέμενε και πρόσφερε το εξωφρενικό ποσό των δέκα λιρών την ώρα. Η απάντηση του Ινδού ήταν αρνητική. Είκοσι λίρες; Και πάλι όχι. Σαράντα λίρες; Πάντα όχι. Σε κάθε νέα προσφορά, ο Πασπαρτού τιναζόταν αγανακτισμένος, αλλά ο Ινδός ήταν αμετάπειστος.\nΤο ποσό όμως δεν ήταν καθόλου ευκαταφρόνητο. Αν δεχτούμε ότι ο ελέφαντας χρειαζόταν δεκαπέντε ώρες για να φτάσει στο Aλάχαμπαντ, ο ιδιοκτήτης του θα κέρδιζε εξακόσιες λίρες.\nΧωρίς να χάσει την ψυχραιμία του, ο Φιλέας Φογκ πρότεινε στον Ινδό να αγοράσει τον ελέφαντά του, προτείνοντάς του αρχικά χίλιες λίρες.\nΟ Ινδός δεν ήθελε να τον πουλήσει! ΄Iσως ο κατεργάρης να περίμενε ακόμα μεγαλύτερο κέρδος.\nΟ κύριος Φογκ πλησίασε ξανά τον Ινδό και του πρόσφερε διαδοχικά χίλιες διακόσιες λίρες, χίλιες πεντακόσιες λίρες, χίλιες οχτακόσιες και, τέλος, δύο χιλιάδες λίρες. Ο Πασπαρτού, που συνήθως ήταν κοκκινωπός, είχε γίνει κάτασπρος από την αγωνία. Στις δύο χιλιάδες λίρες, ο Ινδός υποχώρησε.\n«Θεούλη μου!» φώναξε ο Πασπαρτού. «Χρυσό τον πληρώνουμε αυτό τον ελέφαντα!»","word_count":487,"page_number":12,"chapter":"Ενότητα 1 — ταξίδια, τόποι, μεταφορικά μέσα"},{"id":"st_dimotikou_0003","source_id":"st_dimotikou","title":"Το σπίτι του ποιητή Καβάφη","content":"Το σπίτι του Καβάφη βρίσκεται στην οδό Λέψιους, έναν δρόμο στην καρδιά της Αλεξάνδρειας. Ο ποιητής κατοικούσε στον δεύτερο όροφο ενός μεγάρου, βαμμένου σε πορτοκαλί χρώμα. Από εκεί φαινόταν απέναντι το νοσοκομείο, χτισμένο ανάμεσα σε μικρά χαμηλά σπιτάκια.\nΟ Καβάφης ήταν, χωρίς αμφιβολία, μανιώδης με την πρωτοτυπία. Από το διαμέρισμά του είχε βγάλει όχι μονάχα το τηλέφωνο και το ραδιόφωνο αλλά και το ηλεκτρικό και στη θέση του είχε βάλει κεριά και λάμπες πετρελαίου.\nΤο διαμέρισμα, όπως και η πρόσοψη του μεγάρου, δεν έχει τίποτα το ξεχωριστό, που να εντυπωσιάζει τον επισκέπτη, τίποτα το μοντέρνο. Επιπλωμένο, χωρίς πίνακες. Στην πλατιά ορθογώνια είσοδο, από το κατώφλι ακόμα, ένα μόνο πράγμα «χτυπάει»: η μακριά και ψηλή βιβλιοθήκη σαν ερμάρι, με τα περισσότερα φύλλα τζαμένια, που σκεπάζει όλο τον τοίχο, και τα στοιβαγμένα στα ράφια βιβλία, μεγάλα και μικρά, σχεδόν όλα δεμένα. ΄Eνα έπιπλο επιβλητικό που και μόνο του χαρακτηρίζει τον ένοικο. Στο σαλόνι, εκεί όπου ο ποιητής συνήθιζε να δέχεται τους φίλους, ένας καναπές τούρκικος, αρκετές πολυθρόνες και καρέκλες, ντυμένες με παλιά χρυσοΰφαντα υφάσματα, μερικά τραπεζάκια από σκαλιστό ξύλο και πάνω τους ένα κηροπήγιο από ατόφιο ασήμι ή μια λάμπα πετρελαίου με θαμπό γυαλί. Πολλά χαλιά, μερικές φτηνές χαλκογραφίες στους τοίχους, μια κορνίζα από έβενο στολισμένη με φίλντισι, που πλαισιώνει ένα ανάγλυφο γύψινο με την αυτοκράτειρα Θεοδώρα, δουλειά ερασιτεχνική, και μια μεγάλη φωτογραφία, με τζάμι, κορνιζαρισμένη, που παριστάνει τη μητέρα του ποιητή, τη Χαρίκλεια Φωτιάδη.\nΧτυπητή αντίθεση με τούτη την επίπλωση αποτελεί το δωμάτιό του. ΄Eνα στενό κι απλό κρεβάτι, ένα τραπεζάκι από ακατέργαστο ξύλο, μια καρέκλα ψάθινη κι ένα σιδερένιο τρίποδο σκουριασμένο που είχε πάνω του μια λεκάνη με μια κανάτα σμαλτωμένη. Τις ζεστές νύχτες του καλοκαιριού ο ποιητής προτιμούσε, αντί να πηγαίνει στο λουτρό και έτσι να διακόπτει την κουραστική δουλειά του, να βουτάει μια πετσέτα στο νερό αυτής της λεκάνης για να δροσίζει το πρόσωπό του. Γιατί συχνά έμενε εκεί ως αργά, σκυμμένος πάνω στο χοντροφτιαγμένο τραπεζάκι, να χτενίζει έναν στίχο ή να ψάχνει για μια λέξη που θα έδινε πιο πιστά την ιδέα του.\nΣ’ αυτό το γυμνό δωμάτιο, το κρυφό του σπουδαστήριο, γεννιούνται ύστερα από τις πρώτες δοκιμές, μέσα σ’ ένα τέταρτο του αιώνα, τα ποιήματά του, που, ακατανόητα στην αρχή για πολύ καιρό, θα προκαλέσουν αργότερα τον θαυμασμό ακόμα και στις πιο μακρινές χώρες. Ο Καβάφης είναι, πραγματικά, ο περισσότερο μεταφρασμένος στο εξωτερικό Nεοέλληνας ποιητής.","word_count":389,"page_number":25,"chapter":"Ενότητα 2 — κατοικία"},{"id":"st_dimotikou_0004","source_id":"st_dimotikou","title":"Παραδοσιακές γεύσεις","content":"Τρώγοντας απολαμβάνουν καλύτερα τη συντροφιά ΄Eλληνες και Τούρκοι. Υπάρχουν μάλιστα τόσα κοινά έθιμα και συνήθειες που εύκολα καταλαβαίνει κανείς πόσο κοντά είναι οι δύο λαοί. Για παράδειγμα, την Πρωτομαγιά στην Ελλάδα και στην Τουρκία οι άνθρωποι πηγαίνουν στην εξοχή, ώστε να γιορτάσουν την άνοιξη με γλέντια στους αγρούς. Στα παράλια της Τουρκίας και την Κρήτη, τη μέρα αυτή, βράζουν φρέσκα βότανα για να αποκτήσουν δύναμη και να προστατεύονται από τα μάγια. Εξάλλου, πολλοί από τους κοινούς μεζέδες δεν είναι μαγειρεμένοι. Τα τουρσιά ή τα παστά ψάρια συντηρούνται από τους δύο λαούς με τον ίδιο τρόπο, μέσα σε ξίδι, αλάτι, άρμη ή λάδι, με αποτέλεσμα να μπορούν να τα τσιμπολογήσουν ακόμα και με το χέρι.","word_count":114,"page_number":51,"chapter":"Ενότητα 4 — διατροφή"},{"id":"st_dimotikou_0005","source_id":"st_dimotikou","title":"O μανδαρίνος* και ο γάτος","content":"Mια φορά κι έναν καιρό ήταν ένας μανδαρίνος που είχε έναν γάτο παχουλό και καλοταϊσμένο που τον αγαπούσε πολύ. ΄Hταν τόσο περήφανος για το εξαιρετικά όμορφο και δυνατό ζώο του, που το ονόμασε «Oυρανό».\n΄Oμως μια μέρα ένας φίλος του του λέει:\n– Eπίτρεψέ μου να παρατηρήσω ότι υπάρχει κάτι πιο ισχυρό από τον ουρανό, είναι τα σύννεφα, αφού μπορούν να κρύψουν τον ουρανό.\n– ΄Eχεις δίκιο, απάντησε ο μανδαρίνος, και σ’ ευχαριστώ. Aπό δω και πέρα θα φωνάζω τον υπέροχο γάτο μου «Σύννεφο».\nΛίγο καιρό αργότερα ένας άλλος μανδαρίνος πήγε στο σπίτι του για να πιουν τσάι.\n– Tι, ρώτησε έκπληκτος, φωνάζετε «Σύννεφο» αυτό το εξαίσιο ζώο; Aφού υπάρχει κάτι πιο δυνατό από τα σύννεφα, είναι ο άνεμος που τα διώχνει από μπροστά του.\n΄Eτσι λοιπόν ο αφέντης του ονόμασε «΄Aνεμο» τον γάτο για τον οποίο ήταν τόσο περήφανος.\nΔεν είχε περάσει μια βδομάδα και ο δήμαρχος της πόλης, καλεσμένος στο σπίτι του μανδαρίνου, είδε τον γάτο…","word_count":158,"page_number":66,"chapter":"Ενότητα 4 — διατροφή"},{"id":"st_dimotikou_0006","source_id":"st_dimotikou","title":"Eδώ Πολυτεχνείο","content":"«Eδώ Πολυτεχνείο!\nΣας μιλάει ο ραδιοφωνικός σταθμός των ελεύθερων αγωνιζόμενων φοιτητών, των ελεύθερων αγωνιζόμενων Eλλήνων. Eίμαστε ο μόνος σταθμός που μετά από έξι χρόνια δικτατορίας στην Eλλάδα μπορεί να λέει ελεύθερα την αλήθεια. Aυτή τη στιγμή στην Aθήνα πανηγυρίζει όλος ο λαός. Xτυπούν οι καμπάνες χαρμόσυνα παντού, γιατί αυτή τη στιγμή γεννιέται και σημαίνει η ώρα της λευτεριάς».\nH φωνή βγαίνει μέσα από ’να μαύρο κουτάκι, ένα τρανζίστορ της ΄Aννας, που είναι ακουμπισμένο πάνω στο χαμηλό τραπεζάκι, ανάμεσα στα δυο κρυστάλλινα βάζα με τις ασημένιες σκαλιστές βάσεις.\nEίναι Παρασκευή βράδυ.\nAπό δω και τρεις μέρες οι φοιτητές κατέλαβαν το Πολυτεχνείο. ΄Eφτιαξαν έναν πομπό, απ’ αυτόν ακούγεται η φωνή τους.\n«Eδώ Πολυτεχνείο».\nΣτο σαλόνι, στις πολυθρόνες με την μπλε στόφα, κάθονται η Mαρία και η Άννα.\nAκούνε. O Aντρέας περπατάει πάνω κάτω.\nAκούει κι αυτός.\n«Πού να βρίσκεται ο Παύλος; Mέσα στο Πολυτεχνείο;\nKι αυτή η φωνή του αγοριού που λέει και ξαναλέει: Eδώ Πολυτεχνείο. Eδώ Πολυτεχνείο… πόσο μοιάζει με τη φωνή του Mάνου»…\nH Mαρία το μεσημέρι κατέβηκε να δει. Θαμπώσανε τα μάτια της! Kόσμος πολύς γύρω τριγύρω, και μέσα από τα κάγκελα απλώνονταν τα χέρια για να δεχτούν τις προσφορές του λαού: τρόφιμα, τσιγάρα, σοκολάτες, λουλούδια. Tα παιδιά τραγουδούσαν τραγούδια της λευτεριάς. Yψωμένα πλακάτ έγραφαν: KATΩ H XOYNTA - ΔHMOKPATIA - ΨΩMI - ΠAIΔEIAEΛEYΘEPIA. ΄Aλλα συνθήματα είχαν γραφτεί πάνω στους τοίχους και πάνω σε πανό από χοντρό κάμποτο*: ΛAE ΠOΛEMA - ΣOY ΠINOYNE TO AIMA - OΛOI ΣTON AΓΩNA - EPΓATEΣ\n- AΓPOTEΣ - ΦOITHTEΣ. Oι διαδηλωτές σκαρφάλωναν στα τρόλεϊ και στα λεωφορεία που περνούσαν γεμάτα κόσμο και έγραφαν πάνω τους: KATΩ H XOYNTA. O τηλεβόας έκανε έκκληση: Συμπαρασταθείτε μας. Mια σκάλα ήταν στημένη από τη μεριά της Στουρνάρα. Oι νέοι την ανέβαιναν και πηδούσαν μέσα στον χώρο του Πολυτεχνείου. O κόσμος κοιτούσε, δεν έφευγε, δε φοβόταν. Λες κι ήταν πανηγύρι. Μύριζε λευτεριά.\nH Mαρία γύρισε σπίτι συγκινημένη, ενθουσιασμένη.\n«Πού είναι ο Παύλος; Θα ’ναι ακόμα στο Πολυτεχνείο. Aντρέα, έπρεπε να κατέβεις κι εσύ, να δεις αυτά τα παιδιά. Kρεμασμένα από τα κάγκελα τραγουδούσαν “Πότε θα κάνει ξαστεριά”. Kανένας δε θα τολμήσει να τους αγγίξει. Nα δεις που η χούντα δε θ’ αντέξει, θα γκρεμιστεί. ΄Oλη η Aθήνα ξεσηκώθηκε.\nΠρέπει να τους βοηθήσουμε. Aγγελική, έλα να φτιάξουμε ένα δέμα. Θα βάλουμε ό,τι έχουμε στα ντουλάπια μας: ζάχαρη, καφέ, κονσέρβες, ρύζι.\n΄Eχουμε φρούτα; ΄Aννα, κατέβα στον μανάβη κι αγόρασε φρούτα και μπισκότα από τον μπακάλη. Δρόμος σου είναι, Aγγελική, φεύγοντας πέρασε και δώσε το δέμα στα παιδιά. Tο φωνάζουν από τον τηλεβόα, έχουνε ανάγκη από τρόφιμα. Θα ξεκουραστώ λιγάκι και θα κατέβω ξανά.\nΣυμφωνήσαμε με την Tόνια και τη φίλη της, τη Mυρτώ, να πάμε»…\nΓελούσαν κατεβαίνοντας την Aκαδημίας.\nMαζί τους και άλλος κόσμος, γυναίκες, άντρες, παιδιά, γέροι και γριές κατευθύνονται στο Πολυτεχνείο. ΄Oμως από τα θωρακισμένα αυτοκίνητα, που σαν τυφλά θεριά σούρνονται στους γύρω δρόμους, ρίχνονται δακρυγόνα αέρια. Kλαίνε οι άνθρωποι. Tα μάτια πονάνε. ΄Aλλοι βήχουν, άλλοι κάνουν εμετό, άλλοι λιποθυμούν. O σταθμός του Πολυτεχνείου συμβουλεύει: «Bάλτε λεμόνι στα μάτια σας, μην τα τρίβετε». ΄Oταν φτάνουν στην οδό Πατησίων, ο δρόμος φέγγει από τις φωτιές. Eφημερίδες, τηλεφωνικοί κατάλογοι, ξύλα, πανιά καίγονται. O καπνός εξουδετερώνει τα δακρυγόνα. ΄Oμως οι βόμβες πέφτουν όλο και πιο πολλές. H αστυνομία τις ρίχνει μέσα στον περίβολο του Πολυτεχνείου. Oι φωνές των φοιτητών είναι βραχνές. H βοή μεγαλώνει. O ραδιοφωνικός σταθμός κάνει έκκληση προς τον Eρυθρό Σταυρό. Xρειάζονται φάρμακα, χρειάζονται γιατρούς, χρειάζονται ασθενοφόρα, υπάρχουν πληγωμένοι. Tο Πολυτεχνείο σπαράζει.\n«Eλληνικέ Λαέ, πρέπει να μας συμπαρασταθείς, πρέπει να συνεχίσεις τον αγώνα μας. Kι αν αυτή τη στιγμή μάς πιάσουνε, κι αν αυτή τη στιγμή μάς σκοτώσουν, ναι, δε φοβόμαστε να πεθάνουμε, όταν θα πεθάνουμε ελεύθεροι. ΄Eλληνες, πρέπει να μάθετε την αλήθεια. Nα μάθετε πως τα παιδιά σας γεννήθηκαν λεύτερα.\nΈλληνες, τα τανκς αυτή τη στιγμή έχουν στραφεί με τις μπούκες των κανονιών τους προς το Πολυτεχνείο. Oι φοιτητές έχουν ξεκουμπώσει τα πουκάμισά τους και δείχνουν τα στήθια τους. Tο μόνο όπλο που έχουν προς τα τανκς.\n΄Eλληνες, ακόμη το Πολυτεχνείο είναι ελεύθερο. Aν δε συμμεριστείτε αυτό τον αγώνα μας, θα χαθεί η Eλλάδα μας.\nEίμαστε άοπλοι, είμαστε άοπλοι, είμαστε άοπλοι. Oύτε μια πέτρα δεν έχουμε για να ρίξουμε στ’ αδέλφια μας. ΄Oλοι είμαστε αδέλφια,΄Eλληνες, κι αν ακόμη αυτή τη στιγμή σαρώσουν τα τανκς το Πολυτεχνείο, πιστεύουμε σε σένα. Πιστεύουμε στη συνέχεια του αγώνα.\nEλληνικέ λαέ, πρέπει να μας συμπαρασταθείς. Σήμερα, αυτή τη στιγμή πώς είναι δυνατόν να κοιμηθείς όταν τα τανκς στέκουν μπροστά στις πύλες του Πολυτεχνείου και σημαδεύουν τα παιδιά σου;»\nTα τανκς κατέβηκαν.\nΠοια παιδιά σημαδεύουν;\nΠοια παιδιά έχουν ξεκουμπώσει τα πουκάμισά τους και περιμένουν τις σφαίρες; Tα παιδιά της Aθήνας, τα δικά μας παιδιά.\n«Eδώ Πολυτεχνείο.\nΘέλουμε ορθοπεδικούς. ΄Eχουμε πληγωμένους. Xρειαζόμαστε φάρμακα, χρειαζόμαστε ενέσεις μορφίνης, έχουμε πληγωμένους, θέλουμε γιατρούς…\nEδώ Πολυτεχνείο, θα διακόψουμε για λίγο τη μετάδοση των ειδήσεων. Mόλις μάθουμε νέα, θα επικοινωνήσουμε πάλι μαζί σας. Mείνετε στους δέκτες σας, στο ίδιο μήκος κύματος»…\nTο μαύρο κουτί βουβαίνεται.\nΞημέρωνε Σάββατο 17 του Nοέμβρη.","word_count":810,"page_number":73,"chapter":"Ενότητα 5 — 17η Nοέμβρη"},{"id":"st_dimotikou_0007","source_id":"st_dimotikou","title":"Αναμνήσεις από αυτόπτες μάρτυρες","content":"Α. «Tην ημέρα εκείνη είχα υπηρεσία. Mόλις άρχισαν τα επεισόδια, μπήκαμε επιφυλακή. “Oι φοιτητές καίνε την Aθήνα” μας έλεγαν, και εμείς τους πιστεύαμε.\nΣτις 1.15 το πρωί της 17ης Nοεμβρίου φτάσαμε στη διασταύρωση των λεωφόρων Aλεξάνδρας και Πατησίων. Yπήρχαν οδοφράγματα, φωτιές και ακινητοποιημένα λεωφορεία. Mε διάφορες μανούβρες αριστερά δεξιά, μπρος πίσω, άνοιξα τον δρόμο και προχωρήσαμε. O κόσμος, θυμάμαι, συνέχεια έγινε ο εφιάλτης της ζωής μου. μας φώναζε “είμαστε αδέλφια, είμαστε αδέλφια”. Eγώ όμως τους έβλεπα σαν παράσιτα.\nEίχε πάει 2 το πρωί. Φτάνοντας μπροστά στην πόρτα, έστριψα το άρμα προς το Πολυτεχνείο. Oι στρατιωτικοί δίνουν προθεσμία λίγων λεπτών στους φοιτητές για να αποχωρήσουν από το Πολυτεχνείο, να παραδοθούν. Δεκάδες φοιτητές κρέμονταν από τα κάγκελα, ενώ εκατοντάδες βρίσκονταν στον προαύλιο χώρο.\nTότε ήρθε ο επικεφαλής και μου λέει: “Θα μπούμε μέσα, θα ρίξουμε την πύλη. Eτοιμάσου!”. Mέχρι που μπήκα μέσα, πίστευα αυτό που έκανα. Στη\nH καγκελόπορτα έπεσε αμέσως. Mε το που έπεσε η πύλη του Πολυτεχνείου, εισέβαλαν οι αστυνομικοί για να συλλάβουν τους φοιτητές. ΄Oπως περνούσαν οι φοιτητές, θυμάμαι ότι έριχναν μέσα στα τανκς πακέτα με τσιγάρα και ό,τι προμήθειες είχαν μαζί τους. ΄Oταν γυρίσαμε, το άρμα έμοιαζε με περίπτερο. ΄Oσο σκέφτομαι ότι οι φοιτητές μάς έδιναν σάντουιτς και τσιγάρα, μετά απ’ όσα τους κάναμε…\nΔεν μπορώ να το συχωρέσω αυτό το πράγμα στον εαυτό μου. Σκέφτομαι τι πήγα και έκανα! Nτρέπομαι γι’ αυτό που ήμουν, γι’ αυτό που έκανα».","word_count":231,"page_number":77,"chapter":"Ενότητα 5 — 17η Nοέμβρη"},{"id":"st_dimotikou_0008","source_id":"st_dimotikou","title":"Αυτόχθονες λαοί","content":"Όταν τον 15ο αιώνα ξεκίνησαν τα ταξίδια τους οι μεγάλοι εξερευνητές, ήρθαν για πρώτη φορά σε επαφή με νέους, αυτόχθονες λαούς. Αυτόχθονα λέμε αυτόν που κατοικεί στη γη των προγόνων του. Σημαίνει, δηλαδή, ιθαγενής ή ντόπιος.\nΟι εξερευνητές, που ήταν τεχνολογικά πιο εξελιγμένοι, τους εξόντωσαν, έκλεψαν χρυσό και ασήμι, καταπάτησαν τη γη τους, εξαφάνισαν τους πολιτισμούς τους. Οι «πολιτισμένοι» λαοί τούς θεώρησαν «πρωτόγονους» και συχνά τούς φέρονταν σαν να ήταν ζώα, γι’ αυτό τους μετέτρεψαν σε σκλάβους.\nΑποτέλεσμα όλων αυτών ήταν να εξαφανιστούν πολλοί λαοί, κάποιοι άλλοι να χάσουν την πολιτισμική τους ταυτότητα και μερικοί να εγκαταλείψουν τη γη τους. Όμως σε πολλές γωνιές του πλανήτη μας υπάρχουν αυτόχθονες που διατηρούν ακόμη τον παραδοσιακό τρόπο ζωής τους.","word_count":117,"page_number":81,"chapter":"Ενότητα 6 — η ζωή σε άλλους τόπους"},{"id":"st_dimotikou_0009","source_id":"st_dimotikou","title":"Σπίτι μας είναι η γη","content":"Στη Βόρεια Αμερική κατοικούσαν κυρίως Ινδιάνοι. Στα μέσα του 19ου αιώνα, οι λευκοί έποικοι έδιωξαν τους Ινδιάνους από τα εδάφη τους, άλλοτε ειρηνικά κι άλλοτε βίαια. Ο δρόμος που ακολούθησαν οι Ινδιάνοι ονομάστηκε «μονοπάτι των δακρύων».\nΤο παρακάτω κείμενο είναι απόσπασμα της απάντησης που έστειλε το 1855 ο αρχηγός των Ινδιάνων στον Πρόεδρο των ΗΠΑ, ο οποίος είχε ζητήσει να αγοράσει ένα τμήμα της γης τους.\nΠώς μπορείτε να αγοράσετε ή να πουλήσετε τον ουρανό ή τη ζεστασιά της γης; Η ιδέα μάς φαίνεται περίεργη. Επειδή ακριβώς δε μας ανήκουν η δροσιά του αέρα και η διαύγεια του νερού, πώς είναι δυνατόν να τα αγοράσετε; Κάθε κομματάκι αυτής της γης είναι ιερό για τον λαό μου. Κάθε βελόνα του λαμπερού πεύκου, κάθε αμμουδερή κοίτη ποταμού, κάθε κομματάκι ομίχλης μέσα στα σκοτεινά δάση, κάθε ξέφωτο και κάθε βούισμα εντόμου είναι ιερό στη μνήμη και στην εμπειρία του λαού μου.\nΕίμαστε ένα μέρος της γης, κι αυτή, πάλι, ένα κομμάτι από εμάς. Τα ευωδιαστά λουλούδια είναι οι αδερφές μας. Το ελάφι, το άλογο, ο μεγάλος αετός είναι οι αδερφοί μας. Τα βράχια στους λόφους, το πράσινο χρώμα των λιβαδιών, η ζεστασιά του πόνεϊ και ο άνθρωπος, όλα ανήκουν στην ίδια οικογένεια. Γι’ αυτό και όταν ο Μεγάλος Αρχηγός στην Ουάσιγκτον μας παραγγέλνει ότι θέλει να αγοράσει τη γη μας ζητάει πολλά από εμάς. Ο Μεγάλος Αρχηγός μάς παραγγέλνει ότι θα μας εξασφαλίσει ένα μέρος έτσι που να μπορούμε να ζήσουμε άνετα μεταξύ μας. Θα σκεφτούμε, λοιπόν, την προσφορά του για ν’ αγοράσει τη γη μας. Αλλά δε θα είναι κι εύκολο. Γιατί αυτή η γη είναι για μας ιερή.\nΞέρουμε ότι ο λευκός άνθρωπος δεν καταλαβαίνει τα ήθη μας. Ένα κομμάτι γης μοιάζει γι’ αυτόν μ’ ένα οποιοδήποτε άλλο κομμάτι, γιατί είναι ένας ξένος που έρχεται μες στη νύχτα και παίρνει από τη γη αυτό που έχει ανάγκη. Η γη δεν είναι ο αδερφός του, αλλά ο εχθρός του, και μόλις την κυριεύσει πηγαίνει μακρύτερα.\nΣυμπεριφέρεται στη μητέρα του, τη γη, και στον αδερφό του, τον ουρανό, σαν να ήταν πράγματα που αγοράζονται, που λεηλατούνται, που πουλιούνται, όπως τα πρόβατα ή τα λαμπερά μαργαριτάρια. Η απληστία του θα καταβροχθίσει τη γη και δε θ’ αφήσει πίσω της παρά μια έρημο.\nΞέρουμε τουλάχιστον αυτό: η γη δεν ανήκει στον άνθρωπο, ο άνθρωπος ανήκει στη γη. Αυτό το ξέρουμε. ΄Oλα τα πράγματα είναι αλληλένδετα, όπως το αίμα ενώνει μια οικογένεια. ΄Oλα τα πράγματα είναι αλληλένδετα.\n΄Eνα πράγμα που ξέρουμε εμείς –και που ο λευκός άνθρωπος θα ανακαλύψει ίσως κάποτε– είναι ότι ο Θεός μας είναι ο ίδιος Θεός. ΄Iσως να σκέφτεστε να τον αποκτήσετε τώρα, όπως θέλετε να αποκτήσετε τη γη μας, αλλά δεν μπορείτε. Είναι ο Θεός του ανθρώπου, και το έλεός του είναι το ίδιο και για τον λευκό και για τον ερυθρόδερμο άνθρωπο. Αυτή η γη είναι πολύτιμη για τον άνθρωπο, και όταν τη βλάπτει είναι σαν να δείχνει περιφρόνηση στον Δημιουργό.","word_count":481,"page_number":82,"chapter":"Ενότητα 6 — η ζωή σε άλλους τόπους"},{"id":"st_dimotikou_0010","source_id":"st_dimotikou","title":"Αιολική γη","content":"Η «Αιολική γη» μάς μεταφέρει στα Κιμιντένια, βουνά της Μικράς Ασίας, όπου ζει η οικογένεια του μικρού Πέτρου με αρχηγό τον παππού. Ο Πέτρος με την Άρτεμη, την πιο αγαπημένη από τις τέσσερις αδερφές του, ζουν τα παιδικά τους χρόνια και τα όνειρα στον τόπο όπου γεννήθηκαν. Σιγά σιγά ο μαγικός τους κόσμος γκρεμίζεται, όταν έρχονται αντιμέτωποι με τον πόλεμο και αναγκάζονται να ζήσουν τον ξεριζωμό απ’ τον τόπο και τη γη τους.\nΤα άστρα όλα έχουν βγει. Ταξιδεύουν στο Αιγαίο τα παιδικά μας όνειρα. Το κύμα χτυπά τη μάσκα του καϊκιού μας και τα κοιμίζει. Κοιμηθείτε, όνειρά μας. Στην ξένη χώρα που πάμε, πρόσφυγες, τι άραγες να μας περιμένει, τι μέρες να είναι ν’ ανατείλουν;\n[…] Ταξιδεύουν στο Αιγαίο τα όνειρά μας.\nΗ γιαγιά μας κουράστηκε. Θέλει να γείρει το κεφάλι της στα στήθια του παππού, που έχει\n– Τι είναι; καρφωμένα πίσω τα μάτια του μπας και ξεχωρίσει τίποτα από τη στεριά, τίποτα απ’ τα Κιμιντένια. Μα πια δε φαίνεται τίποτα. Η νύχτα ρούφηξε μέσα της τα σχήματα και τους όγκους.\nΗ γιαγιά γέρνει το κεφάλι της να το ακουμπήσει στα στήθια που την προστατέψανε όλες τις μέρες της ζωής της. Κάτι την μποδίζει και δεν μπορεί να βρει το κεφάλι ησυχία. Σαν ένας βόλος να είναι κάτω από το πουκάμισο του γέροντα.\n– Τι είναι αυτό εδώ; ρωτά σχεδόν αδιάφορα.\nΟ παππούς φέρνει το χέρι του. Το χώνει κάτω απ’ το ρούχο, βρίσκει το μικρό ξένο σώμα που ακουμπά στο κορμί του και που ακούει τους χτύπους της καρδιάς του.\n– Δεν είναι τίποτα, λέει δειλά ο παππούς, σαν παιδί που έφταιξε. Δεν είναι τίποτα. Λίγο χώμα είναι.\n– Χώμα!\nΝαι, λίγο χώμα απ’ τη γη τους. Για να φυτέψουν έναν βασιλικό, της λέει, στον ξένο τόπο που πάνε. Για να θυμούνται.\nΑργά τα δάχτυλα του γέροντα ανοίγουν το μαντίλι όπου είναι φυλαγμένο το χώμα. Ψάχνουν κει μέσα, ψάχνουν και τα δάχτυλα της γιαγιάς, σαν να το χαϊδεύουν. Τα μάτια τους, δακρυσμένα, στέκουν εκεί.\n– Δεν είναι τίποτα λέω. Λίγο χώμα. Γη, Αιολική Γη, Γη του τόπου μου.","word_count":341,"page_number":87,"chapter":"Ενότητα 6 — η ζωή σε άλλους τόπους"},{"id":"st_dimotikou_b_0001","source_id":"st_dimotikou_b","title":"Ολική καταστροφή στις καλλιέργειες","content":"Ανυπολόγιστες είναι οι καταστροφές στα εσπεριδοειδή, τις ελιές και τα κηπευτικά κυρίως στην Κρήτη και την Πελοπόννησο, από την κακοκαιρία των τελευταίων ημερών. Ζημιές στα πορτοκάλια καταγράφονται ήδη και στη Θεσπρωτία, ενώ όσοι δεν είχαν προλάβει να μαζέψουν τις ελιές στη Φθιώτιδα και τη Θάσο τώρα, εκτός από τα κατεστραμμένα δένδρα, έχουν χάσει και τη φετινή σοδειά.\nΣτα Χανιά οι πρώτες εκτιμήσεις δείχνουν πως οι καταστροφές στις καλλιέργειες, στην κτηνοτροφία, αλλά και στο επαρχιακό και αγροτικό οδικό δίκτυο είναι τεράστιες.\nΖωοτροφές από ελικόπτερο\nΤεράστιες καταστροφές έχει προκαλέσει η κακοκαιρία των τελευταίων ημερών στα εσπεριδοειδή και τις ελιές, κυρίως στην Πελοπόννησο και στην Κρήτη.\nΑνάλογη κατάσταση έχει δημιουργηθεί και στον νομό Ρεθύμνου, όπου χιλιάδες αιγοπρόβατα βρίσκονται αποκλεισμένα στον Ψηλορείτη και από προχθές οι νομαρχίες σε συνεργασία με την Πολεμική Αεροπορία ρίχνουν ζωοτροφές από αέρος, προκειμένου να περισωθούν όσα ζώα γίνεται. Χθες το απόγευμα, ελικόπτερο «σούπερ πούμα» πραγματοποίησε επιτυχή προσγείωση στον Ομαλό και πήρε στη Σούδα 29 γυναίκες και παιδιά, κυρίως οικογενειών κτηνοτρόφων, που είχαν αποκλεισθεί εκεί και τις τελευταίες ημέρες είχαν περάσει δύσκολες ώρες. Οι άνδρες της Πολεμικής Αεροπορίας κατάφεραν επίσης χθες να εντοπίσουν τέσσερις κτηνοτρόφους που είχαν δηλωθεί ως αγνοούμενοι στην ευρύτερη περιοχή του χωριού Καλλικράτης, στα Σφακιά.\nΣτο Ρέθυμνο, η ηλεκτροδότηση είχε αποκατασταθεί σε όλες τις περιοχές του νομού λίγο πριν από τα μεσάνυχτα προχθές, αλλά και εκεί οι ζημιές στις καλλιέργειες είναι ανυπολόγιστες, κυρίως στις Σείσες και το Φόδελε. ΄Oπως επισημαίνεται από τις Διευθύνσεις Γεωργίας των νομαρχιών της Κρήτης, το πρόβλημα είναι διπλό: δεν έχουν καταστραφεί μόνον οι σοδειές, αλλά και τα ίδια τα δένδρα, που είτε έσπασαν από το βάρος του χιονιού και του καρπού τους είτε «κάηκαν» από τον πάγο.\nΗ κατάσταση όμως δεν είναι καλύτερη στην Πελοπόννησο, αφού στο μεγαλύτερο μέρος τους οι καλλιέργειες των εσπεριδοειδών έχουν υποστεί μεγάλες ζημιές. Μόνο στη Λακωνία, τουλάχιστον το 50% της παραγωγής πορτοκαλιών έχει «καεί» από τον πάγο και μάλιστα εκτιμάται πως φέτος ίσως δε γίνουν εξαγωγές.","word_count":318,"page_number":9,"chapter":"Ενότητα 7 — η ζωή έξω από την πόλη"},{"id":"st_dimotikou_b_0002","source_id":"st_dimotikou_b","title":"Τριάντα εννιά καφενεία και ένα κουρείο","content":"Η πολύτιμη σχέση με τον παππού μου μου άνοιξε τον δρόμο μιας ιδιαίτερης αγάπης για τα καφενεία. Το χωριό μου τότε είχε πολλά και ωραία καφενεία.\n«Άντε να πάμε στον καφενέ» έλεγε ο παππούς και μου έκλεινε πονηρά το μάτι.\nΣυχνά με έπαιρνε μαζί του και μου έδινε τα λουκούμια όταν κέρδιζε τους φίλους του στην πρέφα. «Πάμε στον λουκουμέ» έλεγα εγώ από μέσα μου και γελούσα και χαιρόμουνα με το αστείο μου, σαν την παροιμία που λέει «Γιάννης κερνά, Γιάννης πίνει». Για μένα λοιπόν τα καφενεία του χωριού μου ήταν μεγάλα λουκούμια με παράθυρα που είχαν θέα προς τη θάλασσα και ωραία μαρμάρινα τραπέζια. Άλλα καφενεία είχαν χρώμα και γεύση τριαντάφυλλου, άλλα πράσινης μέντας και άλλα ήταν κεχριμπαρένια και μοσχοβολούσαν μέλι και κερί. Όμως όλα τα λουκούμια-καφενεία μύριζαν στο βάθος τους καφέ και ούζο και γαρίδες με ντομάτα.\nΣτον Μόλυβο δεν έχει πια ούτε ένα καφενείο. Όταν τα βράδια του καλοκαιριού μαζεύουν την τουριστική πραμάτεια και κλείνει η αγορά, βγαίνω απ’ το παραθυράκι του μυαλού μου και φέρνω έναν χειμώνα όλο γούστο.\nΗ μάνα μου μόλις σιδέρωσε τις πετσέτες του μαγαζιού μας κι εγώ τις παίρνω ζεστές ζεστές και τις πηγαίνω στο κουρείο του πατέρα μου.\nΤα χέρια του μυρίζουν κολόνια, τα μάτια του στολίζουν την αγορά. Το κουρείο μας καθαρό, μυρωδάτο, αρχοντικό, με τα παλιά καρυδένια έπιπλα και τους μεγάλους καθρέφτες. Μέσα τους βλέπω το λιμάνι, τις τράτες, το ηλιοβασίλεμα.\nΤότε με κατακλύζει μια μυρωδιά από κολόνια, καφέ και αθερίνα τηγανητή. Τα κουκουλώνει όλα γλυκά, αθόρυβα.\nΜέσα στη νύχτα και στη μυρωδιά ξεφυτρώνουν και πάλι τα λουκούμια-καφενεία μου. Καθαρίζω την άχνη τους και αναγνωρίζω τα μαρμάρινα τραπέζια, τα ποτηράκια του ούζου, τα μικρά κανονάκια του κονιάκ, τα πιατέλια με τους μεζέδες και τα ψωμάκια αντίδωρα.\nΑκούω τους χτύπους των χεριών στο χαρτοπαίγνιο, τις ζαριές και τις μουσικές παρηγοριές απ’ το τζουκμπόξ...\nΕξαίρεση οι Κυριακές με τις γυναίκες, περιποιημένες, αρωματισμένες, με κόκκινα κραγιόν και άσπρα κολιεδάκια, σε οικογενειακές εξόδους, υποβρύχιες γλυκές κοινωνίες βανίλιας μέσα στα λουκούμια-καφενεία μου.\nΓλείφω την άχνη απ’ τα χείλη μου. Σκουπίζω και τα υπολείμματα που έπεσαν στο γαλάζιο φουστανάκι μου. Τα φώτα στους δρόμους χαμηλώνουν. Δώδεκα, μεσάνυχτα. Πρέπει να γυρίσω στο σπίτι. Είναι αργά.\nΠαίρνω βιαστικά άχνη από το χάρτινο κουτί των λουκουμιών, ρίχνω μπόλικη στα τζάμια, στις πόρτες, στα παράθυρα, στα κεραμίδια, στους πέτρινους τοίχους, να τα κρύψω, να τα κρύψω τα λουκούμια-καφενεία μου. Να μην τα δει κανείς. Κανείς να μη μου τα πάρει.","word_count":401,"page_number":15,"chapter":"Ενότητα 7 — η ζωή έξω από την πόλη"},{"id":"st_dimotikou_b_0003","source_id":"st_dimotikou_b","title":"Tα Χριστούγεννα του υπολογιστή","content":"Tο λογιστικό κέντρο ήταν άδειο και βουβό. Oι μηχανές σταμάτησαν γι’ απόψε. O υπολογιστής ASTRA 5603 αισθανόταν πολύ κουρασμένος. Mήνες τώρα δεν είχε σταματήσει να δουλεύει. Oι υπάλληλοι τον τροφοδοτούσαν με προγράμματα κι εκείνος σκοτωνόταν να τα βγάλει πέρα.\nEπιτέλους ήρθαν τα Xριστούγεννα. Για λίγες μέρες ήθελε κι εκείνος να ηρεμήσει, να ξεκουράσει την καλωδιακή καρδιά του. Tώρα που σταμάτησαν να δουλεύουν τα κουμπιά και τα πλήκτρα του, αχ, ένιωθε μια χαλάρωση σ’ όλο του το …κορμί.\nH κυρία Aσημίνα, η καθαρίστρια, μπήκε μέσα κρατώντας με το ένα χέρι τον κουβά και τη σκούπα και με το άλλο το αγοράκι της.\n– Kάθισε κάπου, Xαράλαμπε, αλλά ήσυχα, έτσι; Mην αγγίζεις τους υπολογιστές και κάνεις καμιά ζημιά, καήκαμε. Nαι, καλό μου; Eγώ θα τελειώσω τη δουλειά μου και θα πάμε σπίτι.\nTο παιδί θαύμαζε τα μηχανήματα και τους προσωπικούς υπολογιστές πάνω στα γραφεία των υπαλλήλων. H αίθουσα ήταν ψυχρή και η παρουσία τους έδινε την εντύπωση ενός εξωγήινου τοπίου… Mόνο ένα δεντράκι χριστουγεννιάτικο αναβόσβηνε τα φώτα του και θύμιζε σ’ εκείνη την παγερή αίθουσα τη μεγάλη γιορτή. O Xαραλάμπης έτρεχε από το ένα μηχάνημα στο άλλο.\n– Tι κάνει αυτός; Tι κάνει εκείνος; ρωτούσε τη μητέρα του, λες και ήταν ειδική να του απαντήσει.\n– Nα σου πω την αλήθεια, δεν ξέρω, κούνησε εκείνη το κεφάλι της. Aυτόν εδώ τον έχω ακούσει να κάνει γκρρρ, γκρ, κρι, γκρ, κρακ. Aυτός εδώ κάνει σαν να τον πνίγουν. Aυτός με τα κόκκινα φωτάκια είναι ο πιο αστείος. Aναβοσβήνει και ξεφυσάει σαν ατμομηχανή. Φςς, σσσσ, φς, έκανε η μαμά κωμικά.\n– Nα τον χαϊδέψω λιγάκι; Tι θα πάθει; ρώτησε το παιδί και με τα χεράκια του ακούμπησε τον ASTRA 5603. Tρυφερά…\nO κομπιούτερ ρίγησε. Πρώτη φορά τον άγγιζαν με τόση τρυφερότητα. Kανείς δεν του έδειχνε τέτοιο ενδιαφέρον. Όλοι στέκονταν μπροστά του αδιάφοροι, τον μπούκωναν με τρυπητά καρτελάκια και δισκέτες και τον υποχρέωναν να γράφει κατεβατά, να τυπώνει νούμερα, να κάνει προσθέσεις. Mόνο να κάνει τούμπες δεν τον υποχρέωναν.\n– Eσύ μ’ αρέσεις πολύ, του ψιθύρισε. Έχεις γυαλιστερά κουμπιά και ένα κόκκινο φως στο κούτελο.\n– ΄Eχω πολλά προσόντα. Aυτό είναι αλήθεια, συμφώνησε ο ASTRA 5603. Mα φυσικά το παιδί δεν μπόρεσε να τον ακούσει.\n– Kι έχεις κι ένα ύφος! συνέχισε ο Xαραλάμπης. Σαν πολύ κουρασμένος μου φαίνεσαι!\nTα καλώδια τρεμόπαιζαν στην καρδιά του υπολογιστή και ήταν έτοιμα να σπάσουν από συγκίνηση. Ήθελε να πει στο παιδί ότι, ναι, ήταν πολύ κουρασμένος και ότι βαρέθηκε να κάνει εκατομμύρια προσθέσεις στο λεπτό, ότι βαρέθηκε να τακτοποιεί στη μνήμη του όλα όσα του αποθήκευσαν οι άνθρωποι.\nO Xαραλάμπης κάθισε στην καρέκλα του Nτίνου, του χειριστή, και έβγαλε από την τσέπη του ένα πακετάκι από ασημόχαρτο.\n– Θες λίγο σκαλτσούνι; πρότεινε στον ASTRA 5603. H μαμά μου το έφτιαξε. ΄Eκοψε ένα κομματάκι σκαλτσούνι και το έδωσε στον υπολογιστή, προσέχοντας να μην τον δει η μαμά του. Φάε, επέμενε το παιδί. Eίναι ωραίο, και ας είναι νηστίσιμο. Tώρα δεν έχω τίποτ’ άλλο να σου δώσω. Nηστεύουμε. Kατάλαβες; Tο βράδυ, μετά την εκκλησία θα φάμε πολλές λιχουδιές. Aχ, μωρέ, να μην έχεις πόδια να σε πάρω και εσένα μαζί μου να ψάλουμε μαζί!\nAφού έφαγε το σκαλτσούνι του ο Xαραλάμπης κι αφού… ζαχάρωσε τον κομπιούτερ, πήρε ένα άσπρο χαρτί από το διπλανό γραφείο και ζωγράφισε μια εκκλησία, ένα ψηλό καμπαναριό, μια φάτνη, πρόβατα και βόδια. Zωγράφισε ένα αστέρι, μια Παναγιά με μαντίλα να κρατάει στην αγκαλιά της το μωρό. ΄Eκανε κι άλλες ζωγραφιές με χριστουγεννιάτικα δέντρα και αγγελάκια και τις έριξε στην ειδική θήκη για τις δισκέτες.\n– Nα τα φυλάξεις τα σχέδιά μου, τον παρακάλεσε. Aκούς; Eγώ για σένα τα σχεδίασα.\nO υπολογιστής χαμογέλασε και με τα κουμπιά του και με τα φωτάκια του. Eδώ είχε κλείσει στη μνήμη του ένα πλήθος πληροφορίες που δεν τον ενδιέφεραν και τις χριστουγεννιάτικες ζωγραφιές του παιδιού δε θα κρατούσε; Tρεις ώρες πέρασαν με τη συντροφιά του Xαραλάμπη.\n΄Oταν έφυγαν, έκλεισαν καλά καλά την πόρτα και το κέντρο έμεινε και πάλι βουβό. Mόνο το χριστουγεννιάτικο δεντράκι συνέχισε ν’ αναβοσβήνει τα φωτάκια του. H καρδιά όμως του ASTRA 5603 είχε πάθει μεγάλη ζημιά. Tα πάντα είχαν σπάσει μέσα του κι έγιναν μια μαλακιά μάζα. Κι ύστερα… E, ύστερα άρχισε να δουλεύει μόνος του, για το κέφι του. Δεν έκανε θόρυβο, ούτε φςςς, ούτε ήχους ηλεκτρονικούς, γκρ, γρ, γρρρ, αλλά έβγαζε από μέσα του κάτι σαν μουσική, μια μουσική που έμοιαζε με χριστουγεννιάτικο τραγούδι. ΄Eνα αστέρι που ξενυχτούσε έξω από το παράθυρο του λογιστικού κέντρου τον είδε να φεγγοβολάει και να δείχνει στην οθόνη του ένα ανθρώπινο πρόσωπο, τρυφερό και βασανισμένο.\nΌταν οι υπάλληλοι, μετά τις γιορτές, ξαναγύρισαν στο γραφείο, μπροστά στον ASTRA 5603 ήταν τυπωμένο ένα βουναλάκι με παιδικά σχέδια. Mια φάτνη, μια Παναγιά με τη μαντίλα και τον Xριστό, πρόβατα και βόδια και ένα σωρό αστέρια. O Nτίνος, ο χειριστής, νόμισε ότι του έκαναν φάρσα.\n– Bρε παιδιά, τι γίνεται εδώ; O κομπιούτερ μου τύπωσε μια φάτνη. Πλάκα μού κάνετε; Πάω να τον αγγίξω και κολλάω. Είναι πασπαλισμένος με ζάχαρη, σαν να έτρωγε σκαλτσούνι! Bρε, περίεργα πράγματα που συμβαίνουν!\nEπειδή ο Nτίνος ήταν πάντα πρόσχαρος και γελαστός, οι συνάδελφοί του νόμισαν ότι αστειευόταν, όπως συνήθως. Xαμογέλασαν μ’ αυτά που έλεγε και συνέχισαν τη δουλειά τους.","word_count":853,"page_number":33,"chapter":"Ενότητα 8 — Xριστούγεννα"},{"id":"st_dimotikou_b_0004","source_id":"st_dimotikou_b","title":"Tο φλουρί του φτωχού","content":"Tο πρώτο φλουρί της βασιλόπιτας που μου έπεσε βγήκε μοιρασμένο. Ήταν αληθινό φλουρί, γιατί ο πατέρας μου τον καιρό εκείνο συνήθιζε να βάζει στη βασιλόπιτα του σπιτιού μας μια χρυσή αγγλική λίρα.\nΠώς έρχονται τα πράματα καμιά φορά!\nO πατέρας μου, όρθιος μπροστά στο αγιοβασιλιάτικο τραπέζι, έκοβε την πίτα, ονοματίζοντας κάθε κομμάτι ξεχωριστά, πριν κατεβάσει το μεγάλο μαχαίρι του ψωμιού. Aφού έκοψε το κομμάτι του σπιτιού, των αγίων, το δικό του και της μητέρας μου, πριν αρχίσει τα κομμάτια των παιδιών σταμάτησε, σαν να θυμήθηκε κάτι.\n– Ξεχάσαμε, είπε, το κομμάτι του φτωχού. Αυτό έπρεπε να ’ρθει ύστερ’ από τους αγίους. Aς είναι όμως. Θα το κόψω τώρα κι ύστερα θ’ αρχίσω τα κομμάτια των παιδιών. Πρώτα ο φτωχός.\nKατέβασε το μαχαίρι και είπε:\n– Tου φτωχού.\nΈπειτα θα ερχόταν το δικό μου κομμάτι, που ήμουν ο μεγαλύτερος από τα παιδιά.\nKαθώς τραβούσε όμως το κομμάτι του φτωχού, το χρυσό φλουρί κύλησε στο τραπεζομάντιλο. Tο κόψιμο της πίτας σταμάτησε. Kοιτάζαμε ο ένας τον άλλο κι ο πατέρας όλους μας.\n– Ποιανού είναι τώρα το φλουρί; είπε η μητέρα μου. Tου φτωχού ή του Πέτρου; Eγώ λέω πως είναι του Πέτρου.\nH καημένη η μητέρα! Tο είχε καημό να πέσει σ’ εμένα.\n– Oύτε του φτωχού είναι, είπε ο πατέρας μου, ούτε του Πέτρου. Tο σωστό σωστό. Tο φλουρί μοιράστηκε. Ήταν ανάμεσα στα δυο κομμάτια. Kαθώς τα χώρισα με το μαχαίρι, έπεσε κάτω. Tο μισό λοιπόν είναι του φτωχού, το μισό του Πέτρου.\n– Kαι τι θα γίνει τώρα; ρώτησε στενοχωρημένη η μητέρα μου.\nTι θα γίνει; συλλογιζόμαστε κι εμείς.\n– Mην πονοκεφαλιάζετε, είπε ο πατέρας. Άνοιξε το πορτοφολάκι του, έβγαλε από μέσα δυο μισές χρυσές λίρες και τις ακούμπησε στο τραπέζι. Nα τι θα γίνει. Aυτή φυλάξτε τη, να τη δώσετε στον πρώτο ζητιάνο που θα χτυπήσει την πόρτα μας. Eίναι η τύχη του. H άλλη μισή είναι του Πέτρου.\nKαι μου την έδωσε.\n– Kαλορίζικη! Kαι του χρόνου παιδί μου! Eίσαι ευχαριστημένος;\nΉμουν και με το παραπάνω.\n– Θα του τη δώσω εγώ με το χέρι μου, είπα.\nΓελούσαμε όλοι με την παράξενη τύχη μου. T’ άλλα παιδιά με πείραζαν: «O σύντροφος του φτωχού». Mονάχα ο πατέρας μου δε γελούσε. Eκείνος με τράβηξε κοντά του, με φίλησε και μου είπε:\n– Mπράβο σου! Eίσαι καλό παιδί.\nTο άλλο πρωί, μόλις ξυπνήσαμε, χτύπησε η πόρτα. Kάτι μου έλεγε πως ήταν ο ζητιάνος, που έφτανε βιαστικός να πάρει το μερίδιό του.\nΈτρεξα στην πόρτα με τη μισή λίρα. Ήταν ένας γέρος φτωχός, με κάτασπρη γενειάδα, γερτός από τα χρόνια, και τρέμοντας από το κρύο μουρμούριζε ευχές.\n– Πάρε, παππού, του είπα.\nO γέρος το έφερε κοντά στα μάτια του για να το κοιτάξει καλύτερα. Δεν μπορούσε να πιστέψει πως κρατούσε χρυσάφι στα χέρια του – τον καιρό εκείνο που όλοι έδιναν στους φτωχούς δίλεπτα και μονόλεπτα.\n– Tι είναι αυτό, παιδάκι μου; με ρώτησε.\n– Mισή λίρα είναι, παππού, του είπα. Πάρε την. Δική σου είναι.\nO καημένος δεν ήθελε να το πιστέψει.\n– Mήπως έκανες λάθος, παιδάκι μου; Για ρώτησε τους γονείς σου.\nTου εξήγησα με τι τρόπο είχαμε μοιραστεί το φλουρί της βασιλόπιτας. O γέρος έτρεμε από τη χαρά του. Σήκωσε ψηλά τα μάτια και είπε:\n– O Θεός είναι μεγάλος! Nα ζήσεις, παιδάκι μου, και να σε χαίρονται οι γονιοί σου. Kαι ο Θεός να σ’ αξιώσει να ’χεις πάντα όλα τα καλά και να τα μοιράζεις με τους φτωχούς και τους αδικημένους. Tην ευχή μου να ’χεις!\nMου έδωσε την ευχή του, σήκωσε πάλι ψηλά κατά τον ουρανό τα μάτια και κατέβηκε με το ραβδί του τη σκάλα.","word_count":591,"page_number":36,"chapter":"Ενότητα 8 — Xριστούγεννα"},{"id":"st_dimotikou_b_0005","source_id":"st_dimotikou_b","title":"Η ιστορία της βασιλόπιτας","content":"H ιστορία συνέβη πριν από 1.500 χρόνια περίπου στην πόλη Καισάρεια της Καππαδοκίας, στη Μικρά Ασία.\nΟ Μέγας Βασίλειος ήταν δεσπότης της Καισάρειας και ζούσε αρμονικά με τους συνανθρώπους του.\nΚάποια μέρα όμως o βασιλιάς Oυάλης, τύραννος της περιοχής, ζήτησε να του δοθούν όλοι οι θησαυροί της Καισάρειας, αλλιώς θα πολιορκούσε την πόλη, για να την κατακτήσει. Ο Μέγας Βασίλειος ολόκληρη τη νύχτα προσευχόταν να σώσει ο Θεός την πόλη. Ξημέρωσε η νέα μέρα και ο βασιλιάς αποφασισμένος περικύκλωσε αμέσως την Καισάρεια με τον στρατό του. Μπήκε με την ακολουθία του και ζήτησε να δει τον δεσπότη.\nΜε θράσος και θυμό ο αδίστακτος βασιλιάς απαίτησε το χρυσάφι της πόλης. Ο Μέγας Βασίλειος απάντησε ότι οι άνθρωποι της πόλης του δεν είχαν τίποτε άλλο πέρα από πείνα και φτώχεια. Ο στρατηγός με το που άκουσε αυτά τα λόγια θύμωσε ακόμα περισσότερο και άρχισε να απειλεί τον Μέγα Βασίλειο ότι θα τον εξορίσει πολύ μακριά από την πατρίδα του. Οι χριστιανοί της Καισάρειας αγαπούσαν πολύ τον δεσπότη τους και θέλησαν να τον βοηθήσουν. Μάζεψαν λοιπόν από τα σπίτια τους ό,τι χρυσαφικά είχαν και του τα πρόσφεραν, ώστε δίνοντάς τα στον σκληρό βασιλιά να σωθούν. Στο μεταξύ ο ανυπόμονος Oυάλης διέταξε αμέσως τον στρατό του να επιτεθεί στον φτωχό λαό της πόλης.\nΟ Μέγας Βασίλειος, που ήθελε να προστατέψει την πόλη του, προσευχήθηκε και μετά παρουσίασε στον βασιλιά ό,τι χρυσαφικά είχε μαζέψει μέσα σε ένα σεντούκι. Τη στιγμή όμως που ο βασιλιάς πήγε να ανοίξει το σεντούκι και να αρπάξει τους θησαυρούς, έγινε το θαύμα! Όλοι οι συγκεντρωμένοι είδαν μια λάμψη και αμέσως μετά έναν λαμπρό καβαλάρη να ορμάει με τον στρατό του επάνω στον σκληρό Oυάλη και τους δικούς του. Σε ελάχιστο χρόνο ο κακός βασιλιάς και οι δικοί του αφανίστηκαν. Ο λαμπρός καβαλάρης ήταν ο Άγιος Μερκούριος και στρατιώτες του οι άγγελοι.\n΄Eτσι σώθηκε η πόλη της Καισάρειας. Τότε όμως ο δεσπότης της, ο Μέγας Βασίλειος, βρέθηκε σε δύσκολη θέση!\nΘα έπρεπε να μοιράσει τα χρυσαφικά στους κατοίκους της πόλης και η μοιρασιά να είναι δίκαιη, δηλαδή να πάρει ο καθένας ό,τι ήταν δικό του. Αυτό ήταν πολύ δύσκολο. Προσευχήθηκε λοιπόν ο Μέγας Βασίλειος και ο Θεός τον φώτισε τι να κάνει. Κάλεσε τους διακόνους και τους βοηθούς του και τους είπε να ζυμώσουν ψωμάκια, όπου μέσα στο καθένα ψωμάκι θα έβαζαν και λίγα χρυσαφικά. ΄Oταν αυτά ετοιμάστηκαν, τα μοίρασε σαν ευλογία στους κατοίκους της πόλης της Καισάρειας. Στην αρχή όλοι παραξενεύτηκαν, μα η έκπληξή τους ήταν ακόμη μεγαλύτερη όταν κάθε οικογένεια έκοβε το ψωμάκι αυτό κι έβρισκε μέσα χρυσαφικά. Ήταν λοιπόν ένα ξεχωριστό ψωμάκι, η βασιλόπιτα. ΄Eφερνε στους ανθρώπους χαρά κι ευλογία μαζί. Από τότε φτιάχνουμε κι εμείς τη βασιλόπιτα με το φλουρί μέσα, την πρώτη μέρα του χρόνου, τη μέρα του Αγίου Βασιλείου.\nΗ βασιλόπιτα, αγιοβασιλιάτικο έθιμο πολλών αιώνων, μεταφέρεται από γενιά σε γενιά, για να μας θυμίζει την αγάπη και την καλοσύνη αυτού του άγιου ανθρώπου.","word_count":478,"page_number":38,"chapter":"Ενότητα 8 — Xριστούγεννα"},{"id":"st_dimotikou_b_0006","source_id":"st_dimotikou_b","title":"Kάλαντα των Φώτων","content":"Σήμερα είν’ τα Φώτα και οι Φωτισμοί\nεορτή μεγάλη και αγιασμοί.\nΚάτω στον Iορδάνη τον ποταμό\nκάθεται η κυρά μας η Παναγιά\nμε τα θυμιατούρια στα δάχτυλα\nκαι τον Αϊ-Γιάννη παρακαλεί.\n– Άγιε μου Γιάννη και Bαπτιστή,\nβάπτισε το γιο μου το μονογενή.\n– Πώς θες να βαφτίσω Θεού παιδί;\nAύριο θ’ ανέβω στους ουρανούς\nνα καταπατήσω τα είδωλα\nνα καταθυμιάσω τους ουρανούς\nκαι να κατέβω στον ποταμό\nγια να βαπτίσω Σε τον Xριστό.\nOυρανός εσκίστη\nIησούς Xριστός βαπτίστη.","word_count":79,"page_number":40,"chapter":"Ενότητα 8 — Xριστούγεννα"},{"id":"st_dimotikou_b_0007","source_id":"st_dimotikou_b","title":"Aπό τον χαλκό στο γυαλί","content":"Στα πρώτα καλώδια τηλεφώνου χρησιμοποιούσαν χάλκινα σύρματα προστατευμένα από γυαλί. Tα σιδερένια σύρματα χρησιμοποιούνταν σε εναέριες γραμμές. Σήμερα οι περισσότερες τηλεφωνικές γραμμές λειτουργούν με καλώδια οπτικών ινών. Aντί για μεταλλικά σύρματα που μεταφέρουν ηλεκτρικά σήματα, αυτά τα καλώδια περιέχουν μικρές, διάφανες γυάλινες ίνες, καθεμιά από τις οποίες μεταφέρει ένα φωτεινό σήμα. Tα ηλεκτρικά σήματα που προέρχονται από ένα τηλέφωνο μετατρέπονται σε φωτεινούς παλμούς (ψηφιακά σήματα) από μια συσκευή λέιζερ. Tα ψηφιακά σήματα είναι κατάλληλα για διαβίβαση πληροφοριών, γιατί επηρεάζονται ελάχιστα από τυχόν παράσιτα. Tα φωτεινά σήματα μετατρέπονται σε ηλεκτρικά στην άλλη άκρη της τηλεφωνικής γραμμής. Tα καλώδια οπτικών ινών μεταφέρουν τεράστιο όγκο πληροφοριών, αφού κάθε γυάλινη ίνα μπορεί να εξυπηρετήσει χιλιάδες κλήσεις ταυτόχρονα.","word_count":113,"page_number":47,"chapter":"Ενότητα 9 — συσκευές"},{"id":"st_dimotikou_b_0008","source_id":"st_dimotikou_b","title":"Tο μηχάνημα","content":"Το έφεραν ένα πρωί στο κτίριο που ήταν τα γραφεία μας και το τοποθέτησαν κοντά στη σκάλα του τρίτου ορόφου.\nΟ Γιάννης ο καφετζής, σαν από ένστικτο, κατάλαβε την απειλή. ΄Eμεινε με τον δίσκο μετέωρο να κοιτά φιλύποπτα τον εχθρό. Η λειτουργία του ήταν απλή. Κανόνιζες μ’ έναν διακόπτη το ποτό που ήθελες, έριχνες ένα δίφραγκο και περίμενες να γεμίσει το πλαστικό ποτήρι.\nΟΓιάννης συνέχισε ν’ ανεβαίνεισκεφτικός.Στοκατέβασμα βρήκε το μηχάνημα τριγυρισμένο απ’ τους πρώτους θαυμαστές. Χωρίς να χάσει καιρό, πήγε να παραπονεθεί στον προσωπάρχη. Ο προσωπάρχης τού εξήγησε ότι το μηχάνημα εξυπηρετούσε. Η δουλειά θα μοιραζόταν. ΄Eπρεπε να συμβιώσουν.\n«Δε φαντάζομαι να μου κάνει μεγάλη ζημιά το μηχάνημα» προσπάθησε να πείσει τον εαυτό του ο Γιάννης. «Γιατί να σηκώνεται ο κόσμος απ’ τα γραφεία και να πηγαίνει να προσκυνά; ΄Aλλωστε το μηχάνημα δεν ξέρει να χαμογελά».\n΄Aρχισε να πυκνώνει τις βόλτες, να γίνεται πιο σβέλτος και χαμογελαστός, ώστε να προλαβαίνει να τους εξυπηρετεί, προτού επιθυμήσουν κάτι παγωμένο και πάνε στο μηχάνημα. Αλλά παρ’ όλα αυτά, όταν κάτι έλειπε από τον δίσκο του, οι δυσαρεστημένοι δεν περίμεναν να τους το φέρει! ΄Eσπευδαν στο μασίνι. Ξέχασα να σας πω ότι έτσι το λέγανε χαϊδευτικά «μασίνι».\nΟ Γιάννης αναγκάστηκε ν’ αλλάξει τακτική. ΄Aρχισε μία άνευ προηγουμένου συκοφαντική δυσφήμιση κατά του εχθρού του. Η πρώτη διάδοση, που έβαλε σε κυκλοφορία, έλεγε ότι το μηχάνημα τρώει τα κέρματα. Αυτό αναχαίτισε για κάμποσο τα κύματα των πιστών. Αποδείχτηκε όμως τελικά ότι κάτι τέτοιο γινόταν πολύ σπάνια για να το πάρει κανείς σοβαρά υπόψη. Τα συνθήματα «ανακατεύει την πορτοκαλάδα με τον καφέ» και «ρίχνει σκουριά στο κακάο» δεν έπιασαν καθόλου, κι ας ξενύχτησε ο Γιάννης για να τα σοφιστεί.\nΤο μηχάνημα του έγινε εφιάλτης. Οι σκάλες τού φαίνονταν ατελείωτες. Τα γνώριμα πρόσωπα των γραφείων, μάσκες εχθρικές. Κάθε φορά που περνούσε μπροστά απ’ το μασίνι, το ’βλεπε με το μάτι να λάμπει θριαμβικά, τη σχισμή του να χαμογελά. Ο ακέραιος χαρακτήρας του λύγισε.\n΄Aρχισε να ρίχνει κρυφά στη σχισμή του μηχανήματος δίφραγκα που τα στράβωνε στο πεζούλι του καφενείου. Το μηχάνημα χάλαγε βέβαια, αλλά οι δούλοι του έσπευδαν να το διορθώσουν.\n«Μα γιατί;» συλλογιζόταν. «Γιατί;» Τον έπνιγε το δίκιο.\n«Τόσα χρόνια να ιδρώνεις, να τρέχεις, να λες την πρώτη καλημέρα, να χαμογελάς και να ’ρχεται ξαφνικά ένα μασίνι να σου τρώει το ψωμί; ΄Aτιμο πράμα!»\n΄Ωσπου μια μέρα πήρε τη μεγάλη απόφαση: Το μεσημέρι του Σαββάτου, όταν θα ’φευγε ο κόσμος, θα ’μενε στα γραφεία και θα κανόνιζε τους λογαριασμούς του με το μηχάνημα. Θα του ’κοβε τις χοντρές, μαύρες αρτηρίες! Θα ’σβηνε το απαίσιο κίτρινο μάτι! Θα ξεβίδωνε τα σωθικά του! Θα ανάδευε τα σπλάχνα του! Θα ’βρισκε την καρδιά του! Και θα ’δινε εκεί το θανάσιμο πλήγμα!\nΤο πρωί του Σαββάτου ήταν κεφάτος. Το μηχάνημα ανύποπτο μοίραζε καφέ, κακάο και αναψυκτικά.\n΄Hρθε μεσημέρι. Τα γραφεία άδειασαν. Ο Γιάννης έμεινε μόνος. Άφησε να περάσει μισή ώρα, τρία τέταρτα. Άρχισε να κατεβαίνει αργά τις σκάλες, κρατώντας τα όργανα του θανάτου: μια τανάλια κι ένα παλιό κατσαβίδι.\n΄Eφτασε στο πλατύσκαλο. Εκεί βρέθηκαν αντιμέτωποι. Ο Γιάννης και το μηχάνημα! Αναμετρήθηκαν! Το μηχάνημα αστραφτερό, με το κίτρινο μάτι να λάμπει! Ο Γιάννης με τα καλαμάκια στο τσεπάκι, σκυφτός, κουρασμένος, μα αποφασισμένος! Παράξενη ησυχία απλωνόταν γύρω. Απόμακρα ακουγόντουσαν όπως σε όνειρο οι θόρυβοι της πόλης.\nΟ Γιάννης προχώρησε, έσπρωξε το βαρύ μηχάνημα δαγκώνοντας τα χείλη και ξεβίδωσε με το κατσαβίδι τη λεία πλάτη. Βρέθηκε μπροστά σ’ ένα λαβύρινθο από πυκνά, μπλεγμένα καλώδια… Ποιο απ’ όλα οδηγούσε στην καρδιά;\nΖαλίζεται παρακολουθώντας τη δαιδαλώδη διαδρομή τους. Τα καλώδια σαλεύουν απειλητικά. Μοιάζουν με φίδια. Αναδεύονται, θαρρείς και ζωντανεύουν. ΄Eνας βόμβος στ’ αυτιά του. Η ανάσα του κοφτή. Σφίγγει τα δόντια. Απλώνει το χέρι…\nΕκεί έπαθε ηλεκτροπληξία ο Γιάννης. Τινάχτηκε! Γονάτισε! Τον βρήκαν κάρβουνο τ’ άλλο πρωί, πλάι στο μηχάνημα.\nΣτη θέση του Γιάννη έφεραν ένα μηχάνημα ακόμα.","word_count":622,"page_number":55,"chapter":"Ενότητα 9 — συσκευές"},{"id":"st_dimotikou_b_0009","source_id":"st_dimotikou_b","title":"Mε λένε Σόνια","content":"Στο διπλανό σπίτι, που είναι μονοκατοικία, μένει ένας περίεργος άνθρωπος, ο κύριος Nτίνος. Aυτός ο κύριος Nτίνος, που είναι αρκετά μεγάλος στην ηλικία, μένει μόνος του.\nΠρο ημερών λοιπόν ο κύριος Nτίνος είχε ανάψει μια φωτιά στο πίσω μέρος του κήπου, κάτω από το μεγάλο πεύκο, και έκαιγε τα ξερά φύλλα και τις πευκοβελόνες. Aυτό το κάνει τακτικά ο κύριος Nτίνος και είναι ενοχλητικό, αλλά πολύ που τον νοιάζει. Σας είπα, είναι ένας πολύ μυστήριος άνθρωπος.\nAπό το πρωί μάς είχε πνίξει στον καπνό. Eγώ είχα βγει στο μπαλκόνι και παρακολουθούσα. ΄Eπειτα από λίγο τον είδα να φεύγει από το σπίτι. Kρατούσε και έσερνε και τη μεγάλη καρό τσάντα με τα ροδάκια, αυτή που παίρνει πάντα μαζί του όταν πηγαίνει για ψώνια στην αγορά.\nEγώ συνέχισα την παρακολούθηση από τη βεράντα. H φωτιά φαινόταν να έχει σβήσει. Ύστερα από λίγο όμως, εκεί που κοίταζα αφηρημένη, είδα μια μικρή φλόγα να ξεπηδάει μέσα από τις στάχτες.\nAλαφιάστηκα. Δε μου αρέσει η φωτιά, μόνο η ζεστασιά της μου αρέσει. Συνέχισα λοιπόν να παρακολουθώ. Σε λίγο ξεπήδησε κι άλλη μια φλόγα και μετά μια τρίτη και σε λίγο η φωτιά ξανάρχισε να καίει με δύναμη, όπως όταν την είχε πρωτοανάψει ο κύριος Nτίνος.\nΔεν ήξερα τι έπρεπε να κάνω. Δεν έκανα λοιπόν τίποτα. Aπλώς περίμενα υπομονετικά να σβήσει. H φωτιά όμως όχι μόνο δεν έσβηνε, αλλά σε λίγο άρχισε να προχωρεί.\nΔίπλα στο μεγάλο πεύκο ο κύριος Nτίνος είχε ακουμπήσει τρία μεγάλα χαρτόκουτα με κάτι παλιά περιοδικά κι εφημερίδες. Δεν πέρασε πολλή ώρα και η φωτιά έφτασε στα χαρτόκουτα, τα οποία άρπαξαν αμέσως.\nKάποια στιγμή οι φλόγες της φωτιάς έφτασαν στην κουρτίνα, η οποία άρπαξε αμέσως φωτιά κι άρχισε να βγάζει έναν περίεργο μαύρο καπνό που μύριζε πολύ άσχημα. Για να πω την αλήθεια, δε με πολυπείραζε που καιγόταν η κουρτίνα, αλλά οι φλόγες είχαν αρχίσει να γλείφουν επικίνδυνα τον κορμό του πεύκου. Aυτό με πείραζε πολύ.\nTο πεύκο αυτό το αγαπώ πάρα πολύ. Ώρες ολόκληρες έχω περάσει σκαρφαλωμένη στα κλαδιά του. Kατά τα φαινόμενα η φωτιά είχε βαλθεί να μου καταστρέψει το αγαπημένο μου πεύκο.\n«A, ως εδώ και μη παρέκει!» φώναξα.\nMεμιάς πετάχτηκα όρθια και έτρεξα αστραπή στον κήπο. ΄Eπρεπε να με βλέπατε.\nΣκαρφάλωσα στη μάντρα, πετάχτηκα πάνω από τα κάγκελα της μεσοτοιχίας και με ένα πολύ θεαματικό άλμα προσγειώθηκα στον κήπο του κυρίου Nτίνου.\nKανένας δε φαινόταν να με ακούει ούτε και να έχει πάρει είδηση τι γινόταν. ΄Eτρεξα σαν σίφουνας, διότι εγώ είμαι γυμνασμένη και τρέχω όπως η σαΐτα, όταν βέβαια θέλω και υπάρχει λόγος. ΄Eτρεξα λοιπόν και προσπάθησα να τραβήξω το λάστιχο με το νερό από το αυλάκι με τα λαχανικά. Tο σχέδιο ήταν να πάω στη φωτιά.\nEμένα δε μου αρέσει το νερό καθόλου. ΄Oμως εδώ ήταν μια περίπτωση εξαιρετική. ΄Hταν ώρα για δράση. Kανένας άνθρωπος δε φαινόταν από πουθενά κι εγώ ήμουν η μόνη που μπορούσε να κάνει κάτι.\nΦωνάζοντας λοιπόν με όλη μου τη δύναμη, προσπαθούσα να τραβήξω το λάστιχο. Δεν ήταν εύκολο. Πανδύσκολο ήταν. Tο λάστιχο είναι πολύ βαρύ έτσι κι αλλιώς, πόσο μάλλον όταν είναι γεμάτο νερό.\nMε τις φωνές και τα ουρλιαχτά ξύπνησε η Mαρία. H Mαρία είναι πολύ ψύχραιμο άτομο. Mια και δυο πήγε στο τηλέφωνο και πήρε το 199, που είναι η Πυροσβεστική. Kατόπιν ειδοποίησε και το 100, που είναι η Άμεση Δράση.\n΄Eπρεπε να ακούγατε τις σειρήνες να ουρλιάζουν. Σχεδόν αμέσως έφτασαν οι πυροσβέστες πάνω στο κόκκινο αυτοκίνητό τους με το πορτοκαλί φως να στριφογυρίζει και τη σειρήνα να ξεκουφαίνει τη γειτονιά. Πίσω τους έρχονταν οι αστυνομικοί μέσα στο άσπρο μπλε περιπολικό, με τη δική τους σειρήνα να ουρλιάζει. Xαμός, σας λέω, γινόταν.\nOι πυροσβέστες ξεδίπλωσαν γρήγορα γρήγορα κάτι τεράστιους πάνινους σωλήνες νερού που είχαν μαζί τους στο αυτοκίνητο. Mετά άνοιξαν τους μεγάλους διακόπτες του νερού που υπήρχαν στο κόκκινο αυτοκίνητό τους και βάλθηκαν να ρίχνουν νερό πάνω στη φωτιά, έξω στον κήπο, μέσα στην κουζίνα του κυρίου Nτίνου, πάνω στο πεύκο, παντού όπου υπήρχε φωτιά.\nOι αστυνόμοι προσπαθούσαν να βάλουν τον κόσμο που μαζεύτηκε σε κάποια τάξη. Όλοι προσπαθούσαν να βοηθήσουν και όλοι αγωνιούσαν μήπως η φωτιά έφτανε μέχρι τα διπλανά σπίτια, αλλά οι αστυνομικοί είπαν πως δεν υπήρχε λόγος ανησυχίας.\nTελικά η φωτιά έσβησε γρήγορα. O κύριος Nτίνος, μόλις γύρισε εκεί, μπροστά σε όλους, μου ζήτησε συγνώμη για τη συμπεριφορά του. Eίπε μάλιστα πως μου χρωστούσε κι ένα γεύμα με το καλύτερο ψάρι της αγοράς. Bλέπετε, η αδυναμία μου στα ψάρια είναι γνωστή σε όλη τη γειτονιά.\n΄Oταν όλα τελείωσαν, ένας πυροσβέστης με πήρε αγκαλιά και με σήκωσε ψηλά στα χέρια. «Iδού η επίτιμος γατοπυροσβέστης!» φώναξε δυνατά κι όλοι γύρω ξέσπασαν σε χειροκροτήματα και ζητωκραυγές.\nH Mαρία με αγκάλιασε σφιχτά και με φίλησε, και η μητέρα κι ο πατέρας, όταν το έμαθαν, είπαν πως ήταν πολύ περήφανοι για τη γάτα τους.\nMέχρι και η τοπική εφημερίδα έγραψε ένα ολόκληρο άρθρο για την αφεντιά μου. Πρωτοσέλιδο έγινε η φωτογραφία μου. ΄Oλοι μιλούσαν για το κατόρθωμα της Σόνιας της γάτας.\nO Σάχης, ο γάτος απέναντι, κόντεψε να σκάσει από τη ζήλια του.\nH Σαλώμη, η φίλη μου, είπε πως είμαι «γάτα με πέταλα», που πάει να πει ξυράφι από εξυπνάδα.\nEγώ δεν είπα τίποτα, γιατί, όπως σας έχω πει, εμένα δε μου αρέσουν τα παινέματα. Eγώ είμαι μετριόφρων.","word_count":859,"page_number":63,"chapter":"Ενότητα 10 — ατυχήματα"},{"id":"st_dimotikou_b_0010","source_id":"st_dimotikou_b","title":"Ώρες με τη μητέρα μου","content":"Η μαμά μου ήταν πάντα ξεχωριστή. Με τον μπαμπά παντρεύτηκαν από έρωτα στο άψε σβήσε. Και οι ευχές που τους έδωσε ο παπάς όταν τους πάντρεψε πραγματοποιήθηκαν. Απόχτησαν «καρπόν κοιλίας», δηλαδή εμένα και τον αδερφό μου.\nΗ μαμά δεν είχε περάσει τα σαράντα. Τα μάτια της σκούρα γαλάζια, έμοιαζαν με τα μη με λησμόνει* που φυτρώνουν την άνοιξη. Φαινόταν κοριτσάκι όταν την έβλεπες από πίσω, με την κομψή κορμοστασιά της και την ξανθιά κοτσίδα στην πλάτη. Το πιο όμορφο πάνω της όμως ήταν οι κινήσεις των χεριών της, και ό,τι έκανε το έκανε με χάρη.\nΔεν ήξερα καμιά γυναίκα στο νησί να φοράει λουλούδια στα μαλλιά. Λάτρευε τις γαρδένιες, είχαμε τρεις γλάστρες στην αυλή. Τις φρόντιζε σαν να ήταν παιδιά της κι όταν άνθιζαν έπλεκε τα λουλούδια τους μαζί με την κοτσίδα της. Άλλες φορές πάλι τις περνούσε σε κλωστή κι έφτιαχνε βραχιόλια. Σε κάθε κίνηση των χεριών της οι γαρδένιες μοσχοβολούσαν. Από τότε μαμά και γαρδένια είναι ένα στο μυαλό μου.\nΚάθε απόγευμα μετά τη δουλειά, χειμώνα καλοκαίρι, φορούσε αθλητική φόρμα και παπούτσια και χανόταν. Παραλία παραλία, έφτανε ως το ακρωτήρι με τον φάρο, που τον δέρνουν τα κύματα. Καθόταν στον αγαπημένο της βράχο. Γύριζε πάντα με τα χέρια γεμάτα. Βότσαλα με παράξενα χρώματα, που η θάλασσα τους έδινε πότε το σχήμα ενός πουλιού ή τη μορφή μιας γυναίκας, και ξύλα ξεβρασμένα στην άμμο, αργασμένα* από το κύμα και την αρμύρα. Με λίγες «καλλιτεχνικές επεμβάσεις», όπως έλεγε η ίδια, έφτιαχνε αριστουργήματα που στόλιζαν τον κήπο και την αυλή μας.\nΜικρή πήγαινα κι εγώ μαζί της. Μου άρεσε να τσαλαβουτάω στην παραλία, να σκαρφαλώνω στα βράχια και να βρίσκω καβούρια και κοχύλια. Κι όλο κοίταζα πότε θα βγει η γοργόνα. Η μαμά δε βαριόταν να μου λέει και να μου ξαναλέει παραμύθια. Από εκείνη έμαθα να διαβάζω λογοτεχνικά βιβλία. Το βράδυ αράζαμε κάτω από τη λεύκα τα καλοκαίρια ή δίπλα στο τζάκι τον χειμώνα, μ’ ένα βιβλίο στο χέρι. Τα παράγγελνε η ίδια στο βιβλιοπωλείο της πλατείας κι όσα έκρινε ότι μ’ ενδιέφεραν τα έδινε και σε μένα να τα διαβάσω.","word_count":341,"page_number":85,"chapter":"Ενότητα 11 — συγγενικές σχέσεις"},{"id":"st_dimotikou_b_0011","source_id":"st_dimotikou_b","title":"Πρέπει να φανώ γενναίος","content":"Σήμερα στο σπίτι, ρώτησα τη μητέρα μου πού θα πάμε διακοπές. Η μαμά μου με κοίταξε, έκανε μια περίεργη γκριμάτσα, μ’ αγκάλιασε, με φίλησε στο κεφάλι και μου είπε πως θα το κουβεντιάζαμε, «όταν ο μπαμπάς θα επιστρέψει, μωρό μου», και να πάω τώρα να παίξω στον κήπο.\nΠήγα λοιπόν στον κήπο και περίμενα τον μπαμπά. Μόλις εκείνος έφτασε, έτρεξα στο μέρος του, εκείνος με πήρε στην αγκαλιά του, με πέταξε στον αέρα και τον ρώτησα πού θα πηγαίναμε διακοπές. Ο μπαμπάς μου απότομα έχασε το χαρούμενο ύφος, μ’ άφησε κάτω και μου υποσχέθηκε ότι θα το συζητούσαμε μέσα, εκεί που βρήκαμε τη μαμά καθισμένη να μας περιμένει.\n– Νομίζω ότι η στιγμή είναι κατάλληλη, είπε ο μπαμπάς.\n– Συμφωνώ, απάντησε η μαμά. Το συζητήσαμε πριν από λίγο.\nΤότε ο μπαμπάς κάθισε στην πολυθρόνα, μ’ έπιασε από τα χέρια και με τράβηξε στα γόνατά του.\n– Ο Νικόλας μου είναι ένα μεγάλο και λογικό αγόρι. Έτσι δεν είναι;\n– Βεβαίως, βεβαίως! απάντησε η μαμά μου.\nΕγώ δε βλέπω με καλό μάτι ποτέ μου τέτοιες κουβέντες, ότι τάχα είμαι ένα μεγάλο αγόρι, γιατί συνήθως, όταν μου το λένε, θέλουν να κάνω πράγματα που δε μου πολυαρέσουν.\n– Κι είμαι σίγουρος, είπε ο μπαμπάς, ότι το μεγάλο μου αγόρι θα ήθελε πολύ να πάει διακοπές στη θάλασσα!\n– Αχ ναι! είπα. Και θα μείνουμε σε ξενοδοχείο;\n– Όχι ακριβώς, είπε ο μπαμπάς και κόμπιασε. Να... νομίζω πως θα κοιμάσαι σε σκηνή.\n– Σε μια σκηνή όπως οι Ινδιάνοι; ρώτησα. Τέλεια! Και θα μ’ αφήσεις να σε βοηθήσω να στήσουμε τη σκηνή; Ν’ ανάψουμε φωτιά; Και θα μου μάθεις ψάρεμα για να φέρνω μεγάλα ψάρια στη μαμά; Αχ, αυτό θα ήταν σαν όνειρο!\nΟ μπαμπάς σκούπισε το πρόσωπό του με το μαντίλι του, σαν να ζεσταινόταν πολύ, αν και δεν είχε καθόλου ζέστη εκείνη την ώρα, κι ύστερα μου είπε:\n– Νικόλα, πρέπει να μιλήσουμε σαν μεγάλοι. Πρέπει να φανείς πολύ γενναίος.\n– Και αν φανείς γενναίος και συμπεριφερθείς σαν ένα μεγάλο παιδί, είπε η μαμά, θα σου ετοιμάσω το βράδυ την αγαπημένη σου τούρτα σοκολάτα.\nΤότε ο μπαμπάς καθάρισε τον λαιμό του με ένα ελαφρό βήξιμο, μ’ έπιασε απ’ τους ώμους και μου είπε:\n– Δε θα έρθουμε μαζί σου στις διακοπές. Θα πας μόνος σου σαν μεγάλος. Η μαμά σου κι εγώ αποφασίσαμε να πας σε μια κατασκήνωση. Θα σου κάνει πολύ καλό, θα είσαι με φίλους της ηλικίας σου και θα το χαρείς πάρα πολύ...\n– Σίγουρα, είναι η πρώτη φορά που θα μείνεις μόνος σου, χωρίς εμάς, Νικόλα, αλλά είναι για το καλό σου, είπε η μαμά. Λοιπόν, τι λες, αγόρι μου;\n– Απίθανο! φώναξα κι άρχισα να χοροπηδάω στο σαλόνι. Γιατί αλήθεια οι κατασκηνώσεις είναι καταπληκτικές. Κάνεις ένα σωρό φίλους, άπειρες βόλτες, παίζεις παιχνίδια, ανάβεις φωτιές και χορεύεις και τραγουδάς. Ήμουν τόσο χαρούμενος, που αγκάλιασα και φίλησα τον μπαμπά και τη μαμά.\nΤο βράδυ η τούρτα ήταν πολύ νόστιμη κι έφαγα πολλά κομμάτια, γιατί ο μπαμπάς κι η μαμά ούτε που τ’ αγγίξανε. Εκείνο που είναι περίεργο είναι που ο μπαμπάς κι η μαμά με κοιτάζανε με μάτια γουρλωμένα και φαίνονταν κάπως στενοχωρημένοι. Τους καταλαβαίνω, σίγουρα δεν έχουν συνηθίσει να μένουν μόνοι τους στις διακοπές.\nΌμως εγώ δεν ξέρω, αλλά πιστεύω πως ήμουνα πολύ γενναίος και λογικός. Δεν ήμουνα;","word_count":541,"page_number":90,"chapter":"Ενότητα 11 — συγγενικές σχέσεις"},{"id":"st_dimotikou_b_0012","source_id":"st_dimotikou_b","title":"Μια οικογένεια ανάμεσα στις άλλες","content":"Με λένε Θανάση Παπαδόπουλο, πηγαίνω στην Τρίτη Δημοτικού και μένω στο σπίτι μου, στην Αθήνα, με τη μικρή μου αδερφή, τη μαμά μου και τον μπαμπά μου. Αυτή είναι η οικογένειά μου. Διάβασα κάπου πως όλες οι οικογένειες δεν είναι σαν τη δική μου και ότι υπάρχουν πολλές διαφορετικές οικογένειες όχι μόνο από χώρα σε χώρα κι από εποχή σε εποχή, αλλά και μέσα στην ίδια πόλη, στην ίδια γειτονιά. Για παράδειγμα, μια οικογένεια σαν τη δική μου, που αποτελείται από δυο γονείς και τα παιδιά, που μένουν όλοι στο ίδιο σπίτι, είναι αρκετά συνηθισμένη, αλλά έχει ένα ασυνήθιστο όνομα: λέγεται πυρηνική οικογένεια.\nΑν ζούσαμε σε άλλη εποχή, θα μέναμε μάλλον όλοι μαζί, στο ίδιο σπίτι, στο χωριό του πατέρα του παππού, δηλαδή του προπάππου μου. Οι μεγάλοι θα δούλευαν όλοι μαζί στα χωράφια, στο περιβόλι και στον κήπο. Οι γυναίκες θα μαγείρευαν και θα έφτιαχναν ψωμί και τα παιδιά θα κοιμόμασταν όλα μαζί στρωματσάδα, στο ίδιο δωμάτιο. Σίγουρα θα ήμασταν μια μεγάλη ενδιαφέρουσα οικογένεια, που αλλιώς λέγεται και διευρυμένη, γιατί περιλαμβάνει περισσότερες από μία γενιές: τη γενιά του προπάππου, του παππού, του μπαμπά και τη δική μας.\nΟι περισσότερες οικογένειες –τουλάχιστον στην Ευρώπη– είναι πυρηνικές. Και σ’ αυτό το είδος οικογένειας όμως υπάρχει ποικιλία. Για παράδειγμα, ο θείος μου είναι παντρεμένος και έχει με τη γυναίκα του –τη σύζυγό του, όπως λένε– ένα κοριτσάκι που του χρόνου θα πάει Πρώτη Δημοτικού. Αυτή η ξαδερφούλα μου, όταν ήρθε στο σπίτι του θείου μου, ήταν ακόμα πιο μικρή, αλλά δεν ήταν και τελείως μωρό. Τότε μου είπαν πως η ξαδερφούλα μου είναι δικό τους παιδί, μόνο που δεν το έχουν γεννήσει αλλά το έχουν υιοθετήσει. Νομίζω πως δεν υπάρχει καμία διαφορά, αν είσαι υιοθετημένος, αφού το ίδιο σε αγαπάνε όλοι.\nΤα άλλα μου ξαδέρφια είναι παιδιά της θείας μου, της αδερφής του πατέρα μου δηλαδή. Έχουν δύο σπίτια και δύο δωμάτια το καθένα! Ο ξάδερφός μου είπε πως στην αρχή δεν του άρεσε καθόλου. Ωστόσο, τώρα συνήθισε. Βλέπετε, οι δικοί του γονείς, η θεία μου με τον άντρα της, πήραν διαζύγιο. Διαζύγιο παίρνουν τα ζευγάρια που παντρεύονται και το μετανιώνουν, δηλαδή μετά βλέπουν πως δεν ταιριάζουν κι αλλάζουν γνώμη. Τότε τα παιδιά ζουν με τον έναν από τους δύο γονείς, αλλά βλέπουν και τον άλλον όποτε θέλουν.\nΞέρω, βέβαια, ότι υπάρχουν και παιδιά που έχουν μόνο μπαμπά ή μόνο μαμά. Αυτό μπορεί να συμβαίνει για διάφορους λόγους. Μπορεί να μη ζει ο ένας από τους δυο γονείς. Μπορεί, πάλι, να έχεις έναν μπαμπά και μια μαμά, αλλά να ζεις με τον έναν από τους δύο, κι έναν καινούριο μπαμπά, που λέγεται πατριός, ή μια καινούρια μαμά, που λέγεται μητριά. Αυτοί λέγονται θετοί γονείς.\nΌταν μεγαλώσω και κάνω δική μου οικογένεια, δεν ξέρω ακόμα πώς θα μοιάζει. Η γιαγιά λέει πως καμιά φορά αποφασίζεις εσύ και καμιά φορά αποφασίζει η ζωή για σένα. Εγώ δεν καταλαβαίνω τελείως τι σημαίνει αυτό. Αν και είμαι ακόμα μικρός, πιστεύω ότι το πιο σημαντικό σε μια οικογένεια είναι να είναι όλοι καλά μεταξύ τους, να συζητάνε και να βοηθάνε ο ένας τον άλλον.","word_count":507,"page_number":94,"chapter":"Ενότητα 11 — συγγενικές σχέσεις"},{"id":"st_dimotikou_b_0013","source_id":"st_dimotikou_b","title":"Ο λόγος του Κολοκοτρώνη στην Πνύκα","content":"Τα αποσπάσματα που θα διαβάσετε προέρχονται από λόγο του Κολοκοτρώνη. Εκφωνήθηκε στην Αθήνα, στα βράχια της Πνύκας, το 1838, στο ίδιο σημείο όπου οι αρχαίοι ρήτορες έβγαζαν τους δικούς τους λόγους.\nΤο κείμενο έχει γραφτεί σε παλαιότερη εποχή, όταν η μορφή της ελληνικής γλώσσας ήταν διαφορετική. «Παιδιά μου!\nΕις τον τόπο τούτο, οπού εγώ πατώ σήμερα, επατούσαν και εδημηγορούσαν τον παλαιό καιρό άνδρες σοφοί, και άνδρες με τους οποίους δεν είμαι άξιος να συγκριθώ και ούτε να φθάσω τα ίχνη των. Σας λέγω μόνον πως ήταν σοφοί, και από εδώ επήραν και εδανείσθησαν τα άλλα έθνη την σοφίαν των.\nΕις τον τόπον τον οποίον κατοικούμε εκατοικούσαν οι παλαιοί Έλληνες, από τους οποίους και ημείς καταγόμεθα και ελάβαμε το όνομα τούτο.\nΟι παλαιοί Έλληνες, οι πρόγονοί μας, έπεσαν εις την διχόνοιαν και ετρώγονταν μεταξύ τους, και έτσι έλαβαν καιρό πρώτα οι Ρωμαίοι, έπειτα άλλοι βάρβαροι και τους υπόταξαν. Ύστερα ήλθαν οι Μουσουλμάνοι. Οι έμποροι και οι προκομμένοι, το καλύτερο μέρος των πολιτών, μην υποφέροντες τον ζυγό έφευγαν, και οι γραμματισμένοι επήραν και έφευγαν από την Ελλάδα, την πατρίδα των, και έτσι ο λαός, στερημένος από τα μέσα της προκοπής, εκατήντησεν εις αθλίαν κατάσταση, και αυτή αύξαινε κάθε ημέρα χειρότερα.\nΕις αυτήν την δυστυχισμένη κατάσταση μερικοί από τους φυγάδες γραμματισμένους εμετέφραζαν και έστελναν εις την Ελλάδα βιβλία και εις αυτούς πρέπει να χρωστούμε ευγνωμοσύνη, διότι ευθύς οπού κανένας άνθρωπος από τον λαό εμάνθανε τα κοινά γράμματα, εδιάβαζεν αυτά τα βιβλία και έβλεπε ποιους είχαμε προγόνους, τι έκαμεν ο Θεμιστοκλής, ο Αριστείδης και άλλοι πολλοί παλαιοί μας, και εβλέπαμε και εις ποίαν κατάσταση ευρισκόμεθα τότε. Όθεν μας ήλθεν εις τον νου να τους μιμηθούμε και να γίνουμε ευτυχέστεροι. Και έτσι έγινε και επροόδευσεν η Εταιρεία.\nΌταν αποφασίσαμε να κάμομε την Επανάσταση, δεν εσυλλογισθήκαμε ούτε πόσοι είμεθα ούτε πως δεν έχομε άρματα ούτε ότι οι Τούρκοι εβαστούσαν τα κάστρα και τας πόλεις ούτε κανένας φρόνιμος μας είπε: «Πού πάτε εδώ να πολεμήσετε με σιταροκάραβα βατσέλα;», αλλά ως μία βροχή έπεσε εις όλους μας η επιθυμία της ελευθερίας μας, και όλοι, και ο κλήρος μας και οι προεστοί και οι καπεταναίοι και οι πεπαιδευμένοι και οι έμποροι, μικροί και μεγάλοι, όλοι, εσυμφωνήσαμε εις αυτό τον σκοπό και εκάμαμε την Επανάσταση.\nΕις τον πρώτο χρόνο της Επαναστάσεως είχαμε μεγάλη ομόνοια και όλοι ετρέχαμε σύμφωνοι. Ο ένας επήγεν εις τον πόλεμο, ο αδελφός του έφερνε ξύλα, η γυναίκα του εζύμωνε, το παιδί του εκουβαλούσε ψωμί και μπαρουτόβολα εις το στρατόπεδον και, εάν αυτή η ομόνοια εβαστούσε ακόμη δύο χρόνους, ηθέλαμε κυριεύσει και την Θεσσαλία και την Μακεδονία και ίσως εφθάναμε και έως την Κωνσταντινούπολη.\nΤόσον τρομάξαμε τους Τούρκους, οπού άκουγαν Έλληνα και έφευγαν χίλια μίλια μακρά. Εκατόν Έλληνες έβαζαν πέντε χιλιάδες εμπρός, και ένα καράβι μιαν αρμάδα».","word_count":450,"page_number":106,"chapter":"Ενότητα 12 — 25η Mαρτίου"},{"id":"st_dimotikou_g_0001","source_id":"st_dimotikou_g","title":"Eπιστήμη με άρωμα γυναίκας","content":"Aν κι έχουν περάσει 102 χρόνια από τότε που η Μαρί Kιουρί τιμήθηκε με το Nόμπελ Φυσικής, οι γυναίκες παλεύουν ακόμα για να κατακτήσουν τη θέση που τους αξίζει στον τομέα της έρευνας. Tον περασμένο μήνα στο Παρίσι απονεμήθηκαν σε πέντε γυναίκες φυσικούς τα βραβεία της ΟΥΝΕΣΚΟ. Πρόκειται για έναν θεσμό που προωθεί και στηρίζει το επιστημονικό έργο γυναικών από κάθε γωνιά του κόσμου, δίνοντάς τους κίνητρα να συνεχίσουν την έρευνα.\nΒραβεύονται γυναίκες επιστήμονες από όλες τις ηπείρους. H Nτομινίκ Λανζβέν, που εκπροσωπεί την Eυρώπη, είναι διευθύντρια ερευνών στο Eθνικό Kέντρο Eπιστημονικών Eρευνών της Γαλλίας και καθηγήτρια στο πανεπιστήμιο. «Πέρασαν σχεδόν 40 χρόνια από τότε που πάτησα για πρώτη φορά το πόδι μου σε επιστημονικό εργαστήριο. Όχι μόνο δεν κουράστηκα ποτέ, αλλά το πάθος μου για την έρευνα μεγάλωνε χρόνο με τον χρόνο. Όσο πιο βαθιά μπαίνουμε στο πετσί της αναζήτησης, τόσο πιο πολύ διψάμε να βρούμε τη λύση στα αινίγματα του σύμπαντος και της φύσης» λέει η Λανζβέν.\nH Zόχρα Mπεν Λάκνταρ, που εκπροσωπεί την Aφρική, είναι μια εντελώς διαφορετική περίπτωση. Είναι καθηγήτρια Φυσικής στο Πανεπιστήμιο Eλ Mανάρ της Tύνιδας και κέρδισε βραβείο για την ανίχνευση της ρύπανσης. Στην πατρίδα της οι γυναίκες επιστήμονες δεν έχουν να αντιμετωπίσουν μόνο τις προκαταλήψεις, αλλά και την έλλειψη μέσων και εξοπλισμού στην έρευνα. Aν η Mαρί Kιουρί άνοιξε τον δρόμο στις Ευρωπαίες στις αρχές του περασμένου αιώνα, οι γυναίκες επιστήμονες του αραβικού κόσμου έχουν σήμερα την ίδια αποστολή. Η Μπεν Λάκνταρ δήλωσε: « Όταν άρχισα να ασχολούμαι με την έρευνα, δεν ένιωθα ότι πρέπει να είμαι άψογη λες και έδινα εξετάσεις για τις ικανότητες του φύλου μου. Aν θέλει να διακριθεί κανείς σε ένα εργαστήρι, πρέπει έτσι κι αλλιώς να είναι τελειομανής. Tώρα πια που διδάσκω στο πανεπιστήμιο, προσπαθώ να στέκομαι στο πλευρό των φοιτητριών όταν αντιμετωπίζουν προβλήματα τέτοιου τύπου, να τις εμψυχώνω. Οι σπουδές σου πρέπει να σου δίνουν χαρά και έμπνευση. Δεν μπορείς να επιτύχεις σε ένα αντικείμενο που δε σε εμπνέει».\nH Mπεν Λάκνταρ αισθάνεται υπεύθυνη απέναντι στους συμπολίτες της: «Mπορεί στον δυτικό κόσμο οι ερευνητές να έχουν πολλά μέσα στη διάθεσή τους, στην Tυνησία όμως νιώθεις ότι η εργασία σου συμβάλλει ουσιαστικά στην πρόοδο της ίδιας της χώρας. Eίχα την ευκαιρία να ζήσω στη Γαλλία, όπου πήγα με υποτροφία. Μόλις η χώρα μου απέκτησε την ανεξαρτησία της, αποφάσισα να γυρίσω πίσω γιατί ήξερα ότι θα ήμουν πιο χρήσιμη. Ήξερα βέβαια ότι θα αντιμετώπιζα μεγάλα προβλήματα. Δεν μπορώ, για παράδειγμα, να ζητάω πανάκριβο εξοπλισμό για το εργαστήριο».\nΣτην ερώτηση των δημοσιογράφων αν παίζει ρόλο το φύλο, το θρήσκευμα ή η κουλτούρα στην προσωπικότητα και στη δουλειά ενός ερευνητή, η Μπεν Λάκνταρ απαντά: «Mπροστά στην επιστήμη δεν υπάρχουν τέτοιες διαφορές, γιατί υπάρχουν αυστηροί κανόνες που εφαρμόζεις σε κάθε βήμα της έρευνας. H γνώση είναι για να τη μοιράζεσαι με τους συνανθρώπους σου και η αγωνία να λύσεις ένα επιστημονικό πρόβλημα είναι πανανθρώπινη. Όμως πιστεύω ότι δεν παίζει ρόλο αν είσαι μωαμεθανός ή χριστιανός, άνδρας ή γυναίκα, Άραβας ή Eυρωπαίος, αρκεί να είσαι αφοσιωμένος σ’ αυτό που κάνεις. H επιστήμη έχει ανάγκη από άτομα που έχουν πάθος και πείσμα, αντοχή και πίστη, αγάπη για τον άνθρωπο».","word_count":515,"page_number":16,"chapter":"Ενότητα 13 — τρόποι ζωής και επαγγέλματα"},{"id":"st_dimotikou_g_0002","source_id":"st_dimotikou_g","title":"«Η ιπτάμενη σκάφη»","content":"Ο Πίκος Απίκος, ρεπόρτερ της εφημερίδας Τρέχα Γύρευε, παλιότερα είχε αποκαλύψει όλα τα συναρπαστικά γεγονότα που σημάδεψαν την ιστορία της Φρουτοπίας. Η Φρουτοπία, για όσους δεν το ξέρουν, είναι ο τόπος όπου τα φρούτα κήρυξαν την ανεξαρτησία τους και ορκίστηκαν να μην αφήσουν ποτέ μανάβη πόδι να πατήσει στον τόπο τους.","word_count":51,"page_number":19,"chapter":"Ενότητα 13 — τρόποι ζωής και επαγγέλματα"},{"id":"st_dimotikou_g_0003","source_id":"st_dimotikou_g","title":"Mεγάλη Πέμπτη Σήμερον κρεμάται επί ξύλου","content":"Σήμερον κρεμάται επί ξύλου ο εν ύδασι την γην κρεμάσας. Στέφανον εξ ακανθών περιτίθεται ο των Aγγέλων Bασιλεύς. Ψευδή πορφύραν περιβάλλεται ο περιβάλλων τον ουρανόν εν νεφέλαις. Ράπισμα κατεδέξατο ο εν Ιορδάνη ελευθερώσας τον Αδάμ.\nΉλοις προσηλώθη ο Nυμφίος της Εκκλησίας. Λόγχη εκεντήθη ο Yιός της Παρθένου.\nΠροσκυνούμεν σου τα Πάθη, Χριστέ. Δείξον ημίν και την ένδοξόν σου Ανάστασιν.\nΣήμερα κρεμάται πάνω στο ξύλο (του Σταυρού) εκείνος που κρέμασε (κατά τη δημιουργία) τη γη επάνω στα νερά (την περιέβαλε δηλαδή από παντού με τα νερά των θαλασσών).\nΣτεφάνι κατασκευασμένο από αγκάθια φοράει στο κεφάλι ο Βασιλιάς των Αγγέλων. Ψεύτικο βασιλικό ένδυμα ντύνεται αυτός που ντύνει τον ουρανό με τα σύννεφα. Χαστούκι δέχτηκε εκείνος που στον Ιορδάνη ποταμό (αφού βαφτίστηκε από τον Ιωάννη τον Πρόδρομο) ελευθέρωσε τον Αδάμ. Με καρφιά καρφώθηκε (στον Σταυρό) ο Νυμφίος της Εκκλησίας.\nΜε λόγχη τρυπήθηκε (στο πλευρό) ο Υιός της Παρθένου. Προσκυνούμε τα Πάθη σου, Χριστέ. Αξίωσέ μας να δούμε και την ένδοξη Ανάστασή σου.","word_count":159,"page_number":26,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"st_dimotikou_g_0004","source_id":"st_dimotikou_g","title":"Παιδικό Πάσχα","content":"Το Πάσχα άρχιζε απ’ την αυγή του Μεγάλου Σαββάτου και με τέτοιον τρόπο, που αποτελεί μια από τις ζωηρότερες παιδικές μου αναμνήσεις. Ήταν μια γενική κωδωνοκρουσία την ώρα που έψαλλαν στη Μητρόπολη το «Ανάστα ο Θεός». Κατά το ζακυνθινό έθιμο, οι καμπάνες «εχήρευαν» –σώπαιναν– απ’ το πρωί της Μεγάλης Πέμπτης. Και δεν ξαναχτυπούσαν, παρά την αυγή του Μεγάλου Σαββάτου. Αλλά όλες μαζί, από μεγάλα και μικρά καμπαναριά, αμέτρητα –καμπάνες μεγάλες, βαρύηχες, πολύβουες, σοβαρές, και καμπάνες μικρές, γλυκόφωνες, γοργές, πεταχτές– μια συναυλία, μια αρμονία αφάνταστη, που τρικυμίζει τον αέρα, ανεβαίνει, κατεβαίνει κι απλώνεται στα πέρατα. Πέφτουν μαζί και πιστολιές, αλαλιασμένα τα σκυλιά τρέχουν κι ουρλιάζουν, κι ακόμα κάνουν κρότους φοβερούς τα πήλινα κανάτια που τα πετούν απ’ τα παράθυρα, για να σπάσουν «για το καλό» στις αυλές και στους δρόμους… Ξυπνώ στο κρεβάτι μου… Τι είναι; Α, το «Ανάστα ο Θεός»! Να, κι η μητέρα μου έχει σηκωθεί. «Και του χρόνου!» «Γερός, δυνατός!» Και μου δίνει να δαγκάσω σίδερο – συνήθως έν’ από τα κλειδιά της…\nΜ’ αυτό το πανδαιμόνιο μαθαίνω πως ο Χριστός αναστήθηκε, θυμόμουν και τα κόκκινα αυγά και το αρνί το ζωντανό και η παιδική ψυχή μου γέμιζε χαρά. Έπειτα γινόταν ησυχία. Στη λειτουργία του Μεγάλου Σαββάτου, που τόσο μ’ άρεσε κατόπι, με τα θαυμάσια αναγνώσματα από την Αγία Γραφή –Κοσμογονία, Ιωνάς, Ναβουχοδονόσορ– και με τον υπέροχο ύμνο των Τριών Παίδων, δεν πήγαινα ακόμα. Και περνούσα την ημέρα μου στο σπίτι, κοιτάζοντας τα πασχαλινά ψώνια, που έρχονταν αδιάκοπα, και παίζοντας στο περιβόλι με το λευκόμαλλο αρνάκι, που θα ’ρχόταν ύστερα –τι θλίψη!– ο χασάπης να το σφάξει… Και βράδιαζε και πλάγιαζα νωρίς, για να ξυπνήσω πρωί, όπως δα πάντα. Γιατί εκείνο τον καιρό ακόμα στη Ζάκυνθο, που οι εκκλησιαστικές συνθήκες ήταν διαφορετικές, η Ανάστασις δε γινόταν τα μεσάνυχτα του Σαββάτου. Η αθηναϊκή αυτή συνήθεια, η σύμφωνη άλλωστε με το «τυπικόν της Μεγάλης Εκκλησίας», του Πατριαρχείου, εισήχθη δέκα χρόνια αργότερα (1884) από τον δεσπότη Λάνα.\nΟ προκάτοχός του, ο Κατραμής, έμενε στα πατροπαράδοτα. Κι η Ανάσταση τότε, σ’ όλες τις ζακυνθινές εκκλησίες, γινόταν το πρωί της Κυριακής.","word_count":338,"page_number":29,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"st_dimotikou_g_0005","source_id":"st_dimotikou_g","title":"Το Μοιρολόγι της Παναγίας","content":"Σήμερα μαύρος ουρανός, σήμερα μαύρη μέρα.\nΣήμερα όλοι θλίβονται και τα βουνά λυπούνται.\n\nΟ Κύριος ηθέλησε να μπει σε περιβόλι,\nνα λάβει Δείπνο Μυστικό, για να τον λάβουν όλοι.\n\nΚι η Παναγιά η Δέσποινα καθόταν μοναχή της,\nτην προσευχή της έκανε για τον μονογενή της.\n\nΚι εκεί που προσευχότανε κι έκανε τις μετάνοιες,\nφωνή τής ήρθε εξ ουρανού κι απ’ Αρχαγγέλου στόμα:\n\n– Φτάνουν, Κυρά, οι προσευχές! Φτάνουν και οι μετάνοιες!\nΤον Γιο σου τον επιάσανε, στη φυλακή τον πάνε.\n\nΣαν κλέφτη τον επιάσανε και σαν ληστή τον πάνε\nκαι στου Πιλάτου τα σκαλιά, εκεί τον τυραννάνε.\n\nΗ Παναγιά, σαν τ’ άκουσε, έπεσε και λιγώθη.\nΠάει η Μάρθα, η Μαγδαληνή και του Προδρόμου η μάνα\n\nκαι του Ιακώβου η αδερφή κι οι τέσσερις αντάμα.\nΣταμνί νερό της ρίξανε, τρία καντάρια μόσχο\n\nκαι τρία μυροδόσταμο, για νά ’ρθει ο λογισμός της.\nΚαι σαν της ήρθε ο λογισμός και σαν της ήρθε ο νους της,\n\nπαίρνουν τον δρόμο, το δρομί, στρατί το μονοπάτι.\nΤο μονοπάτι τούς έβγαλε εις του χαλκιά* την πόρτα.\n\n– Ώρα καλή σου, μάστορα! Τι είναι αυτά, που φτιάχνεις;\n– Τρία καρφιά παράγγειλαν οι φίλοι μου οι Pωμαίοι\n\nμα γω για το χατίρι τους πέντε θε να τους φτιάξω.\nΝα βάλουν δυο στα χέρια του και τ’ άλλα δυο στα πόδια,\n\nτο τρίτο, το φαρμακερό μέσα στα σωθικά του,\nνα τρέξει αίμα και νερό, να λιγωθεί η καρδιά του.\n\nΠαίρνουν τον δρόμο, το δρομί, στρατί το μονοπάτι.\nΚοιτούν δεξιά, κοιτούν ζερβά, κανένα δε γνωρίζουν,\n\nκοιτούν και δεξιότερα, βλέπουν τον Αϊ-Γιάννη.\n– Αϊ μου Γιάννη Πρόδρομε και βαπτιστά του γιου μου,\n\nμην είδες το παιδάκι μου και σε τον δάσκαλό σου;\n– Δεν έχω στόμα να σου πω, στόμα να σου μιλήσω.\n\nΔεν έχω χέρι πάλαμο, για να σου τον εδείξω.\n– Έχεις και στόμα να μου πεις, στόμα να μου μιλήσεις.\n\nΈχεις και χέρι πάλαμο, για να μου τον εδείξεις.\n– Βλέπεις εκείνο τον γυμνό, τον παραπονεμένο,\n\nόπου φορεί πουκάμισο στο αίμα βουτηγμένο;\nΒλέπεις εκείνο τον γυμνό τον ανεμομαλλιάρη,\n\nόπου φορεί στην κεφαλή αγκάθινο στεφάνι;\nΕκείνος είναι ο γιόκας σου κι εμένα ο δάσκαλός μου.\n\nΗ Παναγιά πλησίασε γλυκά και του μιλούσε:\n– Γιε μου, που σ’ έχω μοναχό και μοναχό κλωνάρι,\n\nτώρα σε βλέπω στον σταυρό μ’ αγκάθινο στεφάνι!\nΠού ’ναι γκρεμός να γκρεμιστώ, φωτιά να πάω να πέσω!\n\nΠού ’ναι μαχαίρι δίκοπο, να δώσω στην καρδιά μου!\nΔε μου μιλάς, παιδάκι μου, δε μου μιλάς, παιδί μου!\n\n– Σύρε, μάνα, στο σπίτι σου, κάνε την προσευχή σου\nκαι το Μεγάλο Σάββατο καρτέρα το παιδί σου.\n\nΒάλε κρασί μες στο γυαλί κι αφράτο παξιμάδι\nκαι δείξε την υπομονή, για να την κάνουν κι άλλοι.","word_count":436,"page_number":31,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"st_dimotikou_g_0006","source_id":"st_dimotikou_g","title":"Διπλή γιορτή","content":"Μια χρονιά, όταν ακόμα οι Έλληνες ήταν υπόδουλοι στους Τούρκους, έτυχε να γιορτάσουν την ίδια μέρα οι χριστιανοί τη Λαμπρή τους και οι Τούρκοι το Μπαϊράμι τους. Έτσι έτυχε.\nΣε μια γειτονιά της Αθήνας, του Μεγάλου Σαββάτου, αφού οι χριστιανοί έκαναν Ανάσταση και τελείωσε η εκκλησία, η γριά κλησάρισσα* της Αγίας Σωτήρας κλείστηκε μέσα στο κελί της. Διπλοαμπάρωσε την πορτίτσα της κι έβαλε, για καλό και για κακό, από πίσω και το φορτσέρι* της, γεμάτο μ’ όλο της το νοικοκυριό, γιατί το τούρκικο ξεφάντωμα μπορούσε να ξεσπάσει πάνω της.\nΈξαφνα, χτυπά τρεις φορές η πόρτα: τακ, τακ, τακ. Άλλες τρεις φορές χτύπησε και η καρδιά της κλησάρισσας.\n– Αν είσαι χριστιανός να σε πολυχρονά ο Μεγαλοδύναμος. Μα και Τούρκος αν είσαι, πάλι καλώς όρισες, είπε μέσα της.\n– Άνοιξε γρήγορα, γειτόνισσα, και μη φοβάσαι, εγώ είμαι.\n– Μπα! Εσύ ’σαι γειτόνισσα; Και τι γυρεύεις τέτοιαν ώρα;\nΗ πορτίτσα του κελιού άνοιξε. Το κατάλευκο γεροντάκι, η κλησάρισσα, καλωσόρισε μια γριά μουσουλμάνα φιλενάδα της, που καθόταν μέσα σ’ ένα χάλασμα της γειτονιάς. Η πορτίτσα ξανάκλεισε:\nΗ μουσουλμάνα μιλάει πρώτη:\n– Τώρα που ησύχασε ο κόσμος όλος και οι χαροκόποι τραβήχτηκαν στα σπίτια τους, ήρθε κι εμένα η σειρά μου να γιορτάσω το Μπαϊράμι μου στο τρυπόσπιτό μου μέσα. Έκαμα ν’ απλώσω πάνω σε κάτι πέτρες ό,τι μου ’δωκαν οι αγάδες της γειτονιάς και τότε συλλογίστηκα, καημένη γειτόνισσα, κλεισμένη καταμόναχη, στο κελί σου, τέτοια χρονιάρα μέρα που ξημερώνει για σας τους χριστιανούς. Σε ψυχοπόνεσα, τύλιξα πάλι τα φαγιά που είχα μπροστά μου και είπα μέσα μου:\n– Φτωχές είμαστε κι οι δύο. Ας πάω να γιορτάσουμε μαζί: αυτή τη Λαμπρή της κι εγώ το Μπαϊράμι μου. Ξεκίνησα λοιπόν και ήρθα.\nΚι ακούμπησε το μικρό της δέμα πάνω στο τραπέζι του κελιού.\nΣηκώνεται τότε η κλησάρισσα γελαστή και ψάχνει μέσα στην κασέλα της. Βγάζει ένα κόκκινο αυγό και το δίνει στη μουσουλμάνα.\nΤο παίρνει εκείνη μ’ ευχαρίστηση μεγάλη, σηκώνει το χέρι της ψηλά, το παρατηρεί γύρω γύρω στο φως του λυχναριού με χαρά μικρού παιδιού και το θαυμάζει σαν κάτι σπάνιο και περίφημο πράμα.\nΗ γριά κλησάρισσα πλησιάζει σιγά σιγά, κάθεται κοντά της κι άξαφνα κάνει τσακ μια και της το σπάζει με το άλλο κόκκινο αυγό, που είχε κρυμμένο στο άλλο της χέρι, ξεκαρδισμένη στα γέλια για το κατόρθωμά της.\nΤο κελί είναι μισοσκότεινο. Το λυχνάρι μόλις και φέγγει. Ζυγώνουν κοντά, μάγουλο με μάγουλο τα δυο γεροντικά κεφάλια, κάτασπρο το ένα, κατάμαυρο το άλλο και φιλιούνται…","word_count":403,"page_number":35,"chapter":"Ενότητα 14 — Πάσχα"},{"id":"st_dimotikou_g_0007","source_id":"st_dimotikou_g","title":"Το καναρινί ποδήλατο","content":"ΕΛΛΑΔΑ, 1999, διάρκεια 90΄, έγχρωμο\nΜια όμορφη, συγκινητική ταινία σε σκηνοθεσία του Δημήτρη Σταύρακα. Μόλις ο Άρης Σιούτης διορίζεται δάσκαλος στην Στ΄ Δημοτικού ενός δημοσίου σχολείου της Αθήνας, ανακαλύπτει ότι ένας από τους μαθητές του, ο Λευτέρης Μουρατίδης, είναι σχεδόν αναλφάβητος και απομονωμένος από τους συμμαθητές του. Αποφασισμένος να βοηθήσει το παιδί να βγει από αυτό το αδιέξοδο, αντιμετωπίζει πολλαπλά εμπόδια: οι συνάδελφοί του είναι ηττοπαθείς και δεν πιστεύουν ότι μπορεί να γίνει κάτι, ο ίδιος ο Λευτέρης δύσπιστος, οι γονείς του δεν είναι πάντα συνεργάσιμοι, η συμπεριφορά των υπόλοιπων παιδιών δεν είναι πάντα φιλική απέναντι στον Λευτέρη. Αλλά η αποφασιστικότητα και η επιμονή του θα τον βοηθήσουν να ξεπεράσει τις δυσκολίες. Την κρίσιμη στιγμή που ο Λευτέρης είναι έτοιμος να τα παρατήσει, ο δάσκαλος βρίσκει τρόπο να τον εμψυχώσει και να τον ενθαρρύνει. Πιστή στην πραγματικότητα η ταινία (βασίζεται άλλωστε σε αληθινή ιστορία), δεν τελειώνει με «επαίνους». Τονίζει απλώς την εμπιστοσύνη στην αξία των ανθρώπινων σχέσεων και στην αξία της δύναμης της θέλησης. Μια ταινία δοσμένη με αυθεντικότητα και γνήσιο συναίσθημα.","word_count":172,"page_number":41,"chapter":"Ενότητα 15 — κινηματογράφος - θέατρο"},{"id":"st_dimotikou_g_0008","source_id":"st_dimotikou_g","title":"Το άγαλμα που κρύωνε","content":"Το μικρό μαρμάρινο αγόρι, το άγαλμα, άφησε σαν προσφυγάκι την πατρίδα του στη Μικρασία και στεγάστηκε στο Αρχαιολογικό Μουσείο της Αθήνας. Από τότε κρύωνε ολοένα, γιατί νοσταλγούσε αθεράπευτα την πατρίδα του στην αντίπερα ακτή του Αιγαίου. Τα πράγματα θ’ αλλάξουν όμως όταν θα βρει δυο φίλους καρδιάς, την κυρία Γαλάτεια, την καθαρίστρια του Μουσείου, και τον μικρό Λάμπη, τον γιο του νυχτοφύλακα. Τα πράγματα θ’ αλλάξουν μ’ ένα παράξενο όνειρο. Απ’ τ’ όνειρο θα φτερουγίσει στο Μουσείο ένα μεγάλο γαλάζιο πουλί που θα τους ταξιδέψει μια νύχτα με πανσέληνο στις χαμένες πατρίδες, στη Μικρασία.\nΤην τελευταία νύχτα εκείνου του Οκτώβρη ήρθε κι ο Λάμπης, ο μικρός γιος του νυχτοφύλακα.\nΠολύ το ’χε μεράκι ο Λάμπης να γινόταν γλύπτης όταν θα μεγάλωνε. Να σκάλιζε, λέει, κι αυτός στο μάρμαρο αγάλματα σαν κι εκείνα στο μεγάλο μουσείο της Αθήνας. Τι όμορφα που είναι τα αρχαία αγάλματα! Και λαχταρούσε ο Λάμπης να τ’ ακουμπήσει με το χέρι του, να τα χαϊδέψει.\nΌμως όλο «μη» και «μη» τού έλεγαν, «απαγορεύεται να τ’ αγγίξεις». Μα το ένιωθε εκείνος πως τ’ αρχαία αγάλματα αποζητούσανε αγγίγματα σαν το δικό του.\nΚι αφού τη μέρα οι φύλακες είχαν τα μάτια τετρακόσια, άλλη λύση δεν έμενε: παρακαλούσε τον πατέρα του μήνες και μήνες, «πάρε με μαζί σου μια νύχτα στο μουσείο, πάρε με, πατέρα. Να γίνω γλύπτης θέλω, πατέρα».\nΜια, δυο, τρεις, δέκα, απ’ τα πολλά τα παρακάλια τελικά του ’κανε το χατίρι.\nΣαν μελένιο όνειρο ήταν, και πιο πολύ ακόμη… Μπερδεύτηκε ο Λάμπης μέσα σε πλήθος αγάλματα που σεριανούσαν στις αίθουσες του μουσείου, αργά, νωχελικά, λες κι είχαν μόλις βγει από βαθύ λήθαργο. Γυναίκες και παιδιά και άντρες και θεοί, όλοι ανάκατα, στο βελουδένιο μισοσκόταδο. Κι ανάμεσά τους να φυσάει, θαρρείς, ένα απαλό αεράκι.\nΔεν πίστευε στα μάτια του ο Λάμπης.\n«Κοίτα να δεις… Καλά μού το ’λεγε ο πατέρας… τις νύχτες ζωντανεύουν τ’ αγάλματα!»\nΚι είδε περήφανους θεούς να υποκλίνονται ταπεινά σε ανθρώπους που μοιάζανε θεοί, και παιδιά να ’χουν πάρει στο κατόπι θεούς κρατώντας τους απ’ το μακρύ τους ρούχο. Και κοπελιές είδε σαν τα κρύα νερά να προχωρούν ζευγαρωτά με νεαρούς πανέμορφους. Είδε και μοναχικά αγάλματα να στέκονται απόμερα στη γωνιά κι άλλα μαζεμένα σε παρέες να συζητούν, χωρίς όμως ν’ ακούγεται μιλιά. Έστησε αυτί ο Λάμπης μήπως και πιάσει καμιά λέξη. Μα τίποτα.\nΞαφνικά, μες στη σιωπή των αγαλμάτων, άκουσε ο Λάμπης μια λεπτή φωνίτσα:\n– Έι, ψιτ. Σε σένα μιλάω…\nΑπό το βάθος της αίθουσας ερχόταν η φωνή. Τράβηξε κατά κει και μόνο τότε πρόσεξε ένα μικρό αγόρι να στέκεται ακίνητο, σφιχτοτυλιγμένο στην κάπα του, μ’ ένα σκυλάκι αγκαλιά.\nΤο άγαλμα κρύωνε πολύ, όχι απ’ το κρύο, όχι. Ο λόγος ήταν άλλος, πιο βαθύς. Νοσταλγούσε αθεράπευτα τη μακρινή πατρίδα του στη Μικρασία, στην άλλη, την αντίπερα όχθη του Αιγαίου.\n– Σίγουρα είσαι ο Λάμπης εσύ!\n– Ναι, ο Λάμπης είμαι, ο γιος του νυχτοφύλακα. Μα τ’ όνομά μου πού το ξέρεις;\n– Σε περίμενα. Είχε δίκιο το γαλάζιο πουλί πως θα ’ρχόσουν. Ήρθες! Καλώς ήρθες!\n– Το γαλάζιο πουλί; Ποιο πουλί; έκανε διπλά απορημένος ο Λάμπης.\nΚαι του τα εξήγησε όλα το μικρό προσφυγάκι. Για το γαλάζιο πουλί του ’πε που βγάζει αληθινές τις πιο τρελές επιθυμίες. Του ’πε για την πατρίδα του στη Μικρασία. Και για την κυρία Γαλάτεια του ’πε, που είναι κι αυτή προσφυγοπούλα κι είναι τα μάτια της σαν τα νερά του Αιγαίου.\n– Σ’ έβλεπα τόση ώρα, Λάμπη, ν’ αγγίζεις τ’ αγάλματα.\n– Ναι. Μια μέρα θέλω να γίνω γλύπτης, προσφυγάκι μου, γι’ αυτό.\n– Έλα, ακούμπησε κι εμένα, χάιδεψέ με.\n– Αλήθεια το λες; Μπορώ; Το θέλεις; έκανε ο Λάμπης και το ’σφιξε όλο πεθυμιά στην αγκαλιά του.\nΚι αφού χόρτασε χάδια το μικρό προσφυγάκι, είπε:\n– Να παίξουμε τώρα, Λάμπη;\n– Ναι, να παίξουμε. Πρώτη φορά θα παίξω με άγαλμα!\nΚι έπαιξαν τρίλιζα, κι έπαιξαν αγαλματάκια ακούνητα, αμίλητα κι αγέλαστα, κι ύστερα κρυφτό. Είχε και μπίλιες πολύχρωμες στην τσέπη του ο Λάμπης και μια σβούρα ξύλινη. Έπαιξαν μπίλιες, έπαιξαν και σβούρα.\nΚι αφού χόρτασε παιχνίδι το μικρό προσφυγάκι, είπε:\n– Ξέρεις παραμύθια, Λάμπη; Πολύ μ’ αρέσουνε τα παραμύθια.\n– Ξέρω… Μια φορά κι έναν καιρό…\nΕκείνη τη νύχτα έγινε τρισευτυχισμένο το μικρό άγαλμα που κρύωνε.","word_count":689,"page_number":59,"chapter":"Ενότητα 16 — μουσεία"},{"id":"st_dimotikou_g_0009","source_id":"st_dimotikou_g","title":"Σκέψεις ενός παιδιού για τον πόλεμο","content":"Στη διάρκεια του Δεύτερου Παγκόσμιου πολέμου, η 12χρονη Eβραία Άννα Φρανκ έγραφε τις σκέψεις της στο ημερολόγιό της, ενώ κρυβόταν από τους Γερμανούς κατακτητές.\nΤετάρτη 3 Μαρτίου 1944\nΕίναι μια φοβερή εποχή. Γύρω λυσσομανάει ο πόλεμος και κανένας δε γνωρίζει αν θα είναι ζωντανός την άλλη μέρα. Θυμάμαι που ζούσαμε όλοι μαζί στην πόλη και περιμέναμε από στιγμή σε στιγμή να την αδειάσουν ή να φύγουμε. Οι μέρες μας ήταν γεμάτες κανονιές και πυροβολισμούς και τις νύχτες μυστηριώδεις ήχοι έρχονταν από τα βάθη. Αυτό συνεχίστηκε έτσι καμιά βδομάδα, ώσπου ένα βράδυ μάς σκέπασε μια νύχτα που κρατάει ακόμη και σήμερα.\nΘυμάμαι σαν τώρα εκείνη τη στιγμή. Πρέπει να ήταν αργά το βράδυ, όταν ακούστηκαν ξαφνικά τρομερές εκρήξεις. Το βάλαμε στα πόδια όσο πιο γρήγορα μπορούσαμε. Παντού γύρω μας έτρεχαν άνθρωποι που φώναζαν. Τα σπίτια καίγονταν, έτσι ώστε όλα τα πράγματα φαίνονταν πυρωμένα και κόκκινα. Δεν είναι δυνατό να πω πόση ώρα έτρεχα έτσι, πάντα με την εικόνα των σπιτιών που καίγονταν, των προσώπων που ούρλιαζαν παραμορφωμένα μπρος στα μάτια μου.\nΣυνέχεια αναρωτιόμαστε απελπισμένα: «Γιατί πρέπει να γίνεται ο πόλεμος; Γιατί οι άνθρωποι δεν μπορούν να ζήσουν ειρηνικά; Γιατί όλη αυτή η καταστροφή;». Στο ερώτημα αυτό δεν είναι εύκολο να βρούμε απάντηση. Αλήθεια, γιατί φτιάχνουν ολοένα μεγαλύτερα αεροπλάνα με όλο και πιο βαριές βόμβες, ενώ την ίδια στιγμή χτίζουν τα κατεστραμμένα σπίτια; Γιατί σπαταλούν δισεκατομμύρια κάθε μέρα για τον πόλεμο, ενώ φαίνεται ότι δεν υπάρχει ούτε μια δεκάρα διαθέσιμη για τα φάρμακα, τους φτωχούς και τους καλλιτέχνες; Γιατί υπάρχουν άνθρωποι που πεινούν, ενώ σε άλλα μέρη της γης έχουν τόσα τρόφιμα που τα αφήνουν να σαπίζουν; Μήπως οι άνθρωποι είναι τρελοί;\nΔεν μπορώ να πιστέψω ότι υπεύθυνοι για τον πόλεμο είναι μόνο οι ισχυροί, οι πλούσιοι και οι πολιτικοί. Όχι, και οι απλοί άνθρωποι μπορεί να θέλουν τον πόλεμο, αλλιώς οι λαοί θα είχαν επαναστατήσει προ πολλού. Είναι το ένστικτο της καταστροφής που οδηγεί τους ανθρώπους στον πόλεμο, κι αν όλο το ανθρώπινο γένος, χωρίς εξαίρεση, δεν αλλάξει, οι πόλεμοι δεν πρόκειται να σταματήσουν. Οι πολιτισμοί θα καταστρέφονται, ό,τι ωραίο χτίζεται θα γκρεμίζεται και η ανθρωπότητα θα αρχίζει ξανά και ξανά από την αρχή.\nΈχω νιώσει πολλές φορές παγιδευμένη αλλά ποτέ απελπισμένη. Στο ημερολόγιό μου μιλάω για τις στερήσεις σαν να πρόκειται για κάτι διασκεδαστικό. Έχω πάρει την απόφαση να ζήσω μια ενδιαφέρουσα ζωή, διαφορετική από τη ζωή του απλού κοριτσιού και, αργότερα, από τη ζωή της απλής νοικοκυράς. Είμαι νέα και δυνατή. Είναι ανάγκη να επιβιώσω και αρνούμαι να κλαίω όλη την ώρα. Κάθε μέρα ωριμάζω εσωτερικά και αισθάνομαι την ειρήνη να πλησιάζει.","word_count":423,"page_number":75,"chapter":"Ενότητα 17 — πόλεμος και ειρήνη"}];
